               <> ARRAY['attempt_id','binding_hash','call_deadline','capability_name',
                        'decision_hash','delivery_generation','effect_identity','fencing_token',
                        'invocation_id','job_id','phase','run_id','schema_version','segment_id',
                        'sequence','tenant_id']
             ) OR (
