              'propose_api_key_revocation',p_model_arguments,p_trusted_context);
          END IF;
          RETURN jsonb_build_object('schema_version','mcp-wrapper-result.v1',
                                    'authorized',v_allowed,'capability_name','propose_api_key_revocation',
                                    'phase',v_phase);
        END $$;


ALTER FUNCTION public.supportguard_action_mcp_propose_api_key_revocation(p_model_arguments jsonb, p_trusted_context jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_action_mcp_propose_entitlement_change(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_action_mcp_propose_entitlement_change(p_model_arguments jsonb, p_trusted_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_allowed boolean; v_phase text;
        BEGIN
          IF session_user <> 'supportguard_action_mcp' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security_definer_session_user_forbidden';
          END IF;
          v_phase:=p_trusted_context->>'phase';
          IF jsonb_typeof(p_model_arguments)<>'object'
             OR jsonb_typeof(p_trusted_context)<>'object'
             OR p_trusted_context->>'schema_version'<>'action-mcp-wrapper.v1'
             OR p_trusted_context->>'capability_name'<>'propose_entitlement_change'
             OR v_phase NOT IN ('reserve','recheck','execute','record_result')
             OR (
               v_phase='record_result' AND
               (SELECT array_agg(key ORDER BY key)
                  FROM jsonb_object_keys(p_trusted_context) key)
               <> ARRAY['attempt_id','binding_hash','call_deadline','capability_name',
                        'decision_hash','delivery_generation','effect_identity','fencing_token',
                        'invocation_id','job_id','payload_hash','phase','run_id','schema_version',
                        'segment_id','sequence','tenant_id']
             ) OR (
               v_phase IN ('reserve','recheck') AND
               (SELECT array_agg(key ORDER BY key)
                  FROM jsonb_object_keys(p_trusted_context) key)
               <> ARRAY['attempt_id','binding_hash','call_deadline','capability_name',
                        'decision_hash','delivery_generation','effect_identity','fencing_token',
                        'invocation_id','job_id','phase','run_id','schema_version','segment_id',
                        'sequence','tenant_id']
             ) OR (
               v_phase='execute' AND
               (SELECT array_agg(key ORDER BY key)
                  FROM jsonb_object_keys(p_trusted_context) key)
               <> ARRAY['attempt_id','binding_hash','call_deadline','capability_name',
                        'decision_hash','delivery_generation','effect_identity',
                        'execution_payload','fencing_token','invocation_id','job_id','phase',
                        'run_id','schema_version','segment_id','sequence','tenant_id']
             )
          THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid action MCP wrapper envelope';
          END IF;
          IF v_phase='reserve' THEN
            v_allowed:=supportguard_mcp_consume_capability_reservation(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer,
              p_trusted_context->>'invocation_id',p_trusted_context->>'attempt_id',
              (p_trusted_context->>'sequence')::integer,'propose_entitlement_change',
              p_trusted_context->>'effect_identity',p_trusted_context->>'decision_hash',
              p_trusted_context->>'binding_hash',
              (p_trusted_context->>'call_deadline')::timestamptz);
          ELSIF v_phase='record_result' THEN
            v_allowed:=supportguard_mcp_record_capability_result(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'invocation_id',
              p_trusted_context->>'attempt_id',p_trusted_context->>'effect_identity',
              p_trusted_context->>'payload_hash',p_model_arguments);
          ELSE
            v_allowed:=supportguard_mcp_verify_fence(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer);
          END IF;

          IF v_phase='execute' THEN
            IF v_allowed IS DISTINCT FROM true THEN
              RETURN pg_catalog.jsonb_build_object(
                'schema_version','mcp-wrapper-result.v1','authorized',false,
                'capability_name','propose_entitlement_change','phase','execute');
            END IF;
            RETURN public.supportguard_action_mcp_execute(
              'propose_entitlement_change',p_model_arguments,p_trusted_context);
          END IF;
          RETURN jsonb_build_object('schema_version','mcp-wrapper-result.v1',
                                    'authorized',v_allowed,'capability_name','propose_entitlement_change',
                                    'phase',v_phase);
        END $$;


ALTER FUNCTION public.supportguard_action_mcp_propose_entitlement_change(p_model_arguments jsonb, p_trusted_context jsonb) OWNER TO supportguard_owner;

