--
-- Name: supportguard_action_observation_bound(jsonb, jsonb, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_action_observation_bound(p_trusted_context jsonb, p_bindings jsonb, p_tool_name text, p_resource_field text, p_resource_id text, p_resource_version integer) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_target jsonb; v_policy jsonb; v_count integer; v_item jsonb;
        BEGIN
          IF current_user<>'supportguard_owner' OR jsonb_typeof(p_bindings)<>'array' THEN
            RETURN false;
          END IF;
          SELECT count(*),min(value::text)::jsonb INTO v_count,v_target
          FROM jsonb_array_elements(p_bindings)
          WHERE value->>'tool_name'=p_tool_name AND value->>'status'='ok'
            AND value->>'resource_field'=p_resource_field
            AND value->>'resource_id'=p_resource_id
            AND (value->>'resource_version')::integer=p_resource_version;
          IF v_count<>1 THEN RETURN false; END IF;
          SELECT value INTO v_policy
          FROM jsonb_array_elements(p_bindings) WITH ORDINALITY b(value,n)
          WHERE value->>'tool_name'='search_knowledge' AND value->>'status'='ok'
            AND jsonb_array_length(COALESCE(value->'source_refs','[]'::jsonb))>0
          ORDER BY n DESC LIMIT 1;
          IF v_policy IS NULL THEN RETURN false; END IF;
          FOREACH v_item IN ARRAY ARRAY[v_target,v_policy] LOOP
            IF NOT EXISTS (
              SELECT 1 FROM tool_observations o
              JOIN tool_invocations i ON i.id=o.invocation_id
              JOIN turn_groups g ON g.id=i.turn_group_id
              WHERE o.id=v_item->>'observation_id'
                AND o.invocation_id=v_item->>'invocation_id'
                AND o.content_hash=v_item->>'observation_content_hash'
                AND o.tenant_id=p_trusted_context->>'tenant_id'
                AND o.run_id=p_trusted_context->>'run_id'
                AND o.job_id=p_trusted_context->>'job_id'
                AND o.segment_id=p_trusted_context->>'segment_id'
                AND o.fencing_token=(p_trusted_context->>'fencing_token')::bigint
                AND o.status='ok' AND i.tool_name=v_item->>'tool_name'
                AND i.lifecycle='terminal' AND i.outcome='succeeded'
                AND g.id=v_item->>'turn_group_id' AND g.status='closed'
                AND (CASE WHEN v_item->>'tool_name'=p_tool_name THEN
                  o.payload::jsonb->'data'->>p_resource_field=p_resource_id
                  AND (o.payload::jsonb->'data'->>'version')::integer=p_resource_version
                  ELSE jsonb_array_length(COALESCE(
                    o.payload::jsonb->'source_refs','[]'::jsonb))>0 END)
            ) THEN RETURN false; END IF;
          END LOOP;
          RETURN true;
        END $$;


ALTER FUNCTION public.supportguard_action_observation_bound(p_trusted_context jsonb, p_bindings jsonb, p_tool_name text, p_resource_field text, p_resource_id text, p_resource_version integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_active_job_consistency_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_active_job_consistency_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
            v_job public.runtime_jobs%ROWTYPE;
            v_run public.agent_runs%ROWTYPE;
            v_tenant_id text;
            v_run_id text;
        BEGIN
            IF TG_TABLE_NAME = 'agent_runs' THEN
                v_tenant_id := NEW.tenant_id;
                v_run_id := NEW.id;
            ELSE
                v_tenant_id := NEW.tenant_id;
                v_run_id := NEW.run_id;
            END IF;

            -- A deferred constraint trigger may have several queued events for one
            -- transaction.  NEW is the historical event image, not the state being
            -- committed, so always re-read the authoritative aggregate.
            SELECT * INTO v_run
            FROM public.agent_runs
            WHERE tenant_id = v_tenant_id AND id = v_run_id;

            IF v_run.id IS NULL THEN
                RETURN NULL;
            END IF;
            IF v_run.active_job_id IS NULL THEN
                IF EXISTS (
                    SELECT 1 FROM public.runtime_jobs j
                    WHERE j.tenant_id = v_run.tenant_id
                      AND j.run_id = v_run.id
                      AND j.status = 'leased'
                ) THEN
                    RAISE EXCEPTION USING
                        ERRCODE = '23514',
                        MESSAGE = 'leased_job_without_active_pointer',
                        DETAIL = format('trigger=%s run=%s', TG_TABLE_NAME, v_run.id);
                END IF;
                RETURN NULL;
            END IF;

            SELECT * INTO v_job
            FROM public.runtime_jobs j
            WHERE j.tenant_id = v_run.tenant_id
              AND j.run_id = v_run.id
              AND j.id = v_run.active_job_id;
            IF v_job.id IS NULL
               OR v_job.status <> 'leased'
               OR v_job.fencing_token <> v_run.active_fencing_token THEN
                RAISE EXCEPTION USING
                    ERRCODE = '23514',
                    MESSAGE = 'active_job_pointer_inconsistent',
                    DETAIL = format(
                        'trigger=%s run=%s active_job=%s run_fence=%s job_status=%s job_fence=%s',
                        TG_TABLE_NAME, v_run.id, v_run.active_job_id,
                        v_run.active_fencing_token, v_job.status, v_job.fencing_token
                    );
            END IF;
            RETURN NULL;
        END $$;


ALTER FUNCTION public.supportguard_active_job_consistency_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_api_accept_approval_decision(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_accept_approval_decision(p_approval_id text, p_decision text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_tenant_id text := current_setting('app.tenant_id', true);
          v_principal_id text := current_setting('app.principal_id', true);
          v_route text := 'POST /api/approvals/' || p_approval_id || '/decision';
          v_request_hash text;
          v_existing public.idempotency_requests%ROWTYPE;
          v_approval public.approval_requests%ROWTYPE;
          v_run public.agent_runs%ROWTYPE;
          v_ticket public.support_tickets%ROWTYPE;
          v_proposal public.proposal_records%ROWTYPE;
          v_marker public.checkpoint_commit_markers%ROWTYPE;
          v_revision public.approval_action_revisions%ROWTYPE;
          v_human public.human_decisions%ROWTYPE;
          v_existing_job public.runtime_jobs%ROWTYPE;
          v_parent public.agent_events%ROWTYPE;
          v_accepted_at timestamptz := pg_catalog.clock_timestamp();
          v_timing_version bigint;
          v_active_count bigint;
          v_oldest_age bigint;
          v_backlog_limit integer;
          v_oldest_limit integer;
          v_status text;
          v_action_payload jsonb;
          v_action_hash text;
          v_revision_id text;
          v_revision_number integer;
          v_decision_hash text;
          v_payload jsonb;
          v_payload_canonical text;
          v_payload_hash text;
          v_created_at_text text;
          v_envelope text;
          v_event_hash text;
          v_ticket_sequence bigint;
          v_run_sequence bigint;
          v_chain_count bigint;
          v_chain_min bigint;
          v_chain_max bigint;
        BEGIN
          IF session_user <> 'supportguard_api'
             OR p_request IS NULL
             OR p_request - ARRAY[
               'schema_version','actor_id','idempotency_key','reason','approver_note',
               'edited_payload','idempotency_id','revision_id','decision_id','event_id',
               'job_id','outbox_id','delivery_id','audit_id','trace_id'
             ]::text[] <> '{}'::jsonb
             OR (SELECT pg_catalog.count(*)
                 FROM pg_catalog.jsonb_object_keys(p_request)) <> 15
             OR p_request->>'schema_version' <> 'api-accept-approval-decision.v1'
             OR p_request->>'actor_id' IS DISTINCT FROM v_principal_id
             OR p_decision NOT IN ('approve','edit_and_approve','reject','manual_takeover')
             OR coalesce(p_approval_id,'') = ''
             OR coalesce(p_request->>'idempotency_key','') = ''
             OR coalesce(p_request->>'reason','') = ''
             OR pg_catalog.jsonb_typeof(p_request->'edited_payload') <> 'object' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='api_accept_approval_decision_invalid';
          END IF;
          IF (p_decision='edit_and_approve') IS DISTINCT FROM
             (p_request->'edited_payload' <> '{}'::jsonb)
             OR (
               p_decision='edit_and_approve'
               AND (
                 (p_request->'edited_payload') - 'refund_reason'::text <> '{}'::jsonb
                 OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(
                       p_request->'edited_payload')) <> 1
                 OR coalesce(p_request#>>'{edited_payload,refund_reason}','')=''
               )
             ) THEN
            RETURN pg_catalog.jsonb_build_object('error_code','approval_edit_not_allowed');
          END IF;

          SELECT * INTO v_approval FROM public.approval_requests a
          WHERE a.tenant_id=v_tenant_id AND a.id=p_approval_id FOR UPDATE;
          IF NOT FOUND THEN
            RETURN pg_catalog.jsonb_build_object('error_code','approval_not_found');
          END IF;
          IF NOT EXISTS (
            SELECT 1 FROM public.memberships m
            JOIN public.approver_tenant_scopes s
              ON s.user_id=m.user_id AND s.tenant_id=m.tenant_id
            WHERE m.tenant_id=v_tenant_id AND m.user_id=v_principal_id
              AND m.role='support_approver' AND m.status='active'
          ) THEN
            RETURN pg_catalog.jsonb_build_object('error_code','approver_scope_invalid');
          END IF;

          v_request_hash := pg_catalog.md5(pg_catalog.jsonb_build_object(
            'decision',p_decision,'reason',p_request->>'reason',
            'approver_note',p_request->>'approver_note',
            'edited_payload',p_request->'edited_payload'
          )::text);
          SELECT * INTO v_existing FROM public.idempotency_requests i
          WHERE i.tenant_id=v_tenant_id AND i.principal_id=v_principal_id
            AND i.route=v_route AND i.idempotency_key=p_request->>'idempotency_key'
          FOR UPDATE;
          IF FOUND THEN
            IF v_existing.request_hash <> v_request_hash THEN
              RETURN pg_catalog.jsonb_build_object('error_code','idempotency_conflict');
            END IF;
            IF v_existing.response_snapshot::jsonb <> '{}'::jsonb THEN
              RETURN v_existing.response_snapshot::jsonb
                || pg_catalog.jsonb_build_object('reused',true);
            END IF;
          END IF;

          SELECT * INTO v_human FROM public.human_decisions h
          WHERE h.tenant_id=v_tenant_id AND h.approval_id=p_approval_id;
          IF FOUND THEN
            SELECT * INTO v_existing_job FROM public.runtime_jobs j
            WHERE j.tenant_id=v_tenant_id AND j.approval_id=p_approval_id;
            IF NOT FOUND OR v_human.decision <> p_decision THEN
              RETURN pg_catalog.jsonb_build_object(
                'error_code','approval_decision_conflict'
              );
            END IF;
            IF v_existing.id IS NULL THEN
              INSERT INTO public.idempotency_requests(
                id,tenant_id,principal_id,route,idempotency_key,request_hash,status,
                resource_ids,response_snapshot,completed_at,retention_class,
                created_at,updated_at
              ) VALUES (
                p_request->>'idempotency_id',v_tenant_id,v_principal_id,v_route,
                p_request->>'idempotency_key',v_request_hash,'accepted','{}'::jsonb,
                pg_catalog.jsonb_build_object(
                  'schema_version','decision-accepted.v1',
                  'approval_id',p_approval_id,'decision',p_decision,
                  'ticket_id',v_approval.ticket_id,'run_id',v_approval.run_id,
                  'job_id',v_existing_job.id,'accepted_at',public.supportguard_internal_format_utc_timestamp(v_human.created_at),
                  'status','decision_accepted',
                  'status_url','/api/runs/'||v_approval.run_id,
                  'events_url','/api/tickets/'||v_approval.ticket_id||'/events/stream','reused',false
                ),v_human.created_at,'protected_action',v_accepted_at,v_accepted_at
              );
            END IF;
            RETURN pg_catalog.jsonb_build_object(
              'schema_version','decision-accepted.v1',
                  'approval_id',p_approval_id,'decision',p_decision,
                  'ticket_id',v_approval.ticket_id,'run_id',v_approval.run_id,
                  'job_id',v_existing_job.id,'accepted_at',public.supportguard_internal_format_utc_timestamp(v_human.created_at),
                  'status','decision_accepted',
                  'status_url','/api/runs/'||v_approval.run_id,
                  'events_url','/api/tickets/'||v_approval.ticket_id||'/events/stream','reused',false,'reused',true
            );
          END IF;

          SELECT * INTO v_run FROM public.agent_runs r
          WHERE r.tenant_id=v_tenant_id AND r.id=v_approval.run_id FOR UPDATE;
          SELECT * INTO v_ticket FROM public.support_tickets t
          WHERE t.tenant_id=v_tenant_id AND t.id=v_approval.ticket_id FOR UPDATE;
          SELECT * INTO v_proposal FROM public.proposal_records p
          WHERE p.tenant_id=v_tenant_id AND p.id=v_approval.proposal_id;
          SELECT * INTO v_marker FROM public.checkpoint_commit_markers m
          WHERE m.tenant_id=v_tenant_id AND m.id=v_approval.marker_id;
          IF v_approval.status <> 'pending' OR v_run.id IS NULL OR v_ticket.id IS NULL
             OR v_proposal.id IS NULL OR v_marker.id IS NULL
             OR v_proposal.status <> 'bound' OR v_marker.status <> 'finalized'
             OR v_run.status <> 'interrupted' OR v_ticket.status <> 'awaiting_approval'
             OR v_run.canonical_checkpoint_ns IS DISTINCT FROM
                  v_approval.canonical_checkpoint_ns
             OR v_run.canonical_checkpoint_id IS DISTINCT FROM v_approval.checkpoint_id
             OR v_run.canonical_checkpoint_hash IS DISTINCT FROM
                  v_approval.canonical_checkpoint_hash
             OR v_marker.final_checkpoint_id IS DISTINCT FROM v_approval.checkpoint_id
             OR v_marker.final_checkpoint_hash IS DISTINCT FROM
                  v_approval.canonical_checkpoint_hash
             OR v_run.canonical_checkpoint_version IS DISTINCT FROM
                  v_approval.checkpoint_version
             OR v_marker.final_checkpoint_version IS DISTINCT FROM
                  v_approval.checkpoint_version
             OR v_approval.expected_ticket_sequence IS NULL THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','checkpoint_binding_conflict'
            );
          END IF;
          SELECT * INTO v_revision FROM public.approval_action_revisions r
          WHERE r.tenant_id=v_tenant_id AND r.id=v_approval.selected_revision_id;
          IF NOT FOUND OR v_revision.approval_id<>p_approval_id
             OR v_revision.revision_number IS DISTINCT FROM
                  v_approval.selected_revision_number THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','approval_revision_binding_conflict'
            );
          END IF;

          SELECT * INTO v_parent FROM public.agent_events e
          WHERE e.tenant_id=v_tenant_id AND e.ticket_id=v_ticket.id
          ORDER BY e.ticket_sequence DESC LIMIT 1;
          SELECT pg_catalog.count(*),pg_catalog.min(ticket_sequence),
                 pg_catalog.max(ticket_sequence)
          INTO v_chain_count,v_chain_min,v_chain_max
          FROM public.agent_events e
          WHERE e.tenant_id=v_tenant_id AND e.ticket_id=v_ticket.id;
          IF v_parent.id IS DISTINCT FROM v_approval.expected_ticket_head_event_id
             OR v_parent.event_hash IS DISTINCT FROM v_approval.expected_ticket_event_hash
             OR coalesce(v_parent.ticket_sequence,0) IS DISTINCT FROM
                  v_approval.expected_ticket_sequence
             OR v_ticket.next_event_sequence IS DISTINCT FROM
                  v_approval.expected_ticket_sequence
             OR v_chain_count<>v_approval.expected_ticket_sequence
             OR (v_chain_count>0 AND (v_chain_min<>1 OR v_chain_max<>v_chain_count))
             OR EXISTS (
               SELECT 1 FROM public.agent_events child
               LEFT JOIN public.agent_events parent
                 ON parent.tenant_id=child.tenant_id
                AND parent.ticket_id=child.ticket_id
                AND parent.ticket_sequence=child.ticket_sequence-1
               WHERE child.tenant_id=v_tenant_id AND child.ticket_id=v_ticket.id
                 AND child.ticket_sequence>1
                 AND (child.previous_event_id IS DISTINCT FROM parent.id
                      OR child.parent_event_hash IS DISTINCT FROM parent.event_hash)
             ) THEN
            RETURN pg_catalog.jsonb_build_object('error_code','event_chain_conflict');
          END IF;
          IF v_run.next_run_sequence IS DISTINCT FROM (
            SELECT coalesce(pg_catalog.max(e.run_sequence),0)
            FROM public.agent_events e
            WHERE e.tenant_id=v_tenant_id AND e.run_id=v_run.id
          ) THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','approval_expected_head_conflict'
            );
          END IF;

          v_action_payload := v_revision.action_payload::jsonb;
          v_action_hash := v_revision.action_hash;
          v_revision_id := v_revision.id;
          v_revision_number := v_revision.revision_number;
          IF p_decision='edit_and_approve' THEN
            IF v_approval.action_type<>'refund'
               OR v_action_payload - ARRAY[
                 'amount','billing_record_id','business_version','currency',
                 'customer_id','refund_reason'
               ]::text[] <> '{}'::jsonb
               OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(
                    v_action_payload))<>6 THEN
              RETURN pg_catalog.jsonb_build_object(
                'error_code','approval_edit_not_allowed'
              );
            END IF;
            v_action_payload := pg_catalog.jsonb_set(
              v_action_payload,'{refund_reason}',
              pg_catalog.to_jsonb(p_request#>>'{edited_payload,refund_reason}')
            );
            v_action_hash := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
              '{"amount":'||pg_catalog.to_jsonb(v_action_payload->>'amount')::text
              ||',"billing_record_id":'
              ||pg_catalog.to_jsonb(v_action_payload->>'billing_record_id')::text
              ||',"business_version":'||(v_action_payload->'business_version')::text
              ||',"currency":'||pg_catalog.to_jsonb(v_action_payload->>'currency')::text
              ||',"customer_id":'||pg_catalog.to_jsonb(v_action_payload->>'customer_id')::text
              ||',"refund_reason":'
              ||pg_catalog.to_jsonb(v_action_payload->>'refund_reason')::text||'}','UTF8'
            )),'hex');
            v_revision_id := p_request->>'revision_id';
            v_revision_number := v_revision.revision_number+1;
            INSERT INTO public.approval_action_revisions(
              id,tenant_id,approval_id,proposal_id,snapshot_id,revision_number,
              action_payload,action_hash,resource_version,created_by_ref,
              revision_reason,created_at,updated_at
            ) VALUES (
              v_revision_id,v_tenant_id,p_approval_id,v_approval.proposal_id,
              v_revision.snapshot_id,v_revision_number,v_action_payload,v_action_hash,
              v_revision.resource_version,v_principal_id,'edit_and_approve',
              v_accepted_at,v_accepted_at
            );
          END IF;

          v_status := CASE p_decision
            WHEN 'approve' THEN 'approved'
            WHEN 'edit_and_approve' THEN 'approved'
            WHEN 'reject' THEN 'rejected'
            ELSE 'manual_takeover' END;
          v_decision_hash := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            '{"action_hash":'||pg_catalog.to_jsonb(v_action_hash)::text
            ||',"actor_id":'||pg_catalog.to_jsonb(v_principal_id)::text
            ||',"approval_id":'||pg_catalog.to_jsonb(p_approval_id)::text
            ||',"approver_note":'||pg_catalog.to_jsonb(p_request->>'approver_note')::text
            ||',"decision":'||pg_catalog.to_jsonb(p_decision)::text
            ||',"reason":'||pg_catalog.to_jsonb(p_request->>'reason')::text
            ||',"revision_id":'||pg_catalog.to_jsonb(v_revision_id)::text
            ||',"revision_number":'||v_revision_number::text||'}','UTF8'
          )),'hex');
          v_payload := pg_catalog.jsonb_build_object(
            'approval_id',p_approval_id,'human_decision_id',p_request->>'decision_id',
            'decision',p_decision,'decision_hash',v_decision_hash,
            'action_hash',v_action_hash,'revision_id',v_revision_id,
            'revision_number',v_revision_number
          );
          v_payload_canonical := '{"action_hash":'||pg_catalog.to_jsonb(v_action_hash)::text
            ||',"approval_id":'||pg_catalog.to_jsonb(p_approval_id)::text
            ||',"decision":'||pg_catalog.to_jsonb(p_decision)::text
            ||',"decision_hash":'||pg_catalog.to_jsonb(v_decision_hash)::text
            ||',"human_decision_id":'
            ||pg_catalog.to_jsonb(p_request->>'decision_id')::text
            ||',"revision_id":'||pg_catalog.to_jsonb(v_revision_id)::text
            ||',"revision_number":'||v_revision_number::text||'}';
          v_payload_hash := pg_catalog.encode(pg_catalog.sha256(
            pg_catalog.convert_to(v_payload_canonical,'UTF8')),'hex');
          v_ticket_sequence := v_ticket.next_event_sequence+1;
          v_run_sequence := v_run.next_run_sequence+1;
          v_created_at_text := pg_catalog.to_char(
            v_accepted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US'
          )||'+00:00';
          v_envelope := '{"aggregate_id":'||pg_catalog.to_jsonb(v_ticket.id)::text
            ||',"aggregate_type":"SupportTicket"'
            ||',"canonicalization_version":"json-sort-keys.v1"'
            ||',"causation_id":'||coalesce(pg_catalog.to_jsonb(v_parent.id)::text,'null')
            ||',"correlation_id":'||pg_catalog.to_jsonb(v_run.id)::text
            ||',"created_at":'||pg_catalog.to_jsonb(v_created_at_text)::text
            ||',"customer_id":'||pg_catalog.to_jsonb(v_ticket.customer_id)::text
            ||',"delivery_generation":null'
            ||',"event_id":'||pg_catalog.to_jsonb(p_request->>'event_id')::text
            ||',"event_schema_version":"support-ticket-event.v1"'
            ||',"event_type":"human_decision_accepted"'
            ||',"fencing_token":null'
            ||',"idempotency_id":'
            ||pg_catalog.to_jsonb(p_request->>'idempotency_key')::text
            ||',"job_id":null'
            ||',"payload_hash":'||pg_catalog.to_jsonb(v_payload_hash)::text
            ||',"previous_event_id":'
            ||coalesce(pg_catalog.to_jsonb(v_parent.id)::text,'null')
            ||',"run_id":'||pg_catalog.to_jsonb(v_run.id)::text
            ||',"run_sequence":'||v_run_sequence::text
            ||',"status":"completed"'
            ||',"step_index":'||v_run.step_index::text
            ||',"tenant_id":'||pg_catalog.to_jsonb(v_tenant_id)::text
            ||',"ticket_sequence":'||v_ticket_sequence::text
            ||',"tool_call_id":null'
            ||',"tool_round":'||v_run.tool_rounds::text
            ||',"visibility":"approver"}';
          v_event_hash := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            'event-hash.v1'||v_envelope||coalesce(v_parent.event_hash,repeat('0',64)),
            'UTF8')),'hex');

          SELECT timing_version,backlog_count_limit,oldest_backlog_seconds
          INTO v_timing_version,v_backlog_limit,v_oldest_limit
          FROM supportguard_control.runtime_timing_snapshots
          WHERE is_active FOR UPDATE;
          IF v_timing_version IS NULL THEN
            RETURN pg_catalog.jsonb_build_object('error_code','runtime_backpressure');
          END IF;
          SELECT pg_catalog.count(*),coalesce(greatest(pg_catalog.floor(
            extract(epoch FROM v_accepted_at-pg_catalog.min(created_at))
          )::bigint,0::bigint),0::bigint)
          INTO v_active_count,v_oldest_age FROM public.runtime_jobs
          WHERE status IN ('queued','retry_wait','leased');
          IF v_active_count+1>v_backlog_limit OR v_oldest_age>=v_oldest_limit THEN
            RETURN pg_catalog.jsonb_build_object('error_code','runtime_backpressure');
          END IF;
          IF v_existing.id IS NULL THEN
            INSERT INTO public.idempotency_requests(
              id,tenant_id,principal_id,route,idempotency_key,request_hash,status,
              resource_ids,response_snapshot,completed_at,retention_class,
              created_at,updated_at
            ) VALUES (
              p_request->>'idempotency_id',v_tenant_id,v_principal_id,v_route,
              p_request->>'idempotency_key',v_request_hash,'accepted','{}'::jsonb,
              '{}'::jsonb,v_accepted_at,'protected_action',v_accepted_at,v_accepted_at
            );
          END IF;
          UPDATE public.approval_requests SET
            status=v_status,decided_at=v_accepted_at,
            selected_revision_id=v_revision_id,selected_revision_number=v_revision_number,
            status_version=status_version+1,updated_at=v_accepted_at
          WHERE tenant_id=v_tenant_id AND id=p_approval_id;
          UPDATE public.support_tickets SET
            status='queued',version=version+1,next_event_sequence=v_ticket_sequence,
            updated_at=v_accepted_at
          WHERE tenant_id=v_tenant_id AND id=v_ticket.id;
          UPDATE public.agent_runs SET
            status='queued',status_version=status_version+1,
            next_run_sequence=v_run_sequence,updated_at=v_accepted_at
          WHERE tenant_id=v_tenant_id AND id=v_run.id;
          INSERT INTO public.agent_events(
            id,tenant_id,run_id,ticket_id,customer_id,sequence,ticket_sequence,
            run_sequence,step_index,tool_round,event_type,status,visibility,payload,
            payload_hash,previous_event_id,parent_event_hash,event_hash,
            event_schema_version,canonicalization_version,event_hash_schema_version,
            correlation_id,causation_id,idempotency_id,created_at
          ) VALUES (
            p_request->>'event_id',v_tenant_id,v_run.id,v_ticket.id,v_ticket.customer_id,
            v_run_sequence,v_ticket_sequence,v_run_sequence,v_run.step_index,v_run.tool_rounds,
            'human_decision_accepted','completed','approver',v_payload,v_payload_hash,
            v_parent.id,coalesce(v_parent.event_hash,repeat('0',64)),v_event_hash,
            'support-ticket-event.v1','json-sort-keys.v1','event-hash.v1',v_run.id,
            v_parent.id,p_request->>'idempotency_key',v_accepted_at
          );
          INSERT INTO public.human_decisions(
            id,tenant_id,approval_id,action_revision_id,actor_id,decision,reason,
            action_hash,decision_hash,canonical_event_id,canonical_event_hash,
            audit_metadata,created_at,updated_at
          ) VALUES (
            p_request->>'decision_id',v_tenant_id,p_approval_id,v_revision_id,
            v_principal_id,p_decision,p_request->>'reason',v_action_hash,v_decision_hash,
            p_request->>'event_id',v_event_hash,
            pg_catalog.jsonb_build_object('approver_note',p_request->>'approver_note'),
            v_accepted_at,v_accepted_at
          );
          INSERT INTO public.runtime_jobs(
            id,tenant_id,run_id,approval_id,kind,status,attempt,available_at,
            fencing_token,timing_version,status_version,created_at,updated_at
          ) VALUES (
            p_request->>'job_id',v_tenant_id,v_run.id,p_approval_id,'approval_resume',
            'queued',0,v_accepted_at,0,v_timing_version,1,v_accepted_at,v_accepted_at
          );
          INSERT INTO public.outbox_events(
            id,delivery_id,tenant_id,job_id,run_id,delivery_generation,event_type,
            schema_version,payload,available_at,publish_attempts,delivery_state_version,
            created_at,updated_at
          ) VALUES (
            p_request->>'outbox_id',p_request->>'delivery_id',v_tenant_id,
            p_request->>'job_id',v_run.id,1,'runtime_job_available','runtime-job.v1',
            pg_catalog.jsonb_build_object('traceparent',p_request->>'trace_id'),
            v_accepted_at,0,1,v_accepted_at,v_accepted_at
          );
          INSERT INTO public.audit_events(
            id,tenant_id,ticket_id,customer_id,event_type,actor_type,actor_ref,run_id,
            trace_id,payload,created_at
          ) VALUES (
            p_request->>'audit_id',v_tenant_id,v_ticket.id,v_ticket.customer_id,
            'approval_decision_accepted','approver',v_principal_id,v_run.id,
            p_request->>'trace_id',pg_catalog.jsonb_build_object(
              'approval_id',p_approval_id,'decision',p_decision,
              'proposal_id',v_proposal.id,'marker_id',v_marker.id,
              'job_id',p_request->>'job_id','approver_note',p_request->>'approver_note'
            ),v_accepted_at
          );
          UPDATE public.idempotency_requests SET
            resource_ids=pg_catalog.jsonb_build_object(
              'approval_id',p_approval_id,'ticket_id',v_ticket.id,'run_id',v_run.id,
              'job_id',p_request->>'job_id'
            ),response_snapshot=pg_catalog.jsonb_build_object(
              'schema_version','decision-accepted.v1',
              'approval_id',p_approval_id,'decision',p_decision,
              'ticket_id',v_ticket.id,'run_id',v_run.id,
              'job_id',p_request->>'job_id','accepted_at',public.supportguard_internal_format_utc_timestamp(v_accepted_at),
              'status','decision_accepted',
              'status_url','/api/runs/'||v_run.id,
              'events_url','/api/tickets/'||v_ticket.id||'/events/stream','reused',false
            ),completed_at=v_accepted_at,retention_class='protected_action',
            updated_at=v_accepted_at
          WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
            AND route=v_route AND idempotency_key=p_request->>'idempotency_key';
          RETURN pg_catalog.jsonb_build_object(
            'schema_version','decision-accepted.v1',
              'approval_id',p_approval_id,'decision',p_decision,
              'ticket_id',v_ticket.id,'run_id',v_run.id,
              'job_id',p_request->>'job_id','accepted_at',public.supportguard_internal_format_utc_timestamp(v_accepted_at),
              'status','decision_accepted',
              'status_url','/api/runs/'||v_run.id,
              'events_url','/api/tickets/'||v_ticket.id||'/events/stream','reused',false,'reused',false
          );
        END
        $$;


ALTER FUNCTION public.supportguard_api_accept_approval_decision(p_approval_id text, p_decision text, p_request jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_accept_conversation_approval_decision(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_accept_conversation_approval_decision(p_approval_id text, p_decision text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_tenant_id text := current_setting('app.tenant_id', true);
          v_principal_id text := current_setting('app.principal_id', true);
          v_route text := 'POST /api/approvals/' || p_approval_id || '/decision';
          v_request_hash text;
          v_existing public.idempotency_requests%ROWTYPE;
          v_approval public.approval_requests%ROWTYPE;
          v_run public.agent_runs%ROWTYPE;
          v_turn public.conversation_turns%ROWTYPE;
          v_ticket public.support_tickets%ROWTYPE;
          v_proposal public.proposal_records%ROWTYPE;
          v_marker public.checkpoint_commit_markers%ROWTYPE;
          v_revision public.approval_action_revisions%ROWTYPE;
          v_human public.human_decisions%ROWTYPE;
          v_existing_job public.runtime_jobs%ROWTYPE;
          v_parent public.agent_events%ROWTYPE;
          v_frozen public.agent_events%ROWTYPE;
          v_accepted_at timestamptz := pg_catalog.clock_timestamp();
          v_timing_version bigint;
          v_active_count bigint;
          v_oldest_age bigint;
          v_backlog_limit integer;
          v_oldest_limit integer;
          v_status text;
          v_action_payload jsonb;
          v_action_hash text;
          v_revision_id text;
          v_revision_number integer;
          v_decision_hash text;
          v_payload jsonb;
          v_payload_canonical text;
          v_payload_hash text;
          v_created_at_text text;
          v_envelope text;
          v_event_hash text;
          v_ticket_sequence bigint;
          v_run_sequence bigint;
          v_chain_count bigint;
          v_chain_min bigint;
          v_chain_max bigint;
          v_claimed boolean := false;
          v_inserted bigint := 0;
        BEGIN
          IF session_user <> 'supportguard_api'
             OR p_request IS NULL
             OR p_request - ARRAY[
               'schema_version','actor_id','idempotency_key','reason','approver_note',
               'edited_payload','idempotency_id','revision_id','decision_id','event_id',
               'job_id','outbox_id','delivery_id','audit_id','trace_id'
             ]::text[] <> '{}'::jsonb
             OR (SELECT pg_catalog.count(*)
                 FROM pg_catalog.jsonb_object_keys(p_request)) <> 15
             OR p_request->>'schema_version' <> 'api-accept-approval-decision.v1'
             OR p_request->>'actor_id' IS DISTINCT FROM v_principal_id
             OR p_decision NOT IN ('approve','edit_and_approve','reject','manual_takeover')
             OR coalesce(p_approval_id,'') = ''
             OR coalesce(p_request->>'idempotency_key','') = ''
             OR (p_decision<>'approve'
                 AND coalesce(p_request->>'reason','') = '')
             OR pg_catalog.jsonb_typeof(p_request->'edited_payload') <> 'object' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='api_accept_approval_decision_invalid';
          END IF;
          IF p_decision='manual_takeover' THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','manual_takeover_public_unsupported'
            );
          END IF;
          IF (p_decision='edit_and_approve') IS DISTINCT FROM
             (p_request->'edited_payload' <> '{}'::jsonb) THEN
            RETURN pg_catalog.jsonb_build_object('error_code','approval_edit_not_allowed');
          END IF;

          SELECT * INTO v_approval FROM public.approval_requests a
          WHERE a.tenant_id=v_tenant_id AND a.id=p_approval_id;
          IF NOT FOUND THEN
            RETURN pg_catalog.jsonb_build_object('error_code','approval_not_found');
          END IF;
          IF NOT EXISTS (
            SELECT 1 FROM public.memberships m
            JOIN public.approver_tenant_scopes s
              ON s.user_id=m.user_id AND s.tenant_id=m.tenant_id
            WHERE m.tenant_id=v_tenant_id AND m.user_id=v_principal_id
              AND m.role='support_approver' AND m.status='active'
          ) THEN
            RETURN pg_catalog.jsonb_build_object('error_code','approver_scope_invalid');
          END IF;

          v_request_hash := pg_catalog.md5(pg_catalog.jsonb_build_object(
            'decision',p_decision,'reason',p_request->>'reason',
            'approver_note',p_request->>'approver_note',
            'edited_payload',p_request->'edited_payload'
          )::text);
          INSERT INTO public.idempotency_requests(
            id,tenant_id,principal_id,route,idempotency_key,request_hash,status,
            resource_ids,response_snapshot,completed_at,retention_class,
            created_at,updated_at
          ) VALUES (
            p_request->>'idempotency_id',v_tenant_id,v_principal_id,v_route,
            p_request->>'idempotency_key',v_request_hash,'accepted','{}'::jsonb,
            '{}'::jsonb,NULL,'protected_action',v_accepted_at,v_accepted_at
          ) ON CONFLICT ON CONSTRAINT uq_idempotency_request_scope
            DO NOTHING;
          GET DIAGNOSTICS v_inserted=ROW_COUNT;
          v_claimed:=v_inserted=1;
          SELECT * INTO v_existing FROM public.idempotency_requests i
          WHERE i.tenant_id=v_tenant_id AND i.principal_id=v_principal_id
            AND i.route=v_route AND i.idempotency_key=p_request->>'idempotency_key'
          FOR UPDATE;
          IF v_existing.request_hash <> v_request_hash THEN
            RETURN pg_catalog.jsonb_build_object('error_code','idempotency_conflict');
          END IF;
          IF NOT v_claimed THEN
            IF v_existing.response_snapshot::jsonb <> '{}'::jsonb THEN
              RETURN v_existing.response_snapshot::jsonb
                || pg_catalog.jsonb_build_object('reused',true);
            END IF;
            RAISE EXCEPTION USING ERRCODE='40001',
              MESSAGE='idempotency_claim_incomplete';
          END IF;

          SELECT * INTO v_ticket FROM public.support_tickets t
          WHERE t.tenant_id=v_tenant_id AND t.id=v_approval.ticket_id
          FOR UPDATE;
          SELECT * INTO v_approval FROM public.approval_requests a
          WHERE a.tenant_id=v_tenant_id AND a.id=p_approval_id
            AND a.ticket_id=v_ticket.id
          FOR UPDATE;
          IF NOT FOUND THEN
            DELETE FROM public.idempotency_requests
            WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
              AND route=v_route
              AND idempotency_key=p_request->>'idempotency_key'
              AND id=p_request->>'idempotency_id' AND v_claimed;
            RETURN pg_catalog.jsonb_build_object('error_code','approval_not_found');
          END IF;
          SELECT * INTO v_proposal FROM public.proposal_records p
          WHERE p.tenant_id=v_tenant_id AND p.id=v_approval.proposal_id
          FOR UPDATE;
          SELECT * INTO v_run FROM public.agent_runs r
          WHERE r.tenant_id=v_tenant_id AND r.id=v_approval.run_id
          FOR UPDATE;
          IF v_run.turn_id IS NOT NULL THEN
            SELECT * INTO v_turn FROM public.conversation_turns t
            WHERE t.tenant_id=v_tenant_id AND t.id=v_run.turn_id
            FOR UPDATE;
          END IF;
          SELECT * INTO v_marker FROM public.checkpoint_commit_markers m
          WHERE m.tenant_id=v_tenant_id AND m.id=v_approval.marker_id;
          SELECT * INTO v_human FROM public.human_decisions h
          WHERE h.tenant_id=v_tenant_id AND h.approval_id=p_approval_id
          FOR UPDATE;
          IF FOUND THEN
            SELECT * INTO v_existing_job FROM public.runtime_jobs j
            WHERE j.tenant_id=v_tenant_id AND j.approval_id=p_approval_id
            FOR UPDATE;
            IF (
                 p_decision IN ('approve','edit_and_approve')
                 AND v_existing_job.id IS NULL
               ) OR v_human.decision <> p_decision THEN
              DELETE FROM public.idempotency_requests
              WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
                AND route=v_route
                AND idempotency_key=p_request->>'idempotency_key'
                AND id=p_request->>'idempotency_id' AND v_claimed;
              RETURN pg_catalog.jsonb_build_object(
                'error_code','approval_decision_conflict'
              );
            END IF;
            UPDATE public.idempotency_requests SET
              resource_ids=pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
                'approval_id',p_approval_id,'ticket_id',v_approval.ticket_id,
                'run_id',v_approval.run_id,
                'job_id',CASE WHEN p_decision IN ('approve','edit_and_approve')
                  THEN v_existing_job.id END)),
              response_snapshot=pg_catalog.jsonb_build_object(
                'schema_version','decision-accepted.v1',
                'approval_id',p_approval_id,'decision',p_decision,
                'ticket_id',v_approval.ticket_id,'run_id',v_approval.run_id,
                'job_id',CASE WHEN p_decision IN ('approve','edit_and_approve')
                  THEN v_existing_job.id END,
                'accepted_at',public.supportguard_internal_format_utc_timestamp(v_human.created_at),
                'status','decision_accepted',
                'status_url',CASE WHEN p_decision IN ('approve','edit_and_approve') THEN '/api/runs/'||v_approval.run_id END,
                'events_url','/api/tickets/'||v_approval.ticket_id||'/events/stream',
                'reused',false),
              completed_at=v_human.created_at,updated_at=v_accepted_at
            WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
              AND route=v_route
              AND idempotency_key=p_request->>'idempotency_key'
              AND id=p_request->>'idempotency_id';
            RETURN pg_catalog.jsonb_build_object(
              'schema_version','decision-accepted.v1',
                  'approval_id',p_approval_id,'decision',p_decision,
                  'ticket_id',v_approval.ticket_id,'run_id',v_approval.run_id,
                  'job_id',CASE WHEN p_decision IN ('approve','edit_and_approve')
                    THEN v_existing_job.id END,
                  'accepted_at',public.supportguard_internal_format_utc_timestamp(v_human.created_at),
                  'status','decision_accepted',
                  'status_url',CASE WHEN p_decision IN ('approve','edit_and_approve') THEN '/api/runs/'||v_approval.run_id END,
                  'events_url','/api/tickets/'||v_approval.ticket_id||'/events/stream','reused',false,'reused',true
            );
          END IF;

          IF v_approval.status <> 'pending' OR v_run.id IS NULL OR v_ticket.id IS NULL
             OR v_proposal.id IS NULL OR v_marker.id IS NULL
             OR v_proposal.status <> 'bound' OR v_marker.status <> 'finalized'
             OR v_run.status <> 'interrupted'
             OR v_run.canonical_checkpoint_ns IS DISTINCT FROM
                  v_approval.canonical_checkpoint_ns
             OR v_run.canonical_checkpoint_id IS DISTINCT FROM v_approval.checkpoint_id
             OR v_run.canonical_checkpoint_hash IS DISTINCT FROM
                  v_approval.canonical_checkpoint_hash
             OR v_marker.final_checkpoint_id IS DISTINCT FROM v_approval.checkpoint_id
             OR v_marker.final_checkpoint_hash IS DISTINCT FROM
                  v_approval.canonical_checkpoint_hash
             OR v_run.canonical_checkpoint_version IS DISTINCT FROM
                  v_approval.checkpoint_version
             OR v_marker.final_checkpoint_version IS DISTINCT FROM
                  v_approval.checkpoint_version
             OR v_approval.expected_ticket_sequence IS NULL THEN
            DELETE FROM public.idempotency_requests
            WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
              AND route=v_route
              AND idempotency_key=p_request->>'idempotency_key'
              AND id=p_request->>'idempotency_id' AND v_claimed;
            RETURN pg_catalog.jsonb_build_object(
              'error_code','checkpoint_binding_conflict'
            );
          END IF;
          SELECT * INTO v_revision FROM public.approval_action_revisions r
          WHERE r.tenant_id=v_tenant_id AND r.id=v_approval.selected_revision_id;
          IF NOT FOUND OR v_revision.approval_id<>p_approval_id
             OR v_revision.revision_number IS DISTINCT FROM
                  v_approval.selected_revision_number THEN
            DELETE FROM public.idempotency_requests
            WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
              AND route=v_route
              AND idempotency_key=p_request->>'idempotency_key'
              AND id=p_request->>'idempotency_id' AND v_claimed;
            RETURN pg_catalog.jsonb_build_object(
              'error_code','approval_revision_binding_conflict'
            );
          END IF;

          SELECT * INTO v_parent FROM public.agent_events e
          WHERE e.tenant_id=v_tenant_id AND e.ticket_id=v_ticket.id
          ORDER BY e.ticket_sequence DESC LIMIT 1;
          SELECT * INTO v_frozen FROM public.agent_events e
          WHERE e.tenant_id=v_tenant_id AND e.ticket_id=v_ticket.id
            AND e.id=v_approval.expected_ticket_head_event_id
            AND e.ticket_sequence=v_approval.expected_ticket_sequence
            AND e.event_hash=v_approval.expected_ticket_event_hash;
          SELECT pg_catalog.count(*),pg_catalog.min(ticket_sequence),
                 pg_catalog.max(ticket_sequence)
          INTO v_chain_count,v_chain_min,v_chain_max
          FROM public.agent_events e
          WHERE e.tenant_id=v_tenant_id AND e.ticket_id=v_ticket.id;
          IF v_frozen.id IS NULL
             OR v_ticket.next_event_sequence IS DISTINCT FROM v_parent.ticket_sequence
             OR v_chain_count<>v_parent.ticket_sequence
             OR (v_chain_count>0 AND (v_chain_min<>1 OR v_chain_max<>v_chain_count))
             OR EXISTS (
               SELECT 1 FROM public.agent_events child
               LEFT JOIN public.agent_events parent
                 ON parent.tenant_id=child.tenant_id
                AND parent.ticket_id=child.ticket_id
                AND parent.ticket_sequence=child.ticket_sequence-1
               WHERE child.tenant_id=v_tenant_id AND child.ticket_id=v_ticket.id
                 AND child.ticket_sequence>1
                 AND (child.previous_event_id IS DISTINCT FROM
                        CASE WHEN child.run_id=parent.run_id THEN parent.id ELSE NULL END
                      OR child.parent_event_hash IS DISTINCT FROM parent.event_hash)
             ) THEN
            DELETE FROM public.idempotency_requests
            WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
              AND route=v_route
              AND idempotency_key=p_request->>'idempotency_key'
              AND id=p_request->>'idempotency_id' AND v_claimed;
            RETURN pg_catalog.jsonb_build_object('error_code','event_chain_conflict');
          END IF;
          IF v_run.next_run_sequence IS DISTINCT FROM (
            SELECT coalesce(pg_catalog.max(e.run_sequence),0)
            FROM public.agent_events e
            WHERE e.tenant_id=v_tenant_id AND e.run_id=v_run.id
          ) THEN
            DELETE FROM public.idempotency_requests
            WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
              AND route=v_route
              AND idempotency_key=p_request->>'idempotency_key'
              AND id=p_request->>'idempotency_id' AND v_claimed;
            RETURN pg_catalog.jsonb_build_object(
              'error_code','approval_expected_head_conflict'
            );
          END IF;

          v_action_payload := v_revision.action_payload::jsonb;
          v_action_hash := v_revision.action_hash;
          v_revision_id := v_revision.id;
          v_revision_number := v_revision.revision_number;
          IF p_decision='edit_and_approve' THEN
            IF NOT coalesce(CASE v_approval.action_type
              WHEN 'refund' THEN
                (p_request->'edited_payload') - 'refund_reason'::text = '{}'::jsonb
                AND (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(
                      p_request->'edited_payload'))=1
                AND pg_catalog.jsonb_typeof(
                      p_request#>'{edited_payload,refund_reason}'
                    )='string'
                AND pg_catalog.btrim(coalesce(
                      p_request#>>'{edited_payload,refund_reason}',''
                    ))<>''
                AND v_action_payload - ARRAY[
                  'amount','billing_record_id','business_version','currency',
                  'customer_id','refund_reason'
                ]::text[] = '{}'::jsonb
                AND (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(
                      v_action_payload))=6
              WHEN 'entitlement_change' THEN
                (p_request->'edited_payload') - 'target_concurrency'::text = '{}'::jsonb
                AND (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(
                      p_request->'edited_payload'))=1
                AND CASE WHEN pg_catalog.jsonb_typeof(
                      p_request#>'{edited_payload,target_concurrency}'
                    )='number' THEN
                      (p_request#>>'{edited_payload,target_concurrency}')::numeric
                        BETWEEN 1 AND 1000000
                      AND (p_request#>>'{edited_payload,target_concurrency}')::numeric
                        = pg_catalog.trunc(
                          (p_request#>>'{edited_payload,target_concurrency}')::numeric
                        )
                    ELSE false END
                AND v_action_payload->>'change_type'='quota_change'
                AND pg_catalog.jsonb_typeof(v_action_payload->'target')='object'
                AND (v_action_payload->'target') - 'concurrency_limit'::text
                      = '{}'::jsonb
                AND (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(
                      v_action_payload->'target'))=1
              ELSE false
            END,false) THEN
              DELETE FROM public.idempotency_requests
              WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
                AND route=v_route
                AND idempotency_key=p_request->>'idempotency_key'
                AND id=p_request->>'idempotency_id' AND v_claimed;
              RETURN pg_catalog.jsonb_build_object(
                'error_code','approval_edit_not_allowed'
              );
            END IF;
            IF v_approval.action_type='refund' THEN
              v_action_payload := pg_catalog.jsonb_set(
                v_action_payload,'{refund_reason}',
                pg_catalog.to_jsonb(pg_catalog.btrim(
                  p_request#>>'{edited_payload,refund_reason}'
                )),false
              );
            ELSE
              v_action_payload := pg_catalog.jsonb_set(
                v_action_payload,'{target,concurrency_limit}',
                p_request#>'{edited_payload,target_concurrency}',false
              );
            END IF;
            v_action_hash := pg_catalog.encode(pg_catalog.sha256(
              pg_catalog.convert_to(
                public.supportguard_canonical_jsonb(v_action_payload),'UTF8'
              )
            ),'hex');
            v_revision_id := p_request->>'revision_id';
            v_revision_number := v_revision.revision_number+1;
            INSERT INTO public.approval_action_revisions(
              id,tenant_id,approval_id,proposal_id,snapshot_id,revision_number,
              action_payload,action_hash,resource_version,created_by_ref,
              revision_reason,created_at,updated_at
            ) VALUES (
              v_revision_id,v_tenant_id,p_approval_id,v_approval.proposal_id,
              v_revision.snapshot_id,v_revision_number,v_action_payload,v_action_hash,
              v_revision.resource_version,v_principal_id,'edit_and_approve',
              v_accepted_at,v_accepted_at
            );
          END IF;

          v_status := CASE p_decision
            WHEN 'approve' THEN 'approved'
            WHEN 'edit_and_approve' THEN 'approved'
            WHEN 'reject' THEN 'rejected'
            ELSE 'manual_takeover' END;
          v_decision_hash := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            '{"action_hash":'||pg_catalog.to_jsonb(v_action_hash)::text
            ||',"actor_id":'||pg_catalog.to_jsonb(v_principal_id)::text
            ||',"approval_id":'||pg_catalog.to_jsonb(p_approval_id)::text
            ||',"approver_note":'||pg_catalog.to_jsonb(p_request->>'approver_note')::text
            ||',"decision":'||pg_catalog.to_jsonb(p_decision)::text
            ||',"reason":'||pg_catalog.to_jsonb(p_request->>'reason')::text
            ||',"revision_id":'||pg_catalog.to_jsonb(v_revision_id)::text
            ||',"revision_number":'||v_revision_number::text||'}','UTF8'
          )),'hex');
          v_payload := pg_catalog.jsonb_build_object(
            'approval_id',p_approval_id,'human_decision_id',p_request->>'decision_id',
            'decision',p_decision,'decision_hash',v_decision_hash,
            'action_hash',v_action_hash,'revision_id',v_revision_id,
            'revision_number',v_revision_number
          );
          v_payload_canonical := '{"action_hash":'||pg_catalog.to_jsonb(v_action_hash)::text
            ||',"approval_id":'||pg_catalog.to_jsonb(p_approval_id)::text
            ||',"decision":'||pg_catalog.to_jsonb(p_decision)::text
            ||',"decision_hash":'||pg_catalog.to_jsonb(v_decision_hash)::text
            ||',"human_decision_id":'
            ||pg_catalog.to_jsonb(p_request->>'decision_id')::text
            ||',"revision_id":'||pg_catalog.to_jsonb(v_revision_id)::text
            ||',"revision_number":'||v_revision_number::text||'}';
          v_payload_hash := pg_catalog.encode(pg_catalog.sha256(
            pg_catalog.convert_to(v_payload_canonical,'UTF8')),'hex');
          v_ticket_sequence := v_ticket.next_event_sequence+1;
          v_run_sequence := v_run.next_run_sequence+1;
          v_created_at_text := pg_catalog.to_char(
            v_accepted_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US'
          )||'+00:00';
          v_envelope := '{"aggregate_id":'||pg_catalog.to_jsonb(v_ticket.id)::text
            ||',"aggregate_type":"SupportTicket"'
            ||',"canonicalization_version":"json-sort-keys.v1"'
            ||',"causation_id":'||coalesce(pg_catalog.to_jsonb(v_parent.id)::text,'null')
            ||',"correlation_id":'||pg_catalog.to_jsonb(v_run.id)::text
            ||',"created_at":'||pg_catalog.to_jsonb(v_created_at_text)::text
            ||',"customer_id":'||pg_catalog.to_jsonb(v_ticket.customer_id)::text
            ||',"delivery_generation":null'
            ||',"event_id":'||pg_catalog.to_jsonb(p_request->>'event_id')::text
            ||',"event_schema_version":"support-ticket-event.v1"'
            ||',"event_type":"human_decision_accepted"'
            ||',"fencing_token":null'
            ||',"idempotency_id":'
            ||pg_catalog.to_jsonb(p_request->>'idempotency_key')::text
            ||',"job_id":null'
            ||',"payload_hash":'||pg_catalog.to_jsonb(v_payload_hash)::text
            ||',"previous_event_id":'
            ||coalesce(pg_catalog.to_jsonb(CASE WHEN v_parent.run_id=v_run.id THEN v_parent.id ELSE NULL END)::text,'null')
            ||',"run_id":'||pg_catalog.to_jsonb(v_run.id)::text
            ||',"run_sequence":'||v_run_sequence::text
            ||',"status":"completed"'
            ||',"step_index":'||v_run.step_index::text
            ||',"tenant_id":'||pg_catalog.to_jsonb(v_tenant_id)::text
            ||',"ticket_sequence":'||v_ticket_sequence::text
            ||',"tool_call_id":null'
            ||',"tool_round":'||v_run.tool_rounds::text
            ||',"visibility":"approver"}';
          v_event_hash := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            'event-hash.v1'||v_envelope||coalesce(v_parent.event_hash,repeat('0',64)),
            'UTF8')),'hex');

          IF p_decision IN ('approve','edit_and_approve') THEN
            SELECT timing_version,backlog_count_limit,oldest_backlog_seconds
            INTO v_timing_version,v_backlog_limit,v_oldest_limit
            FROM supportguard_control.runtime_timing_snapshots
            WHERE is_active FOR UPDATE;
            IF v_timing_version IS NULL THEN
              DELETE FROM public.idempotency_requests
              WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
                AND route=v_route
                AND idempotency_key=p_request->>'idempotency_key'
                AND id=p_request->>'idempotency_id' AND v_claimed;
              RETURN pg_catalog.jsonb_build_object('error_code','runtime_backpressure');
            END IF;
            SELECT pg_catalog.count(*),coalesce(greatest(pg_catalog.floor(
              extract(epoch FROM v_accepted_at-pg_catalog.min(created_at))
            )::bigint,0::bigint),0::bigint)
            INTO v_active_count,v_oldest_age FROM public.runtime_jobs
            WHERE status IN ('queued','retry_wait','leased');
            IF v_active_count+1>v_backlog_limit OR v_oldest_age>=v_oldest_limit THEN
              DELETE FROM public.idempotency_requests
              WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
                AND route=v_route
                AND idempotency_key=p_request->>'idempotency_key'
                AND id=p_request->>'idempotency_id' AND v_claimed;
              RETURN pg_catalog.jsonb_build_object('error_code','runtime_backpressure');
            END IF;
          END IF;
          UPDATE public.approval_requests SET
            status=v_status,decided_at=v_accepted_at,
            selected_revision_id=v_revision_id,selected_revision_number=v_revision_number,
            status_version=status_version+1,updated_at=v_accepted_at
          WHERE tenant_id=v_tenant_id AND id=p_approval_id;
          UPDATE public.support_tickets SET
            status=CASE WHEN p_decision='reject' THEN 'rejected' ELSE 'queued' END,
            version=version+1,next_event_sequence=v_ticket_sequence,
            updated_at=v_accepted_at
          WHERE tenant_id=v_tenant_id AND id=v_ticket.id;
          UPDATE public.agent_runs SET
            status=CASE WHEN p_decision='reject' THEN 'completed' ELSE 'queued' END,
            agent_finish_reason=CASE WHEN p_decision='reject' THEN 'rejected' ELSE agent_finish_reason END,
            completed_at=CASE WHEN p_decision='reject' THEN v_accepted_at ELSE completed_at END,
            active_job_id=CASE WHEN p_decision='reject' THEN NULL ELSE active_job_id END,
            active_fencing_token=CASE WHEN p_decision='reject' THEN NULL ELSE active_fencing_token END,
            status_version=status_version+1,
            next_run_sequence=v_run_sequence,updated_at=v_accepted_at
          WHERE tenant_id=v_tenant_id AND id=v_run.id;
          IF p_decision='reject' THEN
            UPDATE public.proposal_records
            SET status='stale',status_version=status_version+1,updated_at=v_accepted_at
            WHERE tenant_id=v_tenant_id AND id=v_proposal.id;
            IF v_turn.id IS NOT NULL THEN
              UPDATE public.conversation_turns
              SET activity_state='completed',result_state='refused',
                  completed_at=v_accepted_at,updated_at=v_accepted_at
              WHERE tenant_id=v_tenant_id AND id=v_turn.id;
            END IF;
            INSERT INTO public.ticket_messages(
              id,tenant_id,ticket_id,turn_id,run_id,approval_id,message_kind,
              publication_key,role,content,source_refs,created_at,updated_at
            ) VALUES (
              'message_'||pg_catalog.md5('approval:'||v_tenant_id||':'||p_approval_id||':rejected'),
              v_tenant_id,v_ticket.id,v_run.turn_id,v_run.id,
              p_approval_id,'action_update','approval:'||p_approval_id||':rejected',
              'action','审批者已拒绝该操作申请；系统未执行任何业务动作。','[]'::jsonb,
              v_accepted_at,v_accepted_at
            ) ON CONFLICT (tenant_id,publication_key) DO NOTHING;
          END IF;
          INSERT INTO public.agent_events(
            id,tenant_id,run_id,ticket_id,customer_id,sequence,ticket_sequence,
            run_sequence,step_index,tool_round,event_type,status,visibility,payload,
            payload_hash,previous_event_id,parent_event_hash,event_hash,
            event_schema_version,canonicalization_version,event_hash_schema_version,
            correlation_id,causation_id,idempotency_id,created_at
          ) VALUES (
            p_request->>'event_id',v_tenant_id,v_run.id,v_ticket.id,v_ticket.customer_id,
            v_run_sequence,v_ticket_sequence,v_run_sequence,v_run.step_index,v_run.tool_rounds,
            'human_decision_accepted','completed','approver',v_payload,v_payload_hash,
            CASE WHEN v_parent.run_id=v_run.id THEN v_parent.id ELSE NULL END,coalesce(v_parent.event_hash,repeat('0',64)),v_event_hash,
            'support-ticket-event.v1','json-sort-keys.v1','event-hash.v1',v_run.id,
            v_parent.id,p_request->>'idempotency_key',v_accepted_at
          );
          INSERT INTO public.human_decisions(
            id,tenant_id,approval_id,action_revision_id,actor_id,decision,reason,
            action_hash,decision_hash,canonical_event_id,canonical_event_hash,
            audit_metadata,created_at,updated_at
          ) VALUES (
            p_request->>'decision_id',v_tenant_id,p_approval_id,v_revision_id,
            v_principal_id,p_decision,p_request->>'reason',v_action_hash,v_decision_hash,
            p_request->>'event_id',v_event_hash,
            pg_catalog.jsonb_build_object('approver_note',p_request->>'approver_note'),
            v_accepted_at,v_accepted_at
          );
          IF p_decision IN ('approve','edit_and_approve') THEN
            INSERT INTO public.runtime_jobs(
              id,tenant_id,run_id,approval_id,kind,status,attempt,available_at,
              fencing_token,timing_version,status_version,created_at,updated_at
            ) VALUES (
              p_request->>'job_id',v_tenant_id,v_run.id,p_approval_id,'approval_resume',
              'queued',0,v_accepted_at,0,v_timing_version,1,v_accepted_at,v_accepted_at
            );
            INSERT INTO public.outbox_events(
              id,delivery_id,tenant_id,job_id,run_id,delivery_generation,event_type,
              schema_version,payload,available_at,publish_attempts,delivery_state_version,
              created_at,updated_at
            ) VALUES (
              p_request->>'outbox_id',p_request->>'delivery_id',v_tenant_id,
              p_request->>'job_id',v_run.id,1,'runtime_job_available','runtime-job.v1',
              pg_catalog.jsonb_build_object('traceparent',p_request->>'trace_id'),
              v_accepted_at,0,1,v_accepted_at,v_accepted_at
            );
          END IF;
          INSERT INTO public.audit_events(
            id,tenant_id,ticket_id,customer_id,event_type,actor_type,actor_ref,run_id,
            trace_id,payload,created_at
          ) VALUES (
            p_request->>'audit_id',v_tenant_id,v_ticket.id,v_ticket.customer_id,
            'approval_decision_accepted','approver',v_principal_id,v_run.id,
            p_request->>'trace_id',pg_catalog.jsonb_build_object(
              'approval_id',p_approval_id,'decision',p_decision,
              'proposal_id',v_proposal.id,'marker_id',v_marker.id,
              'job_id',CASE WHEN p_decision IN ('approve','edit_and_approve')
                THEN p_request->>'job_id' END,
              'approver_note',p_request->>'approver_note'
            ),v_accepted_at
          );
          UPDATE public.idempotency_requests SET
            resource_ids=pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
              'approval_id',p_approval_id,'ticket_id',v_ticket.id,'run_id',v_run.id,
              'job_id',CASE WHEN p_decision IN ('approve','edit_and_approve')
                THEN p_request->>'job_id' END
            )),response_snapshot=pg_catalog.jsonb_build_object(
              'schema_version','decision-accepted.v1',
              'approval_id',p_approval_id,'decision',p_decision,
              'ticket_id',v_ticket.id,'run_id',v_run.id,
              'job_id',CASE WHEN p_decision IN ('approve','edit_and_approve')
                THEN p_request->>'job_id' END,
              'accepted_at',public.supportguard_internal_format_utc_timestamp(v_accepted_at),
              'status','decision_accepted',
              'status_url',CASE WHEN p_decision IN ('approve','edit_and_approve') THEN '/api/runs/'||v_run.id END,
              'events_url','/api/tickets/'||v_ticket.id||'/events/stream','reused',false
            ),completed_at=v_accepted_at,retention_class='protected_action',
            updated_at=v_accepted_at
          WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
            AND route=v_route AND idempotency_key=p_request->>'idempotency_key';
          IF p_decision='reject' THEN
            PERFORM public.supportguard_internal_activate_next_ticket_turn(
              v_tenant_id,v_ticket.id,NULL
            );
            PERFORM public.supportguard_internal_converge_ticket_status(
              v_tenant_id,v_ticket.id,'rejected'
            );
          END IF;
          RETURN pg_catalog.jsonb_build_object(
            'schema_version','decision-accepted.v1',
              'approval_id',p_approval_id,'decision',p_decision,
              'ticket_id',v_ticket.id,'run_id',v_run.id,
              'job_id',CASE WHEN p_decision IN ('approve','edit_and_approve')
                THEN p_request->>'job_id' END,
              'accepted_at',public.supportguard_internal_format_utc_timestamp(v_accepted_at),
              'status','decision_accepted',
              'status_url',CASE WHEN p_decision IN ('approve','edit_and_approve') THEN '/api/runs/'||v_run.id END,
              'events_url','/api/tickets/'||v_ticket.id||'/events/stream','reused',false,'reused',false
          );
        END
        $$;


ALTER FUNCTION public.supportguard_api_accept_conversation_approval_decision(p_approval_id text, p_decision text, p_request jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_accept_conversation_message(text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_accept_conversation_message(p_ticket_id text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_tenant_id text := current_setting('app.tenant_id',true);
          v_principal_id text := current_setting('app.principal_id',true);
          v_request_hash text;
          v_existing public.idempotency_requests%ROWTYPE;
          v_ticket public.support_tickets%ROWTYPE;
          v_accepted_at timestamptz := pg_catalog.clock_timestamp();
          v_timing_version bigint;
          v_active_count bigint;
          v_oldest_age bigint;
          v_backlog_limit integer;
          v_oldest_limit integer;
          v_route text := 'POST /api/tickets/'||p_ticket_id||'/messages';
          v_inserted bigint;
          v_scheduled boolean;
          v_status text;
        BEGIN
          IF session_user<>'supportguard_api' OR p_request IS NULL
             OR p_request->>'schema_version'<>'api-accept-message.v1'
             OR p_request->>'principal_id' IS DISTINCT FROM v_principal_id
             OR coalesce(p_ticket_id,'')='' OR coalesce(p_request->>'customer_id','')=''
             OR coalesce(p_request->>'idempotency_key','')=''
             OR coalesce(p_request->>'message','')='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='api_accept_message_invalid';
          END IF;
          v_request_hash := pg_catalog.md5(pg_catalog.jsonb_build_object(
            'message',p_request->>'message')::text);
          INSERT INTO public.idempotency_requests(
            id,tenant_id,principal_id,route,idempotency_key,request_hash,status,
            resource_ids,response_snapshot,expires_at,completed_at,retention_class,
            created_at,updated_at
          ) VALUES (
            p_request->>'idempotency_id',v_tenant_id,v_principal_id,v_route,
            p_request->>'idempotency_key',v_request_hash,'accepted',
            '{}'::jsonb,'{}'::jsonb,v_accepted_at+interval '24 hours',NULL,
            'low_risk_non_action',v_accepted_at,v_accepted_at
          ) ON CONFLICT ON CONSTRAINT uq_idempotency_request_scope DO NOTHING;
          GET DIAGNOSTICS v_inserted=ROW_COUNT;
          IF v_inserted=0 THEN
            SELECT * INTO v_existing FROM public.idempotency_requests i
              WHERE i.tenant_id=v_tenant_id AND i.principal_id=v_principal_id
                AND i.route=v_route
                AND i.idempotency_key=p_request->>'idempotency_key'
              FOR UPDATE;
            IF NOT FOUND THEN RAISE EXCEPTION 'idempotency_claim_disappeared'; END IF;
            IF v_existing.request_hash<>v_request_hash THEN
              RETURN pg_catalog.jsonb_build_object('error_code','idempotency_conflict');
            END IF;
            IF v_existing.response_snapshot::jsonb='{}'::jsonb THEN
              RAISE EXCEPTION USING ERRCODE='40001',
                MESSAGE='idempotency_claim_incomplete';
            END IF;
            RETURN v_existing.response_snapshot::jsonb||
              pg_catalog.jsonb_build_object('reused',true);
          END IF;
          SELECT * INTO v_ticket FROM public.support_tickets t
            WHERE t.tenant_id=v_tenant_id AND t.id=p_ticket_id FOR UPDATE;
          IF NOT FOUND OR v_ticket.customer_id<>p_request->>'customer_id' THEN
            DELETE FROM public.idempotency_requests
            WHERE tenant_id=v_tenant_id AND id=p_request->>'idempotency_id';
            RETURN pg_catalog.jsonb_build_object('error_code','ticket_not_found');
          END IF;
          IF v_ticket.lifecycle<>'active' THEN
            DELETE FROM public.idempotency_requests
            WHERE tenant_id=v_tenant_id AND id=p_request->>'idempotency_id';
            RETURN pg_catalog.jsonb_build_object('error_code','conversation_archived');
          END IF;
          v_scheduled := v_ticket.automation_mode='agent';
          v_status := CASE WHEN v_scheduled THEN 'queued' ELSE 'accepted' END;
          IF v_scheduled THEN
            SELECT timing_version,backlog_count_limit,oldest_backlog_seconds
              INTO v_timing_version,v_backlog_limit,v_oldest_limit
              FROM supportguard_control.runtime_timing_snapshots
              WHERE is_active FOR UPDATE;
            IF v_timing_version IS NULL THEN
              DELETE FROM public.idempotency_requests
              WHERE tenant_id=v_tenant_id AND id=p_request->>'idempotency_id';
              RETURN pg_catalog.jsonb_build_object('error_code','runtime_backpressure');
            END IF;
            SELECT pg_catalog.count(*),coalesce(greatest(pg_catalog.floor(
              extract(epoch FROM v_accepted_at-pg_catalog.min(created_at))
            )::bigint,0::bigint),0::bigint)
              INTO v_active_count,v_oldest_age
              FROM public.runtime_jobs
              WHERE status IN ('queued','retry_wait','leased');
            IF v_active_count+1>v_backlog_limit OR v_oldest_age>v_oldest_limit THEN
              DELETE FROM public.idempotency_requests
              WHERE tenant_id=v_tenant_id AND id=p_request->>'idempotency_id';
              RETURN pg_catalog.jsonb_build_object('error_code','runtime_backpressure');
            END IF;
          END IF;
          UPDATE public.idempotency_requests SET
            resource_ids=pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
              'ticket_id',p_ticket_id,
              'run_id',CASE WHEN v_scheduled THEN p_request->>'run_id' END,
              'job_id',CASE WHEN v_scheduled THEN p_request->>'job_id' END)),
            response_snapshot=pg_catalog.jsonb_build_object(
              'schema_version','command-accepted.v1','ticket_id',p_ticket_id,
              'run_id',CASE WHEN v_scheduled THEN p_request->>'run_id' END,
              'job_id',CASE WHEN v_scheduled THEN p_request->>'job_id' END,
              'accepted_at',public.supportguard_internal_format_utc_timestamp(v_accepted_at),
              'status',v_status,
              'status_url',CASE WHEN v_scheduled THEN '/api/runs/'||(p_request->>'run_id') END,
              'events_url','/api/tickets/'||p_ticket_id||'/events/stream',
              'reused',false),
            completed_at=v_accepted_at,updated_at=v_accepted_at
          WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
            AND route=v_route AND idempotency_key=p_request->>'idempotency_key'
            AND id=p_request->>'idempotency_id';
          IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='40001',
              MESSAGE='idempotency_claim_lost';
          END IF;
          INSERT INTO public.ticket_messages(
            id,tenant_id,ticket_id,role,message_kind,content,source_refs,created_at,updated_at
          ) VALUES (p_request->>'message_id',v_tenant_id,p_ticket_id,'user','customer',
            p_request->>'message','[]'::jsonb,v_accepted_at,v_accepted_at);
          UPDATE public.conversation_turns SET model=p_request->>'model',
            provider_mode=p_request->>'provider_mode',tool_call_mode=p_request->>'tool_call_mode',
            context_version=p_request->>'context_version'
            WHERE tenant_id=v_tenant_id AND customer_message_id=p_request->>'message_id';
          IF v_scheduled THEN
            UPDATE public.support_tickets SET status='queued',version=version+1,
              title=CASE WHEN p_request->>'conversation_title' IS NOT NULL
                AND pg_catalog.char_length(p_request->>'conversation_title') BETWEEN 1 AND 80
                AND pg_catalog.lower(pg_catalog.btrim(coalesce(title,''),
                  E' \t\n\r.,!?;:''"，。！？；：、~～·')) IN (
                  'hello','hello there','hi','hey','good morning',
                  'good afternoon','good evening','你好','您好','嗨','哈喽',
                  '早上好','下午好','晚上好'
                ) THEN p_request->>'conversation_title' ELSE title END,
              updated_at=v_accepted_at WHERE tenant_id=v_tenant_id AND id=p_ticket_id;
            INSERT INTO public.agent_runs(
              id,tenant_id,ticket_id,customer_id,message_id,status,checkpoint_stage,
              status_version,next_run_sequence,canonical_checkpoint_version,step_index,
              tool_rounds,tool_attempts,llm_calls,model,provider_mode,tool_call_mode,
              prompt_version,schema_version,context_version,created_at,updated_at
            ) VALUES (p_request->>'run_id',v_tenant_id,p_ticket_id,p_request->>'customer_id',
              p_request->>'message_id','queued','request_created',1,0,0,0,0,0,0,
              p_request->>'model',p_request->>'provider_mode',p_request->>'tool_call_mode',
              p_request->>'prompt_version',p_request->>'agent_schema_version',
              p_request->>'context_version',v_accepted_at,v_accepted_at);
            INSERT INTO public.runtime_jobs(
              id,tenant_id,run_id,kind,status,attempt,available_at,fencing_token,
              timing_version,status_version,created_at,updated_at
            ) VALUES (p_request->>'job_id',v_tenant_id,p_request->>'run_id','agent_start',
              'queued',0,v_accepted_at,0,v_timing_version,1,v_accepted_at,v_accepted_at);
            INSERT INTO public.outbox_events(
              id,delivery_id,tenant_id,job_id,run_id,delivery_generation,event_type,
              schema_version,payload,available_at,publish_attempts,delivery_state_version,
              created_at,updated_at
            ) VALUES (p_request->>'outbox_id',p_request->>'delivery_id',v_tenant_id,
              p_request->>'job_id',p_request->>'run_id',1,'runtime_job_available',
              'runtime-job.v1',pg_catalog.jsonb_build_object('traceparent',p_request->>'trace_id'),
              v_accepted_at,0,1,v_accepted_at,v_accepted_at);
          ELSE
            UPDATE public.support_tickets SET version=version+1,
              title=CASE WHEN p_request->>'conversation_title' IS NOT NULL
                AND pg_catalog.char_length(p_request->>'conversation_title') BETWEEN 1 AND 80
                AND pg_catalog.lower(pg_catalog.btrim(coalesce(title,''),
                  E' \t\n\r.,!?;:''"，。！？；：、~～·')) IN (
                  'hello','hello there','hi','hey','good morning',
                  'good afternoon','good evening','你好','您好','嗨','哈喽',
                  '早上好','下午好','晚上好'
                ) THEN p_request->>'conversation_title' ELSE title END,updated_at=v_accepted_at
              WHERE tenant_id=v_tenant_id AND id=p_ticket_id;
          END IF;
          INSERT INTO public.audit_events(
            id,tenant_id,ticket_id,customer_id,event_type,actor_type,actor_ref,run_id,
            trace_id,payload,created_at
          ) VALUES (p_request->>'audit_id',v_tenant_id,p_ticket_id,p_request->>'customer_id',
            'conversation_message_accepted','customer',v_principal_id,
            CASE WHEN v_scheduled THEN p_request->>'run_id' END,p_request->>'trace_id',
            pg_catalog.jsonb_build_object('scheduled',v_scheduled,'route',v_route),v_accepted_at);
          RETURN pg_catalog.jsonb_build_object(
            'schema_version','command-accepted.v1','ticket_id',p_ticket_id,
            'run_id',CASE WHEN v_scheduled THEN p_request->>'run_id' END,
            'job_id',CASE WHEN v_scheduled THEN p_request->>'job_id' END,
            'accepted_at',public.supportguard_internal_format_utc_timestamp(v_accepted_at),
            'status',v_status,
            'status_url',CASE WHEN v_scheduled THEN '/api/runs/'||(p_request->>'run_id') END,
            'events_url','/api/tickets/'||p_ticket_id||'/events/stream',
            'reused',false);
        END $$;


ALTER FUNCTION public.supportguard_api_accept_conversation_message(p_ticket_id text, p_request jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_accept_message(text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_accept_message(p_ticket_id text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_tenant_id text := current_setting('app.tenant_id', true);
          v_principal_id text := current_setting('app.principal_id', true);
          v_request_hash text;
          v_existing public.idempotency_requests%ROWTYPE;
          v_ticket public.support_tickets%ROWTYPE;
          v_accepted_at timestamptz := pg_catalog.clock_timestamp();
          v_timing_version bigint;
          v_route text := 'POST /api/tickets/' || p_ticket_id || '/messages';
          v_inserted bigint;
          v_active_count bigint;
          v_oldest_age bigint;
          v_backlog_limit integer;
          v_oldest_limit integer;
        BEGIN
          IF session_user <> 'supportguard_api'
             OR p_request IS NULL
             OR p_request - ARRAY[
               'schema_version','customer_id','principal_id','idempotency_key','message',
               'trace_id','idempotency_id','message_id','run_id','job_id','outbox_id',
               'delivery_id','audit_id','model','provider_mode','tool_call_mode',
               'prompt_version','agent_schema_version','context_version'
             ]::text[] <> '{}'::jsonb
             OR (SELECT pg_catalog.count(*)
                 FROM pg_catalog.jsonb_object_keys(p_request)) <> 19
             OR p_request->>'schema_version' <> 'api-accept-message.v1'
             OR p_request->>'principal_id' IS DISTINCT FROM v_principal_id
             OR coalesce(p_ticket_id,'') = ''
             OR coalesce(p_request->>'customer_id','') = ''
             OR coalesce(p_request->>'idempotency_key','') = ''
             OR coalesce(p_request->>'message','') = '' THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='api_accept_message_invalid';
          END IF;

          SELECT * INTO v_ticket FROM public.support_tickets t
          WHERE t.tenant_id=v_tenant_id AND t.id=p_ticket_id FOR UPDATE;
          IF NOT FOUND OR v_ticket.customer_id <> p_request->>'customer_id' THEN
            RETURN pg_catalog.jsonb_build_object('error_code','ticket_not_found');
          END IF;

          v_request_hash := pg_catalog.md5(
            pg_catalog.jsonb_build_object('message',p_request->>'message')::text
          );
          SELECT * INTO v_existing FROM public.idempotency_requests i
          WHERE i.tenant_id=v_tenant_id AND i.principal_id=v_principal_id
            AND i.route=v_route AND i.idempotency_key=p_request->>'idempotency_key'
          FOR UPDATE;
          IF FOUND THEN
            IF v_existing.request_hash <> v_request_hash THEN
              RETURN pg_catalog.jsonb_build_object('error_code','idempotency_conflict');
            END IF;
            RETURN v_existing.response_snapshot::jsonb
              || pg_catalog.jsonb_build_object('reused',true);
          END IF;
          IF v_ticket.status NOT IN ('open','needs_clarification','resolved','manual_takeover') THEN
            RETURN pg_catalog.jsonb_build_object('error_code','ticket_state_conflict');
          END IF;

          SELECT timing_version,backlog_count_limit,oldest_backlog_seconds
          INTO v_timing_version,v_backlog_limit,v_oldest_limit
          FROM supportguard_control.runtime_timing_snapshots
          WHERE is_active FOR UPDATE;
          IF v_timing_version IS NULL THEN
            RETURN pg_catalog.jsonb_build_object('error_code','runtime_backpressure');
          END IF;
          SELECT pg_catalog.count(*),coalesce(greatest(pg_catalog.floor(
            extract(epoch FROM v_accepted_at-pg_catalog.min(created_at))
          )::bigint,0::bigint),0::bigint)
          INTO v_active_count,v_oldest_age FROM public.runtime_jobs
          WHERE status IN ('queued','retry_wait','leased');
          IF v_active_count+1>v_backlog_limit OR v_oldest_age>=v_oldest_limit THEN
            RETURN pg_catalog.jsonb_build_object('error_code','runtime_backpressure');
          END IF;

          INSERT INTO public.idempotency_requests(
            id,tenant_id,principal_id,route,idempotency_key,request_hash,status,
            resource_ids,response_snapshot,expires_at,completed_at,retention_class,
            created_at,updated_at
          ) VALUES (
            p_request->>'idempotency_id',v_tenant_id,v_principal_id,v_route,
            p_request->>'idempotency_key',v_request_hash,'accepted',
            pg_catalog.jsonb_build_object(
              'ticket_id',p_ticket_id,'run_id',p_request->>'run_id',
              'job_id',p_request->>'job_id'
            ),
            pg_catalog.jsonb_build_object(
              'schema_version','command-accepted.v1',
              'ticket_id',p_ticket_id,'run_id',p_request->>'run_id',
              'job_id',p_request->>'job_id','accepted_at',public.supportguard_internal_format_utc_timestamp(v_accepted_at),
              'status','queued',
              'status_url','/api/runs/'||(p_request->>'run_id'),
              'events_url','/api/tickets/'||p_ticket_id||'/events/stream','reused',false
            ),
            v_accepted_at + interval '24 hours',v_accepted_at,'low_risk_non_action',
            v_accepted_at,v_accepted_at
          ) ON CONFLICT ON CONSTRAINT uq_idempotency_request_scope DO NOTHING;
          GET DIAGNOSTICS v_inserted = ROW_COUNT;
          IF v_inserted = 0 THEN
            SELECT * INTO v_existing FROM public.idempotency_requests i
            WHERE i.tenant_id=v_tenant_id AND i.principal_id=v_principal_id
              AND i.route=v_route AND i.idempotency_key=p_request->>'idempotency_key'
            FOR UPDATE;
            IF NOT FOUND THEN
              RAISE EXCEPTION 'idempotency_claim_disappeared';
            END IF;
            IF v_existing.request_hash <> v_request_hash THEN
              RETURN pg_catalog.jsonb_build_object('error_code','idempotency_conflict');
            END IF;
            RETURN v_existing.response_snapshot::jsonb
              || pg_catalog.jsonb_build_object('reused',true);
          END IF;

          INSERT INTO public.ticket_messages(
            id,tenant_id,ticket_id,role,content,source_refs,created_at,updated_at
          ) VALUES (
            p_request->>'message_id',v_tenant_id,p_ticket_id,'user',
            p_request->>'message','[]'::jsonb,v_accepted_at,v_accepted_at
          );
          UPDATE public.support_tickets
          SET status='queued',version=version+1,updated_at=v_accepted_at
          WHERE tenant_id=v_tenant_id AND id=p_ticket_id;
          INSERT INTO public.agent_runs(
            id,tenant_id,ticket_id,customer_id,message_id,status,checkpoint_stage,
            status_version,next_run_sequence,canonical_checkpoint_version,step_index,
            tool_rounds,tool_attempts,llm_calls,model,provider_mode,tool_call_mode,
            prompt_version,schema_version,context_version,created_at,updated_at
          ) VALUES (
            p_request->>'run_id',v_tenant_id,p_ticket_id,p_request->>'customer_id',
            p_request->>'message_id','queued','request_created',1,0,0,0,0,0,0,
            p_request->>'model',p_request->>'provider_mode',p_request->>'tool_call_mode',
            p_request->>'prompt_version',p_request->>'agent_schema_version',
            p_request->>'context_version',v_accepted_at,v_accepted_at
          );
          INSERT INTO public.runtime_jobs(
            id,tenant_id,run_id,kind,status,attempt,available_at,fencing_token,
            timing_version,status_version,created_at,updated_at
          ) VALUES (
            p_request->>'job_id',v_tenant_id,p_request->>'run_id','agent_start','queued',
            0,v_accepted_at,0,v_timing_version,1,v_accepted_at,v_accepted_at
          );
          INSERT INTO public.outbox_events(
            id,delivery_id,tenant_id,job_id,run_id,delivery_generation,event_type,
            schema_version,payload,available_at,publish_attempts,delivery_state_version,
            created_at,updated_at
          ) VALUES (
            p_request->>'outbox_id',p_request->>'delivery_id',v_tenant_id,
            p_request->>'job_id',p_request->>'run_id',1,'runtime_job_available',
            'runtime-job.v1',pg_catalog.jsonb_build_object('traceparent',p_request->>'trace_id'),
            v_accepted_at,0,1,v_accepted_at,v_accepted_at
          );
          INSERT INTO public.audit_events(
            id,tenant_id,ticket_id,customer_id,event_type,actor_type,actor_ref,run_id,
            trace_id,payload,created_at
          ) VALUES (
            p_request->>'audit_id',v_tenant_id,p_ticket_id,p_request->>'customer_id',
            'command_accepted','customer',v_principal_id,p_request->>'run_id',
            p_request->>'trace_id',
            pg_catalog.jsonb_build_object('job_id',p_request->>'job_id','route',v_route),
            v_accepted_at
          );
          RETURN pg_catalog.jsonb_build_object(
            'schema_version','command-accepted.v1',
              'ticket_id',p_ticket_id,'run_id',p_request->>'run_id',
              'job_id',p_request->>'job_id','accepted_at',public.supportguard_internal_format_utc_timestamp(v_accepted_at),
              'status','queued',
              'status_url','/api/runs/'||(p_request->>'run_id'),
              'events_url','/api/tickets/'||p_ticket_id||'/events/stream','reused',false,'reused',false
          );
        END
        $$;


ALTER FUNCTION public.supportguard_api_accept_message(p_ticket_id text, p_request jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_accept_ticket(jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_accept_ticket(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_tenant_id text := current_setting('app.tenant_id', true);
          v_principal_id text := current_setting('app.principal_id', true);
          v_request_hash text;
          v_existing public.idempotency_requests%ROWTYPE;
          v_accepted_at timestamptz := pg_catalog.clock_timestamp();
          v_timing_version bigint;
          v_inserted bigint;
          v_active_count bigint;
          v_oldest_age bigint;
          v_backlog_limit integer;
          v_oldest_limit integer;
        BEGIN
          IF session_user <> 'supportguard_api'
             OR p_request IS NULL
             OR p_request - ARRAY[
               'schema_version','customer_id','principal_id','idempotency_key','message',
               'trace_id','idempotency_id','ticket_id','message_id','run_id','job_id',
               'outbox_id','delivery_id','audit_id','model','provider_mode',
               'tool_call_mode','prompt_version','agent_schema_version','context_version'
             ]::text[] <> '{}'::jsonb
             OR (SELECT pg_catalog.count(*)
                 FROM pg_catalog.jsonb_object_keys(p_request)) <> 20
             OR p_request->>'schema_version' <> 'api-accept-ticket.v1'
             OR p_request->>'principal_id' IS DISTINCT FROM v_principal_id
             OR coalesce(p_request->>'customer_id','') = ''
             OR coalesce(p_request->>'idempotency_key','') = ''
             OR coalesce(p_request->>'message','') = '' THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='api_accept_ticket_invalid';
          END IF;

          IF NOT EXISTS (
            SELECT 1 FROM public.customers c
            WHERE c.tenant_id=v_tenant_id AND c.id=p_request->>'customer_id'
              AND c.status='active'
          ) THEN
            RETURN pg_catalog.jsonb_build_object('error_code','customer_not_found');
          END IF;

          v_request_hash := pg_catalog.md5(
            pg_catalog.jsonb_build_object('message',p_request->>'message')::text
          );
          SELECT * INTO v_existing FROM public.idempotency_requests i
          WHERE i.tenant_id=v_tenant_id AND i.principal_id=v_principal_id
            AND i.route='POST /api/tickets'
            AND i.idempotency_key=p_request->>'idempotency_key'
          FOR UPDATE;
          IF FOUND THEN
            IF v_existing.request_hash <> v_request_hash THEN
              RETURN pg_catalog.jsonb_build_object('error_code','idempotency_conflict');
            END IF;
            RETURN v_existing.response_snapshot::jsonb
              || pg_catalog.jsonb_build_object('reused',true);
          END IF;

          SELECT timing_version,backlog_count_limit,oldest_backlog_seconds
          INTO v_timing_version,v_backlog_limit,v_oldest_limit
          FROM supportguard_control.runtime_timing_snapshots
          WHERE is_active FOR UPDATE;
          IF v_timing_version IS NULL THEN
            RETURN pg_catalog.jsonb_build_object('error_code','runtime_backpressure');
          END IF;
          SELECT pg_catalog.count(*),coalesce(greatest(pg_catalog.floor(
            extract(epoch FROM v_accepted_at-pg_catalog.min(created_at))
          )::bigint,0::bigint),0::bigint)
          INTO v_active_count,v_oldest_age FROM public.runtime_jobs
          WHERE status IN ('queued','retry_wait','leased');
          IF v_active_count+1>v_backlog_limit OR v_oldest_age>=v_oldest_limit THEN
            RETURN pg_catalog.jsonb_build_object('error_code','runtime_backpressure');
          END IF;

          INSERT INTO public.idempotency_requests(
            id,tenant_id,principal_id,route,idempotency_key,request_hash,status,
            resource_ids,response_snapshot,expires_at,completed_at,retention_class,
            created_at,updated_at
          ) VALUES (
            p_request->>'idempotency_id',v_tenant_id,v_principal_id,'POST /api/tickets',
            p_request->>'idempotency_key',v_request_hash,'accepted',
            pg_catalog.jsonb_build_object(
              'ticket_id',p_request->>'ticket_id','run_id',p_request->>'run_id',
              'job_id',p_request->>'job_id'
            ),
            pg_catalog.jsonb_build_object(
              'schema_version','command-accepted.v1',
              'ticket_id',p_request->>'ticket_id','run_id',p_request->>'run_id',
              'job_id',p_request->>'job_id','accepted_at',public.supportguard_internal_format_utc_timestamp(v_accepted_at),
              'status','queued',
              'status_url','/api/runs/'||(p_request->>'run_id'),
              'events_url','/api/tickets/'||(p_request->>'ticket_id')||'/events/stream','reused',false
            ),
            v_accepted_at + interval '24 hours',v_accepted_at,'low_risk_non_action',
            v_accepted_at,v_accepted_at
          ) ON CONFLICT ON CONSTRAINT uq_idempotency_request_scope DO NOTHING;
          GET DIAGNOSTICS v_inserted = ROW_COUNT;
          IF v_inserted = 0 THEN
            SELECT * INTO v_existing FROM public.idempotency_requests i
            WHERE i.tenant_id=v_tenant_id AND i.principal_id=v_principal_id
              AND i.route='POST /api/tickets'
              AND i.idempotency_key=p_request->>'idempotency_key'
            FOR UPDATE;
            IF NOT FOUND THEN
              RAISE EXCEPTION 'idempotency_claim_disappeared';
            END IF;
            IF v_existing.request_hash <> v_request_hash THEN
              RETURN pg_catalog.jsonb_build_object('error_code','idempotency_conflict');
            END IF;
            RETURN v_existing.response_snapshot::jsonb
              || pg_catalog.jsonb_build_object('reused',true);
          END IF;
          INSERT INTO public.support_tickets(
            id,tenant_id,customer_id,status,issue_type,risk,version,next_event_sequence,
            created_at,updated_at
          ) VALUES (
            p_request->>'ticket_id',v_tenant_id,p_request->>'customer_id','queued',
            'unknown','low',1,0,v_accepted_at,v_accepted_at
          );
          INSERT INTO public.ticket_messages(
            id,tenant_id,ticket_id,role,content,source_refs,created_at,updated_at
          ) VALUES (
            p_request->>'message_id',v_tenant_id,p_request->>'ticket_id','user',
            p_request->>'message','[]'::jsonb,v_accepted_at,v_accepted_at
          );
          INSERT INTO public.agent_runs(
            id,tenant_id,ticket_id,customer_id,message_id,status,checkpoint_stage,
            status_version,next_run_sequence,canonical_checkpoint_version,step_index,
            tool_rounds,tool_attempts,llm_calls,model,provider_mode,tool_call_mode,
            prompt_version,schema_version,context_version,created_at,updated_at
          ) VALUES (
            p_request->>'run_id',v_tenant_id,p_request->>'ticket_id',
            p_request->>'customer_id',p_request->>'message_id','queued','request_created',
            1,0,0,0,0,0,0,p_request->>'model',p_request->>'provider_mode',
            p_request->>'tool_call_mode',p_request->>'prompt_version',
            p_request->>'agent_schema_version',p_request->>'context_version',
            v_accepted_at,v_accepted_at
          );
          INSERT INTO public.runtime_jobs(
            id,tenant_id,run_id,kind,status,attempt,available_at,fencing_token,
            timing_version,status_version,created_at,updated_at
          ) VALUES (
            p_request->>'job_id',v_tenant_id,p_request->>'run_id','agent_start','queued',
            0,v_accepted_at,0,v_timing_version,1,v_accepted_at,v_accepted_at
          );
          INSERT INTO public.outbox_events(
            id,delivery_id,tenant_id,job_id,run_id,delivery_generation,event_type,
            schema_version,payload,available_at,publish_attempts,delivery_state_version,
            created_at,updated_at
          ) VALUES (
            p_request->>'outbox_id',p_request->>'delivery_id',v_tenant_id,
            p_request->>'job_id',p_request->>'run_id',1,'runtime_job_available',
            'runtime-job.v1',pg_catalog.jsonb_build_object('traceparent',p_request->>'trace_id'),
            v_accepted_at,0,1,v_accepted_at,v_accepted_at
          );
          INSERT INTO public.audit_events(
            id,tenant_id,ticket_id,customer_id,event_type,actor_type,actor_ref,run_id,
            trace_id,payload,created_at
          ) VALUES (
            p_request->>'audit_id',v_tenant_id,p_request->>'ticket_id',
            p_request->>'customer_id','command_accepted','customer',v_principal_id,
            p_request->>'run_id',p_request->>'trace_id',
            pg_catalog.jsonb_build_object(
              'job_id',p_request->>'job_id','route','POST /api/tickets'
            ),v_accepted_at
          );
          RETURN pg_catalog.jsonb_build_object(
            'schema_version','command-accepted.v1',
              'ticket_id',p_request->>'ticket_id','run_id',p_request->>'run_id',
              'job_id',p_request->>'job_id','accepted_at',public.supportguard_internal_format_utc_timestamp(v_accepted_at),
              'status','queued',
              'status_url','/api/runs/'||(p_request->>'run_id'),
              'events_url','/api/tickets/'||(p_request->>'ticket_id')||'/events/stream','reused',false,'reused',false
          );
        END
        $$;


ALTER FUNCTION public.supportguard_api_accept_ticket(p_request jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_converge_checkpoint_binding_stale(text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_converge_checkpoint_binding_stale(p_approval_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_tenant_id text:=current_setting('app.tenant_id',true);
          v_principal_id text:=current_setting('app.principal_id',true);
          v_discovered_ticket_id text;
          v_approval public.approval_requests%ROWTYPE;
          v_ticket public.support_tickets%ROWTYPE;
          v_proposal public.proposal_records%ROWTYPE;
          v_run public.agent_runs%ROWTYPE;
          v_turn public.conversation_turns%ROWTYPE;
          v_marker public.checkpoint_commit_markers%ROWTYPE;
          v_parent public.agent_events%ROWTYPE;
          v_existing_event public.agent_events%ROWTYPE;
          v_existing_message public.ticket_messages%ROWTYPE;
          v_now timestamptz:=clock_timestamp();
          v_event_id text;
          v_message_id text;
          v_publication_key text;
          v_idempotency_id text;
          v_payload jsonb;
          v_payload_canonical text;
          v_payload_hash text;
          v_created_at_text text;
          v_envelope text;
          v_event_hash text;
          v_ticket_sequence bigint;
          v_run_sequence bigint;
          v_chain_count bigint;
          v_chain_min bigint;
          v_chain_max bigint;
          v_binding_valid boolean;
          v_activation jsonb;
          v_ticket_status text;
        BEGIN
          IF session_user<>'supportguard_api'
             OR coalesce(v_tenant_id,'')=''
             OR coalesce(v_principal_id,'')=''
             OR coalesce(p_approval_id,'')='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='checkpoint_binding_stale_invalid';
          END IF;

          -- Lock-free identity discovery is followed by the frozen aggregate
          -- order: Ticket -> Approval -> Proposal -> Run/Turn.  Every identity
          -- is revalidated after its lock is acquired.
          SELECT approval.ticket_id INTO v_discovered_ticket_id
          FROM public.approval_requests approval
          WHERE approval.tenant_id=v_tenant_id
            AND approval.id=p_approval_id;
          IF v_discovered_ticket_id IS NULL THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','approval_not_found'
            );
          END IF;
          IF NOT EXISTS (
            SELECT 1
            FROM public.memberships membership
            JOIN public.approver_tenant_scopes scope
              ON scope.user_id=membership.user_id
             AND scope.tenant_id=membership.tenant_id
            WHERE membership.tenant_id=v_tenant_id
              AND membership.user_id=v_principal_id
              AND membership.role='support_approver'
              AND membership.status='active'
          ) THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','approver_scope_invalid'
            );
          END IF;

          SELECT * INTO v_ticket
          FROM public.support_tickets ticket
          WHERE ticket.tenant_id=v_tenant_id
            AND ticket.id=v_discovered_ticket_id
          FOR UPDATE;
          SELECT * INTO v_approval
          FROM public.approval_requests approval
          WHERE approval.tenant_id=v_tenant_id
            AND approval.id=p_approval_id
            AND approval.ticket_id=v_ticket.id
          FOR UPDATE;
          IF v_ticket.id IS NULL OR v_approval.id IS NULL THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','approval_not_found'
            );
          END IF;
          SELECT * INTO v_proposal
          FROM public.proposal_records proposal
          WHERE proposal.tenant_id=v_tenant_id
            AND proposal.id=v_approval.proposal_id
          FOR UPDATE;
          SELECT * INTO v_run
          FROM public.agent_runs run_row
          WHERE run_row.tenant_id=v_tenant_id
            AND run_row.id=v_approval.run_id
            AND run_row.ticket_id=v_ticket.id
          FOR UPDATE;
          IF v_run.turn_id IS NOT NULL THEN
            SELECT * INTO v_turn
            FROM public.conversation_turns turn_row
            WHERE turn_row.tenant_id=v_tenant_id
              AND turn_row.id=v_run.turn_id
              AND turn_row.ticket_id=v_ticket.id
              AND turn_row.run_id=v_run.id
            FOR UPDATE;
          END IF;
          SELECT * INTO v_marker
          FROM public.checkpoint_commit_markers marker
          WHERE marker.tenant_id=v_tenant_id
            AND marker.id=v_approval.marker_id;

          v_event_id:='event_'||pg_catalog.md5(
            'v1512:checkpoint-binding-stale:'||v_tenant_id||':'||p_approval_id
          );
          v_message_id:='message_'||pg_catalog.md5(
            'v1512:checkpoint-binding-stale:'||v_tenant_id||':'||p_approval_id
          );
          v_publication_key:='approval:'||p_approval_id||':stale:checkpoint-binding';
          v_idempotency_id:='binding-stale:'||pg_catalog.md5(
            v_tenant_id||':'||p_approval_id
          );

          IF v_approval.status='stale' THEN
            SELECT * INTO v_existing_event
            FROM public.agent_events event
            WHERE event.tenant_id=v_tenant_id AND event.id=v_event_id;
            SELECT * INTO v_existing_message
            FROM public.ticket_messages message
            WHERE message.tenant_id=v_tenant_id
              AND message.publication_key=v_publication_key;
            IF v_existing_event.id IS NULL
               OR v_existing_event.ticket_id IS DISTINCT FROM v_ticket.id
               OR v_existing_event.run_id IS DISTINCT FROM v_run.id
               OR v_existing_event.customer_id IS DISTINCT FROM v_ticket.customer_id
               OR v_existing_event.event_type IS DISTINCT FROM
                    'runtime_action_reconciliation'
               OR v_existing_event.status IS DISTINCT FROM 'completed'
               OR v_existing_event.visibility IS DISTINCT FROM 'customer'
               OR v_existing_event.idempotency_id IS DISTINCT FROM v_idempotency_id
               OR v_existing_event.payload::jsonb IS DISTINCT FROM
                    pg_catalog.jsonb_build_object(
                      'approval_id',p_approval_id,
                      'proposal_id',v_approval.proposal_id,
                      'reason','checkpoint_binding_conflict'
                    )
               OR v_existing_message.id IS NULL
               OR v_existing_message.ticket_id IS DISTINCT FROM v_ticket.id
               OR v_existing_message.run_id IS DISTINCT FROM v_run.id
               OR v_existing_message.approval_id IS DISTINCT FROM p_approval_id
               OR v_existing_message.message_kind IS DISTINCT FROM 'action_update' THEN
              RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='checkpoint_binding_stale_replay_conflict';
            END IF;
            RETURN pg_catalog.jsonb_build_object(
              'schema_version','checkpoint-binding-stale.v1',
              'approval_id',p_approval_id,
              'status','stale',
              'event_id',v_existing_event.id,
              'message_id',v_existing_message.id,
              'reused',true
            );
          END IF;
          IF v_approval.status<>'pending' THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','approval_state_conflict'
            );
          END IF;

          -- This compensation must not be usable as an alternate rejection
          -- path.  It is authorized only before any human decision, resume
          -- work, or business effect exists.
          IF EXISTS (
               SELECT 1 FROM public.human_decisions decision
               WHERE decision.tenant_id=v_tenant_id
                 AND decision.approval_id=p_approval_id
             )
             OR EXISTS (
               SELECT 1 FROM public.runtime_jobs job
               WHERE job.tenant_id=v_tenant_id
                 AND job.approval_id=p_approval_id
             )
             OR EXISTS (
               SELECT 1 FROM public.business_actions action
               WHERE action.tenant_id=v_tenant_id
                 AND action.approval_id=p_approval_id
             ) THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','approval_state_conflict'
            );
          END IF;
          IF v_ticket.id IS NULL OR v_proposal.id IS NULL
             OR v_run.id IS NULL OR v_turn.id IS NULL
             OR v_marker.id IS NULL THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','checkpoint_binding_repair_incomplete'
            );
          END IF;

          v_binding_valid:=(
            v_proposal.status='bound'
            AND v_marker.status='finalized'
            AND v_run.status='interrupted'
            AND v_ticket.status='awaiting_approval'
            AND v_run.canonical_checkpoint_ns IS NOT DISTINCT FROM
                  v_approval.canonical_checkpoint_ns
            AND v_run.canonical_checkpoint_id IS NOT DISTINCT FROM
                  v_approval.checkpoint_id
            AND v_run.canonical_checkpoint_hash IS NOT DISTINCT FROM
                  v_approval.canonical_checkpoint_hash
            AND v_marker.final_checkpoint_id IS NOT DISTINCT FROM
                  v_approval.checkpoint_id
            AND v_marker.final_checkpoint_hash IS NOT DISTINCT FROM
                  v_approval.canonical_checkpoint_hash
            AND v_run.canonical_checkpoint_version IS NOT DISTINCT FROM
                  v_approval.checkpoint_version
            AND v_marker.final_checkpoint_version IS NOT DISTINCT FROM
                  v_approval.checkpoint_version
            AND v_approval.expected_ticket_sequence IS NOT NULL
          );
          IF v_binding_valid THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','checkpoint_binding_valid'
            );
          END IF;

          SELECT * INTO v_parent
          FROM public.agent_events event
          WHERE event.tenant_id=v_tenant_id
            AND event.ticket_id=v_ticket.id
          ORDER BY event.ticket_sequence DESC,event.id DESC
          LIMIT 1;
          SELECT pg_catalog.count(*),pg_catalog.min(event.ticket_sequence),
                 pg_catalog.max(event.ticket_sequence)
          INTO v_chain_count,v_chain_min,v_chain_max
          FROM public.agent_events event
          WHERE event.tenant_id=v_tenant_id
            AND event.ticket_id=v_ticket.id;
          IF v_ticket.next_event_sequence IS DISTINCT FROM
                coalesce(v_parent.ticket_sequence,0)
             OR v_chain_count<>coalesce(v_parent.ticket_sequence,0)
             OR (
               v_chain_count>0
               AND (v_chain_min<>1 OR v_chain_max<>v_chain_count)
             )
             OR EXISTS (
               SELECT 1
               FROM public.agent_events child
               LEFT JOIN public.agent_events parent
                 ON parent.tenant_id=child.tenant_id
                AND parent.ticket_id=child.ticket_id
                AND parent.ticket_sequence=child.ticket_sequence-1
               WHERE child.tenant_id=v_tenant_id
                 AND child.ticket_id=v_ticket.id
                 AND child.ticket_sequence>1
                 AND (
                   child.previous_event_id IS DISTINCT FROM parent.id
                   OR child.parent_event_hash IS DISTINCT FROM parent.event_hash
                 )
             )
             OR v_run.next_run_sequence IS DISTINCT FROM (
               SELECT coalesce(pg_catalog.max(event.run_sequence),0)
               FROM public.agent_events event
               WHERE event.tenant_id=v_tenant_id
                 AND event.run_id=v_run.id
             ) THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','event_chain_conflict'
            );
          END IF;
          SELECT * INTO v_existing_event
          FROM public.agent_events event
          WHERE event.tenant_id=v_tenant_id AND event.id=v_event_id;
          SELECT * INTO v_existing_message
          FROM public.ticket_messages message
          WHERE message.tenant_id=v_tenant_id
            AND message.publication_key=v_publication_key;
          IF v_existing_event.id IS NOT NULL OR v_existing_message.id IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',
              MESSAGE='checkpoint_binding_stale_identity_conflict';
          END IF;

          v_ticket_sequence:=v_ticket.next_event_sequence+1;
          v_run_sequence:=v_run.next_run_sequence+1;
          v_payload:=pg_catalog.jsonb_build_object(
            'approval_id',p_approval_id,
            'proposal_id',v_proposal.id,
            'reason','checkpoint_binding_conflict'
          );
          v_payload_canonical:='{"approval_id":'
            ||pg_catalog.to_jsonb(p_approval_id)::text
            ||',"proposal_id":'||pg_catalog.to_jsonb(v_proposal.id)::text
            ||',"reason":"checkpoint_binding_conflict"}';
          v_payload_hash:=pg_catalog.encode(
            pg_catalog.sha256(
              pg_catalog.convert_to(v_payload_canonical,'UTF8')
            ),
            'hex'
          );
          v_created_at_text:=pg_catalog.to_char(
            v_now AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US'
          )||'+00:00';
          v_envelope:='{"aggregate_id":'||pg_catalog.to_jsonb(v_ticket.id)::text
            ||',"aggregate_type":"SupportTicket"'
            ||',"canonicalization_version":"json-sort-keys.v1"'
            ||',"causation_id":'||coalesce(pg_catalog.to_jsonb(v_parent.id)::text,'null')
            ||',"correlation_id":'||pg_catalog.to_jsonb(v_run.id)::text
            ||',"created_at":'||pg_catalog.to_jsonb(v_created_at_text)::text
            ||',"customer_id":'||pg_catalog.to_jsonb(v_ticket.customer_id)::text
            ||',"delivery_generation":null'
            ||',"event_id":'||pg_catalog.to_jsonb(v_event_id)::text
            ||',"event_schema_version":"support-ticket-event.v1"'
            ||',"event_type":"runtime_action_reconciliation"'
            ||',"fencing_token":null'
            ||',"idempotency_id":'||pg_catalog.to_jsonb(v_idempotency_id)::text
            ||',"job_id":null'
            ||',"payload_hash":'||pg_catalog.to_jsonb(v_payload_hash)::text
            ||',"previous_event_id":'
            ||coalesce(
              pg_catalog.to_jsonb(
                CASE WHEN v_parent.run_id=v_run.id THEN v_parent.id END
              )::text,
              'null'
            )
            ||',"run_id":'||pg_catalog.to_jsonb(v_run.id)::text
            ||',"run_sequence":'||v_run_sequence::text
            ||',"status":"completed"'
            ||',"step_index":'||v_run.step_index::text
            ||',"tenant_id":'||pg_catalog.to_jsonb(v_tenant_id)::text
            ||',"ticket_sequence":'||v_ticket_sequence::text
            ||',"tool_call_id":null'
            ||',"tool_round":'||v_run.tool_rounds::text
            ||',"visibility":"customer"}';
          v_event_hash:=pg_catalog.encode(
            pg_catalog.sha256(
              pg_catalog.convert_to(
                'event-hash.v1'||v_envelope
                  ||coalesce(v_parent.event_hash,pg_catalog.repeat('0',64)),
                'UTF8'
              )
            ),
            'hex'
          );

          UPDATE public.approval_requests
          SET status='stale',
              decided_at=v_now,
              status_version=status_version+1,
              updated_at=v_now
          WHERE tenant_id=v_tenant_id
            AND id=p_approval_id
            AND status='pending';
          IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='40001',
              MESSAGE='approval_state_conflict';
          END IF;
          UPDATE public.proposal_records
          SET status='stale',
              status_version=status_version+1,
              updated_at=v_now
          WHERE tenant_id=v_tenant_id
            AND id=v_proposal.id
            AND status IN ('draft','bound');
          UPDATE public.agent_runs
          SET status='completed',
              checkpoint_stage='completed',
              agent_finish_reason='binding_stale',
              error_code=NULL,
              active_job_id=NULL,
              active_fencing_token=NULL,
              completed_at=coalesce(completed_at,v_now),
              next_run_sequence=v_run_sequence,
              status_version=status_version+1,
              updated_at=v_now
          WHERE tenant_id=v_tenant_id AND id=v_run.id;
          UPDATE public.conversation_turns
          SET activity_state='completed',
              result_state='stale',
              completed_at=coalesce(completed_at,v_now),
              updated_at=v_now
          WHERE tenant_id=v_tenant_id AND id=v_turn.id;
          UPDATE public.support_tickets
          SET next_event_sequence=v_ticket_sequence,
              final_response=(
                '申请所绑定的处理状态已发生变化，系统已安全关闭该申请，'
                '且未执行任何业务操作。请刷新事实后重新提交。'
              ),
              version=version+1,
              updated_at=v_now
          WHERE tenant_id=v_tenant_id AND id=v_ticket.id;
          INSERT INTO public.agent_events(
            id,tenant_id,run_id,ticket_id,customer_id,sequence,ticket_sequence,
            run_sequence,step_index,tool_round,event_type,status,visibility,
            payload,payload_hash,previous_event_id,parent_event_hash,event_hash,
            event_schema_version,canonicalization_version,
            event_hash_schema_version,correlation_id,causation_id,
            idempotency_id,created_at
          ) VALUES (
            v_event_id,v_tenant_id,v_run.id,v_ticket.id,v_ticket.customer_id,
            v_run_sequence,v_ticket_sequence,v_run_sequence,
            v_run.step_index,v_run.tool_rounds,
            'runtime_action_reconciliation','completed','customer',
            v_payload,v_payload_hash,
            CASE WHEN v_parent.run_id=v_run.id THEN v_parent.id END,
            coalesce(v_parent.event_hash,pg_catalog.repeat('0',64)),
            v_event_hash,'support-ticket-event.v1','json-sort-keys.v1',
            'event-hash.v1',v_run.id,v_parent.id,v_idempotency_id,v_now
          );
          INSERT INTO public.ticket_messages(
            id,tenant_id,ticket_id,turn_id,run_id,approval_id,message_kind,
            publication_key,role,content,source_refs,created_at,updated_at
          ) VALUES (
            v_message_id,v_tenant_id,v_ticket.id,v_turn.id,v_run.id,
            p_approval_id,'action_update',v_publication_key,'action',
            '申请所绑定的处理状态已发生变化，系统已安全关闭该申请，'
              '且未执行任何业务操作。请刷新事实后重新提交。',
            '[]'::jsonb,v_now,v_now
          );
          INSERT INTO public.audit_events(
            id,tenant_id,ticket_id,customer_id,event_type,actor_type,actor_ref,
            run_id,trace_id,payload,created_at
          ) VALUES (
            'audit_'||pg_catalog.md5(
              'v1512:checkpoint-binding-stale:'||v_tenant_id||':'||p_approval_id
            ),
            v_tenant_id,v_ticket.id,v_ticket.customer_id,
            'approval_checkpoint_binding_staled','system',
            'checkpoint-binding-convergence',v_run.id,
            v_idempotency_id,
            pg_catalog.jsonb_build_object(
              'approval_id',p_approval_id,
              'proposal_id',v_proposal.id,
              'canonical_event_id',v_event_id,
              'canonical_event_hash',v_event_hash,
              'reason','checkpoint_binding_conflict'
            ),
            v_now
          );

          v_activation:=public.supportguard_internal_activate_next_ticket_turn(
            v_tenant_id,v_ticket.id,NULL
          );
          v_ticket_status:=public.supportguard_internal_converge_ticket_status(
            v_tenant_id,v_ticket.id,'open'
          );
          RETURN pg_catalog.jsonb_build_object(
            'schema_version','checkpoint-binding-stale.v1',
            'approval_id',p_approval_id,
            'status','stale',
            'event_id',v_event_id,
            'message_id',v_message_id,
            'ticket_status',v_ticket_status,
            'activation',v_activation,
            'reused',false
          );
        END
        $$;


ALTER FUNCTION public.supportguard_api_converge_checkpoint_binding_stale(p_approval_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_customer_exists(text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_customer_exists(p_customer_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF session_user <> 'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          RETURN (
            SELECT EXISTS(SELECT 1 FROM public.customers c
                WHERE c.tenant_id=current_setting('app.tenant_id',true)
                  AND c.id=p_customer_id AND c.status='active')
          );
        END
        $$;


ALTER FUNCTION public.supportguard_api_customer_exists(p_customer_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_approval(text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_approval(p_approval_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
        DECLARE
          v_result jsonb;
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF current_setting('app.principal_role',true)
             NOT IN ('approver','support_approver') THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='approver_role_required';
          END IF;
          IF p_approval_id IS NULL OR p_approval_id='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='approval_projection_input_invalid';
          END IF;

          SELECT pg_catalog.jsonb_strip_nulls(
            pg_catalog.jsonb_build_object(
              'id',CASE WHEN a.id~'^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'
                THEN a.id END,
              'ticket_id',CASE
                WHEN a.ticket_id~'^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'
                THEN a.ticket_id END,
              'status',CASE
                WHEN a.status='manual_takeover' THEN 'manual_takeover_legacy'
                WHEN a.status IN ('executed','rejected','stale','withdrawn','failed')
                  THEN a.status
                WHEN a.status='approved' AND (
                  coalesce(resume.verification_pending,false)
                  OR action_row.status IN ('unknown','verification_pending')
                ) THEN 'verification_pending'
                WHEN a.status='approved' AND (
                  resume.status='leased'
                  OR action_row.status IN ('pending','running','executing')
                ) THEN 'executing'
                WHEN a.status IN ('pending','approved') THEN a.status
                ELSE 'projection_unavailable'
              END,
              'action_type',CASE
                WHEN a.action_type IN (
                  'refund','api_key_revocation','entitlement_change'
                ) THEN a.action_type END,
              'resource_type',CASE
                WHEN a.action_type='refund' THEN 'billing_record_id'
                WHEN a.action_type='api_key_revocation' THEN 'api_key_id'
                WHEN a.action_type='entitlement_change' THEN 'subscription_id'
              END,
              'resource_id',CASE
                WHEN a.resource_id~'^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'
                THEN a.resource_id END,
              'origin_turn_id',CASE
                WHEN a.origin_turn_id~'^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'
                THEN a.origin_turn_id END,
              'original_request',(
                SELECT pg_catalog.left(original_message.content,8000)
                FROM public.conversation_turns origin_turn
                JOIN public.ticket_messages original_message
                  ON original_message.tenant_id=origin_turn.tenant_id
                 AND original_message.ticket_id=origin_turn.ticket_id
                 AND original_message.turn_id=origin_turn.id
                 AND original_message.id=origin_turn.customer_message_id
                 AND original_message.message_kind='customer'
                 AND original_message.role IN ('user','customer')
                WHERE origin_turn.tenant_id=a.tenant_id
                  AND origin_turn.ticket_id=a.ticket_id
                  AND origin_turn.id=a.origin_turn_id
                  AND origin_turn.run_id=a.run_id
                LIMIT 1
              ),
              'requested_change',CASE
                WHEN a.action_type='refund' THEN
                  pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
                    'refund_reason',CASE WHEN pg_catalog.jsonb_typeof(
                      coalesce(
                        selected_revision.action_payload,NULL::json
                      )::jsonb->'refund_reason'
                    )='string' AND pg_catalog.btrim(coalesce(
                      coalesce(
                        selected_revision.action_payload,NULL::json
                      )->>'refund_reason',''
                    ))<>'' THEN pg_catalog.left(
                      coalesce(
                        selected_revision.action_payload,NULL::json
                      )->>'refund_reason',500
                    ) END
                  ))
                WHEN a.action_type='entitlement_change' THEN
                  pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
                    'change_type',CASE
                      WHEN coalesce(
                        selected_revision.action_payload,NULL::json
                      )->>'change_type'
                        IN ('quota_change','plan_change')
                      THEN coalesce(
                        selected_revision.action_payload,NULL::json
                      )->>'change_type' END,
                    'current',pg_catalog.jsonb_strip_nulls(
                      pg_catalog.jsonb_build_object(
                        'plan',CASE
                          WHEN coalesce(
                            selected_revision.action_payload,NULL::json
                          )->'current'->>'plan'
                            ~'^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'
                          THEN coalesce(
                            selected_revision.action_payload,NULL::json
                          )->'current'->>'plan' END,
                        'rpm_limit',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            (coalesce(
                              selected_revision.action_payload,NULL::json
                            ))::jsonb->'current'->'rpm_limit'
                          )='number'
                          THEN coalesce(
                            selected_revision.action_payload,NULL::json
                          )->'current'->'rpm_limit' END,
                        'concurrency_limit',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            (coalesce(
                              selected_revision.action_payload,NULL::json
                            ))::jsonb->'current'->'concurrency_limit'
                          )='number'
                          THEN coalesce(
                            selected_revision.action_payload,NULL::json
                          )->'current'->'concurrency_limit' END
                      )
                    ),
                    'target',pg_catalog.jsonb_strip_nulls(
                      pg_catalog.jsonb_build_object(
                        'plan',CASE
                          WHEN coalesce(
                            selected_revision.action_payload,NULL::json
                          )->'target'->>'plan'
                            ~'^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'
                          THEN coalesce(
                            selected_revision.action_payload,NULL::json
                          )->'target'->>'plan' END,
                        'rpm_limit',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            (coalesce(
                              selected_revision.action_payload,NULL::json
                            ))::jsonb->'target'->'rpm_limit'
                          )='number'
                          THEN coalesce(
                            selected_revision.action_payload,NULL::json
                          )->'target'->'rpm_limit' END,
                        'concurrency_limit',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            (coalesce(
                              selected_revision.action_payload,NULL::json
                            ))::jsonb->'target'->'concurrency_limit'
                          )='number'
                          THEN coalesce(
                            selected_revision.action_payload,NULL::json
                          )->'target'->'concurrency_limit' END
                      )
                    )
                  ))
                ELSE '{}'::jsonb
              END,
              'resource_facts',CASE
                WHEN a.action_type='refund' AND billing.id IS NOT NULL THEN
                  pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
                    'status',CASE WHEN billing.status IN (
                      'charged','refunded','pending','failed','void'
                    ) THEN billing.status ELSE 'unknown' END,
                    'amount',billing.amount::text,
                    'currency',CASE
                      WHEN billing.currency~'^[A-Z]{3}$' THEN billing.currency END,
                    'duplicate_of',CASE
                      WHEN billing.duplicate_of
                        ~'^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'
                      THEN billing.duplicate_of END,
                    'version',billing.version
                  ))
                WHEN a.action_type='api_key_revocation'
                     AND key_row.id IS NOT NULL THEN
                  pg_catalog.jsonb_build_object(
                    'status',CASE WHEN key_row.status IN (
                      'active','revoked','disabled','expired'
                    ) THEN key_row.status ELSE 'unknown' END,
                    'version',key_row.version
                  )
                WHEN a.action_type='entitlement_change'
                     AND subscription.id IS NOT NULL THEN
                  pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
                    'status',CASE WHEN subscription.status IN (
                      'active','past_due','suspended','cancelled','canceled'
                    ) THEN subscription.status ELSE 'unknown' END,
                    'plan',CASE
                      WHEN subscription.plan
                        ~'^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$'
                      THEN subscription.plan END,
                    'rpm_limit',subscription.rpm_limit,
                    'concurrency_limit',subscription.concurrency_limit,
                    'version',subscription.version
                  ))
                ELSE '{}'::jsonb
              END,
              'risk',CASE WHEN ticket.risk IN ('low','medium','high')
                THEN ticket.risk ELSE 'high' END,
              'business_version',a.business_version,
              'status_version',a.status_version,
              'conversation_action_sources',(
      SELECT pg_catalog.jsonb_build_object(
        'schema_version','conversation-action-source-bundle.v1',
        'approval',pg_catalog.jsonb_build_object(
          'id',a.id,
          'tenant_id',a.tenant_id,
          'ticket_id',a.ticket_id,
          'customer_id',a.customer_id,
          'proposal_id',a.proposal_id,
          'run_id',a.run_id,
          'action_type',a.action_type,
          'resource_type',a.resource_type,
          'resource_id',a.resource_id,
          'origin_turn_id',a.origin_turn_id,
          'business_version',a.business_version,
          'status',a.status,
          'status_version',a.status_version,
          'expected_ticket_head_event_id',a.expected_ticket_head_event_id,
          'expected_ticket_event_hash',a.expected_ticket_event_hash,
          'transition_event_id',transition.value->>'id',
          'transition_event_hash',transition.value->>'event_hash',
          'transition_event_type',transition.value->>'event_type',
          'created_at',a.created_at,
          'updated_at',a.updated_at
        ),
        'proposal',(
          SELECT pg_catalog.jsonb_build_object(
            'id',proposal.id,
            'tenant_id',proposal.tenant_id,
            'run_id',proposal.run_id,
            'action_type',proposal.action_type,
            'resource_id',proposal.resource_id,
            'resource_version',proposal.resource_version,
            'status',proposal.status,
            'created_at',proposal.created_at,
            'updated_at',proposal.updated_at
          )
          FROM public.proposal_records proposal
          WHERE proposal.tenant_id=a.tenant_id
            AND proposal.id=a.proposal_id
          LIMIT 1
        ),
        'decision',(
          SELECT pg_catalog.jsonb_build_object(
            'id',decision.id,
            'tenant_id',decision.tenant_id,
            'approval_id',decision.approval_id,
            'decision',decision.decision,
            'canonical_event_id',decision.canonical_event_id,
            'canonical_event_hash',decision.canonical_event_hash,
            'created_at',decision.created_at,
            'updated_at',decision.updated_at
          )
          FROM public.human_decisions decision
          WHERE decision.tenant_id=a.tenant_id
            AND decision.approval_id=a.id
          ORDER BY decision.created_at DESC,decision.id DESC
          LIMIT 1
        ),
        'business_action',(
          SELECT pg_catalog.jsonb_build_object(
            'id',business_action.id,
            'tenant_id',business_action.tenant_id,
            'ticket_id',business_action.ticket_id,
            'customer_id',business_action.customer_id,
            'approval_id',business_action.approval_id,
            'action_type',business_action.action_type,
            'resource_id',business_action.resource_id,
            'resource_version',business_action.resource_version,
            'status',business_action.status,
            'canonical_event_id',business_action.canonical_event_id,
            'canonical_event_hash',business_action.canonical_event_hash,
            'created_at',business_action.created_at,
            'updated_at',business_action.updated_at
          )
          FROM public.business_actions business_action
          WHERE business_action.tenant_id=a.tenant_id
            AND business_action.approval_id=a.id
          ORDER BY business_action.created_at DESC,business_action.id DESC
          LIMIT 1
        ),
        'withdrawal',(
          SELECT pg_catalog.jsonb_build_object(
            'id',withdrawal.id,
            'tenant_id',withdrawal.tenant_id,
            'ticket_id',withdrawal.ticket_id,
            'customer_id',withdrawal.customer_id,
            'approval_id',withdrawal.approval_id,
            'proposal_id',withdrawal.proposal_id,
            'created_at',withdrawal.created_at,
            'updated_at',withdrawal.updated_at
          )
          FROM public.proposal_withdrawals withdrawal
          WHERE withdrawal.tenant_id=a.tenant_id
            AND withdrawal.approval_id=a.id
          ORDER BY withdrawal.created_at DESC,withdrawal.id DESC
          LIMIT 1
        ),
        'runtime_job',(
          SELECT pg_catalog.jsonb_build_object(
            'id',approval_job.id,
            'tenant_id',approval_job.tenant_id,
            'ticket_id',approval_job.ticket_id,
            'run_id',approval_job.run_id,
            'approval_id',approval_job.approval_id,
            'kind',approval_job.kind,
            'status',approval_job.status,
            'outcome',approval_job.outcome,
            'delivery_hold_reason',approval_job.delivery_hold_reason,
            'created_at',approval_job.created_at,
            'updated_at',approval_job.updated_at
          )
          FROM public.runtime_jobs approval_job
          WHERE approval_job.tenant_id=a.tenant_id
            AND approval_job.approval_id=a.id
            AND approval_job.kind='approval_resume'
          ORDER BY approval_job.created_at DESC,approval_job.id DESC
          LIMIT 1
        )
      )
      FROM (SELECT (
      SELECT pg_catalog.jsonb_build_object(
        'id',event.id,
        'event_hash',event.event_hash,
        'event_type',event.event_type
      )
      FROM public.agent_events event
      WHERE event.tenant_id=a.tenant_id
        AND event.ticket_id=a.ticket_id
        AND event.run_id=a.run_id
        AND (
          (
            a.status='withdrawn'
            AND event.event_type='proposal_withdrawn'
            AND event.payload->>'approval_id'=a.id
          )
          OR (
            a.status='stale'
            AND event.event_type IN (
              'runtime_action_reconciliation',
              'approval_staled_duplicate_identity'
            )
            AND event.payload->>'approval_id'=a.id
          )
          OR (
            a.status='failed'
            AND event.event_type='runtime_failed'
            AND EXISTS (
              SELECT 1
              FROM public.runtime_jobs failed_job
              WHERE failed_job.tenant_id=a.tenant_id
                AND failed_job.id=event.job_id
                AND failed_job.ticket_id=a.ticket_id
                AND failed_job.run_id=a.run_id
                AND failed_job.approval_id=a.id
            )
          )
        )
      ORDER BY event.ticket_sequence DESC,event.id DESC
      LIMIT 1
    ) AS value) transition
    ),
              'actionable',coalesce((
                a.status='pending'
                AND run.status='interrupted'
                AND run.checkpoint_stage='awaiting_approval'
                AND run.checkpoint_id=a.checkpoint_id
                AND proposal.status='bound'
                AND marker.status='finalized'
                AND run.canonical_checkpoint_ns=a.canonical_checkpoint_ns
                AND run.canonical_checkpoint_hash=a.canonical_checkpoint_hash
              ),false),
              'proposal_summary',CASE WHEN proposal.id IS NULL THEN NULL ELSE
                pg_catalog.jsonb_build_object(
                  'status',CASE WHEN proposal.status IN ('draft','bound','stale')
                    THEN proposal.status ELSE 'unknown' END,
                  'resource_version',proposal.resource_version
                ) END,
              'snapshot_summary',CASE WHEN snapshot.id IS NULL THEN NULL ELSE
                pg_catalog.jsonb_build_object(
                  'resource_version',snapshot.resource_version,
                  'policy_bound',(
                    pg_catalog.jsonb_typeof(snapshot.policy_binding::jsonb)='object'
                    AND snapshot.policy_binding::jsonb<>'{}'::jsonb
                  ),
                  'citation_count',CASE
                    WHEN pg_catalog.jsonb_typeof(
                      snapshot.citation_binding_refs::jsonb
                    )='array'
                    THEN least(
                      pg_catalog.jsonb_array_length(
                        snapshot.citation_binding_refs::jsonb
                      ),20
                    )
                    ELSE 0
                  END
                ) END,
              'evidence_summaries',coalesce((
                SELECT pg_catalog.jsonb_agg(
                  pg_catalog.jsonb_build_object(
                    'title',pg_catalog.left(document.title,300),
                    'section_path',pg_catalog.left(chunk.section_path,500),
                    'version',pg_catalog.left(document.version,64),
                    'freshness',CASE observation.payload->>'freshness_status'
                      WHEN 'fresh' THEN 'current'
                      WHEN 'stale' THEN 'changed_since_proposal'
                      ELSE 'unavailable' END
                  ) ORDER BY frozen_ref.ordinality
                )
                FROM pg_catalog.jsonb_array_elements_text(
                  CASE WHEN pg_catalog.jsonb_typeof(
                    snapshot.citation_binding_refs::jsonb
                  )='array' THEN snapshot.citation_binding_refs::jsonb
                  ELSE '[]'::jsonb END
                ) WITH ORDINALITY AS frozen_ref(binding_id,ordinality)
                JOIN public.citation_bindings binding
                  ON binding.tenant_id=a.tenant_id
                 AND binding.run_id=a.run_id
                 AND binding.id=frozen_ref.binding_id
                JOIN public.retrieval_traces trace
                  ON trace.tenant_id=binding.tenant_id
                 AND trace.run_id=binding.run_id
                 AND trace.origin_job_id=binding.origin_job_id
                 AND trace.logical_invocation_id=binding.tool_invocation_id
                 AND trace.id=binding.retrieval_trace_id
                JOIN public.tool_observations observation
                  ON observation.tenant_id=binding.tenant_id
                 AND observation.run_id=binding.run_id
                 AND observation.job_id=binding.origin_job_id
                 AND observation.invocation_id=binding.tool_invocation_id
                 AND observation.id=binding.observation_id
                 AND observation.status='ok'
                 AND observation.payload->>'tool_name'='search_knowledge'
                JOIN public.knowledge_chunks chunk
                  ON chunk.chunk_key=(
                    trace.selected_candidates::jsonb
                    -> binding.selected_candidate_ordinal ->> 'chunk_id'
                  )
                 AND chunk.index_version=trace.index_version
                 AND chunk.ingest_run_id=trace.corpus_snapshot_id
                JOIN public.knowledge_documents document
                  ON document.id=chunk.document_id
                 AND document.index_version=chunk.index_version
                 AND document.ingest_run_id=chunk.ingest_run_id
                WHERE frozen_ref.ordinality<=20
              ),'[]'::jsonb),
              'ticket_summary',CASE WHEN ticket.id IS NULL THEN NULL ELSE
                pg_catalog.jsonb_build_object(
                  'status',CASE WHEN ticket.status IN (
                    'open','queued','running','awaiting_approval',
                    'verification_pending','resolved','rejected','failed',
                    'human_queue','archived'
                  ) THEN ticket.status ELSE 'unknown' END
                ) END,
              'human_decision_summary',CASE
                WHEN decision_row.decision IN (
                  'approve','edit_and_approve','reject','manual_takeover'
                ) THEN pg_catalog.jsonb_build_object(
                  'decision',decision_row.decision,
                  'created_at',decision_row.created_at
                ) END,
              'resume_job_summary',CASE WHEN resume.status IS NULL THEN NULL ELSE
                pg_catalog.jsonb_build_object(
                  'status',CASE WHEN resume.status IN (
                    'queued','leased','succeeded','retry_wait','dead'
                  ) THEN resume.status ELSE 'unknown' END,
                  'verification_pending',resume.verification_pending
                ) END,
              'business_action_summary',CASE
                WHEN action_row.status IS NULL THEN NULL ELSE
                  pg_catalog.jsonb_build_object(
                    'status',CASE WHEN action_row.status IN (
                      'pending','running','executing','succeeded','failed',
                      'stale','unknown','verification_pending'
                    ) THEN action_row.status ELSE 'unknown' END,
                    'resource_version',action_row.resource_version,
                    'created_at',action_row.created_at
                  ) END,
              'created_at',a.created_at,
              'updated_at',a.updated_at,
              'decided_at',a.decided_at,
              'consumed_at',a.consumed_at
            )
          ) INTO v_result
          FROM public.approval_requests a
          LEFT JOIN public.agent_runs run
            ON run.tenant_id=a.tenant_id AND run.id=a.run_id
          LEFT JOIN public.proposal_records proposal
            ON proposal.tenant_id=a.tenant_id AND proposal.id=a.proposal_id
          LEFT JOIN public.approval_action_revisions selected_revision
            ON selected_revision.tenant_id=a.tenant_id
           AND selected_revision.approval_id=a.id
           AND selected_revision.id=a.selected_revision_id
           AND selected_revision.revision_number=a.selected_revision_number
          LEFT JOIN public.checkpoint_commit_markers marker
            ON marker.tenant_id=a.tenant_id AND marker.id=a.marker_id
          LEFT JOIN public.support_tickets ticket
            ON ticket.tenant_id=a.tenant_id
           AND ticket.id=a.ticket_id
           AND ticket.customer_id=a.customer_id
          LEFT JOIN public.billing_records billing
            ON billing.tenant_id=a.tenant_id
           AND billing.customer_id=a.customer_id
           AND billing.id=a.resource_id
           AND a.action_type='refund'
          LEFT JOIN public.api_key_metadata key_row
            ON key_row.tenant_id=a.tenant_id
           AND key_row.customer_id=a.customer_id
           AND key_row.key_id=a.resource_id
           AND a.action_type='api_key_revocation'
          LEFT JOIN public.subscriptions subscription
            ON subscription.tenant_id=a.tenant_id
           AND subscription.customer_id=a.customer_id
           AND subscription.id=a.resource_id
           AND a.action_type='entitlement_change'
          LEFT JOIN LATERAL (
            SELECT s.id,s.resource_version,s.policy_binding,s.citation_binding_refs
            FROM public.approval_snapshots s
            WHERE s.tenant_id=a.tenant_id AND s.approval_id=a.id
            ORDER BY s.created_at DESC,s.id DESC LIMIT 1
          ) snapshot ON true
          LEFT JOIN LATERAL (
            SELECT d.decision,d.created_at
            FROM public.human_decisions d
            WHERE d.tenant_id=a.tenant_id AND d.approval_id=a.id
            ORDER BY d.created_at DESC,d.id DESC LIMIT 1
          ) decision_row ON true
          LEFT JOIN LATERAL (
            SELECT j.status,(
              j.outcome='verification_pending'
              OR j.delivery_hold_reason='state_unknown'
            ) AS verification_pending
            FROM public.runtime_jobs j
            WHERE j.tenant_id=a.tenant_id
              AND j.run_id=a.run_id
              AND j.approval_id=a.id
              AND j.kind='approval_resume'
            ORDER BY j.created_at DESC,j.id DESC LIMIT 1
          ) resume ON true
          LEFT JOIN LATERAL (
            SELECT b.status,b.resource_version,b.created_at
            FROM public.business_actions b
            WHERE b.tenant_id=a.tenant_id AND b.approval_id=a.id
            ORDER BY b.created_at DESC,b.id DESC LIMIT 1
          ) action_row ON true
          WHERE a.tenant_id=current_setting('app.tenant_id',true)
            AND a.id=p_approval_id;
          RETURN v_result;
        END
        $_$;


ALTER FUNCTION public.supportguard_api_get_approval(p_approval_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_approval_source(text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_approval_source(p_approval_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_result jsonb;
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF current_setting('app.principal_role',true)
             NOT IN ('approver','support_approver') THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='approver_role_required';
          END IF;
          IF p_approval_id IS NULL OR p_approval_id='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='approval_source_input_invalid';
          END IF;

          SELECT pg_catalog.jsonb_build_object(
            'approval_id',approval.id,
            'ticket_id',ticket.id,
            'title',coalesce(ticket.title,'未命名对话'),
            'origin_turn_id',turn_row.id,
            'messages',coalesce(source_window.messages,'[]'::jsonb),
            'returned',coalesce(source_window.returned,0),
            'has_more',coalesce(source_window.has_more,false)
          ) INTO v_result
          FROM public.approval_requests approval
          JOIN public.support_tickets ticket
            ON ticket.tenant_id=approval.tenant_id
           AND ticket.id=approval.ticket_id
           AND ticket.customer_id=approval.customer_id
          JOIN public.conversation_turns turn_row
            ON turn_row.tenant_id=approval.tenant_id
           AND turn_row.ticket_id=approval.ticket_id
           AND turn_row.id=approval.origin_turn_id
           AND turn_row.run_id=approval.run_id
          LEFT JOIN LATERAL (
            SELECT coalesce(
              pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                  'id',bounded_message.id,
                  'turn_id',bounded_message.turn_id,
                  'is_origin_turn',bounded_message.turn_id=turn_row.id,
                  'kind',bounded_message.message_kind,
                  'role',CASE WHEN bounded_message.role='user' THEN 'customer'
                    ELSE bounded_message.role END,
                  'content',bounded_message.content,
                  'sequence',bounded_message.conversation_sequence,
                  'created_at',bounded_message.created_at
                ) ORDER BY bounded_message.conversation_sequence,
                  bounded_message.id
              ) FILTER (WHERE bounded_message.source_ordinal<=100),
              '[]'::jsonb
            ) AS messages,
            least(pg_catalog.count(*),100) AS returned,
            pg_catalog.count(*)>100 AS has_more
            FROM (
              SELECT message.id,message.turn_id,message.message_kind,
                message.role,message.content,message.conversation_sequence,
                message.created_at,
                pg_catalog.row_number() OVER (
                  ORDER BY message.conversation_sequence,message.id
                ) AS source_ordinal
              FROM public.ticket_messages message
              JOIN public.conversation_turns source_turn
                ON source_turn.tenant_id=message.tenant_id
               AND source_turn.ticket_id=message.ticket_id
               AND source_turn.id=message.turn_id
              WHERE message.tenant_id=approval.tenant_id
                AND message.ticket_id=approval.ticket_id
                AND message.message_kind IN ('customer','assistant')
              ORDER BY message.conversation_sequence,message.id
              LIMIT 101
            ) bounded_message
          ) source_window ON true
          WHERE approval.tenant_id=current_setting('app.tenant_id',true)
            AND approval.id=p_approval_id;
          RETURN v_result;
        END
        $$;


ALTER FUNCTION public.supportguard_api_get_approval_source(p_approval_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_approval_source(text, bigint, text, integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_approval_source(p_approval_id text, p_before_sequence bigint, p_before_message_id text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
        DECLARE
          v_tenant_id text := current_setting('app.tenant_id',true);
          v_ticket_id text;
          v_title text;
          v_origin_turn_id text;
          v_origin_ordinal integer;
          v_messages jsonb;
          v_returned integer;
          v_has_more boolean;
          v_next_before_sequence bigint;
          v_next_before_message_id text;
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF current_setting('app.principal_role',true)
             NOT IN ('approver','support_approver') THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='approver_role_required';
          END IF;
          IF p_approval_id IS NULL OR p_approval_id=''
             OR p_limit NOT BETWEEN 1 AND 100
             OR (p_before_sequence IS NULL)<>(p_before_message_id IS NULL)
             OR (p_before_sequence IS NOT NULL AND p_before_sequence<1)
             OR (p_before_message_id IS NOT NULL AND p_before_message_id
                 !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$') THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='approval_source_cursor_invalid';
          END IF;

          SELECT ticket.id,coalesce(ticket.title,'未命名对话'),
            origin_turn.id,origin_turn.ordinal
          INTO v_ticket_id,v_title,v_origin_turn_id,v_origin_ordinal
          FROM public.approval_requests approval
          JOIN public.support_tickets ticket
            ON ticket.tenant_id=approval.tenant_id
           AND ticket.id=approval.ticket_id
           AND ticket.customer_id=approval.customer_id
          JOIN public.conversation_turns origin_turn
            ON origin_turn.tenant_id=approval.tenant_id
           AND origin_turn.ticket_id=approval.ticket_id
           AND origin_turn.id=approval.origin_turn_id
           AND origin_turn.run_id=approval.run_id
          WHERE approval.tenant_id=v_tenant_id
            AND approval.id=p_approval_id;
          IF NOT FOUND THEN
            RETURN NULL;
          END IF;

          IF p_before_sequence IS NOT NULL AND NOT EXISTS (
            SELECT 1
            FROM public.ticket_messages cursor_message
            JOIN public.conversation_turns cursor_turn
              ON cursor_turn.tenant_id=cursor_message.tenant_id
             AND cursor_turn.ticket_id=cursor_message.ticket_id
             AND cursor_turn.id=cursor_message.turn_id
            WHERE cursor_message.tenant_id=v_tenant_id
              AND cursor_message.ticket_id=v_ticket_id
              AND cursor_message.id=p_before_message_id
              AND cursor_message.conversation_sequence=p_before_sequence
              AND cursor_message.message_kind IN ('customer','assistant')
              AND cursor_turn.ordinal<=v_origin_ordinal
          ) THEN
            RETURN pg_catalog.jsonb_build_object(
              'error_code','approval_source_cursor_conflict'
            );
          END IF;

          SELECT coalesce(
              pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                  'id',page.id,
                  'turn_id',page.turn_id,
                  'is_origin_turn',page.turn_id=v_origin_turn_id,
                  'kind',page.message_kind,
                  'role',CASE WHEN page.role='user' THEN 'customer' ELSE page.role END,
                  'content',pg_catalog.left(page.content,8000),
                  'sequence',page.conversation_sequence,
                  'created_at',page.created_at
                ) ORDER BY page.conversation_sequence,page.id
              ) FILTER (WHERE page.page_ordinal<=p_limit),
              '[]'::jsonb
            ),
            least(pg_catalog.count(*),p_limit)::integer,
            pg_catalog.count(*)>p_limit,
            max(page.conversation_sequence)
              FILTER (WHERE page.page_ordinal=p_limit),
            max(page.id) FILTER (WHERE page.page_ordinal=p_limit)
          INTO v_messages,v_returned,v_has_more,
            v_next_before_sequence,v_next_before_message_id
          FROM (
            SELECT message.id,message.turn_id,message.message_kind,message.role,
              message.content,message.conversation_sequence,message.created_at,
              pg_catalog.row_number() OVER (
                ORDER BY message.conversation_sequence DESC,message.id DESC
              ) AS page_ordinal
            FROM public.ticket_messages message
            JOIN public.conversation_turns source_turn
              ON source_turn.tenant_id=message.tenant_id
             AND source_turn.ticket_id=message.ticket_id
             AND source_turn.id=message.turn_id
            WHERE message.tenant_id=v_tenant_id
              AND message.ticket_id=v_ticket_id
              AND message.conversation_sequence IS NOT NULL
              AND message.message_kind IN ('customer','assistant')
              AND source_turn.ordinal<=v_origin_ordinal
              AND (
                p_before_sequence IS NULL
                OR message.conversation_sequence<p_before_sequence
                OR (
                  message.conversation_sequence=p_before_sequence
                  AND message.id<p_before_message_id
                )
              )
            ORDER BY message.conversation_sequence DESC,message.id DESC
            LIMIT p_limit+1
          ) page;

          IF p_before_sequence IS NULL AND NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_messages) message(value)
            WHERE message.value->>'turn_id'=v_origin_turn_id
          ) THEN
            RETURN NULL;
          END IF;

          RETURN pg_catalog.jsonb_build_object(
            'approval_id',p_approval_id,
            'ticket_id',v_ticket_id,
            'title',v_title,
            'origin_turn_id',v_origin_turn_id,
            'messages',v_messages,
            'returned',v_returned,
            'has_more',v_has_more,
            'next_before_sequence',CASE WHEN v_has_more
              THEN v_next_before_sequence ELSE NULL END,
            'next_before_message_id',CASE WHEN v_has_more
              THEN v_next_before_message_id ELSE NULL END
          );
        END
        $_$;


ALTER FUNCTION public.supportguard_api_get_approval_source(p_approval_id text, p_before_sequence bigint, p_before_message_id text, p_limit integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_conversation(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_conversation(p_customer_id text, p_conversation_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_result jsonb;
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security_definer_session_user_forbidden';
          END IF;
          SELECT pg_catalog.jsonb_build_object(
            'id',t.id,'title',coalesce(t.title,'未命名对话'),'lifecycle',t.lifecycle,
            'automation_mode',t.automation_mode,'activity_label',
CASE
  WHEN EXISTS(SELECT 1 FROM public.approval_requests a WHERE a.tenant_id=t.tenant_id AND a.ticket_id=t.id AND a.status IN ('approved','executing')) THEN '正在执行已批准操作'
  WHEN EXISTS(SELECT 1 FROM public.approval_requests a WHERE a.tenant_id=t.tenant_id AND a.ticket_id=t.id AND a.status='pending') THEN '等待审批'
  WHEN EXISTS(SELECT 1 FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id AND x.activity_state='running') THEN '正在处理'
  WHEN EXISTS(SELECT 1 FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id AND x.activity_state='queued') THEN '排队中'
  WHEN t.automation_mode='human_queue' THEN '自动处理已停止'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='needs_clarification' THEN '需要补充信息'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='refused' THEN '请求未执行'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='failed' THEN '本轮未完成'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='proposal_created' THEN '等待审批'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='answered_limited' THEN '已给出有限结论' WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='answered' THEN '已回答'
  WHEN t.lifecycle='archived' THEN '已归档'
  ELSE '等待处理'
END
,
            'allowed_actions',CASE WHEN t.lifecycle='active' THEN jsonb_build_array('append_message','archive') ELSE jsonb_build_array('restore') END,
            'turns',coalesce((SELECT jsonb_agg(jsonb_build_object(
              'id',ct.id,'ordinal',ct.ordinal,'activity_state',ct.activity_state,'result_state',ct.result_state,'run_id',ct.run_id,
              'messages',coalesce((SELECT jsonb_agg(jsonb_build_object(
                'id',m.id,'kind',m.message_kind,'role',CASE WHEN m.role='user' THEN 'customer' ELSE m.role END,
                'content',m.content,'sequence',m.conversation_sequence,'approval_id',m.approval_id,'created_at',m.created_at) ORDER BY m.conversation_sequence)
                FROM public.ticket_messages m WHERE m.tenant_id=ct.tenant_id AND m.turn_id=ct.id),'[]'::jsonb),
              'citations','[]'::jsonb,
              'run',CASE WHEN r.id IS NULL THEN NULL ELSE jsonb_build_object(
                'id',r.id,'status',r.status,'model',r.model,'provider_mode',r.provider_mode,
                'tool_call_mode',r.tool_call_mode,'finish_reason',r.agent_finish_reason,'error_code',r.error_code,
                'budgets',jsonb_build_object('tool_rounds',r.tool_rounds,'tool_attempts',r.tool_attempts,'llm_calls',r.llm_calls)) END
            ) ORDER BY ct.ordinal) FROM public.conversation_turns ct
              LEFT JOIN public.agent_runs r ON r.tenant_id=ct.tenant_id AND r.id=ct.run_id
              WHERE ct.tenant_id=t.tenant_id AND ct.ticket_id=t.id),'[]'::jsonb),
            'conversation_action_sources',coalesce((
      SELECT pg_catalog.jsonb_agg(
        selected.source_bundle
        ORDER BY selected.updated_at DESC,selected.created_at DESC,selected.id DESC
      )
      FROM (
        SELECT
          action_approval.id,
          action_approval.created_at,
          action_approval.updated_at,
          (
      SELECT pg_catalog.jsonb_build_object(
        'schema_version','conversation-action-source-bundle.v1',
        'approval',pg_catalog.jsonb_build_object(
          'id',action_approval.id,
          'tenant_id',action_approval.tenant_id,
          'ticket_id',action_approval.ticket_id,
          'customer_id',action_approval.customer_id,
          'proposal_id',action_approval.proposal_id,
          'run_id',action_approval.run_id,
          'action_type',action_approval.action_type,
          'resource_type',action_approval.resource_type,
          'resource_id',action_approval.resource_id,
          'origin_turn_id',action_approval.origin_turn_id,
          'business_version',action_approval.business_version,
          'status',action_approval.status,
          'status_version',action_approval.status_version,
          'expected_ticket_head_event_id',action_approval.expected_ticket_head_event_id,
          'expected_ticket_event_hash',action_approval.expected_ticket_event_hash,
          'transition_event_id',transition.value->>'id',
          'transition_event_hash',transition.value->>'event_hash',
          'transition_event_type',transition.value->>'event_type',
          'created_at',action_approval.created_at,
          'updated_at',action_approval.updated_at
        ),
        'proposal',(
          SELECT pg_catalog.jsonb_build_object(
            'id',proposal.id,
            'tenant_id',proposal.tenant_id,
            'run_id',proposal.run_id,
            'action_type',proposal.action_type,
            'resource_id',proposal.resource_id,
            'resource_version',proposal.resource_version,
            'status',proposal.status,
            'created_at',proposal.created_at,
            'updated_at',proposal.updated_at
          )
          FROM public.proposal_records proposal
          WHERE proposal.tenant_id=action_approval.tenant_id
            AND proposal.id=action_approval.proposal_id
          LIMIT 1
        ),
        'decision',(
          SELECT pg_catalog.jsonb_build_object(
            'id',decision.id,
            'tenant_id',decision.tenant_id,
            'approval_id',decision.approval_id,
            'decision',decision.decision,
            'canonical_event_id',decision.canonical_event_id,
            'canonical_event_hash',decision.canonical_event_hash,
            'created_at',decision.created_at,
            'updated_at',decision.updated_at
          )
          FROM public.human_decisions decision
          WHERE decision.tenant_id=action_approval.tenant_id
            AND decision.approval_id=action_approval.id
          ORDER BY decision.created_at DESC,decision.id DESC
          LIMIT 1
        ),
        'business_action',(
          SELECT pg_catalog.jsonb_build_object(
            'id',business_action.id,
            'tenant_id',business_action.tenant_id,
            'ticket_id',business_action.ticket_id,
            'customer_id',business_action.customer_id,
            'approval_id',business_action.approval_id,
            'action_type',business_action.action_type,
            'resource_id',business_action.resource_id,
            'resource_version',business_action.resource_version,
            'status',business_action.status,
            'canonical_event_id',business_action.canonical_event_id,
            'canonical_event_hash',business_action.canonical_event_hash,
            'created_at',business_action.created_at,
            'updated_at',business_action.updated_at
          )
          FROM public.business_actions business_action
          WHERE business_action.tenant_id=action_approval.tenant_id
            AND business_action.approval_id=action_approval.id
          ORDER BY business_action.created_at DESC,business_action.id DESC
          LIMIT 1
        ),
        'withdrawal',(
          SELECT pg_catalog.jsonb_build_object(
            'id',withdrawal.id,
            'tenant_id',withdrawal.tenant_id,
            'ticket_id',withdrawal.ticket_id,
            'customer_id',withdrawal.customer_id,
            'approval_id',withdrawal.approval_id,
            'proposal_id',withdrawal.proposal_id,
            'created_at',withdrawal.created_at,
            'updated_at',withdrawal.updated_at
          )
          FROM public.proposal_withdrawals withdrawal
          WHERE withdrawal.tenant_id=action_approval.tenant_id
            AND withdrawal.approval_id=action_approval.id
          ORDER BY withdrawal.created_at DESC,withdrawal.id DESC
          LIMIT 1
        ),
        'runtime_job',(
          SELECT pg_catalog.jsonb_build_object(
            'id',approval_job.id,
            'tenant_id',approval_job.tenant_id,
            'ticket_id',approval_job.ticket_id,
            'run_id',approval_job.run_id,
            'approval_id',approval_job.approval_id,
            'kind',approval_job.kind,
            'status',approval_job.status,
            'outcome',approval_job.outcome,
            'delivery_hold_reason',approval_job.delivery_hold_reason,
            'created_at',approval_job.created_at,
            'updated_at',approval_job.updated_at
          )
          FROM public.runtime_jobs approval_job
          WHERE approval_job.tenant_id=action_approval.tenant_id
            AND approval_job.approval_id=action_approval.id
            AND approval_job.kind='approval_resume'
          ORDER BY approval_job.created_at DESC,approval_job.id DESC
          LIMIT 1
        )
      )
      FROM (SELECT (
      SELECT pg_catalog.jsonb_build_object(
        'id',event.id,
        'event_hash',event.event_hash,
        'event_type',event.event_type
      )
      FROM public.agent_events event
      WHERE event.tenant_id=action_approval.tenant_id
        AND event.ticket_id=action_approval.ticket_id
        AND event.run_id=action_approval.run_id
        AND (
          (
            action_approval.status='withdrawn'
            AND event.event_type='proposal_withdrawn'
            AND event.payload->>'approval_id'=action_approval.id
          )
          OR (
            action_approval.status='stale'
            AND event.event_type IN (
              'runtime_action_reconciliation',
              'approval_staled_duplicate_identity'
            )
            AND event.payload->>'approval_id'=action_approval.id
          )
          OR (
            action_approval.status='failed'
            AND event.event_type='runtime_failed'
            AND EXISTS (
              SELECT 1
              FROM public.runtime_jobs failed_job
              WHERE failed_job.tenant_id=action_approval.tenant_id
                AND failed_job.id=event.job_id
                AND failed_job.ticket_id=action_approval.ticket_id
                AND failed_job.run_id=action_approval.run_id
                AND failed_job.approval_id=action_approval.id
            )
          )
        )
      ORDER BY event.ticket_sequence DESC,event.id DESC
      LIMIT 1
    ) AS value) transition
    ) AS source_bundle
        FROM public.approval_requests action_approval
        WHERE action_approval.tenant_id=t.tenant_id AND action_approval.customer_id=p_customer_id AND (action_approval.ticket_id=t.id OR EXISTS (SELECT 1 FROM public.ticket_messages action_alias WHERE action_alias.tenant_id=action_approval.tenant_id AND action_alias.ticket_id=t.id AND action_alias.approval_id=action_approval.id))
        ORDER BY action_approval.updated_at DESC,action_approval.created_at DESC,action_approval.id DESC
        LIMIT 100
      ) selected
    ),'[]'::jsonb),'pending_actions',coalesce((SELECT jsonb_agg(jsonb_build_object(
              'id',a.id,'turn_id',ct.id,'status',a.status,'action_type',a.action_type,
              'action_payload',CASE a.action_type WHEN 'refund' THEN pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object('billing_record_id',a.resource_id,'amount',coalesce((SELECT selected_display.action_payload FROM public.approval_action_revisions selected_display WHERE selected_display.tenant_id=a.tenant_id AND selected_display.approval_id=a.id AND selected_display.proposal_id=a.proposal_id AND selected_display.id=a.selected_revision_id AND selected_display.revision_number=a.selected_revision_number AND selected_display.resource_version=a.business_version LIMIT 1),a.action_payload)->'amount','currency',coalesce((SELECT selected_display.action_payload FROM public.approval_action_revisions selected_display WHERE selected_display.tenant_id=a.tenant_id AND selected_display.approval_id=a.id AND selected_display.proposal_id=a.proposal_id AND selected_display.id=a.selected_revision_id AND selected_display.revision_number=a.selected_revision_number AND selected_display.resource_version=a.business_version LIMIT 1),a.action_payload)->'currency')) WHEN 'api_key_revocation' THEN pg_catalog.jsonb_build_object('api_key_id',a.resource_id) WHEN 'entitlement_change' THEN pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object('subscription_id',a.resource_id,'target',coalesce((SELECT selected_display.action_payload FROM public.approval_action_revisions selected_display WHERE selected_display.tenant_id=a.tenant_id AND selected_display.approval_id=a.id AND selected_display.proposal_id=a.proposal_id AND selected_display.id=a.selected_revision_id AND selected_display.revision_number=a.selected_revision_number AND selected_display.resource_version=a.business_version LIMIT 1),a.action_payload)->'target')) ELSE pg_catalog.jsonb_build_object('resource_id',a.resource_id) END,'allowed_actions',CASE WHEN a.status='pending' THEN jsonb_build_array('withdraw') ELSE '[]'::jsonb END,
              'created_at',a.created_at) ORDER BY a.created_at,a.id)
              FROM public.approval_requests a LEFT JOIN public.conversation_turns ct ON ct.tenant_id=a.tenant_id AND ct.run_id=a.run_id
              WHERE a.tenant_id=t.tenant_id AND a.customer_id=p_customer_id AND (a.ticket_id=t.id OR EXISTS (SELECT 1 FROM public.ticket_messages action_alias WHERE action_alias.tenant_id=a.tenant_id AND action_alias.ticket_id=t.id AND action_alias.approval_id=a.id))),'[]'::jsonb),
            'created_at',t.created_at,'updated_at',t.last_message_at)
          INTO v_result FROM public.support_tickets t
          WHERE t.tenant_id=current_setting('app.tenant_id',true) AND t.customer_id=p_customer_id AND t.id=p_conversation_id;
          RETURN v_result;
        END $$;


ALTER FUNCTION public.supportguard_api_get_conversation(p_customer_id text, p_conversation_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_conversation_page(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_conversation_page(p_customer_id text, p_conversation_id text, p_before_ordinal integer, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_result jsonb; v_returned integer; v_next_before_ordinal integer; v_has_more boolean;
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF p_limit NOT BETWEEN 1 AND 100 OR (p_before_ordinal IS NOT NULL AND p_before_ordinal<1) THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='conversation_page_invalid';
          END IF;
          SELECT pg_catalog.count(*),pg_catalog.min(page.ordinal)
          INTO v_returned,v_next_before_ordinal
          FROM (
            SELECT selected_turn.ordinal
            FROM public.conversation_turns selected_turn
            JOIN public.support_tickets selected_ticket
              ON selected_ticket.tenant_id=selected_turn.tenant_id
             AND selected_ticket.id=selected_turn.ticket_id
            WHERE selected_turn.tenant_id=current_setting('app.tenant_id',true)
              AND selected_ticket.customer_id=p_customer_id
              AND selected_ticket.id=p_conversation_id
              AND (p_before_ordinal IS NULL OR selected_turn.ordinal<p_before_ordinal)
            ORDER BY selected_turn.ordinal DESC,selected_turn.id DESC
            LIMIT p_limit
          ) page;
          SELECT EXISTS(
            SELECT 1
            FROM public.conversation_turns older_turn
            JOIN public.support_tickets selected_ticket
              ON selected_ticket.tenant_id=older_turn.tenant_id
             AND selected_ticket.id=older_turn.ticket_id
            WHERE older_turn.tenant_id=current_setting('app.tenant_id',true)
              AND selected_ticket.customer_id=p_customer_id
              AND selected_ticket.id=p_conversation_id
              AND v_next_before_ordinal IS NOT NULL
              AND older_turn.ordinal<v_next_before_ordinal
          ) INTO v_has_more;
          SELECT pg_catalog.jsonb_build_object(
            'id',t.id,'title',coalesce(t.title,'未命名对话'),'lifecycle',t.lifecycle,
            'automation_mode',t.automation_mode,'activity_label',
CASE
  WHEN EXISTS(SELECT 1 FROM public.approval_requests a WHERE a.tenant_id=t.tenant_id AND a.ticket_id=t.id AND a.status IN ('approved','executing')) THEN '正在执行已批准操作'
  WHEN EXISTS(SELECT 1 FROM public.approval_requests a WHERE a.tenant_id=t.tenant_id AND a.ticket_id=t.id AND a.status='pending') THEN '等待审批'
  WHEN EXISTS(SELECT 1 FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id AND x.activity_state='running') THEN '正在处理'
  WHEN EXISTS(SELECT 1 FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id AND x.activity_state='queued') THEN '排队中'
  WHEN t.automation_mode='human_queue' THEN '自动处理已停止'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='needs_clarification' THEN '需要补充信息'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='refused' THEN '请求未执行'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='failed' THEN '本轮未完成'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='proposal_created' THEN '等待审批'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='answered_limited' THEN '已给出有限结论' WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='answered' THEN '已回答'
  WHEN t.lifecycle='archived' THEN '已归档'
  ELSE '等待处理'
END
,
            'allowed_actions',CASE WHEN t.lifecycle='active' THEN jsonb_build_array('append_message','archive') ELSE jsonb_build_array('restore') END,
            'turns',coalesce((SELECT pg_catalog.jsonb_agg(
              pg_catalog.jsonb_build_object(
                'id',ct.id,'ordinal',ct.ordinal,
                'activity_state',ct.activity_state,'result_state',ct.result_state,
                'run_id',ct.run_id,
                'messages',coalesce((SELECT pg_catalog.jsonb_agg(
                  pg_catalog.jsonb_build_object(
                    'id',m.id,'kind',m.message_kind,
                    'role',CASE WHEN m.role='user' THEN 'customer' ELSE m.role END,
                    'content',m.content,'sequence',m.conversation_sequence,
                    'approval_id',m.approval_id,'created_at',m.created_at
                  ) ORDER BY m.conversation_sequence)
                  FROM public.ticket_messages m
                  WHERE m.tenant_id=ct.tenant_id AND m.turn_id=ct.id
                ),'[]'::jsonb),
                'citations',CASE WHEN ct.run_id IS NULL THEN '[]'::jsonb
                  ELSE public.supportguard_api_get_run_citations(
                    p_customer_id,ct.run_id
                  ) END,
                'run',CASE WHEN r.id IS NULL THEN NULL ELSE
                  pg_catalog.jsonb_build_object(
                    'id',r.id,'status',r.status,'model',r.model,
                    'provider_mode',r.provider_mode,
                    'tool_call_mode',r.tool_call_mode,
                    'finish_reason',r.agent_finish_reason,
                    'error_code',r.error_code,
                    'budgets',pg_catalog.jsonb_build_object(
                      'tool_rounds',r.tool_rounds,
                      'tool_attempts',r.tool_attempts,
                      'llm_calls',r.llm_calls
                    )
                  ) END
              ) ORDER BY ct.ordinal)
              FROM (
                SELECT selected_turn.*
                FROM public.conversation_turns selected_turn
                WHERE selected_turn.tenant_id=t.tenant_id
                  AND selected_turn.ticket_id=t.id
                  AND (
                    p_before_ordinal IS NULL
                    OR selected_turn.ordinal<p_before_ordinal
                  )
                ORDER BY selected_turn.ordinal DESC,selected_turn.id DESC
                LIMIT p_limit
              ) ct
              LEFT JOIN public.agent_runs r
                ON r.tenant_id=ct.tenant_id AND r.id=ct.run_id
            ),'[]'::jsonb),
            'turn_pagination',pg_catalog.jsonb_build_object(
              'limit',p_limit,
              'returned',v_returned,
              'has_more',v_has_more,
              'next_before_ordinal',CASE WHEN v_has_more
                THEN v_next_before_ordinal ELSE NULL END
            ),
            'conversation_action_sources',coalesce((
      SELECT pg_catalog.jsonb_agg(
        selected.source_bundle
        ORDER BY selected.updated_at DESC,selected.created_at DESC,selected.id DESC
      )
      FROM (
        SELECT
          action_approval.id,
          action_approval.created_at,
          action_approval.updated_at,
          (
      SELECT pg_catalog.jsonb_build_object(
        'schema_version','conversation-action-source-bundle.v1',
        'approval',pg_catalog.jsonb_build_object(
          'id',action_approval.id,
          'tenant_id',action_approval.tenant_id,
          'ticket_id',action_approval.ticket_id,
          'customer_id',action_approval.customer_id,
          'proposal_id',action_approval.proposal_id,
          'run_id',action_approval.run_id,
          'action_type',action_approval.action_type,
          'resource_type',action_approval.resource_type,
          'resource_id',action_approval.resource_id,
          'origin_turn_id',action_approval.origin_turn_id,
          'business_version',action_approval.business_version,
          'status',action_approval.status,
          'status_version',action_approval.status_version,
          'expected_ticket_head_event_id',action_approval.expected_ticket_head_event_id,
          'expected_ticket_event_hash',action_approval.expected_ticket_event_hash,
          'transition_event_id',transition.value->>'id',
          'transition_event_hash',transition.value->>'event_hash',
          'transition_event_type',transition.value->>'event_type',
          'created_at',action_approval.created_at,
          'updated_at',action_approval.updated_at
        ),
        'proposal',(
          SELECT pg_catalog.jsonb_build_object(
            'id',proposal.id,
            'tenant_id',proposal.tenant_id,
            'run_id',proposal.run_id,
            'action_type',proposal.action_type,
            'resource_id',proposal.resource_id,
            'resource_version',proposal.resource_version,
            'status',proposal.status,
            'created_at',proposal.created_at,
            'updated_at',proposal.updated_at
          )
          FROM public.proposal_records proposal
          WHERE proposal.tenant_id=action_approval.tenant_id
            AND proposal.id=action_approval.proposal_id
          LIMIT 1
        ),
        'decision',(
          SELECT pg_catalog.jsonb_build_object(
            'id',decision.id,
            'tenant_id',decision.tenant_id,
            'approval_id',decision.approval_id,
            'decision',decision.decision,
            'canonical_event_id',decision.canonical_event_id,
            'canonical_event_hash',decision.canonical_event_hash,
            'created_at',decision.created_at,
            'updated_at',decision.updated_at
          )
          FROM public.human_decisions decision
          WHERE decision.tenant_id=action_approval.tenant_id
            AND decision.approval_id=action_approval.id
          ORDER BY decision.created_at DESC,decision.id DESC
          LIMIT 1
        ),
        'business_action',(
          SELECT pg_catalog.jsonb_build_object(
            'id',business_action.id,
            'tenant_id',business_action.tenant_id,
            'ticket_id',business_action.ticket_id,
            'customer_id',business_action.customer_id,
            'approval_id',business_action.approval_id,
            'action_type',business_action.action_type,
            'resource_id',business_action.resource_id,
            'resource_version',business_action.resource_version,
            'status',business_action.status,
            'canonical_event_id',business_action.canonical_event_id,
            'canonical_event_hash',business_action.canonical_event_hash,
            'created_at',business_action.created_at,
            'updated_at',business_action.updated_at
          )
          FROM public.business_actions business_action
          WHERE business_action.tenant_id=action_approval.tenant_id
            AND business_action.approval_id=action_approval.id
          ORDER BY business_action.created_at DESC,business_action.id DESC
          LIMIT 1
        ),
        'withdrawal',(
          SELECT pg_catalog.jsonb_build_object(
            'id',withdrawal.id,
            'tenant_id',withdrawal.tenant_id,
            'ticket_id',withdrawal.ticket_id,
            'customer_id',withdrawal.customer_id,
            'approval_id',withdrawal.approval_id,
            'proposal_id',withdrawal.proposal_id,
            'created_at',withdrawal.created_at,
            'updated_at',withdrawal.updated_at
          )
          FROM public.proposal_withdrawals withdrawal
          WHERE withdrawal.tenant_id=action_approval.tenant_id
            AND withdrawal.approval_id=action_approval.id
          ORDER BY withdrawal.created_at DESC,withdrawal.id DESC
          LIMIT 1
        ),
        'runtime_job',(
          SELECT pg_catalog.jsonb_build_object(
            'id',approval_job.id,
            'tenant_id',approval_job.tenant_id,
            'ticket_id',approval_job.ticket_id,
            'run_id',approval_job.run_id,
            'approval_id',approval_job.approval_id,
            'kind',approval_job.kind,
            'status',approval_job.status,
            'outcome',approval_job.outcome,
            'delivery_hold_reason',approval_job.delivery_hold_reason,
            'created_at',approval_job.created_at,
            'updated_at',approval_job.updated_at
          )
          FROM public.runtime_jobs approval_job
          WHERE approval_job.tenant_id=action_approval.tenant_id
            AND approval_job.approval_id=action_approval.id
            AND approval_job.kind='approval_resume'
          ORDER BY approval_job.created_at DESC,approval_job.id DESC
          LIMIT 1
        )
      )
      FROM (SELECT (
      SELECT pg_catalog.jsonb_build_object(
        'id',event.id,
        'event_hash',event.event_hash,
        'event_type',event.event_type
      )
      FROM public.agent_events event
      WHERE event.tenant_id=action_approval.tenant_id
        AND event.ticket_id=action_approval.ticket_id
        AND event.run_id=action_approval.run_id
        AND (
          (
            action_approval.status='withdrawn'
            AND event.event_type='proposal_withdrawn'
            AND event.payload->>'approval_id'=action_approval.id
          )
          OR (
            action_approval.status='stale'
            AND event.event_type IN (
              'runtime_action_reconciliation',
              'approval_staled_duplicate_identity'
            )
            AND event.payload->>'approval_id'=action_approval.id
          )
          OR (
            action_approval.status='failed'
            AND event.event_type='runtime_failed'
            AND EXISTS (
              SELECT 1
              FROM public.runtime_jobs failed_job
              WHERE failed_job.tenant_id=action_approval.tenant_id
                AND failed_job.id=event.job_id
                AND failed_job.ticket_id=action_approval.ticket_id
                AND failed_job.run_id=action_approval.run_id
                AND failed_job.approval_id=action_approval.id
            )
          )
        )
      ORDER BY event.ticket_sequence DESC,event.id DESC
      LIMIT 1
    ) AS value) transition
    ) AS source_bundle
        FROM public.approval_requests action_approval
        WHERE action_approval.tenant_id=t.tenant_id AND action_approval.customer_id=p_customer_id AND (action_approval.ticket_id=t.id OR EXISTS (SELECT 1 FROM public.ticket_messages action_alias WHERE action_alias.tenant_id=action_approval.tenant_id AND action_alias.ticket_id=t.id AND action_alias.approval_id=action_approval.id))
        ORDER BY action_approval.updated_at DESC,action_approval.created_at DESC,action_approval.id DESC
        LIMIT 100
      ) selected
    ),'[]'::jsonb),'pending_actions',coalesce((SELECT jsonb_agg(jsonb_build_object(
              'id',a.id,'turn_id',ct.id,'status',a.status,'action_type',a.action_type,
              'action_payload',CASE a.action_type WHEN 'refund' THEN pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object('billing_record_id',a.resource_id,'amount',coalesce((SELECT selected_display.action_payload FROM public.approval_action_revisions selected_display WHERE selected_display.tenant_id=a.tenant_id AND selected_display.approval_id=a.id AND selected_display.proposal_id=a.proposal_id AND selected_display.id=a.selected_revision_id AND selected_display.revision_number=a.selected_revision_number AND selected_display.resource_version=a.business_version LIMIT 1),a.action_payload)->'amount','currency',coalesce((SELECT selected_display.action_payload FROM public.approval_action_revisions selected_display WHERE selected_display.tenant_id=a.tenant_id AND selected_display.approval_id=a.id AND selected_display.proposal_id=a.proposal_id AND selected_display.id=a.selected_revision_id AND selected_display.revision_number=a.selected_revision_number AND selected_display.resource_version=a.business_version LIMIT 1),a.action_payload)->'currency')) WHEN 'api_key_revocation' THEN pg_catalog.jsonb_build_object('api_key_id',a.resource_id) WHEN 'entitlement_change' THEN pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object('subscription_id',a.resource_id,'target',coalesce((SELECT selected_display.action_payload FROM public.approval_action_revisions selected_display WHERE selected_display.tenant_id=a.tenant_id AND selected_display.approval_id=a.id AND selected_display.proposal_id=a.proposal_id AND selected_display.id=a.selected_revision_id AND selected_display.revision_number=a.selected_revision_number AND selected_display.resource_version=a.business_version LIMIT 1),a.action_payload)->'target')) ELSE pg_catalog.jsonb_build_object('resource_id',a.resource_id) END,'allowed_actions',CASE WHEN a.status='pending' THEN jsonb_build_array('withdraw') ELSE '[]'::jsonb END,
              'created_at',a.created_at) ORDER BY a.created_at,a.id)
              FROM public.approval_requests a LEFT JOIN public.conversation_turns ct ON ct.tenant_id=a.tenant_id AND ct.run_id=a.run_id
              WHERE a.tenant_id=t.tenant_id AND a.customer_id=p_customer_id AND (a.ticket_id=t.id OR EXISTS (SELECT 1 FROM public.ticket_messages action_alias WHERE action_alias.tenant_id=a.tenant_id AND action_alias.ticket_id=t.id AND action_alias.approval_id=a.id))),'[]'::jsonb),
            'created_at',t.created_at,'updated_at',t.last_message_at)
          INTO v_result FROM public.support_tickets t
          WHERE t.tenant_id=current_setting('app.tenant_id',true) AND t.customer_id=p_customer_id AND t.id=p_conversation_id;
          RETURN v_result;
        END $$;


ALTER FUNCTION public.supportguard_api_get_conversation_page(p_customer_id text, p_conversation_id text, p_before_ordinal integer, p_limit integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_run(text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_run(p_run_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_result jsonb;
        BEGIN
          IF session_user <> 'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          SELECT pg_catalog.jsonb_build_object(
            'id',r.id,'ticket_id',r.ticket_id,'status',r.status,
            'status_version',r.status_version,'finish_reason',r.agent_finish_reason,
            'checkpoint_stage',r.checkpoint_stage,'model',r.model,
            'provider_mode',r.provider_mode,'tool_call_mode',r.tool_call_mode,
            'configured_runtime',pg_catalog.jsonb_build_object(
              'model',r.model,'provider_mode',r.provider_mode,
              'tool_call_mode',r.tool_call_mode,'source','command_acceptance'),
            'actual_runtime',(SELECT pg_catalog.jsonb_strip_nulls(
              pg_catalog.jsonb_build_object(
                'model',a.runtime_provenance->'model',
                'provider',a.runtime_provenance->'provider',
                'provider_mode',a.runtime_provenance->'provider_mode',
                'tool_call_mode',a.runtime_provenance->'tool_call_mode',
                'context_version',a.runtime_provenance->'context_version',
                'code_version',a.runtime_provenance->'code_version',
                'runtime_manifest_hash',a.runtime_provenance->'runtime_manifest_hash',
                'prompt_version',a.runtime_provenance->'prompt_version',
                'prompt_hash',a.runtime_provenance->'prompt_hash',
                'schema_version',a.runtime_provenance->'schema_version',
                'schema_hash',a.runtime_provenance->'schema_hash',
                'context_assembly_version',a.runtime_provenance->'context_assembly_version',
                'knowledge_index_contract',a.runtime_provenance->'knowledge_index_contract',
                'embedding_fingerprint',a.runtime_provenance->'embedding_fingerprint',
                'code_commit',a.runtime_provenance->'code_commit',
                'provider_transport_attempts',a.runtime_provenance->'provider_transport_attempts',
                'provider_retry_count',a.runtime_provenance->'provider_retry_count',
                'attempt_id',a.id,'attempt_status',a.status,
                'source','agent_call_attempt'))
              FROM public.agent_call_attempts a
              WHERE a.tenant_id=r.tenant_id AND a.run_id=r.id AND a.call_kind='llm'
              ORDER BY a.created_at DESC,a.id DESC LIMIT 1),
            'knowledge_index_version',r.knowledge_index_version,
            'error_code',r.error_code,'created_at',r.created_at,'completed_at',r.completed_at,
            'budgets',pg_catalog.jsonb_build_object('tool_rounds',r.tool_rounds,
              'tool_attempts',r.tool_attempts,'llm_calls',r.llm_calls),
            'job',(SELECT pg_catalog.jsonb_build_object('id',j.id,'kind',j.kind,
              'status',j.status,'attempt',j.attempt,'has_error',(j.last_error IS NOT NULL),
              'failure_category',r.error_code,'outcome',j.outcome)
              FROM public.runtime_jobs j WHERE j.tenant_id=r.tenant_id AND j.run_id=r.id
              ORDER BY j.created_at DESC,j.id DESC LIMIT 1))
            INTO v_result
          FROM public.agent_runs r
          WHERE r.tenant_id=current_setting('app.tenant_id',true) AND r.id=p_run_id;
          RETURN v_result;
        END $$;


ALTER FUNCTION public.supportguard_api_get_run(p_run_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_run(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_run(p_customer_id text, p_run_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF current_setting('app.principal_role',true)
             NOT IN ('customer','customer_member','customer_admin') THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='customer_role_required';
          END IF;
          IF p_customer_id IS NULL OR p_customer_id=''
             OR p_run_id IS NULL OR p_run_id='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='run_query_input_invalid';
          END IF;
          IF current_setting('app.subject_customer_id',true) IS DISTINCT FROM
             p_customer_id THEN
            RETURN NULL;
          END IF;
          IF NOT EXISTS(
            SELECT 1
            FROM public.agent_runs run
            WHERE run.tenant_id=current_setting('app.tenant_id',true)
              AND run.customer_id=p_customer_id
              AND run.id=p_run_id
          ) THEN
            RETURN NULL;
          END IF;
          RETURN public.supportguard_api_get_run(p_run_id);
        END
        $$;


ALTER FUNCTION public.supportguard_api_get_run(p_customer_id text, p_run_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_run_citations(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_run_citations(p_customer_id text, p_run_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF NOT EXISTS(SELECT 1 FROM public.agent_runs r
            WHERE r.tenant_id=current_setting('app.tenant_id',true)
              AND r.customer_id=p_customer_id AND r.id=p_run_id) THEN
            RETURN '[]'::jsonb;
          END IF;
          RETURN coalesce((SELECT jsonb_agg(items.payload ORDER BY items.ordinal,items.binding_key)
            FROM (
              SELECT 1 AS ordinal,b.id AS binding_key,
                ev.value || jsonb_build_object(
                  'source_type','knowledge','citation_binding_id',b.id,
                  'claim_id',c.id,'claim_summary',c.claim_text,
                  'message_id',(SELECT m.id FROM public.ticket_messages m
                    WHERE m.tenant_id=c.tenant_id AND m.run_id=c.run_id
                      AND m.message_kind='assistant'
                      AND m.publication_key='assistant:'||c.run_id LIMIT 1),
                  'binding_purpose','answer_claim') AS payload
              FROM public.claim_records c
              CROSS JOIN LATERAL jsonb_array_elements_text(
                coalesce((c.support_refs->'citation_binding_ids')::jsonb,'[]'::jsonb)
              ) claim_binding(binding_id)
              JOIN public.citation_bindings b ON b.tenant_id=c.tenant_id AND b.run_id=c.run_id AND b.id=claim_binding.binding_id
              JOIN public.tool_observations o ON o.tenant_id=b.tenant_id AND o.run_id=b.run_id AND o.id=b.observation_id
              CROSS JOIN LATERAL jsonb_array_elements(
                coalesce((o.payload->'data'->'evidence')::jsonb,'[]'::jsonb)
              ) ev(value)
              WHERE c.tenant_id=current_setting('app.tenant_id',true) AND c.run_id=p_run_id
                AND c.status='validated' AND ev.value->'source_locator'->>'locator_hash'=b.locator_hash
              UNION ALL
              SELECT 2 AS ordinal,c.id||':'||src.source_id AS binding_key,
                jsonb_strip_nulls(jsonb_build_object(
                  'source_type','business_fact',
                  'document_id',src.source_id,
                  'observation_source_id',src.source_id,
                  'version',coalesce(nullif(o.payload->>'resource_version',''),nullif(o.payload->'data'->>'version',''),nullif(o.payload->'data'->>'business_version','')),
                  'title',CASE o.payload->>'tool_name'
                    WHEN 'query_account' THEN '客户账户状态'
                    WHEN 'query_api_usage' THEN 'API 使用情况'
                    WHEN 'query_service_status' THEN '服务状态'
                    WHEN 'query_incident_impact' THEN '事故影响'
                    WHEN 'query_request_trace' THEN '请求追踪结果'
                    WHEN 'query_billing_record' THEN '账单状态'
                    WHEN 'query_api_key_metadata' THEN 'API Key 元数据'
                    WHEN 'query_subscription' THEN '套餐与配额'
                    ELSE '实时业务事实' END,
                  'section_path','当前业务事实','supporting_span',c.claim_text,
                  'claim_id',c.id,'claim_summary',c.claim_text,
                  'message_id',(SELECT m.id FROM public.ticket_messages m
                    WHERE m.tenant_id=c.tenant_id AND m.run_id=c.run_id
                      AND m.message_kind='assistant'
                      AND m.publication_key='assistant:'||c.run_id LIMIT 1),
                  'observed_at',o.payload->'observed_at',
                  'freshness',o.payload->'freshness_status','status',o.payload->'status',
                  'binding_purpose','answer_claim')) AS payload
              FROM public.claim_records c
              CROSS JOIN LATERAL jsonb_array_elements_text(
                coalesce((c.support_refs->'observation_source_ids')::jsonb,'[]'::jsonb)
              ) src(source_id)
              JOIN public.tool_observations o ON o.tenant_id=c.tenant_id AND o.run_id=c.run_id
              WHERE c.tenant_id=current_setting('app.tenant_id',true) AND c.run_id=p_run_id
                AND c.status='validated' AND EXISTS(
                  SELECT 1 FROM jsonb_array_elements(
                    coalesce((o.payload->'source_refs')::jsonb,'[]'::jsonb)
                  ) ref(value)
                  WHERE ref.value->>'source_id'=src.source_id)
              LIMIT 50
            ) items),'[]'::jsonb);
        END $$;


ALTER FUNCTION public.supportguard_api_get_run_citations(p_customer_id text, p_run_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_run_inspector(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_run_inspector(p_customer_id text, p_conversation_id text, p_turn_id text, p_message_id text, p_run_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_result jsonb;
          v_run jsonb;
          v_citations jsonb;
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF current_setting('app.principal_role',true)
             NOT IN ('customer','customer_member','customer_admin') THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='customer_role_required';
          END IF;
          IF p_customer_id IS NULL OR p_customer_id=''
             OR p_conversation_id IS NULL OR p_conversation_id=''
             OR p_turn_id IS NULL OR p_turn_id=''
             OR p_message_id IS NULL OR p_message_id=''
             OR p_run_id IS NULL OR p_run_id='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='run_inspector_input_invalid';
          END IF;
          IF current_setting('app.subject_customer_id',true) IS DISTINCT FROM
             p_customer_id THEN
            RETURN NULL;
          END IF;

          SELECT public.supportguard_api_get_run(p_run_id)
          INTO v_run
          FROM public.support_tickets ticket
          JOIN public.conversation_turns turn_row
            ON turn_row.tenant_id=ticket.tenant_id
           AND turn_row.ticket_id=ticket.id
           AND turn_row.id=p_turn_id
           AND turn_row.run_id=p_run_id
          JOIN public.agent_runs run_row
            ON run_row.tenant_id=turn_row.tenant_id
           AND run_row.ticket_id=turn_row.ticket_id
           AND run_row.customer_id=ticket.customer_id
           AND run_row.turn_id=turn_row.id
           AND run_row.id=turn_row.run_id
          JOIN public.ticket_messages message
            ON message.tenant_id=turn_row.tenant_id
           AND message.ticket_id=turn_row.ticket_id
           AND message.turn_id=turn_row.id
           AND message.run_id=run_row.id
           AND message.id=p_message_id
           AND message.message_kind='assistant'
          WHERE ticket.tenant_id=current_setting('app.tenant_id',true)
            AND ticket.customer_id=p_customer_id
            AND ticket.id=p_conversation_id;
          IF v_run IS NULL THEN
            RETURN NULL;
          END IF;

          v_citations:=public.supportguard_api_get_run_citations(
            p_customer_id,p_run_id
          );
          SELECT pg_catalog.jsonb_build_object(
            'message_id',p_message_id,
            'turn_id',p_turn_id,
            'run_id',p_run_id,
            'run',v_run,
            'timeline',coalesce((
              SELECT pg_catalog.jsonb_agg(event_payload.payload
                ORDER BY event_payload.ticket_sequence)
              FROM (
                SELECT event.ticket_sequence,
                  pg_catalog.jsonb_build_object(
                    'id',event.id,
                    'event_type',event.event_type,
                    'payload',pg_catalog.jsonb_strip_nulls(
                      pg_catalog.jsonb_build_object(
                        'tool_name',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            event.payload::jsonb->'tool_name'
                          )='string'
                          THEN event.payload::jsonb->'tool_name' ELSE NULL END,
                        'freshness_status',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            event.payload::jsonb->'freshness_status'
                          )='string'
                          THEN event.payload::jsonb->'freshness_status' ELSE NULL END,
                        'route',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            event.payload::jsonb->'route'
                          )='string'
                          THEN event.payload::jsonb->'route' ELSE NULL END,
                        'error_code',CASE WHEN event.payload::jsonb ? 'error_code'
                          THEN 'redacted' ELSE NULL END,
                        'agent_finish_reason',CASE
                          WHEN event.payload::jsonb ? 'agent_finish_reason'
                          THEN 'recorded' ELSE NULL END,
                        'action_type',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            event.payload::jsonb->'action_type'
                          )='string'
                          THEN event.payload::jsonb->'action_type' ELSE NULL END,
                        'source_count',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            event.payload::jsonb->'source_count'
                          )='number'
                          THEN event.payload::jsonb->'source_count' ELSE NULL END,
                        'injected_tool_allowlist',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            event.payload::jsonb->'injected_tool_allowlist'
                          )='array'
                          THEN event.payload::jsonb->'injected_tool_allowlist' ELSE NULL END,
                        'injected_tools',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            event.payload::jsonb->'injected_tools'
                          )='array'
                          THEN event.payload::jsonb->'injected_tools' ELSE NULL END,
                        'remaining_budget',CASE
                          WHEN pg_catalog.jsonb_typeof(
                            event.payload::jsonb->'remaining_budget'
                          )='object'
                          THEN pg_catalog.jsonb_strip_nulls(
                            pg_catalog.jsonb_build_object(
                              'llm_calls',
                                event.payload::jsonb->'remaining_budget'->'llm_calls',
                              'tool_rounds',
                                event.payload::jsonb->'remaining_budget'->'tool_rounds',
                              'tool_attempts',
                                event.payload::jsonb->'remaining_budget'->'tool_attempts'
                            )
                          ) ELSE NULL END
                      )
                    ),
                    'run_id',event.run_id,
                    'sequence',event.sequence,
                    'ticket_sequence',event.ticket_sequence,
                    'run_sequence',event.run_sequence,
                    'step_index',event.step_index,
                    'tool_round',event.tool_round,
                    'tool_call_id',event.tool_call_id,
                    'status',event.status,
                    'created_at',event.created_at
                  ) AS payload
                FROM public.agent_events event
                WHERE event.tenant_id=current_setting('app.tenant_id',true)
                  AND event.ticket_id=p_conversation_id
                  AND event.run_id=p_run_id
                  AND event.visibility='customer'
                ORDER BY event.ticket_sequence
                LIMIT 500
              ) event_payload
            ),'[]'::jsonb),
            'knowledge_sources',coalesce((
              SELECT pg_catalog.jsonb_agg(citation.value)
              FROM pg_catalog.jsonb_array_elements(
                coalesce(v_citations,'[]'::jsonb)
              ) citation(value)
              WHERE citation.value->>'message_id'=p_message_id
                AND coalesce(citation.value->>'source_type','knowledge')
                    ='knowledge'
            ),'[]'::jsonb),
            'business_facts',coalesce((
              SELECT pg_catalog.jsonb_agg(citation.value)
              FROM pg_catalog.jsonb_array_elements(
                coalesce(v_citations,'[]'::jsonb)
              ) citation(value)
              WHERE citation.value->>'message_id'=p_message_id
                AND citation.value->>'source_type'='business_fact'
            ),'[]'::jsonb)
          ) INTO v_result;
          RETURN v_result;
        END
        $$;


ALTER FUNCTION public.supportguard_api_get_run_inspector(p_customer_id text, p_conversation_id text, p_turn_id text, p_message_id text, p_run_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_ticket(text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_ticket(p_ticket_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_result jsonb;
          v_latest_run_id text;
          v_knowledge_total bigint := 0;
          v_message_total bigint := 0;
          v_timeline_total bigint := 0;
          v_fact_total bigint := 0;
        BEGIN
          IF session_user <> 'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          SELECT r.id INTO v_latest_run_id
          FROM public.agent_runs r
          WHERE r.tenant_id=current_setting('app.tenant_id',true)
            AND r.ticket_id=p_ticket_id
          ORDER BY r.created_at DESC,r.id DESC LIMIT 1;

          SELECT pg_catalog.count(*) INTO v_message_total FROM (
            SELECT 1 FROM public.ticket_messages count_message
            WHERE count_message.tenant_id=current_setting('app.tenant_id',true)
              AND count_message.ticket_id=p_ticket_id LIMIT 101
          ) observed_messages;
          SELECT pg_catalog.count(*) INTO v_timeline_total FROM (
            SELECT 1 FROM public.agent_events count_event
            WHERE count_event.tenant_id=current_setting('app.tenant_id',true)
              AND count_event.ticket_id=p_ticket_id
              AND count_event.run_id=v_latest_run_id
              AND count_event.visibility='customer' LIMIT 201
          ) observed_timeline;
          SELECT pg_catalog.count(*) INTO v_fact_total FROM (
            SELECT 1 FROM public.agent_events count_fact
            WHERE count_fact.tenant_id=current_setting('app.tenant_id',true)
              AND count_fact.ticket_id=p_ticket_id
              AND count_fact.run_id=v_latest_run_id
              AND count_fact.visibility='customer'
              AND count_fact.event_type='tool_observation'
              AND count_fact.payload->>'tool_name'<>'search_knowledge' LIMIT 51
          ) observed_facts;

          SELECT pg_catalog.count(*) INTO v_knowledge_total
          FROM (SELECT DISTINCT b.id
            FROM public.claim_records c
            CROSS JOIN LATERAL pg_catalog.jsonb_array_elements_text(
              coalesce(c.support_refs::jsonb->'citation_binding_ids','[]'::jsonb)
            ) ref(binding_id)
            JOIN public.citation_bindings b
              ON b.tenant_id=c.tenant_id AND b.run_id=c.run_id AND b.id=ref.binding_id
            JOIN public.tool_observations o
              ON o.tenant_id=b.tenant_id AND o.run_id=b.run_id
             AND o.id=b.observation_id AND o.status='ok'
            CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
              coalesce(o.payload::jsonb #> '{data,evidence}','[]'::jsonb)
            ) ev(item)
            WHERE c.tenant_id=current_setting('app.tenant_id',true)
              AND c.run_id=v_latest_run_id AND c.status='validated'
              AND ev.item #>> '{source_locator,locator_hash}'=b.locator_hash
            LIMIT 51
          ) source_count;

          SELECT pg_catalog.jsonb_build_object(
            'id',t.id,'status',t.status,'issue_type',t.issue_type,'risk',t.risk,
            'version',t.version,'final_response',CASE
              WHEN EXISTS (SELECT 1 FROM public.agent_runs current_run
                WHERE current_run.tenant_id=t.tenant_id
                  AND current_run.id=v_latest_run_id
                  AND current_run.status='completed')
              THEN t.final_response ELSE NULL END,
            'title',coalesce((SELECT pg_catalog.left(
              pg_catalog.regexp_replace(m.content,'[[:space:]]+',' ','g'),80)
              FROM public.ticket_messages m
              WHERE m.tenant_id=t.tenant_id AND m.ticket_id=t.id
                AND m.role IN ('user','customer')
              ORDER BY m.created_at,m.id LIMIT 1),'未命名工单'),
            'appendable',t.status IN ('open','needs_clarification'),
            'allowed_actions',CASE WHEN t.status IN ('open','needs_clarification')
              THEN pg_catalog.jsonb_build_array('append_message','new_ticket')
              ELSE pg_catalog.jsonb_build_array('new_ticket_from_context') END,
            'created_at',t.created_at,'updated_at',t.updated_at,
            'messages',coalesce((SELECT pg_catalog.jsonb_agg(
              pg_catalog.jsonb_build_object('id',m.id,
                'role',CASE WHEN m.role='user' THEN 'customer' ELSE m.role END,
                'content',m.content,
                'created_at',m.created_at) ORDER BY m.created_at,m.id)
              FROM (SELECT * FROM public.ticket_messages bounded_message
                WHERE bounded_message.tenant_id=t.tenant_id
                  AND bounded_message.ticket_id=t.id
                ORDER BY bounded_message.created_at DESC,bounded_message.id DESC
                LIMIT 100) m),'[]'::jsonb),
            'summary',(SELECT pg_catalog.jsonb_build_object(
              'confirmed_facts',s.confirmed_facts,'attempted_actions',s.attempted_actions,
              'open_questions',s.open_questions,
              'freshness_at',s.freshness_at,'expires_at',s.expires_at)
              FROM public.ticket_summaries s
              WHERE s.tenant_id=t.tenant_id AND s.ticket_id=t.id),
            'latest_run',(SELECT pg_catalog.jsonb_build_object(
              'id',r.id,'status',r.status,'status_version',r.status_version,
              'finish_reason',r.agent_finish_reason,'checkpoint_stage',r.checkpoint_stage,
              'model',r.model,'provider_mode',r.provider_mode,
              'tool_call_mode',r.tool_call_mode,
              'configured_runtime',pg_catalog.jsonb_build_object(
                'model',r.model,'provider_mode',r.provider_mode,
                'tool_call_mode',r.tool_call_mode,'source','command_acceptance'),
              'actual_runtime',(SELECT pg_catalog.jsonb_strip_nulls(
                pg_catalog.jsonb_build_object(
                  'model',a.runtime_provenance->'model',
                  'provider',a.runtime_provenance->'provider',
                  'provider_mode',a.runtime_provenance->'provider_mode',
                  'tool_call_mode',a.runtime_provenance->'tool_call_mode',
                  'context_version',a.runtime_provenance->'context_version',
                  'code_version',a.runtime_provenance->'code_version',
                  'runtime_manifest_hash',a.runtime_provenance->'runtime_manifest_hash',
                  'prompt_version',a.runtime_provenance->'prompt_version',
                  'prompt_hash',a.runtime_provenance->'prompt_hash',
                  'schema_version',a.runtime_provenance->'schema_version',
                  'schema_hash',a.runtime_provenance->'schema_hash',
                  'context_assembly_version',a.runtime_provenance->'context_assembly_version',
                  'knowledge_index_contract',a.runtime_provenance->'knowledge_index_contract',
                  'embedding_fingerprint',a.runtime_provenance->'embedding_fingerprint',
                  'code_commit',a.runtime_provenance->'code_commit',
                  'provider_transport_attempts',a.runtime_provenance->'provider_transport_attempts',
                  'provider_retry_count',a.runtime_provenance->'provider_retry_count',
                  'attempt_id',a.id,'attempt_status',a.status,
                  'source','agent_call_attempt'))
                FROM public.agent_call_attempts a
                WHERE a.tenant_id=r.tenant_id AND a.run_id=r.id AND a.call_kind='llm'
                ORDER BY a.ordinal DESC,a.created_at DESC,a.id DESC LIMIT 1),
              'knowledge_index_version',r.knowledge_index_version,
              'budgets',pg_catalog.jsonb_build_object('tool_rounds',r.tool_rounds,
                'tool_attempts',r.tool_attempts,'llm_calls',r.llm_calls),
              'error_code',r.error_code,'created_at',r.created_at,
              'completed_at',r.completed_at,
              'job',(SELECT pg_catalog.jsonb_build_object('id',j.id,'kind',j.kind,
                'status',j.status,'attempt',j.attempt,'has_error',(j.last_error IS NOT NULL),
                'failure_category',r.error_code,'outcome',j.outcome)
                FROM public.runtime_jobs j
                WHERE j.tenant_id=r.tenant_id AND j.run_id=r.id
                ORDER BY j.created_at DESC,j.id DESC LIMIT 1))
              FROM public.agent_runs r
              WHERE r.tenant_id=t.tenant_id AND r.id=v_latest_run_id),
            'timeline',coalesce((SELECT pg_catalog.jsonb_agg(
              pg_catalog.jsonb_build_object('id',e.id,'event_type',e.event_type,
                'payload',pg_catalog.jsonb_strip_nulls(
                  pg_catalog.jsonb_build_object(
                    'tool_name',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'tool_name'
                    )='string' THEN e.payload::jsonb->'tool_name' END,
                    'freshness_status',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'freshness_status'
                    )='string' THEN e.payload::jsonb->'freshness_status' END,
                    'route',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'route'
                    )='string' THEN e.payload::jsonb->'route' END,
                    'error_code',CASE WHEN e.payload::jsonb ? 'error_code'
                      THEN 'redacted' END,
                    'agent_finish_reason',CASE
                      WHEN e.payload::jsonb ? 'agent_finish_reason'
                      THEN 'recorded' END,
                    'action_type',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'action_type'
                    )='string' THEN e.payload::jsonb->'action_type' END,
                    'source_count',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'source_count'
                    )='number' THEN e.payload::jsonb->'source_count' END,
                    'injected_tool_allowlist',CASE
                      WHEN pg_catalog.jsonb_typeof(
                        e.payload::jsonb->'injected_tool_allowlist'
                      )='array' THEN e.payload::jsonb->'injected_tool_allowlist' END,
                    'injected_tools',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'injected_tools'
                    )='array' THEN e.payload::jsonb->'injected_tools' END,
                    'remaining_budget',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'remaining_budget'
                    )='object' THEN pg_catalog.jsonb_strip_nulls(
                      pg_catalog.jsonb_build_object(
                        'llm_calls',e.payload::jsonb->'remaining_budget'->'llm_calls',
                        'tool_rounds',e.payload::jsonb->'remaining_budget'->'tool_rounds',
                        'tool_attempts',e.payload::jsonb->'remaining_budget'->'tool_attempts'
                      )
                    ) END
                  )
                ),
                'run_id',e.run_id,'ticket_sequence',e.ticket_sequence,
                'run_sequence',e.run_sequence,'step_index',e.step_index,
                'tool_round',e.tool_round,'tool_call_id',e.tool_call_id,
                'status',e.status,'created_at',e.created_at) ORDER BY e.ticket_sequence)
              FROM (SELECT * FROM public.agent_events bounded_event
                WHERE bounded_event.tenant_id=t.tenant_id
                  AND bounded_event.ticket_id=t.id
                  AND bounded_event.run_id=v_latest_run_id
                  AND bounded_event.visibility='customer'
                ORDER BY bounded_event.ticket_sequence DESC LIMIT 200) e),'[]'::jsonb),
            'knowledge_sources',coalesce((SELECT pg_catalog.jsonb_agg(
                source.item ORDER BY source.binding_id)
              FROM (SELECT DISTINCT b.id AS binding_id,
                  pg_catalog.jsonb_set(ev.item,'{citation_binding_id}',
                    pg_catalog.to_jsonb(b.id),true)
                  || pg_catalog.jsonb_build_object('binding_purpose','answer_claim') AS item
                FROM public.claim_records c
                CROSS JOIN LATERAL pg_catalog.jsonb_array_elements_text(
                  coalesce(c.support_refs::jsonb->'citation_binding_ids','[]'::jsonb)
                ) ref(binding_id)
                JOIN public.citation_bindings b
                  ON b.tenant_id=c.tenant_id AND b.run_id=c.run_id
                 AND b.id=ref.binding_id
                JOIN public.tool_observations o
                  ON o.tenant_id=b.tenant_id AND o.run_id=b.run_id
                 AND o.id=b.observation_id AND o.status='ok'
                CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
                  coalesce(o.payload::jsonb #> '{data,evidence}','[]'::jsonb)
                ) ev(item)
                WHERE c.tenant_id=t.tenant_id AND c.run_id=v_latest_run_id
                  AND c.status='validated'
                  AND ev.item #>> '{source_locator,locator_hash}'=b.locator_hash
                ORDER BY b.id LIMIT 50) source),'[]'::jsonb),
            'business_facts',coalesce((SELECT pg_catalog.jsonb_agg(
              pg_catalog.jsonb_build_object('tool_name',e.payload->>'tool_name',
                'status',e.payload->>'status','observed_at',e.payload->>'observed_at',
                'fact_summary',pg_catalog.jsonb_strip_nulls(
                  pg_catalog.jsonb_build_object(
                    'status',e.payload::jsonb->'data'->'status',
                    'plan',e.payload::jsonb->'data'->'plan',
                    'region',e.payload::jsonb->'data'->'region',
                    'currency',e.payload::jsonb->'data'->'currency',
                    'amount',e.payload::jsonb->'data'->'amount',
                    'limit',e.payload::jsonb->'data'->'limit',
                    'current_limit',e.payload::jsonb->'data'->'current_limit',
                    'requested_limit',e.payload::jsonb->'data'->'requested_limit',
                    'window',e.payload::jsonb->'data'->'window',
                    'request_status',e.payload::jsonb->'data'->'request_status',
                    'impact',e.payload::jsonb->'data'->'impact',
                    'service',e.payload::jsonb->'data'->'service'
                  )
                ))
                ORDER BY e.ticket_sequence)
              FROM (SELECT * FROM public.agent_events bounded_fact
                WHERE bounded_fact.tenant_id=t.tenant_id
                  AND bounded_fact.ticket_id=t.id
                  AND bounded_fact.run_id=v_latest_run_id
                  AND bounded_fact.visibility='customer'
                  AND bounded_fact.event_type='tool_observation'
                  AND bounded_fact.payload->>'tool_name'<>'search_knowledge'
                ORDER BY bounded_fact.ticket_sequence DESC LIMIT 50) e),'[]'::jsonb),
            'approval',(SELECT pg_catalog.jsonb_build_object('id',a.id,
              'status',a.status,'action_type',a.action_type)
              FROM public.approval_requests a
              WHERE a.tenant_id=t.tenant_id AND a.ticket_id=t.id
                AND a.run_id=v_latest_run_id
              ORDER BY a.created_at DESC,a.id DESC LIMIT 1),
            'business_action',(SELECT pg_catalog.jsonb_build_object('id',b.id,
              'status',b.status,'action_type',b.action_type,
              'resource_id',b.resource_id,'resource_version',b.resource_version,
              'created_at',b.created_at)
              FROM public.business_actions b
              JOIN public.approval_requests a
                ON a.tenant_id=b.tenant_id AND a.id=b.approval_id
              WHERE a.tenant_id=t.tenant_id AND a.ticket_id=t.id
                AND a.run_id=v_latest_run_id
              ORDER BY b.created_at DESC,b.id DESC LIMIT 1),
            'aggregation',pg_catalog.jsonb_build_object(
              'messages',pg_catalog.jsonb_build_object('limit',100,'returned',least(100,
                v_message_total),'total',v_message_total,
                'total_is_exact',v_message_total<=100,
                'has_more',v_message_total>100,'boundary',NULL),
              'timeline',pg_catalog.jsonb_build_object('limit',200,
                'returned',least(200,v_timeline_total),'total',v_timeline_total,
                'total_is_exact',v_timeline_total<=200,
                'has_more',v_timeline_total>200,'boundary',NULL),
              'knowledge_sources',pg_catalog.jsonb_build_object('limit',50,
                'returned',least(50,v_knowledge_total),'total',v_knowledge_total,
                'total_is_exact',v_knowledge_total<=50,
                'has_more',v_knowledge_total>50,'boundary',NULL),
              'business_facts',pg_catalog.jsonb_build_object('limit',50,
                'returned',least(50,v_fact_total),'total',v_fact_total,
                'total_is_exact',v_fact_total<=50,
                'has_more',v_fact_total>50,'boundary',NULL))
          ) INTO v_result
          FROM public.support_tickets t
          WHERE t.tenant_id=current_setting('app.tenant_id',true) AND t.id=p_ticket_id;
          RETURN v_result;
        END $$;


ALTER FUNCTION public.supportguard_api_get_ticket(p_ticket_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_get_ticket(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_get_ticket(p_customer_id text, p_ticket_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF current_setting('app.principal_role',true)
             NOT IN ('customer','customer_member','customer_admin') THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='customer_role_required';
          END IF;
          IF p_customer_id IS NULL OR p_customer_id=''
             OR p_ticket_id IS NULL OR p_ticket_id='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='ticket_query_input_invalid';
          END IF;
          IF current_setting('app.subject_customer_id',true) IS DISTINCT FROM
             p_customer_id THEN
            RETURN NULL;
          END IF;
          IF NOT EXISTS(
            SELECT 1
            FROM public.support_tickets ticket
            WHERE ticket.tenant_id=current_setting('app.tenant_id',true)
              AND ticket.customer_id=p_customer_id
              AND ticket.id=p_ticket_id
          ) THEN
            RETURN NULL;
          END IF;
          RETURN public.supportguard_api_get_ticket(p_ticket_id);
        END
        $$;


ALTER FUNCTION public.supportguard_api_get_ticket(p_customer_id text, p_ticket_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_list_approvals(integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_list_approvals(p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF session_user <> 'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF p_limit NOT BETWEEN 1 AND 200 THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='api_limit_invalid';
          END IF;
          IF current_setting('app.principal_role',true)
             NOT IN ('approver','support_approver') THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='approver_role_required';
          END IF;
          RETURN coalesce((SELECT pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'id',a.id,
              'ticket_id',a.ticket_id,
              'source_label',coalesce((SELECT source_ticket.title FROM public.support_tickets source_ticket WHERE source_ticket.tenant_id=a.tenant_id AND source_ticket.id=a.ticket_id AND source_ticket.customer_id=a.customer_id LIMIT 1),a.ticket_id),
              'status',a.status,
              'action_type',a.action_type,
              'resource_summary',coalesce(
                a.action_payload->>'billing_record_id',
                a.action_payload->>'api_key_id',
                a.action_payload->>'subscription_id',
                a.action_payload->>'resource_id',
                '受保护资源'
              ),
              'risk',coalesce(a.review_context->>'risk','high'),
              'actionable',coalesce((
                a.status='pending'
                AND r.status='interrupted'
                AND r.checkpoint_stage='awaiting_approval'
                AND r.checkpoint_id=a.checkpoint_id
                AND p.status='bound'
                AND m.status='finalized'
                AND r.canonical_checkpoint_ns=a.canonical_checkpoint_ns
                AND r.canonical_checkpoint_hash=a.canonical_checkpoint_hash
              ),false),
              'conversation_action_sources',(
      SELECT pg_catalog.jsonb_build_object(
        'schema_version','conversation-action-source-bundle.v1',
        'approval',pg_catalog.jsonb_build_object(
          'id',a.id,
          'tenant_id',a.tenant_id,
          'ticket_id',a.ticket_id,
          'customer_id',a.customer_id,
          'proposal_id',a.proposal_id,
          'run_id',a.run_id,
          'action_type',a.action_type,
          'resource_type',a.resource_type,
          'resource_id',a.resource_id,
          'origin_turn_id',a.origin_turn_id,
          'business_version',a.business_version,
          'status',a.status,
          'status_version',a.status_version,
          'expected_ticket_head_event_id',a.expected_ticket_head_event_id,
          'expected_ticket_event_hash',a.expected_ticket_event_hash,
          'transition_event_id',transition.value->>'id',
          'transition_event_hash',transition.value->>'event_hash',
          'transition_event_type',transition.value->>'event_type',
          'created_at',a.created_at,
          'updated_at',a.updated_at
        ),
        'proposal',(
          SELECT pg_catalog.jsonb_build_object(
            'id',proposal.id,
            'tenant_id',proposal.tenant_id,
            'run_id',proposal.run_id,
            'action_type',proposal.action_type,
            'resource_id',proposal.resource_id,
            'resource_version',proposal.resource_version,
            'status',proposal.status,
            'created_at',proposal.created_at,
            'updated_at',proposal.updated_at
          )
          FROM public.proposal_records proposal
          WHERE proposal.tenant_id=a.tenant_id
            AND proposal.id=a.proposal_id
          LIMIT 1
        ),
        'decision',(
          SELECT pg_catalog.jsonb_build_object(
            'id',decision.id,
            'tenant_id',decision.tenant_id,
            'approval_id',decision.approval_id,
            'decision',decision.decision,
            'canonical_event_id',decision.canonical_event_id,
            'canonical_event_hash',decision.canonical_event_hash,
            'created_at',decision.created_at,
            'updated_at',decision.updated_at
          )
          FROM public.human_decisions decision
          WHERE decision.tenant_id=a.tenant_id
            AND decision.approval_id=a.id
          ORDER BY decision.created_at DESC,decision.id DESC
          LIMIT 1
        ),
        'business_action',(
          SELECT pg_catalog.jsonb_build_object(
            'id',business_action.id,
            'tenant_id',business_action.tenant_id,
            'ticket_id',business_action.ticket_id,
            'customer_id',business_action.customer_id,
            'approval_id',business_action.approval_id,
            'action_type',business_action.action_type,
            'resource_id',business_action.resource_id,
            'resource_version',business_action.resource_version,
            'status',business_action.status,
            'canonical_event_id',business_action.canonical_event_id,
            'canonical_event_hash',business_action.canonical_event_hash,
            'created_at',business_action.created_at,
            'updated_at',business_action.updated_at
          )
          FROM public.business_actions business_action
          WHERE business_action.tenant_id=a.tenant_id
            AND business_action.approval_id=a.id
          ORDER BY business_action.created_at DESC,business_action.id DESC
          LIMIT 1
        ),
        'withdrawal',(
          SELECT pg_catalog.jsonb_build_object(
            'id',withdrawal.id,
            'tenant_id',withdrawal.tenant_id,
            'ticket_id',withdrawal.ticket_id,
            'customer_id',withdrawal.customer_id,
            'approval_id',withdrawal.approval_id,
            'proposal_id',withdrawal.proposal_id,
            'created_at',withdrawal.created_at,
            'updated_at',withdrawal.updated_at
          )
          FROM public.proposal_withdrawals withdrawal
          WHERE withdrawal.tenant_id=a.tenant_id
            AND withdrawal.approval_id=a.id
          ORDER BY withdrawal.created_at DESC,withdrawal.id DESC
          LIMIT 1
        ),
        'runtime_job',(
          SELECT pg_catalog.jsonb_build_object(
            'id',approval_job.id,
            'tenant_id',approval_job.tenant_id,
            'ticket_id',approval_job.ticket_id,
            'run_id',approval_job.run_id,
            'approval_id',approval_job.approval_id,
            'kind',approval_job.kind,
            'status',approval_job.status,
            'outcome',approval_job.outcome,
            'delivery_hold_reason',approval_job.delivery_hold_reason,
            'created_at',approval_job.created_at,
            'updated_at',approval_job.updated_at
          )
          FROM public.runtime_jobs approval_job
          WHERE approval_job.tenant_id=a.tenant_id
            AND approval_job.approval_id=a.id
            AND approval_job.kind='approval_resume'
          ORDER BY approval_job.created_at DESC,approval_job.id DESC
          LIMIT 1
        )
      )
      FROM (SELECT (
      SELECT pg_catalog.jsonb_build_object(
        'id',event.id,
        'event_hash',event.event_hash,
        'event_type',event.event_type
      )
      FROM public.agent_events event
      WHERE event.tenant_id=a.tenant_id
        AND event.ticket_id=a.ticket_id
        AND event.run_id=a.run_id
        AND (
          (
            a.status='withdrawn'
            AND event.event_type='proposal_withdrawn'
            AND event.payload->>'approval_id'=a.id
          )
          OR (
            a.status='stale'
            AND event.event_type IN (
              'runtime_action_reconciliation',
              'approval_staled_duplicate_identity'
            )
            AND event.payload->>'approval_id'=a.id
          )
          OR (
            a.status='failed'
            AND event.event_type='runtime_failed'
            AND EXISTS (
              SELECT 1
              FROM public.runtime_jobs failed_job
              WHERE failed_job.tenant_id=a.tenant_id
                AND failed_job.id=event.job_id
                AND failed_job.ticket_id=a.ticket_id
                AND failed_job.run_id=a.run_id
                AND failed_job.approval_id=a.id
            )
          )
        )
      ORDER BY event.ticket_sequence DESC,event.id DESC
      LIMIT 1
    ) AS value) transition
    ),'created_at',a.created_at
            )
            ORDER BY (a.status='pending') DESC,a.created_at DESC,a.id DESC
          )
          FROM (
            SELECT *
            FROM public.approval_requests
            WHERE tenant_id=current_setting('app.tenant_id',true)
            ORDER BY (status='pending') DESC,created_at DESC,id DESC
            LIMIT p_limit
          ) a
          LEFT JOIN public.agent_runs r
            ON r.tenant_id=a.tenant_id AND r.id=a.run_id
          LEFT JOIN public.proposal_records p
            ON p.tenant_id=a.tenant_id AND p.id=a.proposal_id
          LEFT JOIN public.checkpoint_commit_markers m
            ON m.tenant_id=a.tenant_id AND m.id=a.marker_id
          ),'[]'::jsonb);
        END $$;


ALTER FUNCTION public.supportguard_api_list_approvals(p_limit integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_list_conversations(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_list_conversations(p_customer_id text, p_query text, p_cursor text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF session_user<>'supportguard_api' OR p_limit NOT BETWEEN 1 AND 50 THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='conversation_query_invalid';
          END IF;
          IF NOT EXISTS(SELECT 1 FROM public.customers c WHERE c.tenant_id=current_setting('app.tenant_id',true) AND c.id=p_customer_id) THEN
            RETURN pg_catalog.jsonb_build_object('items','[]'::jsonb,'next_cursor',NULL);
          END IF;
          RETURN (WITH selected AS (
            SELECT t.* FROM public.support_tickets t
            WHERE t.tenant_id=current_setting('app.tenant_id',true) AND t.customer_id=p_customer_id
              AND (p_query IS NULL OR p_query='' OR pg_catalog.to_tsvector('simple',coalesce(t.title,'')) @@ pg_catalog.plainto_tsquery('simple',p_query)
                OR t.title ILIKE '%'||p_query||'%' OR EXISTS(SELECT 1 FROM public.ticket_messages m WHERE m.tenant_id=t.tenant_id AND m.ticket_id=t.id AND (pg_catalog.to_tsvector('simple',m.content) @@ pg_catalog.plainto_tsquery('simple',p_query) OR m.content ILIKE '%'||p_query||'%')))
              AND (p_cursor IS NULL OR (t.last_message_at,t.id)<(SELECT c.last_message_at,c.id FROM public.support_tickets c WHERE c.tenant_id=t.tenant_id AND c.id=p_cursor))
            ORDER BY t.last_message_at DESC,t.id DESC LIMIT p_limit+1
          ), page AS (SELECT * FROM selected ORDER BY last_message_at DESC,id DESC LIMIT p_limit)
          SELECT pg_catalog.jsonb_build_object(
            'items',coalesce((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
              'id',t.id,'title',coalesce(t.title,'未命名对话'),'lifecycle',t.lifecycle,
              'automation_mode',t.automation_mode,'activity_label',
CASE
  WHEN EXISTS(SELECT 1 FROM public.approval_requests a WHERE a.tenant_id=t.tenant_id AND a.ticket_id=t.id AND a.status IN ('approved','executing')) THEN '正在执行已批准操作'
  WHEN EXISTS(SELECT 1 FROM public.approval_requests a WHERE a.tenant_id=t.tenant_id AND a.ticket_id=t.id AND a.status='pending') THEN '等待审批'
  WHEN EXISTS(SELECT 1 FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id AND x.activity_state='running') THEN '正在处理'
  WHEN EXISTS(SELECT 1 FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id AND x.activity_state='queued') THEN '排队中'
  WHEN t.automation_mode='human_queue' THEN '自动处理已停止'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='needs_clarification' THEN '需要补充信息'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='refused' THEN '请求未执行'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='failed' THEN '本轮未完成'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='proposal_created' THEN '等待审批'
  WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='answered_limited' THEN '已给出有限结论' WHEN (SELECT x.result_state FROM public.conversation_turns x WHERE x.tenant_id=t.tenant_id AND x.ticket_id=t.id ORDER BY x.ordinal DESC,x.id DESC LIMIT 1)='answered' THEN '已回答'
  WHEN t.lifecycle='archived' THEN '已归档'
  ELSE '等待处理'
END
,
              'latest_summary',(SELECT left(regexp_replace(m.content,'[[:space:]]+',' ','g'),120) FROM public.ticket_messages m WHERE m.tenant_id=t.tenant_id AND m.ticket_id=t.id ORDER BY m.conversation_sequence DESC,m.id DESC LIMIT 1),
              'pending_action_count',(SELECT count(*) FROM public.approval_requests a WHERE a.tenant_id=t.tenant_id AND a.ticket_id=t.id AND a.status IN ('pending','approved','executing')),
              'updated_at',t.last_message_at) ORDER BY t.last_message_at DESC,t.id DESC) FROM page t),'[]'::jsonb),
            'next_cursor',CASE WHEN (SELECT count(*) FROM selected)>p_limit THEN (SELECT id FROM page ORDER BY last_message_at,id LIMIT 1) ELSE NULL END));
        END $$;


ALTER FUNCTION public.supportguard_api_list_conversations(p_customer_id text, p_query text, p_cursor text, p_limit integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_list_ticket_events(text, bigint, integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_list_ticket_events(p_ticket_id text, p_after_sequence bigint, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
            BEGIN
              IF session_user <> 'supportguard_api' THEN
                RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security_definer_session_user_forbidden';
              END IF;
              IF p_after_sequence<0 OR p_limit NOT BETWEEN 1 AND 500 THEN
                RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='api_event_cursor_invalid';
              END IF;
              IF NOT EXISTS(SELECT 1 FROM public.support_tickets t
                WHERE t.tenant_id=current_setting('app.tenant_id',true) AND t.id=p_ticket_id) THEN
                RETURN NULL;
              END IF;
              RETURN coalesce((SELECT jsonb_agg(jsonb_build_object(
                'id',e.id,'event_type',e.event_type,
                'payload',pg_catalog.jsonb_strip_nulls(
                  pg_catalog.jsonb_build_object(
                    'action_type',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'action_type'
                    )='string' AND pg_catalog.char_length(
                      e.payload::jsonb->>'action_type'
                    ) BETWEEN 1 AND 64 THEN e.payload::jsonb->'action_type' END,
                    'freshness_status',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'freshness_status'
                    )='string' AND pg_catalog.char_length(
                      e.payload::jsonb->>'freshness_status'
                    ) BETWEEN 1 AND 64 THEN e.payload::jsonb->'freshness_status' END,
                    'outcome',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'outcome'
                    )='string' AND pg_catalog.char_length(
                      e.payload::jsonb->>'outcome'
                    ) BETWEEN 1 AND 64 THEN e.payload::jsonb->'outcome' END,
                    'projection_status',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'projection_status'
                    )='string' AND pg_catalog.char_length(
                      e.payload::jsonb->>'projection_status'
                    ) BETWEEN 1 AND 64 THEN e.payload::jsonb->'projection_status' END,
                    'route',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'route'
                    )='string' AND pg_catalog.char_length(
                      e.payload::jsonb->>'route'
                    ) BETWEEN 1 AND 64 THEN e.payload::jsonb->'route' END,
                    'tool_name',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'tool_name'
                    )='string' AND pg_catalog.char_length(
                      e.payload::jsonb->>'tool_name'
                    ) BETWEEN 1 AND 64 THEN e.payload::jsonb->'tool_name' END,
                    'source_count',CASE WHEN pg_catalog.jsonb_typeof(
                      e.payload::jsonb->'source_count'
                    )='number' AND (e.payload::jsonb->>'source_count')
                      ~ '^[0-9]+$' THEN CASE WHEN
                      (e.payload::jsonb->>'source_count')::numeric
                        BETWEEN 0 AND 100
                      THEN e.payload::jsonb->'source_count' END END
                  )
                ),'run_id',e.run_id,
                'sequence',e.sequence,'ticket_sequence',e.ticket_sequence,
                'run_sequence',e.run_sequence,'step_index',e.step_index,
                'tool_round',e.tool_round,'tool_call_id',e.tool_call_id,
                'status',e.status,'created_at',e.created_at) ORDER BY e.ticket_sequence)
                FROM (SELECT * FROM public.agent_events
                  WHERE tenant_id=current_setting('app.tenant_id',true)
                    AND ticket_id=p_ticket_id AND visibility='customer'
                    AND ticket_sequence>p_after_sequence
                  ORDER BY ticket_sequence LIMIT p_limit) e),'[]'::jsonb);
            END $_$;


ALTER FUNCTION public.supportguard_api_list_ticket_events(p_ticket_id text, p_after_sequence bigint, p_limit integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_list_ticket_events(text, text, bigint, integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_list_ticket_events(p_customer_id text, p_ticket_id text, p_after_sequence bigint, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF current_setting('app.principal_role',true)
             NOT IN ('customer','customer_member','customer_admin') THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='customer_role_required';
          END IF;
          IF p_customer_id IS NULL OR p_customer_id=''
             OR p_ticket_id IS NULL OR p_ticket_id='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='ticket_event_query_input_invalid';
          END IF;
          IF p_after_sequence<0 OR p_limit NOT BETWEEN 1 AND 500 THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='api_event_cursor_invalid';
          END IF;
          IF current_setting('app.subject_customer_id',true) IS DISTINCT FROM
             p_customer_id THEN
            RETURN NULL;
          END IF;
          IF NOT EXISTS(
            SELECT 1
            FROM public.support_tickets ticket
            WHERE ticket.tenant_id=current_setting('app.tenant_id',true)
              AND ticket.customer_id=p_customer_id
              AND ticket.id=p_ticket_id
          ) THEN
            RETURN NULL;
          END IF;
          RETURN public.supportguard_api_list_ticket_events(
            p_ticket_id,p_after_sequence,p_limit
          );
        END
        $$;


ALTER FUNCTION public.supportguard_api_list_ticket_events(p_customer_id text, p_ticket_id text, p_after_sequence bigint, p_limit integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_list_tickets(integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_list_tickets(p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF session_user <> 'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF p_limit NOT BETWEEN 1 AND 200 THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='api_limit_invalid';
          END IF;
          RETURN coalesce((SELECT pg_catalog.jsonb_agg(row ORDER BY row->>'updated_at' DESC)
            FROM (SELECT pg_catalog.jsonb_build_object(
              'id',t.id,'status',t.status,'issue_type',t.issue_type,'risk',t.risk,
              'title',coalesce((SELECT pg_catalog.left(
                pg_catalog.regexp_replace(m.content,'[[:space:]]+',' ','g'),80)
                FROM public.ticket_messages m
                WHERE m.tenant_id=t.tenant_id AND m.ticket_id=t.id
                  AND m.role IN ('user','customer')
                ORDER BY m.created_at,m.id LIMIT 1),'未命名工单'),
              'appendable',t.status IN ('open','needs_clarification'),
              'created_at',t.created_at,'updated_at',t.updated_at) row
              FROM public.support_tickets t
              WHERE t.tenant_id=current_setting('app.tenant_id',true)
              ORDER BY t.updated_at DESC LIMIT p_limit) q),'[]'::jsonb);
        END $$;


ALTER FUNCTION public.supportguard_api_list_tickets(p_limit integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_list_tickets(text, integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_list_tickets(p_customer_id text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF session_user<>'supportguard_api' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF current_setting('app.principal_role',true)
             NOT IN ('customer','customer_member','customer_admin') THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='customer_role_required';
          END IF;
          IF p_customer_id IS NULL OR p_customer_id='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='customer_id_invalid';
          END IF;
          IF p_limit NOT BETWEEN 1 AND 200 THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='api_limit_invalid';
          END IF;
          IF current_setting('app.subject_customer_id',true) IS DISTINCT FROM
             p_customer_id THEN
            RETURN '[]'::jsonb;
          END IF;
          RETURN coalesce((
            SELECT pg_catalog.jsonb_agg(row ORDER BY row->>'updated_at' DESC)
            FROM (
              SELECT pg_catalog.jsonb_build_object(
                'id',ticket.id,
                'status',ticket.status,
                'issue_type',ticket.issue_type,
                'risk',ticket.risk,
                'title',coalesce((
                  SELECT pg_catalog.left(
                    pg_catalog.regexp_replace(
                      message.content,'[[:space:]]+',' ','g'
                    ),
                    80
                  )
                  FROM public.ticket_messages message
                  WHERE message.tenant_id=ticket.tenant_id
                    AND message.ticket_id=ticket.id
                    AND message.role IN ('user','customer')
                  ORDER BY message.created_at,message.id
                  LIMIT 1
                ),'未命名工单'),
                'appendable',ticket.status IN ('open','needs_clarification'),
                'created_at',ticket.created_at,
                'updated_at',ticket.updated_at
              ) AS row
              FROM public.support_tickets ticket
              WHERE ticket.tenant_id=current_setting('app.tenant_id',true)
                AND ticket.customer_id=p_customer_id
              ORDER BY ticket.updated_at DESC
              LIMIT p_limit
            ) bounded
          ),'[]'::jsonb);
        END
        $$;


ALTER FUNCTION public.supportguard_api_list_tickets(p_customer_id text, p_limit integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_resolve_principal(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_resolve_principal(p_external_subject text, p_tenant_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_user_id text;
          v_user_name text;
          v_membership_role text;
          v_customer_id text;
          v_customer jsonb;
          v_subscription jsonb;
          v_tenant jsonb;
          v_accessible_tenants jsonb;
          v_match_count bigint;
        BEGIN
          IF session_user <> 'supportguard_api'
             OR p_external_subject IS NULL OR p_external_subject = ''
             OR p_tenant_id IS NULL OR p_tenant_id = ''
             OR p_external_subject IS DISTINCT FROM current_setting('app.principal_id', true)
             OR p_tenant_id IS DISTINCT FROM current_setting('app.tenant_id', true) THEN
            RETURN NULL;
          END IF;

          SELECT count(*), min(u.id), min(u.display_name), min(m.role)
            INTO v_match_count, v_user_id, v_user_name, v_membership_role
          FROM public.users u
          JOIN public.memberships m
            ON m.user_id = u.id
           AND m.tenant_id = p_tenant_id
           AND m.status = 'active'
          WHERE u.external_subject = p_external_subject OR u.id = p_external_subject;

          IF v_match_count <> 1
             OR v_membership_role NOT IN (
               'customer_member', 'customer_admin', 'support_approver'
             ) THEN
            RETURN NULL;
          END IF;

          SELECT pg_catalog.jsonb_build_object(
                   'id', tenant.id,
                   'name', tenant.name,
                   'status', tenant.status
                 )
            INTO v_tenant
          FROM public.tenants tenant
          WHERE tenant.id = p_tenant_id AND tenant.status = 'active';
          IF v_tenant IS NULL THEN
            RETURN NULL;
          END IF;

          IF v_membership_role = 'support_approver' THEN
            SELECT count(*) INTO v_match_count
            FROM public.approver_tenant_scopes scope
            WHERE scope.user_id = v_user_id AND scope.tenant_id = p_tenant_id;
            IF v_match_count <> 1 THEN
              RETURN NULL;
            END IF;
            v_customer_id := NULL;
            v_customer := NULL;
            v_subscription := NULL;
            SELECT coalesce(pg_catalog.jsonb_agg(
                     pg_catalog.jsonb_build_object('id', tenant.id, 'name', tenant.name, 'status', tenant.status)
                     ORDER BY tenant.name, tenant.id
                   ), '[]'::jsonb)
              INTO v_accessible_tenants
            FROM public.approver_tenant_scopes scope
            JOIN public.tenants tenant ON tenant.id = scope.tenant_id
            WHERE scope.user_id = v_user_id AND tenant.status = 'active';
          ELSE
            SELECT count(*), min(customer.id)
              INTO v_match_count, v_customer_id
            FROM public.customers customer
            WHERE customer.tenant_id = p_tenant_id AND customer.status = 'active';
            IF v_match_count <> 1 THEN
              RETURN NULL;
            END IF;
            SELECT pg_catalog.jsonb_build_object(
                     'id', customer.id,
                     'display_name', customer.display_name,
                     'status', customer.status,
                     'security_status', customer.security_status,
                     'region', customer.region,
                     'version', customer.version
                   )
              INTO v_customer
            FROM public.customers customer
            WHERE customer.tenant_id = p_tenant_id AND customer.id = v_customer_id;
            SELECT pg_catalog.jsonb_build_object(
                     'id', subscription.id,
                     'plan', subscription.plan,
                     'status', subscription.status,
                     'balance', subscription.balance,
                     'currency', subscription.currency,
                     'rpm_limit', subscription.rpm_limit,
                     'concurrency_limit', subscription.concurrency_limit,
                     'version', subscription.version
                   )
              INTO v_subscription
            FROM public.subscriptions subscription
            WHERE subscription.tenant_id = p_tenant_id
              AND subscription.customer_id = v_customer_id;
            v_accessible_tenants := pg_catalog.jsonb_build_array(v_tenant);
          END IF;

          RETURN pg_catalog.jsonb_build_object(
            'schema_version', 'principal-resolution.v2',
            'role', CASE WHEN v_membership_role = 'support_approver'
                         THEN 'approver' ELSE 'customer' END,
            'subject_id', v_user_id,
            'display_name', v_user_name,
            'tenant_id', p_tenant_id,
            'tenant', v_tenant,
            'customer_id', v_customer_id,
            'customer', v_customer,
            'subscription', v_subscription,
            'accessible_tenants', v_accessible_tenants,
            'membership_role', v_membership_role
          );
        END
        $$;


ALTER FUNCTION public.supportguard_api_resolve_principal(p_external_subject text, p_tenant_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_runtime_snapshot(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_runtime_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        BEGIN
            IF session_user <> 'supportguard_api' THEN
                RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='api capability caller is not authorized';
            END IF;
            RETURN supportguard_runtime_snapshot_internal(false);
        END $$;


ALTER FUNCTION public.supportguard_api_runtime_snapshot() OWNER TO supportguard_owner;

--
-- Name: supportguard_api_transition_conversation(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_transition_conversation(p_conversation_id text, p_lifecycle text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_tenant_id text := current_setting('app.tenant_id',true);
          v_principal_id text := current_setting('app.principal_id',true);
          v_ticket public.support_tickets%ROWTYPE;
          v_existing public.idempotency_requests%ROWTYPE;
          v_action text;
          v_route text;
          v_hash text;
          v_now timestamptz := clock_timestamp();
          v_response jsonb;
        BEGIN
          IF session_user<>'supportguard_api' OR p_lifecycle NOT IN ('active','archived')
             OR p_request IS NULL
             OR p_request - ARRAY['schema_version','customer_id','actor_id','idempotency_key','idempotency_id','audit_id','trace_id']::text[] <> '{}'::jsonb
             OR (SELECT count(*) FROM jsonb_object_keys(p_request))<>7
             OR p_request->>'schema_version'<>'api-transition-conversation.v1'
             OR p_request->>'actor_id' IS DISTINCT FROM v_principal_id
             OR coalesce(p_request->>'idempotency_key','')='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='conversation_lifecycle_invalid';
          END IF;
          SELECT * INTO v_ticket FROM public.support_tickets t
          WHERE t.tenant_id=v_tenant_id AND t.id=p_conversation_id
            AND t.customer_id=p_request->>'customer_id' FOR UPDATE;
          IF NOT FOUND THEN
            RETURN jsonb_build_object('error_code','conversation_not_found');
          END IF;
          v_action := CASE WHEN p_lifecycle='active' THEN 'restore' ELSE 'archive' END;
          v_route := 'POST /api/conversations/'||p_conversation_id||'/'||v_action;
          v_hash := md5(jsonb_build_object('lifecycle',p_lifecycle)::text);
          SELECT * INTO v_existing FROM public.idempotency_requests i
          WHERE i.tenant_id=v_tenant_id AND i.principal_id=v_principal_id
            AND i.route=v_route AND i.idempotency_key=p_request->>'idempotency_key' FOR UPDATE;
          IF FOUND THEN
            IF v_existing.request_hash<>v_hash THEN
              RETURN jsonb_build_object('error_code','idempotency_conflict');
            END IF;
            IF v_existing.response_snapshot::jsonb<>'{}'::jsonb THEN
              RETURN v_existing.response_snapshot::jsonb||jsonb_build_object('reused',true);
            END IF;
          ELSE
            INSERT INTO public.idempotency_requests(
              id,tenant_id,principal_id,route,idempotency_key,request_hash,status,
              resource_ids,response_snapshot,completed_at,retention_class,created_at,updated_at
            ) VALUES (
              p_request->>'idempotency_id',v_tenant_id,v_principal_id,v_route,
              p_request->>'idempotency_key',v_hash,'accepted','{}','{}',v_now,
              'low_risk_non_action',v_now,v_now
            );
          END IF;
          IF v_ticket.lifecycle<>p_lifecycle THEN
            UPDATE public.support_tickets SET lifecycle=p_lifecycle,version=version+1,
              updated_at=v_now WHERE tenant_id=v_tenant_id AND id=p_conversation_id;
            INSERT INTO public.audit_events(
              id,tenant_id,ticket_id,customer_id,event_type,actor_type,actor_ref,
              trace_id,payload,created_at
            ) VALUES (
              p_request->>'audit_id',v_tenant_id,v_ticket.id,v_ticket.customer_id,
              CASE WHEN p_lifecycle='active' THEN 'conversation_restored' ELSE 'conversation_archived' END,
              'customer',v_principal_id,p_request->>'trace_id',
              jsonb_build_object('lifecycle',p_lifecycle),v_now
            );
          END IF;
          v_response := jsonb_build_object(
            'schema_version','conversation-lifecycle.v1','conversation_id',v_ticket.id,
            'lifecycle',p_lifecycle,'accepted_at',v_now,'reused',false
          );
          UPDATE public.idempotency_requests SET
            resource_ids=jsonb_build_object('conversation_id',v_ticket.id),
            response_snapshot=v_response,completed_at=v_now,updated_at=v_now
          WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
            AND route=v_route AND idempotency_key=p_request->>'idempotency_key';
          RETURN v_response;
        END $$;


ALTER FUNCTION public.supportguard_api_transition_conversation(p_conversation_id text, p_lifecycle text, p_request jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_api_withdraw_proposal(text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_api_withdraw_proposal(p_approval_id text, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_tenant_id text:=current_setting('app.tenant_id',true);
          v_principal_id text:=current_setting('app.principal_id',true);
          v_route text;
          v_hash text;
          v_existing public.idempotency_requests%ROWTYPE;
          v_approval public.approval_requests%ROWTYPE;
          v_ticket public.support_tickets%ROWTYPE;
          v_proposal public.proposal_records%ROWTYPE;
          v_withdrawal public.proposal_withdrawals%ROWTYPE;
          v_run public.agent_runs%ROWTYPE;
          v_turn public.conversation_turns%ROWTYPE;
          v_parent public.agent_events%ROWTYPE;
          v_now timestamptz:=clock_timestamp();
          v_response jsonb;
          v_payload jsonb;
          v_payload_canonical text;
          v_payload_hash text;
          v_created_at_text text;
          v_envelope text;
          v_event_hash text;
          v_event_id text;
          v_ticket_sequence bigint;
          v_run_sequence bigint;
          v_inserted bigint:=0;
          v_claimed boolean:=false;
        BEGIN
          IF session_user<>'supportguard_api' OR p_request IS NULL
             OR p_request - ARRAY[
               'schema_version','customer_id','actor_id','idempotency_key','reason',
               'withdrawal_id','message_id','audit_id','idempotency_id','trace_id'
             ]::text[]<>'{}'::jsonb
             OR (SELECT count(*) FROM jsonb_object_keys(p_request))<>10
             OR p_request->>'schema_version'<>'api-withdraw-proposal.v1'
             OR p_request->>'actor_id' IS DISTINCT FROM v_principal_id
             OR coalesce(p_request->>'idempotency_key','')=''
             OR coalesce(p_request->>'reason','')='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='withdraw_proposal_invalid';
          END IF;

          SELECT * INTO v_approval
          FROM public.approval_requests
          WHERE tenant_id=v_tenant_id AND id=p_approval_id;
          IF v_approval.id IS NULL THEN
            RETURN jsonb_build_object('error_code','approval_not_found');
          END IF;
          v_route:='POST /api/conversations/'||v_approval.ticket_id
            ||'/actions/'||p_approval_id||'/withdraw';
          v_hash:=md5(jsonb_build_object('reason',p_request->>'reason')::text);
          INSERT INTO public.idempotency_requests(
            id,tenant_id,principal_id,route,idempotency_key,request_hash,status,
            resource_ids,response_snapshot,completed_at,retention_class,created_at,updated_at
          ) VALUES (
            p_request->>'idempotency_id',v_tenant_id,v_principal_id,v_route,
            p_request->>'idempotency_key',v_hash,'accepted','{}','{}',NULL,
            'protected_action',v_now,v_now
          ) ON CONFLICT ON CONSTRAINT uq_idempotency_request_scope DO NOTHING;
          GET DIAGNOSTICS v_inserted=ROW_COUNT;
          v_claimed:=v_inserted=1;
          SELECT * INTO v_existing
          FROM public.idempotency_requests
          WHERE tenant_id=v_tenant_id AND principal_id=v_principal_id
            AND route=v_route AND idempotency_key=p_request->>'idempotency_key'
          FOR UPDATE;
          IF v_existing.request_hash<>v_hash THEN
            RETURN jsonb_build_object('error_code','idempotency_conflict');
          END IF;
          IF NOT v_claimed THEN
            IF v_existing.response_snapshot::jsonb<>'{}'::jsonb THEN
              RETURN v_existing.response_snapshot::jsonb||jsonb_build_object('reused',true);
            END IF;
            RAISE EXCEPTION USING ERRCODE='40001',
              MESSAGE='idempotency_claim_incomplete';
          END IF;

          SELECT * INTO v_ticket
          FROM public.support_tickets
          WHERE tenant_id=v_tenant_id AND id=v_approval.ticket_id
            AND customer_id=p_request->>'customer_id'
          FOR UPDATE;
          IF v_ticket.id IS NULL THEN
            DELETE FROM public.idempotency_requests
            WHERE id=p_request->>'idempotency_id' AND v_claimed;
            RETURN jsonb_build_object('error_code','approval_not_found');
          END IF;
          SELECT * INTO v_approval
          FROM public.approval_requests
          WHERE tenant_id=v_tenant_id AND id=p_approval_id AND ticket_id=v_ticket.id
          FOR UPDATE;
          IF v_approval.id IS NULL THEN
            DELETE FROM public.idempotency_requests
            WHERE id=p_request->>'idempotency_id' AND v_claimed;
            RETURN jsonb_build_object('error_code','approval_not_found');
          END IF;
          SELECT * INTO v_proposal
          FROM public.proposal_records
          WHERE tenant_id=v_tenant_id AND id=v_approval.proposal_id
          FOR UPDATE;
          SELECT * INTO v_run
          FROM public.agent_runs
          WHERE tenant_id=v_tenant_id AND id=v_approval.run_id
          FOR UPDATE;
          IF v_run.turn_id IS NOT NULL THEN
            SELECT * INTO v_turn
            FROM public.conversation_turns
            WHERE tenant_id=v_tenant_id AND id=v_run.turn_id
            FOR UPDATE;
          END IF;
          SELECT * INTO v_withdrawal
          FROM public.proposal_withdrawals
          WHERE tenant_id=v_tenant_id AND approval_id=p_approval_id
          FOR UPDATE;
          IF v_withdrawal.id IS NOT NULL THEN
            v_response:=jsonb_build_object(
              'schema_version','withdrawal-accepted.v1','approval_id',p_approval_id,
              'ticket_id',v_ticket.id,'withdrawal_id',v_withdrawal.id,
              'accepted_at',public.supportguard_internal_format_utc_timestamp(
                v_withdrawal.created_at
              ),'action_status','withdrawn',
              'reused',false
            );
            UPDATE public.idempotency_requests SET
              resource_ids=jsonb_build_object(
                'approval_id',p_approval_id,'ticket_id',v_ticket.id,
                'withdrawal_id',v_withdrawal.id),
              response_snapshot=v_response,completed_at=v_withdrawal.created_at,
              updated_at=v_now
            WHERE id=p_request->>'idempotency_id';
            RETURN v_response||jsonb_build_object('reused',true);
          END IF;
          IF v_approval.status<>'pending' OR v_approval.proposal_id IS NULL
             OR v_proposal.id IS NULL OR v_proposal.status<>'bound'
             OR v_run.id IS NULL
             OR EXISTS (
               SELECT 1 FROM public.human_decisions
               WHERE tenant_id=v_tenant_id AND approval_id=p_approval_id
             ) THEN
            DELETE FROM public.idempotency_requests
            WHERE id=p_request->>'idempotency_id' AND v_claimed;
            RETURN jsonb_build_object('error_code','proposal_withdrawal_conflict');
          END IF;

          INSERT INTO public.proposal_withdrawals(
            id,tenant_id,ticket_id,customer_id,approval_id,proposal_id,actor_id,
            reason,idempotency_key,created_at,updated_at
          ) VALUES (
            p_request->>'withdrawal_id',v_tenant_id,v_ticket.id,v_ticket.customer_id,
            p_approval_id,v_proposal.id,v_principal_id,p_request->>'reason',
            p_request->>'idempotency_key',v_now,v_now
          );
          UPDATE public.approval_requests
          SET status='withdrawn',decided_at=v_now,status_version=status_version+1,
              updated_at=v_now
          WHERE tenant_id=v_tenant_id AND id=p_approval_id;
          UPDATE public.proposal_records
          SET status='stale',status_version=status_version+1,updated_at=v_now
          WHERE tenant_id=v_tenant_id AND id=v_proposal.id;

          SELECT * INTO v_parent
          FROM public.agent_events
          WHERE tenant_id=v_tenant_id AND ticket_id=v_ticket.id
          ORDER BY ticket_sequence DESC LIMIT 1;
          v_ticket_sequence:=v_ticket.next_event_sequence+1;
          v_run_sequence:=v_run.next_run_sequence+1;
          v_event_id:='event_'||md5(
            'withdrawal:'||v_tenant_id||':'||(p_request->>'withdrawal_id')
          );
          v_payload:=jsonb_build_object(
            'approval_id',p_approval_id,'proposal_id',v_proposal.id,
            'withdrawal_id',p_request->>'withdrawal_id'
          );
          v_payload_canonical:='{"approval_id":'||to_jsonb(p_approval_id)::text
            ||',"proposal_id":'||to_jsonb(v_proposal.id)::text
            ||',"withdrawal_id":'||to_jsonb(p_request->>'withdrawal_id')::text||'}';
          v_payload_hash:=encode(sha256(convert_to(v_payload_canonical,'UTF8')),'hex');
          v_created_at_text:=to_char(
            v_now AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US'
          )||'+00:00';
          v_envelope:='{"aggregate_id":'||to_jsonb(v_ticket.id)::text
            ||',"aggregate_type":"SupportTicket"'
            ||',"canonicalization_version":"json-sort-keys.v1"'
            ||',"causation_id":'||coalesce(to_jsonb(v_parent.id)::text,'null')
            ||',"correlation_id":'||to_jsonb(v_run.id)::text
            ||',"created_at":'||to_jsonb(v_created_at_text)::text
            ||',"customer_id":'||to_jsonb(v_ticket.customer_id)::text
            ||',"delivery_generation":null'
            ||',"event_id":'||to_jsonb(v_event_id)::text
            ||',"event_schema_version":"support-ticket-event.v1"'
            ||',"event_type":"proposal_withdrawn"'
            ||',"fencing_token":null'
            ||',"idempotency_id":'||to_jsonb(p_request->>'idempotency_key')::text
            ||',"job_id":null'
            ||',"payload_hash":'||to_jsonb(v_payload_hash)::text
            ||',"previous_event_id":'
            ||coalesce(to_jsonb(CASE WHEN v_parent.run_id=v_run.id THEN v_parent.id END)::text,'null')
            ||',"run_id":'||to_jsonb(v_run.id)::text
            ||',"run_sequence":'||v_run_sequence::text
            ||',"status":"completed"'
            ||',"step_index":'||v_run.step_index::text
            ||',"tenant_id":'||to_jsonb(v_tenant_id)::text
            ||',"ticket_sequence":'||v_ticket_sequence::text
            ||',"tool_call_id":null'
            ||',"tool_round":'||v_run.tool_rounds::text
            ||',"visibility":"customer"}';
          v_event_hash:=encode(sha256(convert_to(
            'event-hash.v1'||v_envelope||coalesce(v_parent.event_hash,repeat('0',64)),
            'UTF8'
          )),'hex');

          UPDATE public.support_tickets
          SET status='open',version=version+1,next_event_sequence=v_ticket_sequence,
              updated_at=v_now
          WHERE tenant_id=v_tenant_id AND id=v_ticket.id;
          UPDATE public.agent_runs
          SET status='completed',agent_finish_reason='withdrawn',
              active_job_id=NULL,active_fencing_token=NULL,completed_at=v_now,
              next_run_sequence=v_run_sequence,status_version=status_version+1,
              updated_at=v_now
          WHERE tenant_id=v_tenant_id AND id=v_run.id;
          IF v_turn.id IS NOT NULL THEN
            UPDATE public.conversation_turns
            SET activity_state='completed',result_state='refused',
                completed_at=v_now,updated_at=v_now
            WHERE tenant_id=v_tenant_id AND id=v_turn.id;
          END IF;
          INSERT INTO public.agent_events(
            id,tenant_id,run_id,ticket_id,customer_id,sequence,ticket_sequence,
            run_sequence,step_index,tool_round,event_type,status,visibility,payload,
            payload_hash,previous_event_id,parent_event_hash,event_hash,
            event_schema_version,canonicalization_version,event_hash_schema_version,
            correlation_id,causation_id,idempotency_id,created_at
          ) VALUES (
            v_event_id,v_tenant_id,v_run.id,v_ticket.id,v_ticket.customer_id,
            v_run_sequence,v_ticket_sequence,v_run_sequence,v_run.step_index,v_run.tool_rounds,
            'proposal_withdrawn','completed','customer',v_payload,v_payload_hash,
            CASE WHEN v_parent.run_id=v_run.id THEN v_parent.id END,
            coalesce(v_parent.event_hash,repeat('0',64)),v_event_hash,
            'support-ticket-event.v1','json-sort-keys.v1','event-hash.v1',
            v_run.id,v_parent.id,p_request->>'idempotency_key',v_now
          );
          INSERT INTO public.ticket_messages(
            id,tenant_id,ticket_id,turn_id,run_id,approval_id,message_kind,
            publication_key,role,content,source_refs,created_at,updated_at
          ) VALUES (
            p_request->>'message_id',v_tenant_id,v_ticket.id,v_run.turn_id,v_run.id,
            p_approval_id,'action_update','action:'||p_approval_id||':withdrawn:1',
            'action','你已撤回该操作申请；系统未执行任何业务动作。','[]',v_now,v_now
          );
          INSERT INTO public.audit_events(
            id,tenant_id,ticket_id,customer_id,event_type,actor_type,actor_ref,run_id,
            trace_id,payload,created_at
          ) VALUES (
            p_request->>'audit_id',v_tenant_id,v_ticket.id,v_ticket.customer_id,
            'proposal_withdrawn','customer',v_principal_id,v_run.id,p_request->>'trace_id',
            jsonb_build_object(
              'approval_id',p_approval_id,'proposal_id',v_proposal.id,
              'withdrawal_id',p_request->>'withdrawal_id','canonical_event_id',v_event_id
            ),v_now
          );
          v_response:=jsonb_build_object(
            'schema_version','withdrawal-accepted.v1','approval_id',p_approval_id,
            'ticket_id',v_ticket.id,'withdrawal_id',p_request->>'withdrawal_id',
            'accepted_at',public.supportguard_internal_format_utc_timestamp(v_now),
            'action_status','withdrawn','reused',false
          );
          UPDATE public.idempotency_requests SET
            resource_ids=jsonb_build_object(
              'approval_id',p_approval_id,'ticket_id',v_ticket.id,
              'withdrawal_id',p_request->>'withdrawal_id'),
            response_snapshot=v_response,completed_at=v_now,
            retention_class='protected_action',updated_at=v_now
          WHERE id=p_request->>'idempotency_id';
          PERFORM public.supportguard_internal_activate_next_ticket_turn(
            v_tenant_id,v_ticket.id,NULL
          );
          PERFORM public.supportguard_internal_converge_ticket_status(
            v_tenant_id,v_ticket.id,'open'
          );
          RETURN v_response;
        END
        $$;


ALTER FUNCTION public.supportguard_api_withdraw_proposal(p_approval_id text, p_request jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_approval_identity_compat_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_approval_identity_compat_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_resource_type text;
                v_resource_id text;
                v_origin_turn_id text;
        BEGIN
          SELECT CASE p.action_type
                   WHEN 'refund' THEN 'billing_record_id'
                   WHEN 'api_key_revocation' THEN 'api_key_id'
                   WHEN 'entitlement_change' THEN 'subscription_id'
                 END,
                 p.resource_id,
                 r.turn_id
          INTO v_resource_type,v_resource_id,v_origin_turn_id
          FROM public.proposal_records p
          JOIN public.agent_runs r
            ON r.tenant_id=p.tenant_id AND r.id=p.run_id
          WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.proposal_id
            AND p.run_id=NEW.run_id AND p.action_type=NEW.action_type
            AND p.resource_version=NEW.business_version
            AND r.ticket_id=NEW.ticket_id;
          IF v_resource_type IS NULL OR v_resource_id IS NULL
             OR v_origin_turn_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='23514',
              MESSAGE='approval_resource_identity_invalid';
          END IF;
          IF TG_OP='INSERT' THEN
            IF (NEW.resource_type IS NOT NULL
                AND NEW.resource_type IS DISTINCT FROM v_resource_type)
               OR (NEW.resource_id IS NOT NULL
                   AND NEW.resource_id IS DISTINCT FROM v_resource_id)
               OR (NEW.origin_turn_id IS NOT NULL
                   AND NEW.origin_turn_id IS DISTINCT FROM v_origin_turn_id) THEN
              RAISE EXCEPTION USING ERRCODE='23514',
                MESSAGE='approval_resource_identity_conflict';
            END IF;
            NEW.resource_type:=v_resource_type;
            NEW.resource_id:=v_resource_id;
            NEW.origin_turn_id:=v_origin_turn_id;
            RETURN NEW;
          END IF;
          IF current_setting('app.v1512_backfill_authorized',true)='v1512'
             AND OLD.resource_type IS NULL AND OLD.resource_id IS NULL
             AND OLD.origin_turn_id IS NULL
             AND NEW.resource_type=v_resource_type
             AND NEW.resource_id=v_resource_id
             AND NEW.origin_turn_id=v_origin_turn_id THEN
            RETURN NEW;
          END IF;
          IF NEW.resource_type IS DISTINCT FROM OLD.resource_type
             OR NEW.resource_id IS DISTINCT FROM OLD.resource_id
             OR NEW.origin_turn_id IS DISTINCT FROM OLD.origin_turn_id THEN
            RAISE EXCEPTION USING ERRCODE='55000',
              MESSAGE='approval_resource_identity_immutable';
          END IF;
          RETURN NEW;
        END
        $$;


ALTER FUNCTION public.supportguard_approval_identity_compat_guard() OWNER TO supportguard_owner;

