    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='approval_lineage_immutable';
        END $$;


