--
-- Name: supportguard_approval_revision_binding_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_approval_revision_binding_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF NEW.selected_revision_id IS NULL THEN
            IF NEW.selected_revision_number IS NOT NULL THEN
              RAISE EXCEPTION USING ERRCODE='23514',
                MESSAGE='approval_revision_binding_invalid';
            END IF;
            RETURN NEW;
          END IF;
          IF NEW.selected_revision_number IS NULL OR NOT EXISTS (
            SELECT 1
            FROM public.approval_action_revisions revision
            WHERE revision.id=NEW.selected_revision_id
              AND revision.tenant_id=NEW.tenant_id
              AND revision.approval_id=NEW.id
              AND revision.proposal_id=NEW.proposal_id
              AND revision.revision_number=NEW.selected_revision_number
              AND revision.resource_version=NEW.business_version
          ) THEN
            RAISE EXCEPTION USING ERRCODE='23514',
              MESSAGE='approval_revision_binding_invalid';
          END IF;
          RETURN NEW;
        END
        $$;


ALTER FUNCTION public.supportguard_approval_revision_binding_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_business_action_commit_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_business_action_commit_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_action public.business_actions%ROWTYPE;
        BEGIN
          -- A deferred INSERT event retains the tuple image from INSERT time.
          -- Re-read the final row so a canonical binding added later in this
          -- same transaction satisfies both the INSERT and UPDATE events.
          SELECT b.* INTO v_action FROM public.business_actions b WHERE b.id=NEW.id;
          IF v_action.status='succeeded'
             AND v_action.action_type IN ('refund','api_key_revocation','entitlement_change')
             AND (v_action.approval_id IS NULL OR v_action.human_decision_id IS NULL
                  OR v_action.action_revision_id IS NULL OR v_action.decision_hash IS NULL
                  OR v_action.effect_identity IS NULL OR v_action.canonical_event_id IS NULL
                  OR v_action.canonical_event_hash IS NULL
                  OR NOT EXISTS (
                    SELECT 1 FROM public.human_decisions d
                    JOIN public.approval_requests a
                      ON a.tenant_id=d.tenant_id AND a.id=d.approval_id
                    JOIN public.approval_action_revisions ar
                      ON ar.tenant_id=a.tenant_id AND ar.id=d.action_revision_id
                     AND ar.approval_id=a.id
                    JOIN public.agent_events e
                      ON e.tenant_id=a.tenant_id AND e.id=v_action.canonical_event_id
                     AND e.run_id=a.run_id
                   WHERE a.tenant_id=v_action.tenant_id
                     AND a.id=v_action.approval_id
                     AND d.id=v_action.human_decision_id
                     AND ar.id=v_action.action_revision_id
                     AND d.decision_hash=v_action.decision_hash
                     AND d.action_hash=v_action.action_hash
                     AND ar.action_hash=v_action.action_hash
                     AND e.event_hash=v_action.canonical_event_hash
                  )) THEN
            RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='business_action_commit_binding_invalid';
          END IF;
          RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_business_action_commit_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_canonical_jsonb(jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_canonical_jsonb(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_result text;
        BEGIN
          CASE jsonb_typeof(p_value)
          WHEN 'object' THEN
            SELECT '{'||COALESCE(string_agg(
              to_jsonb(key)::text||':'||supportguard_canonical_jsonb(value),
              ',' ORDER BY key COLLATE "C"),'')||'}' INTO v_result
            FROM jsonb_each(p_value);
          WHEN 'array' THEN
            SELECT '['||COALESCE(string_agg(
              supportguard_canonical_jsonb(value),',' ORDER BY ordinal),'')||']'
              INTO v_result
            FROM jsonb_array_elements(p_value) WITH ORDINALITY item(value,ordinal);
          ELSE v_result:=p_value::text;
          END CASE;
          RETURN v_result;
        END $$;


ALTER FUNCTION public.supportguard_canonical_jsonb(p_value jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_checkpoint_identity_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_checkpoint_identity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF TG_TABLE_NAME IN ('checkpoints','checkpoint_blobs','checkpoint_writes') THEN
            INSERT INTO public.checkpoint_thread_identities(id)
              VALUES (NEW.thread_id) ON CONFLICT DO NOTHING;
          END IF;
          IF TG_TABLE_NAME='checkpoints' THEN
            INSERT INTO public.checkpoint_value_identities(id)
              VALUES (NEW.checkpoint_id) ON CONFLICT DO NOTHING;
            IF NEW.parent_checkpoint_id IS NOT NULL THEN
              INSERT INTO public.checkpoint_value_identities(id)
                VALUES (NEW.parent_checkpoint_id) ON CONFLICT DO NOTHING;
            END IF;
          ELSIF TG_TABLE_NAME='checkpoint_writes' THEN
            INSERT INTO public.checkpoint_value_identities(id)
              VALUES (NEW.checkpoint_id) ON CONFLICT DO NOTHING;
            INSERT INTO public.checkpoint_task_identities(id)
              VALUES (NEW.task_id) ON CONFLICT DO NOTHING;
          END IF;
          RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_checkpoint_identity_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_converge_dead_job(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_converge_dead_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          -- A row trigger already owns RuntimeJob, so it must never acquire a
          -- parent Ticket or any other aggregate lock.  Cross-aggregate dead
          -- convergence belongs to the Ticket-first owner helper.
          IF NEW.status='dead' AND OLD.status<>'dead' THEN
            IF current_setting('app.dead_convergence_authorized',true)
                 IS DISTINCT FROM 'v1512' THEN
              RAISE EXCEPTION USING ERRCODE='42501',
                MESSAGE='dead_transition_requires_owner_capability';
            END IF;
            NEW.lease_owner:=NULL;
            NEW.lease_expires_at:=NULL;
            NEW.heartbeat_at:=NULL;
            NEW.outcome:='infrastructure_exhausted';
          END IF;
          RETURN NEW;
        END
        $$;


ALTER FUNCTION public.supportguard_converge_dead_job() OWNER TO supportguard_owner;

--
-- Name: supportguard_delivery_state_version_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_delivery_state_version_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_delivery text;
        BEGIN
          IF TG_TABLE_NAME='outbox_events' THEN
            IF ROW(NEW.redis_message_id,NEW.published_at,NEW.last_delivery_at,NEW.payload::text,
                   NEW.superseded_at,NEW.superseded_by_delivery_id)
               IS DISTINCT FROM
               ROW(OLD.redis_message_id,OLD.published_at,OLD.last_delivery_at,OLD.payload::text,
                   OLD.superseded_at,OLD.superseded_by_delivery_id) THEN
              NEW.delivery_state_version:=greatest(
                NEW.delivery_state_version,OLD.delivery_state_version+1
              );
            END IF;
            RETURN NEW;
          END IF;
          v_delivery:=coalesce(NEW.delivery_id,OLD.delivery_id);
          UPDATE public.outbox_events
             SET delivery_state_version=delivery_state_version+1,
                 updated_at=clock_timestamp()
           WHERE delivery_id=v_delivery AND superseded_at IS NULL;
          IF TG_OP='DELETE' THEN RETURN OLD; END IF;
          RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_delivery_state_version_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_dispatcher_claim_outbox(integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_dispatcher_claim_outbox(p_batch_size integer) RETURNS TABLE(event_id text, delivery_id text, job_id text, run_id text, tenant_id text, delivery_generation integer, traceparent text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
            IF session_user <> 'supportguard_dispatcher' THEN
                RAISE EXCEPTION 'dispatcher capability caller is not authorized';
            END IF;
            IF p_batch_size < 1 OR p_batch_size > 100 THEN
                RAISE EXCEPTION 'dispatcher batch size is outside the frozen bound';
            END IF;
            RETURN QUERY
            WITH due AS (
                SELECT o.id FROM public.outbox_events o
                WHERE o.published_at IS NULL AND o.available_at <= statement_timestamp()
                ORDER BY o.created_at, o.id LIMIT p_batch_size
                FOR UPDATE SKIP LOCKED
            ), claimed AS (
                UPDATE public.outbox_events o
                SET publish_attempts=o.publish_attempts+1,
                    available_at=statement_timestamp() + interval '30 seconds',
                    updated_at=statement_timestamp()
                FROM due d WHERE o.id=d.id
                RETURNING o.id,o.delivery_id,o.job_id,o.run_id,o.tenant_id,
                          o.delivery_generation,o.payload
            )
            SELECT c.id::text,c.delivery_id::text,c.job_id::text,c.run_id::text,
                   c.tenant_id::text,c.delivery_generation,
                   NULLIF(c.payload->>'traceparent','') FROM claimed c;
        END; $$;


ALTER FUNCTION public.supportguard_dispatcher_claim_outbox(p_batch_size integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_dispatcher_mark_published(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_dispatcher_mark_published(p_event_id text, p_redis_message_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_count integer;
        BEGIN
            IF session_user <> 'supportguard_dispatcher' THEN
                RAISE EXCEPTION 'dispatcher capability caller is not authorized';
            END IF;
            IF p_redis_message_id IS NULL OR length(p_redis_message_id) NOT BETWEEN 1 AND 64 THEN
                RAISE EXCEPTION 'invalid redis message id';
            END IF;
            UPDATE public.outbox_events SET redis_message_id=p_redis_message_id,
                published_at=statement_timestamp(),last_delivery_at=statement_timestamp(),
                updated_at=statement_timestamp()
            WHERE id=p_event_id AND published_at IS NULL AND publish_attempts > 0;
            GET DIAGNOSTICS v_count = ROW_COUNT;
            RETURN v_count=1;
        END; $$;


ALTER FUNCTION public.supportguard_dispatcher_mark_published(p_event_id text, p_redis_message_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_domain_terminal_approval_converge(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_domain_terminal_approval_converge() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_reason text;
                v_approval_id text;
                v_target_status text;
        BEGIN
          IF NEW.status='succeeded' AND NEW.outcome='domain_terminal'
             AND NEW.outcome IS DISTINCT FROM OLD.outcome THEN
            SELECT f.domain_delta->>'domain_outcome_reason',
                   f.domain_delta->>'approval_id'
              INTO v_reason,v_approval_id
              FROM public.checkpoint_commit_markers m
              JOIN public.finalizer_payloads f
                ON f.tenant_id=m.tenant_id
               AND f.run_id=m.run_id
               AND f.job_id=m.job_id
               AND f.marker_id=m.id
             WHERE m.tenant_id=NEW.tenant_id
               AND m.run_id=NEW.run_id
               AND m.job_id=NEW.id
               AND m.status='finalized'
               AND f.schema_version='finalizer.v2'
               AND f.domain_delta->>'variant'='approval_fail_closed'
             ORDER BY m.fencing_token DESC,m.created_at DESC,m.id DESC
             LIMIT 1;
            v_target_status:=CASE v_reason
              WHEN 'binding_stale' THEN 'stale'
              WHEN 'logical_degradation' THEN 'failed'
              ELSE NULL
            END;
            IF v_target_status IS NOT NULL THEN
              UPDATE public.approval_requests
                 SET status=v_target_status,
                     status_version=status_version+1,
                     updated_at=clock_timestamp()
               WHERE tenant_id=NEW.tenant_id
                 AND id=v_approval_id
                 AND run_id=NEW.run_id
                 AND ticket_id=NEW.ticket_id
                 AND status IN ('pending','approved');
            END IF;
          END IF;
          RETURN NULL;
        END
        $$;


ALTER FUNCTION public.supportguard_domain_terminal_approval_converge() OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_action_intent_executed_receipt(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_action_intent_executed_receipt(p_tenant_id text, p_job_id text, p_run_id text, p_domain_delta jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          PERFORM set_config('app.tenant_id',p_tenant_id,true);
          RETURN (
            SELECT count(*)=1
            FROM public.runtime_jobs j
            JOIN public.approval_requests a
              ON a.tenant_id=j.tenant_id AND a.id=j.approval_id
            JOIN public.human_decisions d
              ON d.tenant_id=a.tenant_id
             AND d.approval_id=a.id
             AND d.id=p_domain_delta->>'human_decision_id'
            JOIN public.approval_action_revisions r
              ON r.tenant_id=a.tenant_id
             AND r.approval_id=a.id
             AND r.proposal_id=a.proposal_id
             AND r.id=a.selected_revision_id
             AND r.revision_number=a.selected_revision_number
             AND r.resource_version=a.business_version
             AND d.action_revision_id=r.id
             AND d.action_hash=r.action_hash
            JOIN public.business_actions b
              ON b.tenant_id=a.tenant_id
             AND b.approval_id=a.id
             AND b.human_decision_id=d.id
             AND b.action_revision_id=r.id
             AND b.action_hash=r.action_hash
             AND b.action_type=a.action_type
             AND b.resource_id=a.resource_id
             AND b.resource_version=a.business_version
             AND b.status='succeeded'
            WHERE j.tenant_id=p_tenant_id
              AND j.id=p_job_id
              AND j.run_id=p_run_id
              AND p_domain_delta->>'variant'='approval_action_intent'
              AND p_domain_delta->>'outcome'='completed'
              AND p_domain_delta->>'approval_id'=a.id
              AND p_domain_delta->>'action_hash'=a.action_hash
              AND p_domain_delta->>'human_decision_id'=d.id
              AND p_domain_delta->>'decision'=d.decision
              AND d.decision IN ('approve','edit_and_approve')
              AND a.status='executed'
          );
        END
        $$;


ALTER FUNCTION public.supportguard_internal_action_intent_executed_receipt(p_tenant_id text, p_job_id text, p_run_id text, p_domain_delta jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_action_intent_stale_receipt(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_action_intent_stale_receipt(p_tenant_id text, p_job_id text, p_run_id text, p_domain_delta jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          PERFORM set_config('app.tenant_id',p_tenant_id,true);
          RETURN EXISTS (
            SELECT 1
            FROM public.runtime_jobs j
            JOIN public.approval_requests a
              ON a.tenant_id=j.tenant_id AND a.id=j.approval_id
            JOIN public.human_decisions d
              ON d.tenant_id=a.tenant_id
             AND d.approval_id=a.id
             AND d.id=p_domain_delta->>'human_decision_id'
            WHERE j.tenant_id=p_tenant_id
              AND j.id=p_job_id
              AND j.run_id=p_run_id
              AND p_domain_delta->>'variant'='approval_action_intent'
              AND p_domain_delta->>'outcome'='completed'
              AND p_domain_delta->>'approval_id'=a.id
              AND p_domain_delta->>'action_hash'=a.action_hash
              AND p_domain_delta->>'human_decision_id'=d.id
              AND p_domain_delta->>'decision'=d.decision
              AND d.decision IN ('approve','edit_and_approve')
              AND a.status='stale'
              AND NOT EXISTS (
                SELECT 1
                FROM public.business_actions b
                WHERE b.tenant_id=a.tenant_id AND b.approval_id=a.id
              )
              AND EXISTS (
                SELECT 1
                FROM public.agent_events e
                WHERE e.tenant_id=j.tenant_id
                  AND e.ticket_id=j.ticket_id
                  AND e.run_id=j.run_id
                  AND e.event_type='runtime_action_reconciliation'
                  AND e.payload->>'approval_id'=a.id
                  AND e.payload->>'status'='stale'
                  AND e.payload->>'reason' IN (
                    'binding_stale',
                    'publication_binding_stale',
                    'approver_scope_stale',
                    'resource_snapshot_stale',
                    'policy_stale'
                  )
              )
          );
        END
        $$;


ALTER FUNCTION public.supportguard_internal_action_intent_stale_receipt(p_tenant_id text, p_job_id text, p_run_id text, p_domain_delta jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_activate_next_ticket_turn(text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_activate_next_ticket_turn(p_tenant_id text, p_ticket_id text, p_completed_job_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE
          v_ticket public.support_tickets%ROWTYPE;
          v_turn public.conversation_turns%ROWTYPE;
          v_previous_run public.agent_runs%ROWTYPE;
          v_job public.runtime_jobs%ROWTYPE;
          v_timing_version bigint;
          v_run_id text;
          v_job_id text;
          v_outbox_id text;
          v_delivery_id text;
          v_now timestamptz:=clock_timestamp();
        BEGIN
          IF p_completed_job_id IS NOT NULL THEN
            SELECT * INTO v_job
            FROM public.runtime_jobs
            WHERE tenant_id=p_tenant_id AND id=p_completed_job_id;
            IF v_job.id IS NULL
               OR v_job.ticket_id<>p_ticket_id
               OR v_job.status NOT IN ('succeeded','dead') THEN
              RETURN '{}'::jsonb;
            END IF;
          END IF;
          SELECT * INTO v_ticket
          FROM public.support_tickets
          WHERE tenant_id=p_tenant_id AND id=p_ticket_id
          FOR UPDATE;
          IF v_ticket.id IS NULL
             OR v_ticket.lifecycle<>'active'
             OR v_ticket.automation_mode<>'agent'
             OR EXISTS (
               SELECT 1
               FROM public.conversation_turns active
               WHERE active.tenant_id=p_tenant_id
                 AND active.ticket_id=p_ticket_id
                 AND active.activity_state IN ('queued','running')
             ) THEN
            RETURN '{}'::jsonb;
          END IF;
          SELECT * INTO v_turn
          FROM public.conversation_turns pending
          WHERE pending.tenant_id=p_tenant_id
            AND pending.ticket_id=p_ticket_id
            AND pending.activity_state='accepted'
          ORDER BY pending.ordinal,pending.id
          LIMIT 1 FOR UPDATE;
          IF v_turn.id IS NULL THEN
            RETURN '{}'::jsonb;
          END IF;
          SELECT * INTO v_previous_run
          FROM public.agent_runs previous
          WHERE previous.tenant_id=p_tenant_id
            AND previous.ticket_id=p_ticket_id
          ORDER BY previous.created_at DESC,previous.id DESC
          LIMIT 1;
          SELECT timing_version INTO v_timing_version
          FROM supportguard_control.runtime_timing_snapshots
          WHERE is_active
          ORDER BY timing_version DESC LIMIT 1;
          IF v_timing_version IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',
              MESSAGE='runtime_timing_missing';
          END IF;
          IF coalesce(v_turn.model,v_previous_run.model) IS NULL
             OR coalesce(v_turn.provider_mode,v_previous_run.provider_mode) IS NULL
             OR coalesce(v_turn.tool_call_mode,v_previous_run.tool_call_mode) IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',
              MESSAGE='accepted_turn_runtime_identity_missing';
          END IF;
          v_run_id:='run_'||pg_catalog.md5('v1512:'||v_turn.id);
          v_job_id:='job_'||pg_catalog.md5('v1512:'||v_turn.id);
          v_outbox_id:='outbox_'||pg_catalog.md5('v1512:'||v_turn.id);
          v_delivery_id:='delivery_'||pg_catalog.md5('v1512:'||v_turn.id);
          INSERT INTO public.agent_runs(
            id,tenant_id,ticket_id,customer_id,message_id,status,
            status_version,next_run_sequence,canonical_checkpoint_version,
            checkpoint_stage,step_index,tool_rounds,tool_attempts,llm_calls,
            model,provider_mode,tool_call_mode,prompt_version,schema_version,
            context_version,created_at,updated_at
          ) VALUES (
            v_run_id,p_tenant_id,p_ticket_id,v_ticket.customer_id,
            v_turn.customer_message_id,'queued',1,0,0,'request_created',0,0,0,0,
            coalesce(v_turn.model,v_previous_run.model),
            coalesce(v_turn.provider_mode,v_previous_run.provider_mode),
            coalesce(v_turn.tool_call_mode,v_previous_run.tool_call_mode),
            coalesce(
              v_previous_run.prompt_version,
              'agent_decide.v5+bound_evidence_synthesis.v1'
            ),
            coalesce(v_previous_run.schema_version,'agent-contract.v5'),
            coalesce(v_turn.context_version,v_previous_run.context_version,'context-v1.2'),
            v_now,v_now
          );
          UPDATE public.agent_runs
          SET turn_id=v_turn.id
          WHERE tenant_id=p_tenant_id AND id=v_run_id;
          UPDATE public.conversation_turns
          SET run_id=v_run_id,activity_state='queued',updated_at=v_now
          WHERE tenant_id=p_tenant_id AND id=v_turn.id
            AND (
              activity_state='accepted'
              OR (activity_state='queued' AND run_id=v_run_id)
            );
          IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='40001',
              MESSAGE='next_turn_activation_conflict';
          END IF;
          INSERT INTO public.runtime_jobs(
            id,tenant_id,run_id,kind,status,timing_version,status_version,
            attempt,available_at,fencing_token,created_at,updated_at
          ) VALUES (
            v_job_id,p_tenant_id,v_run_id,'agent_start','queued',
            v_timing_version,1,0,v_now,0,v_now,v_now
          );
          INSERT INTO public.outbox_events(
            id,delivery_id,tenant_id,job_id,run_id,delivery_generation,
            event_type,schema_version,payload,available_at,publish_attempts,
            delivery_state_version,created_at,updated_at
          ) VALUES (
            v_outbox_id,v_delivery_id,p_tenant_id,v_job_id,v_run_id,1,
            'runtime_job_available','runtime-job.v1',
            pg_catalog.jsonb_build_object(
              'traceparent','worker-finish:'||p_completed_job_id
            ),
            v_now,0,1,v_now,v_now
          );
          UPDATE public.support_tickets
          SET status='queued',version=version+1,updated_at=v_now
          WHERE tenant_id=p_tenant_id AND id=p_ticket_id;
          RETURN pg_catalog.jsonb_build_object(
            'activated_turn_id',v_turn.id,
            'activated_run_id',v_run_id,
            'activated_job_id',v_job_id
          );
        END
        $$;


ALTER FUNCTION public.supportguard_internal_activate_next_ticket_turn(p_tenant_id text, p_ticket_id text, p_completed_job_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_allocate_dispatch_sequence(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_allocate_dispatch_sequence(p_tenant_id text, p_ticket_id text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_sequence bigint;
        BEGIN
          UPDATE public.support_tickets
          SET next_dispatch_sequence=next_dispatch_sequence+1
          WHERE tenant_id=p_tenant_id AND id=p_ticket_id
          RETURNING next_dispatch_sequence INTO v_sequence;
          IF v_sequence IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='23503',
              MESSAGE='runtime_job_ticket_missing';
          END IF;
          RETURN v_sequence;
        END
        $$;


ALTER FUNCTION public.supportguard_internal_allocate_dispatch_sequence(p_tenant_id text, p_ticket_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_classify_action_effect(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_classify_action_effect(p_tenant_id text, p_approval_id text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_approval public.approval_requests%ROWTYPE;
          v_revision public.approval_action_revisions%ROWTYPE;
          v_has_action boolean:=false;
          v_effect_visible boolean:=false;
          v_zero_visible boolean:=false;
        BEGIN
          SELECT * INTO v_approval
          FROM public.approval_requests
          WHERE tenant_id=p_tenant_id AND id=p_approval_id;
          IF v_approval.id IS NULL OR v_approval.selected_revision_id IS NULL THEN
            RETURN 'verification_pending';
          END IF;
          SELECT * INTO v_revision
          FROM public.approval_action_revisions
          WHERE tenant_id=p_tenant_id
            AND id=v_approval.selected_revision_id
            AND approval_id=v_approval.id
            AND proposal_id=v_approval.proposal_id
            AND revision_number=v_approval.selected_revision_number
            AND resource_version=v_approval.business_version;
          IF v_revision.id IS NULL THEN
            RETURN 'verification_pending';
          END IF;
          SELECT EXISTS (
            SELECT 1
            FROM public.business_actions action
            WHERE action.tenant_id=p_tenant_id
              AND action.approval_id=v_approval.id
              AND action.action_revision_id=v_revision.id
              AND action.action_type=v_approval.action_type
              AND action.resource_id=v_approval.resource_id
              AND action.resource_version=v_revision.resource_version
              AND action.action_hash=v_revision.action_hash
              AND action.status='succeeded'
          ) INTO v_has_action;
          IF v_approval.action_type='refund' THEN
            SELECT
              billing.version=v_revision.resource_version+1
                AND billing.status='refunded',
              billing.version=v_revision.resource_version
                AND billing.status<>'refunded'
            INTO v_effect_visible,v_zero_visible
            FROM public.billing_records billing
            WHERE billing.tenant_id=p_tenant_id
              AND billing.customer_id=v_approval.customer_id
              AND billing.id=v_approval.resource_id;
          ELSIF v_approval.action_type='api_key_revocation' THEN
            SELECT
              api_key.version=v_revision.resource_version+1
                AND api_key.status='revoked',
              api_key.version=v_revision.resource_version
                AND api_key.status<>'revoked'
            INTO v_effect_visible,v_zero_visible
            FROM public.api_key_metadata api_key
            WHERE api_key.tenant_id=p_tenant_id
              AND api_key.customer_id=v_approval.customer_id
              AND api_key.key_id=v_approval.resource_id;
          ELSIF v_approval.action_type='entitlement_change'
                AND jsonb_typeof(v_revision.action_payload::jsonb->'target')='object'
                AND (v_revision.action_payload::jsonb->'target')
                    - ARRAY['plan','rpm_limit','concurrency_limit']::text[]='{}'::jsonb
                AND v_revision.action_payload::jsonb->'target'<>'{}'::jsonb THEN
            SELECT
              subscription.version=v_revision.resource_version+1
                AND (
                  NOT (v_revision.action_payload::jsonb->'target' ? 'plan')
                  OR subscription.plan=v_revision.action_payload::jsonb#>>'{target,plan}'
                )
                AND (
                  NOT (v_revision.action_payload::jsonb->'target' ? 'rpm_limit')
                  OR subscription.rpm_limit=(
                    v_revision.action_payload::jsonb#>>'{target,rpm_limit}'
                  )::integer
                )
                AND (
                  NOT (v_revision.action_payload::jsonb->'target' ? 'concurrency_limit')
                  OR subscription.concurrency_limit=(
                    v_revision.action_payload::jsonb#>>'{target,concurrency_limit}'
                  )::integer
                ),
              subscription.version=v_revision.resource_version
            INTO v_effect_visible,v_zero_visible
            FROM public.subscriptions subscription
            WHERE subscription.tenant_id=p_tenant_id
              AND subscription.customer_id=v_approval.customer_id
              AND subscription.id=v_approval.resource_id;
          ELSE
            RETURN 'verification_pending';
          END IF;
          IF v_has_action AND coalesce(v_effect_visible,false) THEN
            RETURN 'executed';
          END IF;
          IF NOT v_has_action AND coalesce(v_zero_visible,false) THEN
            RETURN 'confirmed_zero_effect';
          END IF;
          RETURN 'verification_pending';
        EXCEPTION
          WHEN invalid_text_representation OR numeric_value_out_of_range THEN
            RETURN 'verification_pending';
        END
        $$;


ALTER FUNCTION public.supportguard_internal_classify_action_effect(p_tenant_id text, p_approval_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_converge_dead_job(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_converge_dead_job(p_tenant_id text, p_job_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_identity public.runtime_jobs%ROWTYPE;
          v_ticket public.support_tickets%ROWTYPE;
          v_approval public.approval_requests%ROWTYPE;
          v_proposal public.proposal_records%ROWTYPE;
          v_run public.agent_runs%ROWTYPE;
          v_turn public.conversation_turns%ROWTYPE;
          v_job public.runtime_jobs%ROWTYPE;
          v_parent public.agent_events%ROWTYPE;
          v_run_parent public.agent_events%ROWTYPE;
          v_existing_event public.agent_events%ROWTYPE;
          v_now timestamptz:=statement_timestamp();
          v_ticket_sequence bigint;
          v_run_sequence bigint;
          v_event_id text;
          v_payload jsonb;
          v_payload_text text;
          v_payload_hash text;
          v_created_at_text text;
          v_envelope text;
          v_event_hash text;
        BEGIN
          -- Identity discovery is deliberately lock-free.  Every aggregate
          -- lock below follows the frozen dead-convergence order.
          SELECT * INTO v_identity
          FROM public.runtime_jobs
          WHERE tenant_id=p_tenant_id AND id=p_job_id;
          IF v_identity.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='dead_job_aggregate_missing';
          END IF;
          PERFORM set_config('app.tenant_id',p_tenant_id,true);
          SELECT * INTO v_ticket
          FROM public.support_tickets
          WHERE tenant_id=p_tenant_id AND id=v_identity.ticket_id
          FOR UPDATE;
          IF v_identity.approval_id IS NOT NULL THEN
            SELECT * INTO v_approval
            FROM public.approval_requests
            WHERE tenant_id=p_tenant_id AND id=v_identity.approval_id
              AND run_id=v_identity.run_id AND ticket_id=v_identity.ticket_id
            FOR UPDATE;
            IF v_approval.id IS NOT NULL THEN
              SELECT * INTO v_proposal
              FROM public.proposal_records
              WHERE tenant_id=p_tenant_id AND id=v_approval.proposal_id
              FOR UPDATE;
            END IF;
          END IF;
          SELECT * INTO v_run
          FROM public.agent_runs
          WHERE tenant_id=p_tenant_id AND id=v_identity.run_id
          FOR UPDATE;
          IF v_run.turn_id IS NOT NULL THEN
            SELECT * INTO v_turn
            FROM public.conversation_turns
            WHERE tenant_id=p_tenant_id AND id=v_run.turn_id
            FOR UPDATE;
          END IF;
          SELECT * INTO v_job
          FROM public.runtime_jobs
          WHERE tenant_id=p_tenant_id AND id=p_job_id
          FOR UPDATE;
          IF v_ticket.id IS NULL OR v_run.id IS NULL OR v_job.status<>'dead'
             OR v_run.ticket_id IS DISTINCT FROM v_job.ticket_id
             OR (v_job.kind='approval_resume' AND v_approval.id IS NULL) THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='dead_job_aggregate_missing';
          END IF;

          v_event_id:='event_'||md5(
            'runtime-failure:'||p_tenant_id||':'||p_job_id
          );
          v_payload:=jsonb_build_object(
            'job_id',p_job_id,'reason_code','automatic_processing_failed'
          );
          v_payload_text:='{"job_id":'||to_jsonb(p_job_id)::text
            ||',"reason_code":"automatic_processing_failed"}';
          v_payload_hash:=encode(
            sha256(convert_to(v_payload_text,'UTF8')),'hex'
          );
          SELECT * INTO v_existing_event
          FROM public.agent_events
          WHERE tenant_id=p_tenant_id AND id=v_event_id;
          IF v_existing_event.id IS NOT NULL THEN
            SELECT * INTO v_parent
            FROM public.agent_events
            WHERE tenant_id=p_tenant_id
              AND ticket_id=v_ticket.id
              AND ticket_sequence=v_existing_event.ticket_sequence-1;
            SELECT * INTO v_run_parent
            FROM public.agent_events
            WHERE tenant_id=p_tenant_id
              AND run_id=v_run.id
              AND run_sequence<v_existing_event.run_sequence
            ORDER BY run_sequence DESC
            LIMIT 1;
            v_created_at_text:=to_char(
              v_existing_event.created_at AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US'
            )||'+00:00';
            v_envelope:='{"aggregate_id":'||to_jsonb(v_ticket.id)::text
              ||',"aggregate_type":"SupportTicket"'
              ||',"canonicalization_version":"json-sort-keys.v1"'
              ||',"causation_id":'||coalesce(to_jsonb(v_parent.id)::text,'null')
              ||',"correlation_id":'||to_jsonb(v_run.id)::text
              ||',"created_at":'||to_jsonb(v_created_at_text)::text
              ||',"customer_id":'||to_jsonb(v_ticket.customer_id)::text
              ||',"delivery_generation":null'
              ||',"event_id":'||to_jsonb(v_event_id)::text
              ||',"event_schema_version":"support-ticket-event.v1"'
              ||',"event_type":"runtime_failed"'
              ||',"fencing_token":'||v_job.fencing_token::text
              ||',"idempotency_id":'||to_jsonb(p_job_id)::text
              ||',"job_id":'||to_jsonb(p_job_id)::text
              ||',"payload_hash":'||to_jsonb(v_payload_hash)::text
              ||',"previous_event_id":'
              ||coalesce(
                to_jsonb(
                  CASE WHEN v_parent.run_id=v_run.id THEN v_parent.id END
                )::text,
                'null'
              )
              ||',"run_id":'||to_jsonb(v_run.id)::text
              ||',"run_sequence":'||v_existing_event.run_sequence::text
              ||',"status":"completed"'
              ||',"step_index":'||v_run.step_index::text
              ||',"tenant_id":'||to_jsonb(p_tenant_id)::text
              ||',"ticket_sequence":'||v_existing_event.ticket_sequence::text
              ||',"tool_call_id":null'
              ||',"tool_round":'||v_run.tool_rounds::text
              ||',"visibility":"customer"}';
            v_event_hash:=encode(
              sha256(convert_to(
                'event-hash.v1'||v_envelope
                  ||coalesce(v_parent.event_hash,repeat('0',64)),
                'UTF8'
              )),
              'hex'
            );
            IF v_existing_event.customer_id IS DISTINCT FROM v_ticket.customer_id
               OR v_existing_event.ticket_id IS DISTINCT FROM v_ticket.id
               OR v_existing_event.run_id IS DISTINCT FROM v_run.id
               OR v_existing_event.job_id IS DISTINCT FROM p_job_id
               OR v_existing_event.sequence IS DISTINCT FROM
                    v_existing_event.run_sequence
               OR v_existing_event.run_sequence IS DISTINCT FROM
                    v_run.next_run_sequence
               OR v_existing_event.run_sequence IS DISTINCT FROM
                    coalesce(v_run_parent.run_sequence,0)+1
               OR v_existing_event.run_sequence<1
               OR v_existing_event.ticket_sequence<1
               OR v_existing_event.ticket_sequence IS DISTINCT FROM
                    v_ticket.next_event_sequence
               OR (
                 v_existing_event.ticket_sequence=1 AND v_parent.id IS NOT NULL
               )
               OR (
                 v_existing_event.ticket_sequence>1 AND v_parent.id IS NULL
               )
               OR v_existing_event.step_index IS DISTINCT FROM v_run.step_index
               OR v_existing_event.tool_round IS DISTINCT FROM v_run.tool_rounds
               OR v_existing_event.event_type IS DISTINCT FROM 'runtime_failed'
               OR v_existing_event.status IS DISTINCT FROM 'completed'
               OR v_existing_event.visibility IS DISTINCT FROM 'customer'
               OR v_existing_event.tool_call_id IS NOT NULL
               OR v_existing_event.delivery_generation IS NOT NULL
               OR v_existing_event.payload::jsonb IS DISTINCT FROM v_payload
               OR v_existing_event.payload_hash IS DISTINCT FROM v_payload_hash
               OR v_existing_event.previous_event_id IS DISTINCT FROM
                    (
                      CASE
                        WHEN v_parent.run_id=v_run.id THEN v_parent.id
                        ELSE NULL
                      END
                    )
               OR v_existing_event.parent_event_hash IS DISTINCT FROM
                    coalesce(v_parent.event_hash,repeat('0',64))
               OR v_existing_event.event_hash IS DISTINCT FROM v_event_hash
               OR v_existing_event.event_schema_version IS DISTINCT FROM
                    'support-ticket-event.v1'
               OR v_existing_event.canonicalization_version IS DISTINCT FROM
                    'json-sort-keys.v1'
               OR v_existing_event.event_hash_schema_version IS DISTINCT FROM
                    'event-hash.v1'
               OR v_existing_event.correlation_id IS DISTINCT FROM v_run.id
               OR v_existing_event.causation_id IS DISTINCT FROM v_parent.id
               OR v_existing_event.idempotency_id IS DISTINCT FROM p_job_id
               OR v_existing_event.fencing_token IS DISTINCT FROM
                    v_job.fencing_token
            THEN
              RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='dead_job_event_identity_conflict';
            END IF;
          ELSE
            SELECT * INTO v_parent
            FROM public.agent_events
            WHERE tenant_id=p_tenant_id AND ticket_id=v_ticket.id
            ORDER BY ticket_sequence DESC LIMIT 1;
            v_ticket_sequence:=v_ticket.next_event_sequence+1;
            v_run_sequence:=v_run.next_run_sequence+1;
            v_created_at_text:=to_char(
              v_now AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US'
            )||'+00:00';
            v_envelope:='{"aggregate_id":'||to_jsonb(v_ticket.id)::text
              ||',"aggregate_type":"SupportTicket"'
              ||',"canonicalization_version":"json-sort-keys.v1"'
              ||',"causation_id":'||coalesce(to_jsonb(v_parent.id)::text,'null')
              ||',"correlation_id":'||to_jsonb(v_run.id)::text
              ||',"created_at":'||to_jsonb(v_created_at_text)::text
              ||',"customer_id":'||to_jsonb(v_ticket.customer_id)::text
              ||',"delivery_generation":null'
              ||',"event_id":'||to_jsonb(v_event_id)::text
              ||',"event_schema_version":"support-ticket-event.v1"'
              ||',"event_type":"runtime_failed"'
              ||',"fencing_token":'||v_job.fencing_token::text
              ||',"idempotency_id":'||to_jsonb(p_job_id)::text
              ||',"job_id":'||to_jsonb(p_job_id)::text
              ||',"payload_hash":'||to_jsonb(v_payload_hash)::text
              ||',"previous_event_id":'
              ||coalesce(
                to_jsonb(
                  CASE WHEN v_parent.run_id=v_run.id THEN v_parent.id END
                )::text,
                'null'
              )
              ||',"run_id":'||to_jsonb(v_run.id)::text
              ||',"run_sequence":'||v_run_sequence::text
              ||',"status":"completed"'
              ||',"step_index":'||v_run.step_index::text
              ||',"tenant_id":'||to_jsonb(p_tenant_id)::text
              ||',"ticket_sequence":'||v_ticket_sequence::text
              ||',"tool_call_id":null'
              ||',"tool_round":'||v_run.tool_rounds::text
              ||',"visibility":"customer"}';
            v_event_hash:=encode(
              sha256(convert_to(
                'event-hash.v1'||v_envelope
                  ||coalesce(v_parent.event_hash,repeat('0',64)),
                'UTF8'
              )),
              'hex'
            );
            UPDATE public.support_tickets
            SET next_event_sequence=v_ticket_sequence
            WHERE tenant_id=p_tenant_id AND id=v_ticket.id;
            UPDATE public.agent_runs
            SET next_run_sequence=v_run_sequence
            WHERE tenant_id=p_tenant_id AND id=v_run.id;
            INSERT INTO public.agent_events(
              id,tenant_id,run_id,ticket_id,customer_id,sequence,ticket_sequence,
              run_sequence,step_index,tool_round,job_id,event_type,status,
              visibility,payload,payload_hash,previous_event_id,parent_event_hash,
              event_hash,event_schema_version,canonicalization_version,
              event_hash_schema_version,correlation_id,causation_id,
              idempotency_id,fencing_token,created_at
            ) VALUES (
              v_event_id,p_tenant_id,v_run.id,v_ticket.id,v_ticket.customer_id,
              v_run_sequence,v_ticket_sequence,v_run_sequence,v_run.step_index,
              v_run.tool_rounds,p_job_id,'runtime_failed','completed','customer',
              v_payload,v_payload_hash,
              CASE WHEN v_parent.run_id=v_run.id THEN v_parent.id END,
              coalesce(v_parent.event_hash,repeat('0',64)),v_event_hash,
              'support-ticket-event.v1','json-sort-keys.v1','event-hash.v1',
              v_run.id,v_parent.id,p_job_id,v_job.fencing_token,v_now
            );
          END IF;

          UPDATE public.agent_runs
          SET status='failed',error_code=coalesce(v_job.last_error,'runtime_failed'),
              agent_finish_reason='infrastructure_exhausted',
              active_job_id=NULL,active_fencing_token=NULL,
              completed_at=coalesce(completed_at,v_now),
              status_version=status_version+1,updated_at=v_now
          WHERE tenant_id=p_tenant_id AND id=v_run.id
            AND (
              status<>'failed' OR active_job_id IS NOT NULL
              OR active_fencing_token IS NOT NULL
              OR agent_finish_reason IS DISTINCT FROM 'infrastructure_exhausted'
              OR completed_at IS NULL
            );
          IF v_turn.id IS NOT NULL THEN
            UPDATE public.conversation_turns
            SET activity_state='failed',result_state='failed',
                completed_at=coalesce(completed_at,v_now),updated_at=v_now
            WHERE tenant_id=p_tenant_id AND id=v_turn.id
              AND (
                activity_state<>'failed'
                OR result_state IS DISTINCT FROM 'failed'
                OR completed_at IS NULL
              );
          END IF;
          UPDATE public.support_tickets
          SET status='failed',
              final_response=(
                '本次自动处理未能安全完成。你可以稍后重试或发送一条新消息；'
                ||'系统没有因此执行任何新的高风险操作。'
              ),
              version=version+1,updated_at=v_now
          WHERE tenant_id=p_tenant_id AND id=v_ticket.id
            AND status<>'failed';
          IF v_approval.id IS NOT NULL THEN
            UPDATE public.approval_requests
            SET status='failed',status_version=status_version+1,updated_at=v_now
            WHERE tenant_id=p_tenant_id AND id=v_approval.id
              AND status IN ('pending','approved');
          END IF;
          IF v_proposal.id IS NOT NULL THEN
            UPDATE public.proposal_records
            SET status='stale',status_version=status_version+1,updated_at=v_now
            WHERE tenant_id=p_tenant_id AND id=v_proposal.id
              AND status IN ('draft','bound');
          END IF;
          UPDATE public.checkpoint_commit_markers
          SET status='aborted',status_version=status_version+1,updated_at=v_now
          WHERE tenant_id=p_tenant_id AND job_id=p_job_id
            AND status IN ('prepared','checkpoint_written');
          PERFORM public.supportguard_internal_publish_runtime_failure(
            p_tenant_id,v_ticket.id,v_run.id,v_approval.id,p_job_id,
            coalesce(v_job.last_error,'runtime_failed')
          );
          PERFORM public.supportguard_internal_activate_next_ticket_turn(
            p_tenant_id,v_ticket.id,p_job_id
          );
          PERFORM public.supportguard_internal_converge_ticket_status(
            p_tenant_id,v_ticket.id,'failed'
          );
          RETURN jsonb_build_object(
            'ticket_id',v_ticket.id,'run_id',v_run.id,
            'dead_event_id',v_event_id
          );
        END
        $$;


ALTER FUNCTION public.supportguard_internal_converge_dead_job(p_tenant_id text, p_job_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_converge_ticket_status(text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_converge_ticket_status(p_tenant_id text, p_ticket_id text, p_default_status text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_ticket public.support_tickets%ROWTYPE;
          v_status text;
          v_now timestamptz:=statement_timestamp();
        BEGIN
          IF p_default_status IS NULL OR p_default_status NOT IN (
            'open','running','queued','awaiting_approval','verification_pending',
            'needs_clarification','resolved','rejected','manual_takeover','failed'
          ) THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='ticket_convergence_default_status_invalid';
          END IF;
          PERFORM set_config('app.tenant_id',p_tenant_id,true);
          SELECT * INTO v_ticket
          FROM public.support_tickets
          WHERE tenant_id=p_tenant_id AND id=p_ticket_id
          FOR UPDATE;
          IF v_ticket.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='23503',
              MESSAGE='ticket_convergence_ticket_missing';
          END IF;
          IF v_ticket.lifecycle<>'active'
             OR v_ticket.automation_mode<>'agent' THEN
            RETURN v_ticket.status;
          END IF;

          v_status:=CASE
            WHEN EXISTS (
              SELECT 1
              FROM public.conversation_turns turn_row
              WHERE turn_row.tenant_id=p_tenant_id
                AND turn_row.ticket_id=p_ticket_id
                AND turn_row.activity_state IN ('queued','running')
            ) OR EXISTS (
              SELECT 1
              FROM public.runtime_jobs job
              WHERE job.tenant_id=p_tenant_id
                AND job.ticket_id=p_ticket_id
                AND job.status IN ('queued','retry_wait','leased')
            ) THEN 'queued'
            WHEN EXISTS (
              SELECT 1
              FROM public.approval_requests approval
              JOIN public.runtime_jobs job
                ON job.tenant_id=approval.tenant_id
               AND job.ticket_id=approval.ticket_id
               AND job.approval_id=approval.id
              WHERE approval.tenant_id=p_tenant_id
                AND approval.ticket_id=p_ticket_id
                AND approval.status='approved'
                AND job.status='succeeded'
                AND job.outcome='verification_pending'
            ) THEN 'verification_pending'
            WHEN EXISTS (
              SELECT 1
              FROM public.approval_requests approval
              WHERE approval.tenant_id=p_tenant_id
                AND approval.ticket_id=p_ticket_id
                AND approval.status IN ('pending','approved')
            ) THEN 'awaiting_approval'
            ELSE p_default_status
          END;

          UPDATE public.support_tickets
          SET status=v_status,
              final_response=CASE
                WHEN v_status IN (
                  'running','queued','awaiting_approval','verification_pending'
                ) THEN NULL
                ELSE final_response
              END,
              version=version+1,
              updated_at=v_now
          WHERE tenant_id=p_tenant_id AND id=p_ticket_id
            AND (
              status IS DISTINCT FROM v_status
              OR (
                v_status IN (
                  'running','queued','awaiting_approval','verification_pending'
                )
                AND final_response IS NOT NULL
              )
            );
          RETURN v_status;
        END
        $$;


ALTER FUNCTION public.supportguard_internal_converge_ticket_status(p_tenant_id text, p_ticket_id text, p_default_status text) OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_format_utc_timestamp(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_format_utc_timestamp(p_value timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
          SELECT pg_catalog.to_char(
            p_value AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US'
          ) || '+00:00'
        $$;


ALTER FUNCTION public.supportguard_internal_format_utc_timestamp(p_value timestamp with time zone) OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_publish_runtime_failure(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_publish_runtime_failure(p_tenant_id text, p_ticket_id text, p_run_id text, p_approval_id text, p_job_id text, p_error_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_failure_category text;
        BEGIN
          v_failure_category:=CASE
            WHEN p_error_code IS NULL OR p_error_code='' THEN 'runtime'
            WHEN pg_catalog.lower(p_error_code)
              ~ '^(api_request|request_trace|api_gateway|request_id)'
              THEN 'api_request'
            WHEN pg_catalog.strpos(
              pg_catalog.lower(p_error_code),'provider'
            )>0 OR pg_catalog.strpos(
              pg_catalog.lower(p_error_code),'llm'
            )>0 OR pg_catalog.strpos(
              pg_catalog.lower(p_error_code),'model'
            )>0 OR pg_catalog.strpos(
              pg_catalog.lower(p_error_code),'upstream'
            )>0 THEN 'provider'
            WHEN pg_catalog.strpos(
              pg_catalog.lower(p_error_code),'mcp'
            )>0 OR pg_catalog.strpos(
              pg_catalog.lower(p_error_code),'tool'
            )>0 OR pg_catalog.strpos(
              pg_catalog.lower(p_error_code),'capability'
            )>0 OR pg_catalog.strpos(
              pg_catalog.lower(p_error_code),'observation'
            )>0 THEN 'tool'
            ELSE 'runtime'
          END;
          IF EXISTS (
            SELECT 1 FROM public.ticket_messages m
            WHERE m.tenant_id=p_tenant_id
              AND m.publication_key='runtime-failure:'||p_job_id
          ) THEN
            RETURN;
          END IF;
          INSERT INTO public.ticket_messages(
            id,tenant_id,ticket_id,turn_id,run_id,approval_id,message_kind,
            publication_key,role,content,source_refs,created_at,updated_at
          )
          SELECT 'msg_'||pg_catalog.md5('runtime-failure:'||p_job_id),
                 p_tenant_id,p_ticket_id,r.turn_id,p_run_id,p_approval_id,
                 CASE WHEN p_approval_id IS NULL
                   THEN 'assistant' ELSE 'action_update' END,
                 'runtime-failure:'||p_job_id,
                 CASE WHEN p_approval_id IS NULL
                   THEN 'assistant' ELSE 'action' END,
                 '已检查：系统已检查本轮请求并尝试完成自动诊断。'
                   ||E'\n'||'已确认：本轮没有形成可验证的完整结果，自动处理已停止。'
                   ||E'\n'||'仍未知（公开类别：'
                   ||v_failure_category||'）：'
                   ||CASE v_failure_category
                     WHEN 'api_request' THEN
                       '当前还无法把问题与具体 API 请求记录关联'
                     WHEN 'provider' THEN
                       '当前还无法确认模型服务是否完成了本轮推理'
                     WHEN 'tool' THEN
                       '当前还无法确认所需业务数据是否完整返回'
                     ELSE
                       '当前还无法确认自动流程完成到了哪一个可恢复步骤'
                   END||'。'
                   ||E'\n'||'审批与业务副作用状态：'
                   ||CASE
                     WHEN NOT EXISTS (
                       SELECT 1 FROM public.approval_requests approval
                       WHERE approval.tenant_id=p_tenant_id
                         AND approval.id=p_approval_id
                     ) THEN
                       '本轮未绑定审批；系统未记录与本轮失败绑定的成功业务动作。'
                     ELSE
                       '关联审批状态为“'
                       ||CASE (
                         SELECT approval.status
                         FROM public.approval_requests approval
                         WHERE approval.tenant_id=p_tenant_id
                           AND approval.id=p_approval_id
                         LIMIT 1
                       )
                         WHEN 'pending' THEN '待审批'
                         WHEN 'approved' THEN '已批准'
                         WHEN 'executed' THEN '已执行'
                         WHEN 'rejected' THEN '已拒绝'
                         WHEN 'stale' THEN '已失效'
                         WHEN 'withdrawn' THEN '已撤回'
                         WHEN 'failed' THEN '失败'
                         WHEN 'manual_takeover' THEN '自动处理已停止'
                         ELSE '尚无法确认'
                       END||'”；'
                       ||CASE WHEN EXISTS (
                         SELECT 1
                         FROM public.business_actions business_action
                         WHERE business_action.tenant_id=p_tenant_id
                           AND business_action.approval_id=p_approval_id
                           AND business_action.status='succeeded'
                       ) THEN
                         '系统已记录成功的业务动作。'
                       ELSE
                         '系统未记录与其绑定的成功业务动作。'
                       END
                   END
                   ||E'\n'||'可执行下一步：'
                   ||CASE WHEN EXISTS (
                     SELECT 1 FROM public.business_actions business_action
                     WHERE business_action.tenant_id=p_tenant_id
                       AND business_action.approval_id=p_approval_id
                       AND business_action.status='succeeded'
                   ) THEN
                     '请先查看审批详情确认已执行结果，不要直接重复提交同一变更。'
                   ELSE
                     CASE v_failure_category
                       WHEN 'api_request' THEN
                         '请重试；若仍失败，请补充 Request ID 和发生时间。'
                       WHEN 'provider' THEN
                         '请稍后重试；若仍失败，请保留发生时间和相关资源编号。'
                       WHEN 'tool' THEN
                         '请核对账单、API Key 或订阅编号后重试。'
                       ELSE
                         '请稍后重试，或发送一条新消息重新开始本轮处理。'
                     END
                   END,
                 pg_catalog.jsonb_build_array(
                   pg_catalog.jsonb_build_object(
                     'failure_category',v_failure_category
                   )
                 ),
                 statement_timestamp(),statement_timestamp()
          FROM public.agent_runs r
          WHERE r.tenant_id=p_tenant_id AND r.id=p_run_id
          ON CONFLICT (tenant_id,publication_key) DO NOTHING;
        END
        $$;


ALTER FUNCTION public.supportguard_internal_publish_runtime_failure(p_tenant_id text, p_ticket_id text, p_run_id text, p_approval_id text, p_job_id text, p_error_code text) OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_publish_verified_zero_effect_event(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_publish_verified_zero_effect_event(p_tenant_id text, p_ticket_id text, p_run_id text, p_approval_id text, p_job_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
          v_ticket public.support_tickets%ROWTYPE;
          v_run public.agent_runs%ROWTYPE;
          v_approval public.approval_requests%ROWTYPE;
          v_job public.runtime_jobs%ROWTYPE;
          v_parent public.agent_events%ROWTYPE;
          v_run_parent public.agent_events%ROWTYPE;
          v_existing public.agent_events%ROWTYPE;
          v_now timestamptz:=statement_timestamp();
          v_ticket_sequence bigint;
          v_run_sequence bigint;
          v_event_id text;
          v_idempotency_id text;
          v_payload jsonb;
          v_payload_text text;
          v_payload_hash text;
          v_created_at_text text;
          v_envelope text;
          v_event_hash text;
        BEGIN
          IF session_user<>'supportguard_reconciler' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='verified zero-effect event caller is not authorized';
          END IF;

          SELECT * INTO v_ticket
          FROM public.support_tickets
          WHERE tenant_id=p_tenant_id AND id=p_ticket_id
          FOR UPDATE;
          SELECT * INTO v_approval
          FROM public.approval_requests
          WHERE tenant_id=p_tenant_id AND id=p_approval_id
            AND ticket_id=p_ticket_id AND run_id=p_run_id
          FOR UPDATE;
          SELECT * INTO v_run
          FROM public.agent_runs
          WHERE tenant_id=p_tenant_id AND id=p_run_id
            AND ticket_id=p_ticket_id
          FOR UPDATE;
          SELECT * INTO v_job
          FROM public.runtime_jobs
          WHERE tenant_id=p_tenant_id AND id=p_job_id
            AND ticket_id=p_ticket_id AND run_id=p_run_id
            AND approval_id=p_approval_id
          FOR UPDATE;
          IF v_ticket.id IS NULL OR v_approval.id IS NULL
             OR v_run.id IS NULL OR v_job.id IS NULL
             OR v_approval.status<>'failed'
             OR v_job.status<>'succeeded'
             OR v_job.outcome<>'verified_zero_effect'
             OR EXISTS (
               SELECT 1
               FROM public.business_actions action
               WHERE action.tenant_id=p_tenant_id
                 AND action.approval_id=p_approval_id
                 AND action.status IN (
                   'succeeded','unknown','verification_pending',
                   'pending','running','executing'
                 )
             ) THEN
            RAISE EXCEPTION USING ERRCODE='55000',
              MESSAGE='verified_zero_effect_event_state_conflict';
          END IF;

          v_event_id:='event_'||pg_catalog.md5(
            'v1512:verified-zero-effect:'||p_tenant_id||':'||p_job_id
          );
          v_idempotency_id:='verified-zero-effect:'||p_job_id;
          v_payload:=pg_catalog.jsonb_build_object(
            'approval_id',p_approval_id,
            'job_id',p_job_id,
            'reason_code','verified_zero_effect'
          );
          v_payload_text:='{"approval_id":'
            ||pg_catalog.to_jsonb(p_approval_id)::text
            ||',"job_id":'||pg_catalog.to_jsonb(p_job_id)::text
            ||',"reason_code":"verified_zero_effect"}';
          v_payload_hash:=pg_catalog.encode(
            pg_catalog.sha256(
              pg_catalog.convert_to(v_payload_text,'UTF8')
            ),
            'hex'
          );
          SELECT * INTO v_existing
          FROM public.agent_events
          WHERE tenant_id=p_tenant_id AND id=v_event_id;
          IF v_existing.id IS NOT NULL THEN
            SELECT * INTO v_parent
            FROM public.agent_events
            WHERE tenant_id=p_tenant_id AND ticket_id=p_ticket_id
              AND ticket_sequence=v_existing.ticket_sequence-1;
            SELECT * INTO v_run_parent
            FROM public.agent_events
            WHERE tenant_id=p_tenant_id AND run_id=p_run_id
              AND run_sequence<v_existing.run_sequence
            ORDER BY run_sequence DESC,id DESC
            LIMIT 1;
            v_created_at_text:=pg_catalog.to_char(
              v_existing.created_at AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US'
            )||'+00:00';
            v_envelope:='{"aggregate_id":'||pg_catalog.to_jsonb(p_ticket_id)::text
              ||',"aggregate_type":"SupportTicket"'
              ||',"canonicalization_version":"json-sort-keys.v1"'
              ||',"causation_id":'
              ||coalesce(pg_catalog.to_jsonb(v_parent.id)::text,'null')
              ||',"correlation_id":'||pg_catalog.to_jsonb(p_run_id)::text
              ||',"created_at":'||pg_catalog.to_jsonb(v_created_at_text)::text
              ||',"customer_id":'||pg_catalog.to_jsonb(v_ticket.customer_id)::text
              ||',"delivery_generation":null'
              ||',"event_id":'||pg_catalog.to_jsonb(v_event_id)::text
              ||',"event_schema_version":"support-ticket-event.v1"'
              ||',"event_type":"runtime_failed"'
              ||',"fencing_token":'||v_job.fencing_token::text
              ||',"idempotency_id":'||pg_catalog.to_jsonb(v_idempotency_id)::text
              ||',"job_id":'||pg_catalog.to_jsonb(p_job_id)::text
              ||',"payload_hash":'||pg_catalog.to_jsonb(v_payload_hash)::text
              ||',"previous_event_id":'
              ||coalesce(
                pg_catalog.to_jsonb(
                  CASE WHEN v_parent.run_id=p_run_id THEN v_parent.id END
                )::text,
                'null'
              )
              ||',"run_id":'||pg_catalog.to_jsonb(p_run_id)::text
              ||',"run_sequence":'||v_existing.run_sequence::text
              ||',"status":"completed"'
              ||',"step_index":'||v_run.step_index::text
              ||',"tenant_id":'||pg_catalog.to_jsonb(p_tenant_id)::text
              ||',"ticket_sequence":'||v_existing.ticket_sequence::text
              ||',"tool_call_id":null'
              ||',"tool_round":'||v_run.tool_rounds::text
              ||',"visibility":"customer"}';
            v_event_hash:=pg_catalog.encode(
              pg_catalog.sha256(
                pg_catalog.convert_to(
                  'event-hash.v1'||v_envelope
                    ||coalesce(
                      v_parent.event_hash,
                      pg_catalog.repeat('0',64)
                    ),
                  'UTF8'
                )
              ),
              'hex'
            );
            IF v_existing.ticket_id IS DISTINCT FROM p_ticket_id
               OR v_existing.run_id IS DISTINCT FROM p_run_id
               OR v_existing.customer_id IS DISTINCT FROM v_ticket.customer_id
               OR v_existing.job_id IS DISTINCT FROM p_job_id
               OR v_existing.sequence IS DISTINCT FROM v_existing.run_sequence
               OR v_existing.run_sequence IS DISTINCT FROM
                    coalesce(v_run_parent.run_sequence,0)+1
               OR v_existing.run_sequence<1
               OR v_existing.ticket_sequence<1
               OR v_ticket.next_event_sequence<v_existing.ticket_sequence
               OR v_run.next_run_sequence<v_existing.run_sequence
               OR v_existing.step_index IS DISTINCT FROM v_run.step_index
               OR v_existing.tool_round IS DISTINCT FROM v_run.tool_rounds
               OR (
                 v_existing.ticket_sequence=1 AND v_parent.id IS NOT NULL
               )
               OR (
                 v_existing.ticket_sequence>1 AND v_parent.id IS NULL
               )
               OR v_existing.event_type IS DISTINCT FROM 'runtime_failed'
               OR v_existing.status IS DISTINCT FROM 'completed'
               OR v_existing.visibility IS DISTINCT FROM 'customer'
               OR v_existing.tool_call_id IS NOT NULL
               OR v_existing.delivery_generation IS NOT NULL
               OR v_existing.payload::jsonb IS DISTINCT FROM v_payload
               OR v_existing.payload_hash IS DISTINCT FROM v_payload_hash
               OR v_existing.previous_event_id IS DISTINCT FROM
                    (
                      CASE
                        WHEN v_parent.run_id=p_run_id THEN v_parent.id
                        ELSE NULL
                      END
                    )
               OR v_existing.parent_event_hash IS DISTINCT FROM
                    coalesce(
                      v_parent.event_hash,
                      pg_catalog.repeat('0',64)
                    )
               OR v_existing.event_hash IS DISTINCT FROM v_event_hash
               OR v_existing.idempotency_id IS DISTINCT FROM v_idempotency_id
               OR v_existing.fencing_token IS DISTINCT FROM v_job.fencing_token
               OR v_existing.event_schema_version IS DISTINCT FROM
                    'support-ticket-event.v1'
               OR v_existing.canonicalization_version IS DISTINCT FROM
                    'json-sort-keys.v1'
               OR v_existing.event_hash_schema_version IS DISTINCT FROM
                    'event-hash.v1'
               OR v_existing.correlation_id IS DISTINCT FROM p_run_id
               OR v_existing.causation_id IS DISTINCT FROM v_parent.id THEN
              RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='verified_zero_effect_event_identity_conflict';
            END IF;
            RETURN v_existing.id;
          END IF;

          SELECT * INTO v_parent
          FROM public.agent_events
          WHERE tenant_id=p_tenant_id AND ticket_id=p_ticket_id
          ORDER BY ticket_sequence DESC,id DESC
          LIMIT 1;
          SELECT * INTO v_run_parent
          FROM public.agent_events
          WHERE tenant_id=p_tenant_id AND run_id=p_run_id
          ORDER BY run_sequence DESC,id DESC
          LIMIT 1;
          IF v_ticket.next_event_sequence IS DISTINCT FROM
               coalesce(v_parent.ticket_sequence,0)
             OR v_run.next_run_sequence IS DISTINCT FROM
               coalesce(v_run_parent.run_sequence,0) THEN
            RAISE EXCEPTION USING ERRCODE='55000',
              MESSAGE='verified_zero_effect_event_head_conflict';
          END IF;

          v_ticket_sequence:=v_ticket.next_event_sequence+1;
          v_run_sequence:=v_run.next_run_sequence+1;
          v_created_at_text:=pg_catalog.to_char(
            v_now AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US'
          )||'+00:00';
          v_envelope:='{"aggregate_id":'||pg_catalog.to_jsonb(p_ticket_id)::text
            ||',"aggregate_type":"SupportTicket"'
            ||',"canonicalization_version":"json-sort-keys.v1"'
            ||',"causation_id":'
            ||coalesce(pg_catalog.to_jsonb(v_parent.id)::text,'null')
            ||',"correlation_id":'||pg_catalog.to_jsonb(p_run_id)::text
            ||',"created_at":'||pg_catalog.to_jsonb(v_created_at_text)::text
            ||',"customer_id":'||pg_catalog.to_jsonb(v_ticket.customer_id)::text
            ||',"delivery_generation":null'
            ||',"event_id":'||pg_catalog.to_jsonb(v_event_id)::text
            ||',"event_schema_version":"support-ticket-event.v1"'
            ||',"event_type":"runtime_failed"'
            ||',"fencing_token":'||v_job.fencing_token::text
            ||',"idempotency_id":'||pg_catalog.to_jsonb(v_idempotency_id)::text
            ||',"job_id":'||pg_catalog.to_jsonb(p_job_id)::text
            ||',"payload_hash":'||pg_catalog.to_jsonb(v_payload_hash)::text
            ||',"previous_event_id":'
            ||coalesce(
              pg_catalog.to_jsonb(
                CASE WHEN v_parent.run_id=p_run_id THEN v_parent.id END
              )::text,
              'null'
            )
            ||',"run_id":'||pg_catalog.to_jsonb(p_run_id)::text
            ||',"run_sequence":'||v_run_sequence::text
            ||',"status":"completed"'
            ||',"step_index":'||v_run.step_index::text
            ||',"tenant_id":'||pg_catalog.to_jsonb(p_tenant_id)::text
            ||',"ticket_sequence":'||v_ticket_sequence::text
            ||',"tool_call_id":null'
            ||',"tool_round":'||v_run.tool_rounds::text
            ||',"visibility":"customer"}';
          v_event_hash:=pg_catalog.encode(
            pg_catalog.sha256(
              pg_catalog.convert_to(
                'event-hash.v1'||v_envelope
                  ||coalesce(v_parent.event_hash,pg_catalog.repeat('0',64)),
                'UTF8'
              )
            ),
            'hex'
          );

          UPDATE public.support_tickets
          SET next_event_sequence=v_ticket_sequence
          WHERE tenant_id=p_tenant_id AND id=p_ticket_id;
          UPDATE public.agent_runs
          SET next_run_sequence=v_run_sequence
          WHERE tenant_id=p_tenant_id AND id=p_run_id;
          INSERT INTO public.agent_events(
            id,tenant_id,run_id,ticket_id,customer_id,sequence,ticket_sequence,
            run_sequence,step_index,tool_round,job_id,event_type,status,
            visibility,payload,payload_hash,previous_event_id,parent_event_hash,
            event_hash,event_schema_version,canonicalization_version,
            event_hash_schema_version,correlation_id,causation_id,
            idempotency_id,fencing_token,created_at
          ) VALUES (
            v_event_id,p_tenant_id,p_run_id,p_ticket_id,v_ticket.customer_id,
            v_run_sequence,v_ticket_sequence,v_run_sequence,v_run.step_index,
            v_run.tool_rounds,p_job_id,'runtime_failed','completed','customer',
            v_payload,v_payload_hash,
            CASE WHEN v_parent.run_id=p_run_id THEN v_parent.id END,
            coalesce(v_parent.event_hash,pg_catalog.repeat('0',64)),
            v_event_hash,'support-ticket-event.v1','json-sort-keys.v1',
            'event-hash.v1',p_run_id,v_parent.id,v_idempotency_id,
            v_job.fencing_token,v_now
          );
          RETURN v_event_id;
        END
        $$;


ALTER FUNCTION public.supportguard_internal_publish_verified_zero_effect_event(p_tenant_id text, p_ticket_id text, p_run_id text, p_approval_id text, p_job_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_internal_validate_approval_transition(text, text, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_internal_validate_approval_transition(p_old_status text, p_new_status text, p_operation text, p_old_status_version bigint, p_new_status_version bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF p_operation='INSERT' THEN
            IF p_old_status IS NOT NULL OR p_new_status<>'pending'
               OR p_new_status_version<>1 THEN
              RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='approval_insert_state_invalid';
            END IF;
            RETURN;
          END IF;
          IF p_operation='UPDATE' AND p_new_status=p_old_status THEN
            IF p_new_status_version<>p_old_status_version THEN
              RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='approval_same_state_version_invalid';
            END IF;
            RETURN;
          END IF;
          IF p_operation<>'UPDATE'
             OR p_new_status='manual_takeover'
             OR p_new_status_version<>p_old_status_version+1
             OR NOT (
               (p_old_status='pending' AND p_new_status IN (
                 'approved','rejected','withdrawn','stale','failed'
               ))
               OR (
                 p_old_status='approved'
                 AND p_new_status IN ('executed','stale','failed')
               )
             ) THEN
            RAISE EXCEPTION USING ERRCODE='55000',
              MESSAGE='approval_status_transition_invalid';
          END IF;
        END
        $$;


ALTER FUNCTION public.supportguard_internal_validate_approval_transition(p_old_status text, p_new_status text, p_operation text, p_old_status_version bigint, p_new_status_version bigint) OWNER TO supportguard_owner;

--
-- Name: supportguard_knowledge_interval_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_knowledge_interval_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
            IF EXISTS (
                SELECT 1 FROM public.knowledge_documents d
                 WHERE d.id <> NEW.id
                   AND d.index_version = NEW.index_version
                   AND d.document_family_key = NEW.document_family_key
                   AND d.applicability_scope_hash = NEW.applicability_scope_hash
                   AND tstzrange(d.effective_from,d.effective_until,'[)') &&
                       tstzrange(NEW.effective_from,NEW.effective_until,'[)')
            ) THEN
                RAISE EXCEPTION USING ERRCODE='23514',
                    MESSAGE='knowledge_effective_interval_overlap';
            END IF;
            RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_knowledge_interval_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_maintenance_abort_trim(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_maintenance_abort_trim(p_intent_id text, p_typed_negative_redis_receipt_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_intent public.retention_trim_intents%ROWTYPE;
                v_negative text;
                v_unknown text;
        BEGIN
          IF session_user<>'supportguard_maintenance' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='maintenance_role_required';
          END IF;
          SELECT * INTO v_intent FROM public.retention_trim_intents
           WHERE id=p_intent_id FOR UPDATE;
          IF v_intent.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='trim_intent_missing';
          END IF;
          v_negative:=encode(sha256(convert_to(concat_ws('|',
            'negative-xdel.v1',v_intent.id,v_intent.redis_message_locator,
            v_intent.payload_hash,v_intent.group_set_hash),'utf8')),'hex');
          v_unknown:=encode(sha256(convert_to(concat_ws('|',
            'unknown-xdel.v1',v_intent.id,v_intent.redis_message_locator,
            v_intent.payload_hash,v_intent.group_set_hash),'utf8')),'hex');
          IF v_intent.status='aborted' AND v_intent.terminal_receipt_hash=v_negative
             AND p_typed_negative_redis_receipt_hash=v_negative THEN
            RETURN jsonb_build_object('intent_id',v_intent.id,'status','aborted','reused',true);
          END IF;
          IF v_intent.status='unknown_trim_state'
             AND v_intent.terminal_receipt_hash=v_unknown
             AND p_typed_negative_redis_receipt_hash=v_unknown THEN
            RETURN jsonb_build_object('intent_id',v_intent.id,
              'status','unknown_trim_state','reused',true);
          END IF;
          IF v_intent.status NOT IN ('authorized','redis_trimmed') THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='trim_abort_state_invalid';
          END IF;
          IF p_typed_negative_redis_receipt_hash=v_negative
             AND v_intent.status='authorized' THEN
            UPDATE public.retention_trim_intents SET status='aborted',
                aborted_at=clock_timestamp(),terminal_receipt_hash=v_negative,
                updated_at=clock_timestamp() WHERE id=v_intent.id;
            RETURN jsonb_build_object('intent_id',v_intent.id,
              'status','aborted','reused',false);
          ELSIF p_typed_negative_redis_receipt_hash=v_unknown THEN
            UPDATE public.retention_trim_intents SET status='unknown_trim_state',
                terminal_receipt_hash=v_unknown,updated_at=clock_timestamp()
             WHERE id=v_intent.id;
            RETURN jsonb_build_object('intent_id',v_intent.id,
              'status','unknown_trim_state','reused',false);
          END IF;
          RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='trim_negative_receipt_invalid';
        END $$;


ALTER FUNCTION public.supportguard_maintenance_abort_trim(p_intent_id text, p_typed_negative_redis_receipt_hash text) OWNER TO supportguard_owner;

--
-- Name: supportguard_maintenance_apply_pg_retention(text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_maintenance_apply_pg_retention(p_plan_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_plan jsonb;
                v_items jsonb;
                v_count bigint;
                v_deleted jsonb := '{}'::jsonb;
        BEGIN
            IF session_user<>'supportguard_maintenance' THEN
                RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='maintenance_role_required';
            END IF;
            v_plan := public.supportguard_maintenance_plan_pg_retention();
            IF p_plan_id IS NULL OR p_plan_id<>v_plan->>'plan_id' THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='retention_plan_stale';
            END IF;
            v_items := v_plan->'items';
            DELETE FROM public.service_instance_heartbeats h
            WHERE h.id IN (SELECT jsonb_array_elements_text(v_items->'service_instance_heartbeats'));
            GET DIAGNOSTICS v_count=ROW_COUNT;
            v_deleted:=v_deleted||jsonb_build_object('service_instance_heartbeats',v_count);
            DELETE FROM public.api_request_traces t
            WHERE t.id IN (SELECT jsonb_array_elements_text(v_items->'api_request_traces'));
            GET DIAGNOSTICS v_count=ROW_COUNT;
            v_deleted:=v_deleted||jsonb_build_object('api_request_traces',v_count);
            DELETE FROM public.checkpoint_writes w USING jsonb_to_recordset(
                v_items->'checkpoint_namespaces'
            ) AS x(thread_id text,checkpoint_ns text)
            WHERE w.thread_id=x.thread_id AND w.checkpoint_ns=x.checkpoint_ns;
            GET DIAGNOSTICS v_count=ROW_COUNT;
            v_deleted:=v_deleted||jsonb_build_object('checkpoint_writes',v_count);
            DELETE FROM public.checkpoints c USING jsonb_to_recordset(
                v_items->'checkpoint_namespaces'
            ) AS x(thread_id text,checkpoint_ns text)
            WHERE c.thread_id=x.thread_id AND c.checkpoint_ns=x.checkpoint_ns;
            GET DIAGNOSTICS v_count=ROW_COUNT;
            v_deleted:=v_deleted||jsonb_build_object('checkpoints',v_count);
            DELETE FROM public.checkpoint_blobs b USING jsonb_to_recordset(
                v_items->'checkpoint_namespaces'
            ) AS x(thread_id text,checkpoint_ns text)
            WHERE b.thread_id=x.thread_id AND b.checkpoint_ns=x.checkpoint_ns
              AND NOT EXISTS (
                SELECT 1 FROM public.checkpoints c
                WHERE c.thread_id=b.thread_id AND c.checkpoint_ns=b.checkpoint_ns
              );
            GET DIAGNOSTICS v_count=ROW_COUNT;
            v_deleted:=v_deleted||jsonb_build_object('checkpoint_blobs',v_count);
            DELETE FROM public.knowledge_chunks c
            WHERE c.ingest_run_id IN (
                SELECT jsonb_array_elements_text(v_items->'knowledge_ingest_runs')
            );
            GET DIAGNOSTICS v_count=ROW_COUNT;
            v_deleted:=v_deleted||jsonb_build_object('knowledge_chunks',v_count);
            DELETE FROM public.knowledge_documents d
            WHERE d.ingest_run_id IN (
                SELECT jsonb_array_elements_text(v_items->'knowledge_ingest_runs')
            );
            GET DIAGNOSTICS v_count=ROW_COUNT;
            v_deleted:=v_deleted||jsonb_build_object('knowledge_documents',v_count);
            DELETE FROM public.knowledge_ingest_runs k
            WHERE k.id IN (SELECT jsonb_array_elements_text(v_items->'knowledge_ingest_runs'));
            GET DIAGNOSTICS v_count=ROW_COUNT;
            v_deleted:=v_deleted||jsonb_build_object('knowledge_ingest_runs',v_count);
            DELETE FROM public.idempotency_requests i
            WHERE i.id IN (SELECT jsonb_array_elements_text(v_items->'idempotency_requests'));
            GET DIAGNOSTICS v_count=ROW_COUNT;
            v_deleted:=v_deleted||jsonb_build_object('idempotency_requests',v_count);
            RETURN jsonb_build_object(
                'schema_version','pg-retention-apply.v1','plan_id',p_plan_id,
                'deleted',v_deleted
            );
        END $$;


ALTER FUNCTION public.supportguard_maintenance_apply_pg_retention(p_plan_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_maintenance_authorize_trim(text, text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_maintenance_authorize_trim(p_intent_id text, p_stream text, p_redis_message_id text, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
        DECLARE v_outbox public.outbox_events%ROWTYPE;
                v_eligibility jsonb;
                v_intent public.retention_trim_intents%ROWTYPE;
        BEGIN
            IF session_user<>'supportguard_maintenance' THEN
                RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='maintenance_role_required';
            END IF;
            IF coalesce(length(p_intent_id),0)=0 OR coalesce(length(p_stream),0)=0
               OR p_payload_hash !~ '^[0-9a-f]{64}$' THEN
                RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='retention_trim_input_invalid';
            END IF;
            SELECT * INTO v_outbox FROM public.outbox_events
            WHERE redis_message_id=p_redis_message_id AND superseded_at IS NULL
            FOR UPDATE;
            IF v_outbox.id IS NULL THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='trim_outbox_missing';
            END IF;
            v_eligibility := public.supportguard_maintenance_trim_eligibility(
                v_outbox.job_id,v_outbox.run_id,v_outbox.tenant_id
            );
            IF NOT coalesce((v_eligibility->>'eligible')::boolean,false) THEN
                RAISE EXCEPTION USING ERRCODE='55000',
                    MESSAGE='trim_not_eligible',DETAIL=v_eligibility->>'reason';
            END IF;
            INSERT INTO public.retention_trim_intents(
                id,tenant_id,run_id,job_id,outbox_locator,stream,redis_message_locator,
                payload_hash,group_set_hash,status,eligibility_version,
                dependency_set_hash,anchor_at,authorized_at
            ) VALUES (
                p_intent_id,v_outbox.tenant_id,v_outbox.run_id,v_outbox.job_id,
                v_outbox.id,p_stream,p_redis_message_id,p_payload_hash,
                '3a0fde6ba7d90c905877897d4ddad78298e4e7b587248f8520de9393cb60148d','authorized',
                (v_eligibility->>'eligibility_version')::bigint,
                v_eligibility->>'dependency_set_hash',
                (v_eligibility->>'anchor_at')::timestamptz,clock_timestamp()
            ) ON CONFLICT (stream,redis_message_locator) DO NOTHING;
            SELECT * INTO v_intent FROM public.retention_trim_intents
            WHERE stream=p_stream AND redis_message_locator=p_redis_message_id FOR UPDATE;
            IF v_intent.payload_hash<>p_payload_hash
               OR v_intent.group_set_hash<>'3a0fde6ba7d90c905877897d4ddad78298e4e7b587248f8520de9393cb60148d'
               OR v_intent.outbox_locator<>v_outbox.id
               OR v_intent.eligibility_version<>(v_eligibility->>'eligibility_version')::bigint
               OR v_intent.dependency_set_hash<>v_eligibility->>'dependency_set_hash'
               OR v_intent.status NOT IN ('authorized','redis_trimmed','finalized') THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='trim_intent_conflict';
            END IF;
            RETURN jsonb_build_object(
                'intent_id',v_intent.id,'status',v_intent.status,
                'stream',v_intent.stream,
                'redis_message_id',v_intent.redis_message_locator,
                'payload_hash',v_intent.payload_hash,
                'group_set_hash',v_intent.group_set_hash,
                'eligibility_version',v_intent.eligibility_version,
                'dependency_set_hash',v_intent.dependency_set_hash
            );
        END $_$;


ALTER FUNCTION public.supportguard_maintenance_authorize_trim(p_intent_id text, p_stream text, p_redis_message_id text, p_payload_hash text) OWNER TO supportguard_owner;

--
-- Name: supportguard_maintenance_authorize_trim(text, text, text, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_maintenance_authorize_trim(p_job_id text, p_run_id text, p_tenant_id text, p_delivery_id text, p_redis_message_id text, p_payload_hash text, p_threshold_schema text, p_retention_seconds integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE eligibility jsonb; audit_id text;
        BEGIN
            eligibility := supportguard_maintenance_trim_eligibility(
                p_job_id, p_run_id, p_tenant_id
            );
            IF NOT COALESCE((eligibility->>'eligible')::boolean, false) THEN
                RAISE EXCEPTION 'trim_not_eligible:%', eligibility->>'reason'
                    USING ERRCODE = 'P0001';
            END IF;
            audit_id := 'qaudit_' || replace(gen_random_uuid()::text, '-', '');
            INSERT INTO queue_delivery_audits (
                id, tenant_id, job_id, delivery_id, redis_message_id,
                consumer_group, outcome, payload_hash, details
            ) VALUES (
                audit_id, p_tenant_id, p_job_id, p_delivery_id, p_redis_message_id,
                'maintenance-trim', 'maintenance_trim_authorized', p_payload_hash,
                jsonb_build_object(
                    'threshold_schema_version', p_threshold_schema,
                    'retention_seconds', p_retention_seconds
                )
            ) ON CONFLICT (redis_message_id, consumer_group)
              WHERE consumer_group = 'maintenance-trim'
              DO UPDATE SET details = queue_delivery_audits.details
            RETURNING id INTO audit_id;
            RETURN audit_id;
        END $$;


ALTER FUNCTION public.supportguard_maintenance_authorize_trim(p_job_id text, p_run_id text, p_tenant_id text, p_delivery_id text, p_redis_message_id text, p_payload_hash text, p_threshold_schema text, p_retention_seconds integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_maintenance_finalize_trim(text, boolean); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_maintenance_finalize_trim(p_audit_id text, p_deleted boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
            IF session_user NOT IN ('supportguard_maintenance', 'supportguard') THEN
                RAISE EXCEPTION 'maintenance_role_required' USING ERRCODE = '42501';
            END IF;
            UPDATE queue_delivery_audits
            SET outcome = CASE WHEN p_deleted THEN 'maintenance_trimmed_terminal'
                               ELSE 'maintenance_trim_concurrent_absence' END,
                details = (details::jsonb ||
                           jsonb_build_object('redis_deleted', p_deleted))::json
            WHERE id = p_audit_id AND consumer_group = 'maintenance-trim'
              AND outcome IN ('maintenance_trim_authorized',
                              'maintenance_trimmed_terminal',
                              'maintenance_trim_concurrent_absence');
            RETURN FOUND;
        END $$;


ALTER FUNCTION public.supportguard_maintenance_finalize_trim(p_audit_id text, p_deleted boolean) OWNER TO supportguard_owner;

--
-- Name: supportguard_maintenance_finalize_trim(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_maintenance_finalize_trim(p_intent_id text, p_redis_message_id text, p_payload_hash text, p_group_set_hash text, p_redis_receipt_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
        DECLARE v_intent public.retention_trim_intents%ROWTYPE;
                v_receipt public.retention_trim_receipts%ROWTYPE;
                v_eligibility jsonb;
                v_receipt_hash text;
                v_deleted_inbox bigint;
                v_deleted_outbox bigint;
                v_finalized_at timestamptz;
        BEGIN
            IF session_user<>'supportguard_maintenance' THEN
                RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='maintenance_role_required';
            END IF;
            SELECT * INTO v_intent FROM public.retention_trim_intents
            WHERE id=p_intent_id FOR UPDATE;
            IF v_intent.id IS NULL THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='trim_intent_missing';
            END IF;
            IF v_intent.status='finalized' THEN
                SELECT * INTO v_receipt FROM public.retention_trim_receipts
                WHERE intent_id=v_intent.id;
                IF v_intent.redis_message_locator<>p_redis_message_id
                   OR v_intent.payload_hash<>p_payload_hash
                   OR v_intent.group_set_hash<>p_group_set_hash
                   OR v_receipt.redis_receipt_hash<>p_redis_receipt_hash
                   OR v_receipt.receipt_hash<>v_intent.terminal_receipt_hash THEN
                    RAISE EXCEPTION USING ERRCODE='55000',
                        MESSAGE='trim_finalized_receipt_binding_invalid';
                END IF;
                IF v_intent.updated_at<=v_intent.finalized_at THEN
                    UPDATE public.retention_trim_intents SET updated_at=clock_timestamp()
                    WHERE id=v_intent.id;
                END IF;
                RETURN jsonb_build_object(
                    'intent_id',v_intent.id,'status','finalized','reused',true,
                    'ttl_confirmed',true,'receipt_hash',v_intent.terminal_receipt_hash
                );
            END IF;
            IF v_intent.status NOT IN ('authorized','redis_trimmed')
               OR v_intent.redis_message_locator<>p_redis_message_id
               OR v_intent.payload_hash<>p_payload_hash
               OR v_intent.group_set_hash<>p_group_set_hash
               OR p_redis_receipt_hash !~ '^[0-9a-f]{64}$' THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='trim_receipt_binding_invalid';
            END IF;
            v_eligibility := public.supportguard_maintenance_trim_eligibility(
                v_intent.job_id,v_intent.run_id,v_intent.tenant_id
            );
            IF NOT coalesce((v_eligibility->>'eligible')::boolean,false)
               OR (v_eligibility->>'eligibility_version')::bigint<>v_intent.eligibility_version
               OR v_eligibility->>'dependency_set_hash'<>v_intent.dependency_set_hash THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='trim_final_eligibility_changed';
            END IF;
            v_receipt_hash := encode(sha256(convert_to(concat_ws('|',
                'redis-trim-receipt.v1',v_intent.id,p_redis_message_id,p_payload_hash,
                p_group_set_hash,p_redis_receipt_hash),'utf8')),'hex');
            UPDATE public.retention_trim_intents SET status='redis_trimmed',
                redis_trimmed_at=coalesce(redis_trimmed_at,clock_timestamp()),
                updated_at=clock_timestamp() WHERE id=v_intent.id;
            PERFORM set_config('supportguard.retention_finalize_intent',v_intent.id,true);
            DELETE FROM public.inbox_deliveries
            WHERE tenant_id=v_intent.tenant_id AND job_id=v_intent.job_id
              AND redis_message_id=v_intent.redis_message_locator
              AND consumer_group='supportguard-workers-v1';
            GET DIAGNOSTICS v_deleted_inbox=ROW_COUNT;
            DELETE FROM public.outbox_events WHERE id=v_intent.outbox_locator;
            GET DIAGNOSTICS v_deleted_outbox=ROW_COUNT;
            IF v_deleted_inbox<>1 OR v_deleted_outbox<>1 THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='trim_lineage_delete_mismatch';
            END IF;
            v_finalized_at := clock_timestamp();
            INSERT INTO public.retention_trim_receipts(
                id,tenant_id,intent_id,redis_message_locator,payload_hash,group_set_hash,
                redis_receipt_hash,receipt_hash,finalized_at
            ) VALUES (
                'trimreceipt_'||substr(v_receipt_hash,1,48),v_intent.tenant_id,v_intent.id,
                p_redis_message_id,p_payload_hash,p_group_set_hash,p_redis_receipt_hash,
                v_receipt_hash,v_finalized_at
            );
            UPDATE public.retention_trim_intents SET status='finalized',
                finalized_at=v_finalized_at,terminal_receipt_hash=v_receipt_hash,
                updated_at=v_finalized_at WHERE id=v_intent.id;
            RETURN jsonb_build_object(
                'intent_id',v_intent.id,'status','finalized','reused',false,
                'ttl_confirmed',false,'receipt_hash',v_receipt_hash,
                'deleted_inbox',v_deleted_inbox,'deleted_outbox',v_deleted_outbox
            );
        END $_$;


ALTER FUNCTION public.supportguard_maintenance_finalize_trim(p_intent_id text, p_redis_message_id text, p_payload_hash text, p_group_set_hash text, p_redis_receipt_hash text) OWNER TO supportguard_owner;

--
-- Name: supportguard_maintenance_plan_pg_retention(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_maintenance_plan_pg_retention() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $_$
        DECLARE v_schema_hash text;
                v_items jsonb;
                v_plan_id text;
        BEGIN
            IF session_user<>'supportguard_maintenance' THEN
                RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='maintenance_role_required';
            END IF;
            SELECT encode(sha256(convert_to(string_agg(
                CASE WHEN schemaname='public' THEN tablename
                     ELSE schemaname||'.'||tablename END,',' ORDER BY
                CASE WHEN schemaname='public' THEN tablename
                     ELSE schemaname||'.'||tablename END COLLATE "C"),'utf8')),'hex')
              INTO v_schema_hash
            FROM pg_catalog.pg_tables
            WHERE schemaname IN ('public','supportguard_control')
              AND tablename<>'alembic_version';
            IF v_schema_hash<>'9bd2bef1437aea04054cefd5be86f3fd649a433ba2a22448fccbc1d0f87428ba' THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='retention_schema_coverage_mismatch';
            END IF;
            v_items := jsonb_build_object(
                'service_instance_heartbeats',coalesce((
                    SELECT jsonb_agg(h.id ORDER BY h.id)
                    FROM public.service_instance_heartbeats h
                    WHERE h.last_heartbeat_at<=clock_timestamp()-interval '24 hours'
                      AND NOT EXISTS (
                        SELECT 1 FROM public.runtime_jobs j
                        WHERE j.status IN ('queued','retry_wait','leased')
                          AND j.lease_owner=h.id
                      )
                      AND NOT EXISTS (
                        SELECT 1 FROM supportguard_control.upgrade_runs u
                        WHERE u.phase<>'attested' AND u.actor_instance_ref=h.id
                      )
                ),'[]'::jsonb),
                'api_request_traces',coalesce((
                    SELECT jsonb_agg(t.id ORDER BY t.id)
                    FROM public.api_request_traces t
                    WHERE t.created_at<=clock_timestamp()-interval '30 days'
                      AND NOT EXISTS (
                        SELECT 1 FROM public.incident_impacts i WHERE i.request_trace_id=t.id
                      )
                      AND NOT EXISTS (
                        SELECT 1 FROM public.audit_events a
                        WHERE a.payload::text LIKE '%'||t.id||'%'
                      )
                      AND NOT EXISTS (
                        SELECT 1 FROM public.tool_observations o
                        WHERE o.payload::text LIKE '%'||t.id||'%'
                      )
                      AND NOT EXISTS (
                        SELECT 1 FROM public.claim_records c
                        WHERE c.support_refs::text LIKE '%'||t.id||'%'
                      )
                      AND NOT EXISTS (
                        SELECT 1 FROM public.agent_runs r
                        WHERE r.status NOT IN ('completed','failed')
                          AND t.created_at BETWEEN r.created_at AND clock_timestamp()
                      )
                ),'[]'::jsonb),
                'checkpoint_namespaces',coalesce((
                    SELECT jsonb_agg(jsonb_build_object(
                        'thread_id',c.thread_id,'checkpoint_ns',c.checkpoint_ns
                    ) ORDER BY c.thread_id,c.checkpoint_ns)
                    FROM (
                        SELECT DISTINCT c.thread_id,c.checkpoint_ns
                        FROM public.checkpoints c
                        JOIN public.agent_runs r ON r.id=c.thread_id
                        WHERE r.status IN ('completed','failed')
                          AND NOT EXISTS (
                            SELECT 1 FROM public.runtime_jobs j
                            WHERE j.run_id=r.id AND (
                                j.status NOT IN ('succeeded','dead') OR j.terminal_at IS NULL
                                OR j.terminal_at>clock_timestamp()-interval '7 days'
                            )
                          )
                          AND (r.canonical_checkpoint_ns IS DISTINCT FROM c.checkpoint_ns)
                          AND NOT EXISTS (
                            SELECT 1 FROM public.approval_requests a
                            WHERE a.run_id=r.id AND a.canonical_checkpoint_ns=c.checkpoint_ns
                          )
                          AND NOT EXISTS (
                            SELECT 1 FROM public.checkpoint_commit_markers m
                            WHERE m.run_id=r.id AND m.private_namespace=c.checkpoint_ns
                          )
                    ) c
                ),'[]'::jsonb),
                'knowledge_ingest_runs',coalesce((
                    SELECT jsonb_agg(k.id ORDER BY k.id)
                    FROM public.knowledge_ingest_runs k
                    WHERE NOT k.is_active AND k.deactivated_at IS NOT NULL
                      AND k.deactivated_at<=clock_timestamp()-interval '30 days'
                      AND NOT EXISTS (
                        SELECT 1 FROM public.retrieval_traces r
                        WHERE r.index_version=k.index_version
                      )
                      AND NOT EXISTS (
                        SELECT 1 FROM public.citation_bindings b
                        JOIN public.knowledge_chunks c ON c.locator_hash=b.locator_hash
                        WHERE c.ingest_run_id=k.id AND c.index_version=k.index_version
                      )
                ),'[]'::jsonb),
                'idempotency_requests',coalesce((
                    SELECT jsonb_agg(i.id ORDER BY i.id)
                    FROM public.idempotency_requests i
                    WHERE i.retention_class='low_risk_non_action'
                      AND i.completed_at IS NOT NULL
                      AND i.completed_at<=clock_timestamp()-interval '24 hours'
                      AND (
                        i.route='POST /api/tickets'
                        OR i.route ~ '^POST /api/tickets/[^/]+/messages$'
                      )
                      AND coalesce(i.resource_ids->>'run_id','')<>''
                      AND EXISTS (
                        SELECT 1 FROM public.agent_runs r
                        WHERE r.id=i.resource_ids->>'run_id'
                          AND r.status IN ('completed','failed')
                      )
                      AND EXISTS (
                        SELECT 1 FROM public.runtime_jobs j
                        WHERE j.id=i.resource_ids->>'job_id'
                          AND j.run_id=i.resource_ids->>'run_id'
                          AND j.status IN ('succeeded','dead') AND j.terminal_at IS NOT NULL
                      )
                      AND NOT EXISTS (
                        SELECT 1 FROM public.approval_requests a
                        WHERE a.run_id=i.resource_ids->>'run_id'
                      )
                      AND NOT EXISTS (
                        SELECT 1 FROM public.business_actions a
                        WHERE a.ticket_id=i.resource_ids->>'ticket_id'
                      )
                      AND NOT EXISTS (
                        SELECT 1 FROM public.outbox_events o
                        WHERE o.job_id=i.resource_ids->>'job_id'
                      )
                      AND NOT EXISTS (
                        SELECT 1 FROM public.inbox_deliveries d
                        WHERE d.job_id=i.resource_ids->>'job_id'
                      )
                ),'[]'::jsonb)
            );
            v_plan_id := encode(sha256(convert_to(v_items::text,'utf8')),'hex');
            RETURN jsonb_build_object(
                'schema_version','pg-retention-plan.v1','plan_id',v_plan_id,
                'schema_manifest_hash',v_schema_hash,'items',v_items,
                'eligible',jsonb_build_object(
                    'service_instance_heartbeats',jsonb_array_length(v_items->'service_instance_heartbeats'),
                    'api_request_traces',jsonb_array_length(v_items->'api_request_traces'),
                    'checkpoint_namespaces',jsonb_array_length(v_items->'checkpoint_namespaces'),
                    'knowledge_ingest_runs',jsonb_array_length(v_items->'knowledge_ingest_runs'),
                    'idempotency_requests',jsonb_array_length(v_items->'idempotency_requests')
                )
            );
        END $_$;


ALTER FUNCTION public.supportguard_maintenance_plan_pg_retention() OWNER TO supportguard_owner;

--
-- Name: supportguard_maintenance_retention_report(text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_maintenance_retention_report(p_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_intent public.retention_trim_intents%ROWTYPE;
                v_receipt public.retention_trim_receipts%ROWTYPE;
        BEGIN
            IF session_user<>'supportguard_maintenance' THEN
                RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='maintenance_role_required';
            END IF;
            IF p_id='active' THEN
                RETURN jsonb_build_object('found',true,'active',coalesce((
                    SELECT jsonb_agg(jsonb_build_object(
                        'intent_id',i.id,'status',i.status,'stream',i.stream,
                        'redis_message_id',i.redis_message_locator,
                        'payload_hash',i.payload_hash,'group_set_hash',i.group_set_hash
                    ) ORDER BY i.id) FROM public.retention_trim_intents i
                    WHERE i.status IN ('authorized','redis_trimmed','unknown_trim_state')
                ),'[]'::jsonb));
            END IF;
            IF p_id='pending_ttl' THEN
                RETURN jsonb_build_object('found',true,'pending_ttl',coalesce((
                    SELECT jsonb_agg(jsonb_build_object(
                        'intent_id',i.id,'status',i.status,'stream',i.stream,
                        'redis_message_id',i.redis_message_locator,
                        'payload_hash',i.payload_hash,'group_set_hash',i.group_set_hash,
                        'receipt_hash',r.receipt_hash,
                        'redis_receipt_hash',r.redis_receipt_hash
                    ) ORDER BY i.id) FROM public.retention_trim_intents i
                    JOIN public.retention_trim_receipts r ON r.intent_id=i.id
                    WHERE i.status='finalized' AND i.updated_at<=i.finalized_at
                ),'[]'::jsonb));
            END IF;
            SELECT * INTO v_intent FROM public.retention_trim_intents WHERE id=p_id;
            IF v_intent.id IS NULL THEN
                RETURN jsonb_build_object('found',false,'id',p_id);
            END IF;
            SELECT * INTO v_receipt FROM public.retention_trim_receipts
            WHERE intent_id=v_intent.id;
            RETURN jsonb_build_object(
                'found',true,'intent_id',v_intent.id,'status',v_intent.status,
                'stream',v_intent.stream,
                'redis_message_id',v_intent.redis_message_locator,
                'payload_hash',v_intent.payload_hash,'group_set_hash',v_intent.group_set_hash,
                'eligibility_version',v_intent.eligibility_version,
                'dependency_set_hash',v_intent.dependency_set_hash,
                'receipt_hash',v_receipt.receipt_hash
            );
        END $$;


ALTER FUNCTION public.supportguard_maintenance_retention_report(p_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_maintenance_trim_eligibility(text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_maintenance_trim_eligibility(p_job_id text, p_run_id text, p_tenant_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_job public.runtime_jobs%ROWTYPE;
                v_outbox public.outbox_events%ROWTYPE;
                v_anchor timestamptz;
                v_inbox_count bigint;
                v_dependency_hash text;
        BEGIN
            IF session_user<>'supportguard_maintenance' THEN
                RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='maintenance_role_required';
            END IF;
            SELECT * INTO v_job FROM public.runtime_jobs
            WHERE id=p_job_id AND run_id=p_run_id AND tenant_id=p_tenant_id;
            IF v_job.id IS NULL THEN
                RETURN jsonb_build_object('eligible',false,'reason','postgres_job_missing');
            END IF;
            IF v_job.status NOT IN ('succeeded','dead') OR v_job.terminal_at IS NULL THEN
                RETURN jsonb_build_object('eligible',false,'reason','postgres_job_not_terminal');
            END IF;
            IF v_job.approval_id IS NOT NULL THEN
                RETURN jsonb_build_object('eligible',false,'reason','approval_resume_protected');
            END IF;
            SELECT * INTO v_outbox FROM public.outbox_events
            WHERE tenant_id=p_tenant_id AND run_id=p_run_id AND job_id=p_job_id
              AND superseded_at IS NULL;
            IF v_outbox.id IS NULL OR v_outbox.published_at IS NULL
               OR v_outbox.redis_message_id IS NULL THEN
                RETURN jsonb_build_object('eligible',false,'reason','outbox_not_published');
            END IF;
            SELECT count(*),greatest(v_job.terminal_at,v_outbox.published_at,max(i.terminal_at))
              INTO v_inbox_count,v_anchor
            FROM public.inbox_deliveries i
            WHERE i.tenant_id=p_tenant_id AND i.job_id=p_job_id
              AND i.delivery_id=v_outbox.delivery_id
              AND i.redis_message_id=v_outbox.redis_message_id
              AND i.consumer_group='supportguard-workers-v1'
              AND i.status IN ('acked','rejected') AND i.terminal_at IS NOT NULL;
            IF v_inbox_count<>1 OR EXISTS (
                SELECT 1 FROM public.inbox_deliveries i
                WHERE i.tenant_id=p_tenant_id AND i.job_id=p_job_id
                  AND i.delivery_id=v_outbox.delivery_id
                  AND i.consumer_group<>'supportguard-workers-v1'
            ) THEN
                RETURN jsonb_build_object('eligible',false,'reason','consumer_group_incomplete');
            END IF;
            IF v_anchor IS NULL OR v_anchor>clock_timestamp()-interval '7 days' THEN
                RETURN jsonb_build_object('eligible',false,'reason','retention_not_elapsed');
            END IF;
            IF EXISTS (
                SELECT 1 FROM public.reconcile_intents r
                WHERE r.tenant_id=p_tenant_id AND r.run_id=p_run_id
                  AND r.job_id=p_job_id AND r.outbox_id=v_outbox.id
            ) THEN
                RETURN jsonb_build_object('eligible',false,'reason','reconcile_lineage_protected');
            END IF;
            v_dependency_hash := encode(sha256(convert_to(
                concat_ws('|',p_tenant_id,p_run_id,p_job_id,v_outbox.id,
                    v_outbox.delivery_id,v_outbox.redis_message_id,
                    v_outbox.delivery_state_version::text,v_job.status,
                    v_job.terminal_at::text,v_outbox.published_at::text,v_anchor::text,
                    'supportguard-workers-v1'), 'utf8')), 'hex');
            RETURN jsonb_build_object(
                'eligible',true,'reason','eligible','job_id',v_job.id,
                'outbox_id',v_outbox.id,'delivery_id',v_outbox.delivery_id,
                'redis_message_id',v_outbox.redis_message_id,
                'eligibility_version',v_outbox.delivery_state_version,
                'dependency_set_hash',v_dependency_hash,'anchor_at',v_anchor,
                'group_set_hash','3a0fde6ba7d90c905877897d4ddad78298e4e7b587248f8520de9393cb60148d'
            );
        END $$;


ALTER FUNCTION public.supportguard_maintenance_trim_eligibility(p_job_id text, p_run_id text, p_tenant_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_mcp_consume_capability_reservation(text, text, text, text, bigint, integer, text, text, integer, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_mcp_consume_capability_reservation(p_tenant_id text, p_run_id text, p_job_id text, p_segment_id text, p_fencing_token bigint, p_delivery_generation integer, p_invocation_id text, p_attempt_id text, p_sequence integer, p_capability_name text, p_effect_identity text, p_decision_hash text, p_binding_hash text, p_call_deadline timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
            v_attempt_id text;
            v_invocation_id text;
        BEGIN
            IF session_user <> 'supportguard_action_mcp' THEN
                RAISE EXCEPTION 'capability reservation caller is not authorized';
            END IF;
            IF p_call_deadline < statement_timestamp()
               OR NOT supportguard_mcp_verify_fence(
                    p_tenant_id, p_run_id, p_job_id, p_segment_id,
                    p_fencing_token, p_delivery_generation
               ) THEN
                RETURN false;
            END IF;
            UPDATE public.policy_capability_attempts AS attempt
            SET status = 'executing'
            FROM public.policy_capability_invocations AS invocation
            WHERE attempt.id = p_attempt_id
              AND attempt.tenant_id = p_tenant_id
              AND attempt.run_id = p_run_id
              AND attempt.job_id = p_job_id
              AND attempt.fencing_token = p_fencing_token
              AND attempt.status = 'reserved'
              AND invocation.id = p_invocation_id
              AND invocation.id = attempt.invocation_id
              AND invocation.tenant_id = attempt.tenant_id
              AND invocation.run_id = attempt.run_id
              AND invocation.job_id = attempt.job_id
              AND invocation.segment_id = p_segment_id
              AND invocation.fencing_token = attempt.fencing_token
              AND invocation.sequence = p_sequence
              AND invocation.capability_name = p_capability_name
              AND invocation.effect_identity = p_effect_identity
              AND invocation.causal_decision_hash = p_decision_hash
              AND invocation.observation_binding_hash = p_binding_hash
              AND invocation.status = 'reserved'
            RETURNING attempt.id INTO v_attempt_id;
            IF v_attempt_id IS NULL THEN
                RETURN false;
            END IF;
            UPDATE public.policy_capability_invocations
            SET status = 'executing'
            WHERE id = p_invocation_id
              AND tenant_id = p_tenant_id
              AND status = 'reserved'
            RETURNING id INTO v_invocation_id;
            RETURN v_invocation_id IS NOT NULL;
        END;
        $$;


ALTER FUNCTION public.supportguard_mcp_consume_capability_reservation(p_tenant_id text, p_run_id text, p_job_id text, p_segment_id text, p_fencing_token bigint, p_delivery_generation integer, p_invocation_id text, p_attempt_id text, p_sequence integer, p_capability_name text, p_effect_identity text, p_decision_hash text, p_binding_hash text, p_call_deadline timestamp with time zone) OWNER TO supportguard_owner;

--
-- Name: supportguard_mcp_consume_read_reservation(text, text, text, text, bigint, integer, text, text, text, integer, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_mcp_consume_read_reservation(p_tenant_id text, p_run_id text, p_job_id text, p_segment_id text, p_fencing_token bigint, p_delivery_generation integer, p_logical_invocation_id text, p_tool_attempt_id text, p_transport_attempt_id text, p_transport_ordinal integer, p_tool_name text, p_provider_tool_call_id text, p_call_deadline timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
            v_transport_id text;
        BEGIN
            IF session_user <> 'supportguard_read_mcp' THEN
                RAISE EXCEPTION 'read reservation caller is not authorized';
            END IF;
            IF p_call_deadline < statement_timestamp()
               OR NOT supportguard_mcp_verify_fence(
                    p_tenant_id, p_run_id, p_job_id, p_segment_id,
                    p_fencing_token, p_delivery_generation
               ) THEN
                RETURN false;
            END IF;
            UPDATE public.tool_transport_attempts AS transport
            SET status = 'executing'
            FROM public.agent_call_attempts AS attempt,
                 public.tool_invocations AS invocation
            WHERE transport.id = p_transport_attempt_id
              AND transport.tenant_id = p_tenant_id
              AND transport.run_id = p_run_id
              AND transport.job_id = p_job_id
              AND transport.fencing_token = p_fencing_token
              AND transport.transport_ordinal = p_transport_ordinal
              AND transport.status = 'reserved'
              AND attempt.id = p_tool_attempt_id
              AND attempt.tenant_id = transport.tenant_id
              AND attempt.run_id = transport.run_id
              AND attempt.job_id = transport.job_id
              AND attempt.fencing_token = transport.fencing_token
              AND attempt.call_kind = 'read_mcp'
              AND attempt.status = 'started'
              AND attempt.transport_ordinal = transport.transport_ordinal
              AND transport.agent_call_attempt_id = attempt.id
              AND invocation.id = transport.invocation_id
              AND invocation.id = attempt.logical_invocation_id
              AND invocation.tenant_id = transport.tenant_id
              AND invocation.run_id = transport.run_id
              AND invocation.job_id = transport.job_id
              AND invocation.segment_id = p_segment_id
              AND invocation.fencing_token = transport.fencing_token
              AND invocation.logical_invocation_id = p_logical_invocation_id
              AND invocation.provider_tool_call_id = p_provider_tool_call_id
              AND invocation.tool_name = p_tool_name
              AND invocation.lifecycle = 'executing'
            RETURNING transport.id INTO v_transport_id;
            RETURN v_transport_id IS NOT NULL;
        END;
        $$;


ALTER FUNCTION public.supportguard_mcp_consume_read_reservation(p_tenant_id text, p_run_id text, p_job_id text, p_segment_id text, p_fencing_token bigint, p_delivery_generation integer, p_logical_invocation_id text, p_tool_attempt_id text, p_transport_attempt_id text, p_transport_ordinal integer, p_tool_name text, p_provider_tool_call_id text, p_call_deadline timestamp with time zone) OWNER TO supportguard_owner;

--
-- Name: supportguard_mcp_record_capability_result(text, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_mcp_record_capability_result(p_tenant_id text, p_run_id text, p_job_id text, p_invocation_id text, p_attempt_id text, p_effect_identity text, p_payload_hash text, p_payload jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
            v_valid boolean;
            v_result_id text;
        BEGIN
            IF session_user <> 'supportguard_action_mcp' THEN
                RAISE EXCEPTION 'capability result caller is not authorized';
            END IF;
            SELECT true INTO v_valid
            FROM public.policy_capability_invocations AS invocation
            JOIN public.policy_capability_attempts AS attempt
              ON attempt.invocation_id = invocation.id
             AND attempt.tenant_id = invocation.tenant_id
            WHERE invocation.id = p_invocation_id
              AND invocation.tenant_id = p_tenant_id
              AND invocation.run_id = p_run_id
              AND invocation.job_id = p_job_id
              AND invocation.effect_identity = p_effect_identity
              AND invocation.status = 'executing'
              AND attempt.id = p_attempt_id
              AND attempt.status = 'executing';
            IF v_valid IS NOT TRUE THEN
                RETURN false;
            END IF;
            v_result_id := 'capresult_' || md5(p_effect_identity);
            INSERT INTO public.policy_capability_results (
                id, tenant_id, run_id, job_id, invocation_id, effect_identity,
                status, payload_hash, payload, created_at, updated_at
            ) VALUES (
                v_result_id, p_tenant_id, p_run_id, p_job_id, p_invocation_id,
                p_effect_identity, 'succeeded', p_payload_hash, p_payload,
                statement_timestamp(), statement_timestamp()
            )
            ON CONFLICT (invocation_id) DO NOTHING;
            RETURN EXISTS (
                SELECT 1 FROM public.policy_capability_results
                WHERE invocation_id = p_invocation_id
                  AND tenant_id = p_tenant_id
                  AND effect_identity = p_effect_identity
                  AND status = 'succeeded'
                  AND payload_hash = p_payload_hash
            );
        END;
        $$;


ALTER FUNCTION public.supportguard_mcp_record_capability_result(p_tenant_id text, p_run_id text, p_job_id text, p_invocation_id text, p_attempt_id text, p_effect_identity text, p_payload_hash text, p_payload jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_mcp_verify_fence(text, text, text, text, bigint, integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_mcp_verify_fence(p_tenant_id text, p_run_id text, p_job_id text, p_segment_id text, p_fencing_token bigint, p_delivery_generation integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
            v_allowed boolean;
        BEGIN
            IF session_user NOT IN ('supportguard_read_mcp', 'supportguard_action_mcp') THEN
                RAISE EXCEPTION 'mcp fence caller is not authorized';
            END IF;
            IF p_tenant_id IS NULL OR p_run_id IS NULL OR p_job_id IS NULL
               OR p_segment_id IS NULL OR p_fencing_token < 1
               OR p_delivery_generation < 1 THEN
                RETURN false;
            END IF;
            SELECT EXISTS (
                SELECT 1
                FROM public.runtime_jobs AS job
                JOIN public.agent_runs AS run
                  ON run.id = job.run_id AND run.tenant_id = job.tenant_id
                JOIN public.outbox_events AS delivery
                  ON delivery.job_id = job.id
                 AND delivery.run_id = job.run_id
                 AND delivery.tenant_id = job.tenant_id
                 AND delivery.delivery_generation = p_delivery_generation
                JOIN public.checkpoint_commit_markers AS marker
                  ON marker.id = p_segment_id
                 AND marker.run_id = job.run_id
                 AND marker.job_id = job.id
                 AND marker.tenant_id = job.tenant_id
                 AND marker.fencing_token = job.fencing_token
                WHERE job.id = p_job_id
                  AND job.run_id = p_run_id
                  AND job.tenant_id = p_tenant_id
                  AND job.status = 'leased'
                  AND job.fencing_token = p_fencing_token
                  AND job.lease_owner IS NOT NULL
                  AND job.lease_expires_at > statement_timestamp()
                  AND run.active_job_id = job.id
                  AND run.active_fencing_token = job.fencing_token
                  AND run.status = 'running'
            ) INTO v_allowed;
            RETURN v_allowed;
        END;
        $$;


ALTER FUNCTION public.supportguard_mcp_verify_fence(p_tenant_id text, p_run_id text, p_job_id text, p_segment_id text, p_fencing_token bigint, p_delivery_generation integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_migrator_upgrade_transition(jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_migrator_upgrade_transition(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_run supportguard_control.upgrade_runs%ROWTYPE; v_database uuid;
                v_action text:=p_payload->>'action'; v_next text; v_expected text;
        BEGIN
          IF session_user<>'supportguard_migrator' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='migrator capability caller is not authorized';
          END IF;
          PERFORM pg_advisory_xact_lock(hashtextextended('supportguard.writer-barrier.v1',0));
          SELECT database_uuid INTO v_database FROM supportguard_control.database_identity
            WHERE database_name=current_database();
          SELECT * INTO v_run FROM supportguard_control.upgrade_runs
            WHERE database_uuid=v_database AND phase<>'attested' FOR UPDATE;
          IF v_action='begin' THEN
            IF v_run.id IS NOT NULL THEN
              IF v_run.source_revision<>(p_payload->>'source_revision')
                 OR v_run.target_revision<>(p_payload->>'target_revision') THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='upgrade_in_progress';
              END IF;
              RETURN jsonb_build_object('result','resumed','run_id',v_run.id,
                'phase',v_run.phase,'status_version',v_run.status_version);
            END IF;
            INSERT INTO supportguard_control.upgrade_runs(
              id,database_uuid,source_revision,target_revision,phase,actor_instance_ref,
              status_version,started_at
            ) VALUES (
              p_payload->>'run_id',v_database,p_payload->>'source_revision',
              p_payload->>'target_revision','quiescing',p_payload->>'actor_instance_id',1,
              clock_timestamp()
            ) RETURNING * INTO v_run;
            RETURN jsonb_build_object('result','started','run_id',v_run.id,
              'phase',v_run.phase,'status_version',v_run.status_version);
          END IF;
          IF v_run.id IS NULL OR v_run.id<>(p_payload->>'run_id') THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='upgrade_run_not_active';
          END IF;
          v_expected:=p_payload->>'expected_phase'; v_next:=p_payload->>'next_phase';
          IF v_run.phase<>v_expected THEN
            RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='upgrade_phase_conflict';
          END IF;
          IF (v_expected,v_next) NOT IN (
            ('quiescing','quiesced'),('quiesced','preflight_written'),
            ('preflight_written','schema_upgraded'),('schema_upgraded','knowledge_rebuilt'),
            ('knowledge_rebuilt','summaries_restored'),('summaries_restored','verified')
          ) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='upgrade_transition_invalid'; END IF;
          UPDATE supportguard_control.upgrade_runs SET phase=v_next,
            preflight_manifest_hash=coalesce(p_payload->>'preflight_manifest_hash',preflight_manifest_hash),
            external_backup_hash=coalesce(p_payload->>'external_backup_hash',external_backup_hash),
            status_version=status_version+1 WHERE id=v_run.id RETURNING * INTO v_run;
          INSERT INTO supportguard_control.upgrade_phase_events(
            id,upgrade_run_id,phase,sequence,payload_hash,created_at
          ) VALUES ('upgrade_event_'||replace(gen_random_uuid()::text,'-',''),v_run.id,v_next,
            v_run.status_version,encode(sha256(convert_to(p_payload::text,'UTF8')),'hex'),
            clock_timestamp());
          RETURN jsonb_build_object('result','advanced','run_id',v_run.id,
            'phase',v_run.phase,'status_version',v_run.status_version);
        END $$;


ALTER FUNCTION public.supportguard_migrator_upgrade_transition(p_payload jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_migrator_write_attestation(jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_migrator_write_attestation(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_run supportguard_control.upgrade_runs%ROWTYPE; v_hash text;
        BEGIN
          IF session_user<>'supportguard_migrator' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='migrator capability caller is not authorized';
          END IF;
          SELECT * INTO v_run FROM supportguard_control.upgrade_runs
            WHERE id=p_payload->>'run_id' FOR UPDATE;
          IF v_run.phase<>'verified' OR v_run.preflight_manifest_hash IS NULL
             OR v_run.external_backup_hash IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='upgrade_not_verified';
          END IF;
          v_hash:=encode(sha256(convert_to(p_payload::text,'UTF8')),'hex');
          INSERT INTO supportguard_control.upgrade_attestations(
            id,upgrade_run_id,schema_hash,row_inventory_hash,knowledge_locator_hash,
            summary_lineage_hash,attestation_hash,created_at
          ) VALUES ('attestation_'||replace(gen_random_uuid()::text,'-',''),v_run.id,
            p_payload->>'schema_hash',p_payload->>'row_inventory_hash',
            p_payload->>'knowledge_locator_hash',p_payload->>'summary_lineage_hash',v_hash,
            clock_timestamp());
          UPDATE supportguard_control.upgrade_runs SET phase='attested',
            status_version=status_version+1,completed_at=clock_timestamp() WHERE id=v_run.id;
          RETURN jsonb_build_object('result','attested','run_id',v_run.id,
            'attestation_hash',v_hash);
        END $$;


ALTER FUNCTION public.supportguard_migrator_write_attestation(p_payload jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_read_mcp_check_service_status(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_read_mcp_check_service_status(p_model_arguments jsonb, p_trusted_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_allowed boolean;
        BEGIN
          IF session_user <> 'supportguard_read_mcp' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF jsonb_typeof(p_model_arguments)<>'object'
             OR jsonb_typeof(p_trusted_context)<>'object'
             OR p_trusted_context->>'schema_version'<>'read-mcp-wrapper.v1'
             OR p_trusted_context->>'tool_name'<>'check_service_status'
             OR p_trusted_context->>'phase' NOT IN ('reserve','recheck','execute')
             OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_trusted_context) key)
                <> ARRAY['call_deadline','delivery_generation','fencing_token','job_id',
                         'logical_invocation_id','phase','provider_tool_call_id','run_id',
                         'schema_version','segment_id','tenant_id','tool_attempt_id',
                         'tool_name','trace_origin','transport_attempt_id','transport_ordinal']
          THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid read MCP wrapper envelope';
          END IF;
          IF p_trusted_context->>'phase'='reserve'
             AND p_trusted_context->>'trace_origin'='agent_read_tool' THEN
            v_allowed:=supportguard_mcp_consume_read_reservation(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer,
              p_trusted_context->>'logical_invocation_id',
              p_trusted_context->>'tool_attempt_id',
              p_trusted_context->>'transport_attempt_id',
              (p_trusted_context->>'transport_ordinal')::integer,
              'check_service_status',p_trusted_context->>'provider_tool_call_id',
              (p_trusted_context->>'call_deadline')::timestamptz);
          ELSE
            v_allowed:=supportguard_mcp_verify_fence(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer);
          END IF;

          IF p_trusted_context->>'phase'='execute' THEN
            IF v_allowed IS DISTINCT FROM true THEN
              RETURN pg_catalog.jsonb_build_object(
                'schema_version','mcp-wrapper-result.v1','authorized',false,
                'tool_name','check_service_status','phase','execute');
            END IF;
            RETURN public.supportguard_read_mcp_execute(
              'check_service_status',p_model_arguments,p_trusted_context);
          END IF;
          RETURN jsonb_build_object('schema_version','mcp-wrapper-result.v1',
                                    'authorized',v_allowed,'tool_name','check_service_status',
                                    'phase',p_trusted_context->>'phase');
        END $$;


ALTER FUNCTION public.supportguard_read_mcp_check_service_status(p_model_arguments jsonb, p_trusted_context jsonb) OWNER TO supportguard_owner;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: knowledge_chunks; Type: TABLE; Schema: public; Owner: supportguard_owner
--

CREATE TABLE public.knowledge_chunks (
    id character varying(64) NOT NULL,
    document_id character varying(64) NOT NULL,
    chunk_key character varying(128) NOT NULL,
    section_path character varying(500) NOT NULL,
    sequence integer NOT NULL,
    content text NOT NULL,
    token_count integer NOT NULL,
    content_hash character varying(64) NOT NULL,
    index_version character varying(64) NOT NULL,
    embedding public.vector(384),
    search_vector tsvector,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    byte_start bigint NOT NULL,
    byte_end bigint NOT NULL,
    span_hash character varying(64) NOT NULL,
    locator_hash character varying(64) NOT NULL,
    ingest_run_id character varying(64) NOT NULL,
    locator_schema_version character varying(64) DEFAULT 'source-locator.v1'::character varying NOT NULL,
    canonicalization_version character varying(64) DEFAULT 'legacy-unknown.v1'::character varying NOT NULL,
    chunker_fingerprint character varying(64) NOT NULL,
    embedding_fingerprint character varying(64) NOT NULL
);


ALTER TABLE public.knowledge_chunks OWNER TO supportguard_owner;

--
-- Name: knowledge_documents; Type: TABLE; Schema: public; Owner: supportguard_owner
--

CREATE TABLE public.knowledge_documents (
    id character varying(64) NOT NULL,
    document_key character varying(128) NOT NULL,
    title character varying(300) NOT NULL,
    document_type character varying(64) NOT NULL,
    version character varying(64) NOT NULL,
    status character varying(32) NOT NULL,
    effective_at timestamp with time zone NOT NULL,
    authority_level integer NOT NULL,
    applicable_plan character varying(64),
    applicable_region character varying(64),
    content_hash character varying(64) NOT NULL,
    source_path character varying(500) NOT NULL,
    index_version character varying(64) NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    canonical_blob bytea NOT NULL,
    ingest_run_id character varying(64) NOT NULL,
    canonicalization_version character varying(64) DEFAULT 'legacy-unknown.v1'::character varying NOT NULL,
    document_family_key character varying(128) NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_until timestamp with time zone,
    applicability_scope_hash character varying(64) NOT NULL,
    temporal_manifest_hash character varying(64) NOT NULL,
    CONSTRAINT ck_knowledge_documents_knowledge_document_effective_alias_exact CHECK ((effective_at = effective_from)),
    CONSTRAINT ck_knowledge_documents_knowledge_document_effective_int_bbbf CHECK (((effective_until IS NULL) OR (effective_until > effective_from)))
);


ALTER TABLE public.knowledge_documents OWNER TO supportguard_owner;

--
-- Name: supportguard_read_mcp_chunk_payload(public.knowledge_chunks, public.knowledge_documents, double precision, double precision, boolean, integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_read_mcp_chunk_payload(c public.knowledge_chunks, d public.knowledge_documents, p_vector_distance double precision DEFAULT NULL::double precision, p_keyword_score double precision DEFAULT NULL::double precision, p_exact_token_match boolean DEFAULT false, p_channel_rank integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
          SELECT jsonb_build_object(
            'chunk_id',c.chunk_key,'document_id',d.document_key,'document_type',d.document_type,
            'title',d.title,'section_path',c.section_path,'sequence',c.sequence,
            'content',c.content,'token_count',c.token_count,
            'content_hash',c.content_hash,'version',d.version,'status',d.status,
            'effective_at',d.effective_from,'effective_until',d.effective_until,
            'document_family_key',d.document_family_key,
            'applicability_scope_hash',d.applicability_scope_hash,
            'authority_level',d.authority_level,
            'applicable_plan',d.applicable_plan,
            'applicable_region',d.applicable_region,
            'source_locator',jsonb_build_object(
              'locator_schema','source-locator.v2',
              'document_key',d.document_key,
              'document_internal_id',d.id,
              'document_version',d.version,
              'source_hash',d.content_hash,
              'corpus_snapshot_id',c.ingest_run_id,
              'index_version',c.index_version,
              'canonicalization_version',c.canonicalization_version,
              'section_path',c.section_path,
              'byte_start',c.byte_start,
              'byte_end',c.byte_end,
              'span_hash',c.span_hash,
              'chunker_fingerprint',c.chunker_fingerprint,
              'embedding_fingerprint',c.embedding_fingerprint,
              'locator_hash',c.locator_hash),
            'vector_similarity',CASE WHEN p_vector_distance IS NULL THEN NULL
              ELSE 1.0-p_vector_distance END,
            'vector_distance',p_vector_distance,
            'keyword_score',p_keyword_score,
            'exact_token_match',p_exact_token_match,
            'channel_rank',p_channel_rank,
            'filter_reason','eligible',
            'evidence_group',NULL)
        $$;


ALTER FUNCTION public.supportguard_read_mcp_chunk_payload(c public.knowledge_chunks, d public.knowledge_documents, p_vector_distance double precision, p_keyword_score double precision, p_exact_token_match boolean, p_channel_rank integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_read_mcp_execute(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_read_mcp_execute(p_tool_name text, p_model_arguments jsonb, p_trusted_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE
          v_ticket_id text; v_customer_id text; v_tool_call_id text;
          v_row record; v_other record; v_observed_at timestamptz:=clock_timestamp();
          v_logical_time timestamptz; v_window text; v_window_minutes integer;
          v_window_start timestamptz; v_window_end timestamptz;
          v_bucket_count integer; v_request_count bigint; v_input_tokens bigint;
          v_output_tokens bigint; v_concurrency_current integer; v_concurrency_peak integer;
          v_coverage_through timestamptz; v_freshness_seconds integer;
          v_freshness_status text; v_resource_version text;
          v_bucket_sources jsonb; v_first_bucket_id text; v_last_bucket_id text;
          v_first_bucket_end timestamptz; v_last_bucket_end timestamptz;
          v_bucket_complete boolean;
        BEGIN
          IF current_user<>'supportguard_owner'
             OR p_tool_name NOT IN (
               'query_account','query_subscription','query_api_usage',
               'check_service_status','query_billing_record','query_request_trace',
               'query_api_key_metadata','query_incident_impact')
             OR jsonb_typeof(p_model_arguments)<>'object'
             OR jsonb_typeof(p_trusted_context)<>'object' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='read_mcp_execute_forbidden';
          END IF;
          SELECT r.ticket_id,t.customer_id
            INTO v_ticket_id,v_customer_id
          FROM public.agent_runs r
          JOIN public.support_tickets t
            ON t.tenant_id=r.tenant_id AND t.id=r.ticket_id
          JOIN public.runtime_jobs j
            ON j.tenant_id=r.tenant_id AND j.id=p_trusted_context->>'job_id'
           AND j.run_id=r.id
           AND j.fencing_token=(p_trusted_context->>'fencing_token')::bigint
          JOIN public.tool_invocations i
            ON i.tenant_id=r.tenant_id AND i.run_id=r.id AND i.job_id=j.id
           AND i.logical_invocation_id=p_trusted_context->>'logical_invocation_id'
           AND i.provider_tool_call_id=p_trusted_context->>'provider_tool_call_id'
           AND i.tool_name=p_tool_name
           AND i.arguments_hash=encode(pg_catalog.sha256(convert_to(
             supportguard_canonical_jsonb(p_model_arguments),'UTF8')),'hex')
          WHERE r.tenant_id=p_trusted_context->>'tenant_id'
            AND r.id=p_trusted_context->>'run_id'
            AND r.active_job_id=j.id
            AND r.active_fencing_token=j.fencing_token;
          IF v_ticket_id IS NULL OR v_customer_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='read_mcp_scope_unavailable';
          END IF;
          v_tool_call_id:=p_trusted_context->>'provider_tool_call_id';

          IF p_tool_name='query_account' THEN
            IF p_model_arguments<>'{}'::jsonb THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='query_account_arguments_invalid';
            END IF;
            SELECT * INTO v_row FROM public.customers
             WHERE tenant_id=p_trusted_context->>'tenant_id' AND id=v_customer_id;
            IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='customer_not_found';
            END IF;
            RETURN jsonb_build_object(
              'schema_version','mcp-wrapper-result.v1','authorized',true,
              'tool_name',p_tool_name,'phase','execute','result',jsonb_build_object(
                'tool_call_id',v_tool_call_id,'ticket_id',v_ticket_id,
                'account_status',v_row.status,'security_status',v_row.security_status,
                'region',v_row.region,'observed_at',v_row.updated_at,
                'resource_version',v_row.version::text,'source_refs',jsonb_build_array(
                  jsonb_build_object('source_type','business_record','source_id',
                    'customer:'||v_row.id,'observed_at',v_row.updated_at))));
          ELSIF p_tool_name='query_subscription' THEN
            IF p_model_arguments<>'{}'::jsonb THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='query_subscription_arguments_invalid';
            END IF;
            SELECT * INTO v_row FROM public.subscriptions
             WHERE tenant_id=p_trusted_context->>'tenant_id' AND customer_id=v_customer_id;
            IF NOT FOUND THEN
              RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='subscription_not_found';
            END IF;
            RETURN jsonb_build_object(
              'schema_version','mcp-wrapper-result.v1','authorized',true,
              'tool_name',p_tool_name,'phase','execute','result',jsonb_build_object(
                'tool_call_id',v_tool_call_id,'ticket_id',v_ticket_id,
                'subscription_id',v_row.id,'plan',v_row.plan,'status',v_row.status,
                'rpm_limit',v_row.rpm_limit,'concurrency_limit',v_row.concurrency_limit,
                'catalog_eligibility',jsonb_build_array('quota_change','plan_change'),
                'version',v_row.version,'source_refs',jsonb_build_array(
                  jsonb_build_object('source_type','business_record','source_id',
                    'subscription:'||v_row.id,'observed_at',v_observed_at))));
          ELSIF p_tool_name='query_billing_record' THEN
            IF (SELECT count(*) FROM jsonb_object_keys(p_model_arguments))<>1
               OR NOT p_model_arguments ? 'billing_record_id' THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='billing_arguments_invalid';
            END IF;
            SELECT * INTO v_row FROM public.billing_records
             WHERE tenant_id=p_trusted_context->>'tenant_id' AND customer_id=v_customer_id
               AND id=p_model_arguments->>'billing_record_id';
            IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='billing_not_found';
            END IF;
            RETURN jsonb_build_object(
              'schema_version','mcp-wrapper-result.v1','authorized',true,
              'tool_name',p_tool_name,'phase','execute','result',jsonb_build_object(
                'tool_call_id',v_tool_call_id,'ticket_id',v_ticket_id,
                'billing_record_id',v_row.id,'amount',v_row.amount,'currency',v_row.currency,
                'status',v_row.status,'duplicate_of',v_row.duplicate_of,'version',v_row.version,
                'source_refs',jsonb_build_array(jsonb_build_object(
                  'source_type','business_record','source_id','billing_record:'||v_row.id,
                  'observed_at',v_observed_at))));
          ELSIF p_tool_name='query_request_trace' THEN
            IF (SELECT count(*) FROM jsonb_object_keys(p_model_arguments))<>1
               OR NOT p_model_arguments ? 'request_id' THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='trace_arguments_invalid';
            END IF;
            SELECT * INTO v_row FROM public.api_request_traces
             WHERE tenant_id=p_trusted_context->>'tenant_id' AND customer_id=v_customer_id
               AND request_id=p_model_arguments->>'request_id';
            IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='trace_not_found';
            END IF;
            RETURN jsonb_build_object(
              'schema_version','mcp-wrapper-result.v1','authorized',true,
              'tool_name',p_tool_name,'phase','execute','result',jsonb_build_object(
                'tool_call_id',v_tool_call_id,'ticket_id',v_ticket_id,
                'request_id',v_row.request_id,'model',v_row.model,'region',v_row.region,
                'status_code',v_row.status_code,'error_class',v_row.error_class,
                'stage_latency_ms',v_row.stage_latency_ms,'observed_at',v_row.observed_at,
                'version',v_row.version,'source_refs',jsonb_build_array(jsonb_build_object(
                  'source_type','business_record','source_id','api_request_trace:'||v_row.id,
                  'observed_at',v_row.observed_at))));
          ELSIF p_tool_name='query_api_key_metadata' THEN
            IF (SELECT count(*) FROM jsonb_object_keys(p_model_arguments))<>1
               OR NOT p_model_arguments ? 'api_key_ref' THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='api_key_arguments_invalid';
            END IF;
            SELECT * INTO v_row FROM public.api_key_metadata
             WHERE tenant_id=p_trusted_context->>'tenant_id' AND customer_id=v_customer_id
               AND (key_id=p_model_arguments->>'api_key_ref'
                    OR fingerprint=p_model_arguments->>'api_key_ref');
            IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='api_key_not_found';
            END IF;
            RETURN jsonb_build_object(
              'schema_version','mcp-wrapper-result.v1','authorized',true,
              'tool_name',p_tool_name,'phase','execute','result',jsonb_build_object(
                'tool_call_id',v_tool_call_id,'ticket_id',v_ticket_id,
                'api_key_id',v_row.key_id,'fingerprint',v_row.fingerprint,
                'status',v_row.status,'version',v_row.version,
                'last_used_summary',v_row.last_used_summary,'source_refs',jsonb_build_array(
                  jsonb_build_object('source_type','business_record','source_id',
                    'api_key_metadata:'||v_row.id,'observed_at',v_observed_at))));
          ELSIF p_tool_name='check_service_status' THEN
            IF (SELECT count(*) FROM jsonb_object_keys(p_model_arguments))<>2
               OR NOT p_model_arguments ?& ARRAY['model','region'] THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='service_status_arguments_invalid';
            END IF;
            SELECT * INTO v_row FROM public.service_incidents
             WHERE model=p_model_arguments->>'model' AND region=p_model_arguments->>'region'
               AND status<>'resolved' ORDER BY started_at DESC LIMIT 1;
            RETURN jsonb_build_object(
              'schema_version','mcp-wrapper-result.v1','authorized',true,
              'tool_name',p_tool_name,'phase','execute','result',jsonb_build_object(
                'tool_call_id',v_tool_call_id,'ticket_id',v_ticket_id,
                'model',COALESCE(v_row.model,p_model_arguments->>'model'),
                'region',COALESCE(v_row.region,p_model_arguments->>'region'),
                'status',COALESCE(v_row.status,'operational'),
                'summary',COALESCE(v_row.summary,
                  'No active incident is recorded for this model and region.'),
                'observed_at',v_observed_at,'source_refs',jsonb_build_array(
                  jsonb_build_object('source_type','business_record','source_id',
                    CASE WHEN v_row.id IS NULL THEN 'service_status_query:'||
                      (p_model_arguments->>'model')||':'||(p_model_arguments->>'region')
                    ELSE 'service_incident:'||v_row.id END,'observed_at',v_observed_at))));
          ELSIF p_tool_name='query_incident_impact' THEN
            IF (SELECT count(*) FROM jsonb_object_keys(p_model_arguments))<>1
               OR NOT p_model_arguments ? 'request_id' THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='impact_arguments_invalid';
            END IF;
            SELECT * INTO v_row FROM public.api_request_traces
             WHERE tenant_id=p_trusted_context->>'tenant_id' AND customer_id=v_customer_id
               AND request_id=p_model_arguments->>'request_id';
            IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='impact_not_found';
            END IF;
            SELECT * INTO v_other FROM public.incident_impacts
             WHERE tenant_id=p_trusted_context->>'tenant_id' AND request_trace_id=v_row.id;
            RETURN jsonb_build_object(
              'schema_version','mcp-wrapper-result.v1','authorized',true,
              'tool_name',p_tool_name,'phase','execute','result',jsonb_build_object(
                'tool_call_id',v_tool_call_id,'ticket_id',v_ticket_id,
                'request_id',v_row.request_id,'impacted',v_other.impacted,
                'incident_id',v_other.incident_id,'public_incident_ref',v_other.public_incident_ref,
                'observed_at',v_observed_at,'source_refs',jsonb_build_array(
                  jsonb_build_object('source_type','business_record','source_id',
                    'incident_impact:'||COALESCE(v_other.id,v_row.id),
                    'observed_at',v_observed_at))));
          ELSIF p_tool_name='query_api_usage' THEN
            IF (SELECT count(*) FROM jsonb_object_keys(p_model_arguments))<>1
               OR p_model_arguments->>'window' NOT IN ('1m','5m','1h','24h') THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='usage_arguments_invalid';
            END IF;
            v_window:=p_model_arguments->>'window';
            v_window_minutes:=CASE v_window WHEN '1m' THEN 1 WHEN '5m' THEN 5
              WHEN '1h' THEN 60 ELSE 1440 END;
            SELECT logical_time_utc INTO v_logical_time FROM public.tool_invocations
             WHERE tenant_id=p_trusted_context->>'tenant_id'
               AND run_id=p_trusted_context->>'run_id'
               AND job_id=p_trusted_context->>'job_id'
               AND logical_invocation_id=p_trusted_context->>'logical_invocation_id';
            IF v_logical_time IS NULL THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='usage_logical_time_unavailable';
            END IF;
            v_window_end:=date_trunc('minute',v_logical_time);
            v_window_start:=v_window_end-make_interval(mins=>v_window_minutes);
            WITH scoped AS (
              SELECT b.*,
                lag(bucket_end) OVER (ORDER BY bucket_start,bucket_end,id) AS previous_end,
                count(*) OVER (PARTITION BY bucket_start,bucket_end) AS duplicate_count
              FROM public.api_usage_buckets b
              WHERE tenant_id=p_trusted_context->>'tenant_id'
                AND customer_id=v_customer_id AND bucket_end>v_window_start
                AND bucket_end<=v_window_end
            )
            SELECT count(*),COALESCE(sum(request_count),0),COALESCE(sum(input_token_count),0),
                   COALESCE(sum(output_token_count),0),COALESCE(max(concurrency_peak),0),
                   max(bucket_end),COALESCE(jsonb_agg(jsonb_build_array(id,source_version)
                     ORDER BY bucket_start,bucket_end,id),'[]'::jsonb),
                   min(bucket_start)=v_window_start AND max(bucket_end)=v_window_end
                     AND bool_and(bucket_end-bucket_start=interval '1 minute'
                       AND duplicate_count=1
                       AND (previous_end IS NULL OR bucket_start=previous_end))
              INTO v_bucket_count,v_request_count,v_input_tokens,v_output_tokens,
                   v_concurrency_peak,v_coverage_through,v_bucket_sources,v_bucket_complete
            FROM scoped;
            SELECT concurrency_end,id,bucket_end
              INTO v_concurrency_current,v_last_bucket_id,v_last_bucket_end
            FROM public.api_usage_buckets WHERE tenant_id=p_trusted_context->>'tenant_id'
              AND customer_id=v_customer_id AND bucket_end>v_window_start
              AND bucket_end<=v_window_end ORDER BY bucket_start DESC,bucket_end DESC,id DESC LIMIT 1;
            SELECT id,bucket_end INTO v_first_bucket_id,v_first_bucket_end
            FROM public.api_usage_buckets WHERE tenant_id=p_trusted_context->>'tenant_id'
              AND customer_id=v_customer_id AND bucket_end>v_window_start
              AND bucket_end<=v_window_end ORDER BY bucket_start,bucket_end,id LIMIT 1;
            SELECT * INTO v_row FROM public.api_usage_snapshots
             WHERE tenant_id=p_trusted_context->>'tenant_id' AND customer_id=v_customer_id
               AND observed_at<=v_logical_time ORDER BY observed_at DESC LIMIT 1;
            SELECT * INTO v_other FROM public.subscriptions
             WHERE tenant_id=p_trusted_context->>'tenant_id' AND customer_id=v_customer_id;
            IF v_row.id IS NULL OR v_other.id IS NULL THEN
              RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='usage_scope_unavailable';
            END IF;
            v_coverage_through:=COALESCE(v_coverage_through,v_window_start);
            v_observed_at:=LEAST(v_coverage_through,v_row.observed_at);
            v_freshness_seconds:=extract(epoch FROM (v_logical_time-v_observed_at))::integer;
            v_freshness_status:=CASE
              WHEN v_bucket_count<>v_window_minutes OR NOT COALESCE(v_bucket_complete,false)
                OR v_freshness_seconds<0 THEN 'unknown'
              WHEN v_freshness_seconds<=CASE v_window WHEN '1m' THEN 120 WHEN '5m' THEN 300
                WHEN '1h' THEN 900 ELSE 3600 END THEN 'fresh' ELSE 'stale' END;
            v_resource_version:=encode(pg_catalog.sha256(convert_to(
              supportguard_canonical_jsonb(jsonb_build_object(
              'bucket_sources',v_bucket_sources,'balance_source',v_row.id,
              'subscription_version',v_other.version,'window',v_window,
              'window_start',to_char(v_window_start AT TIME ZONE 'UTC',
                'YYYY-MM-DD"T"HH24:MI:SS')||'+00:00',
              'window_end',to_char(v_window_end AT TIME ZONE 'UTC',
                'YYYY-MM-DD"T"HH24:MI:SS')||'+00:00'
            )),'UTF8')),'hex');
            RETURN jsonb_build_object(
              'schema_version','mcp-wrapper-result.v1','authorized',true,
              'tool_name',p_tool_name,'phase','execute','result',jsonb_build_object(
                'tool_call_id',v_tool_call_id,'ticket_id',v_ticket_id,'window',v_window,
                'window_start',v_window_start,'window_end',v_window_end,
                'request_count',v_request_count,'input_token_count',v_input_tokens,
                'output_token_count',v_output_tokens,
                'concurrency_current',COALESCE(v_concurrency_current,0),
                'concurrency_peak',v_concurrency_peak,'remaining_balance',v_row.remaining_balance,
                'balance_currency',v_other.currency,'freshness_seconds',v_freshness_seconds,
                'freshness_status',v_freshness_status,'observed_at',v_observed_at,
                'resource_version',v_resource_version,'source_refs',jsonb_build_array(
                  jsonb_build_object('source_type','business_record','source_id',
                    'api_usage_snapshot:'||v_row.id,'observed_at',v_row.observed_at),
                  jsonb_build_object('source_type','business_record','source_id',
                    'subscription:'||v_other.id,'observed_at',v_logical_time))
                  || CASE WHEN v_bucket_count>0 THEN jsonb_build_array(
                    jsonb_build_object('source_type','business_record','source_id',
                      'api_usage_bucket:'||v_first_bucket_id,
                      'observed_at',v_first_bucket_end),
                    jsonb_build_object('source_type','business_record','source_id',
                      'api_usage_bucket:'||v_last_bucket_id,
                      'observed_at',v_last_bucket_end)) ELSE '[]'::jsonb END));
          END IF;
          RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='read_mcp_tool_unknown';
        END $$;


ALTER FUNCTION public.supportguard_read_mcp_execute(p_tool_name text, p_model_arguments jsonb, p_trusted_context jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_read_mcp_query_account(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_read_mcp_query_account(p_model_arguments jsonb, p_trusted_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_allowed boolean;
        BEGIN
          IF session_user <> 'supportguard_read_mcp' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF jsonb_typeof(p_model_arguments)<>'object'
             OR jsonb_typeof(p_trusted_context)<>'object'
             OR p_trusted_context->>'schema_version'<>'read-mcp-wrapper.v1'
             OR p_trusted_context->>'tool_name'<>'query_account'
             OR p_trusted_context->>'phase' NOT IN ('reserve','recheck','execute')
             OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_trusted_context) key)
                <> ARRAY['call_deadline','delivery_generation','fencing_token','job_id',
                         'logical_invocation_id','phase','provider_tool_call_id','run_id',
                         'schema_version','segment_id','tenant_id','tool_attempt_id',
                         'tool_name','trace_origin','transport_attempt_id','transport_ordinal']
          THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid read MCP wrapper envelope';
          END IF;
          IF p_trusted_context->>'phase'='reserve'
             AND p_trusted_context->>'trace_origin'='agent_read_tool' THEN
            v_allowed:=supportguard_mcp_consume_read_reservation(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer,
              p_trusted_context->>'logical_invocation_id',
              p_trusted_context->>'tool_attempt_id',
              p_trusted_context->>'transport_attempt_id',
              (p_trusted_context->>'transport_ordinal')::integer,
              'query_account',p_trusted_context->>'provider_tool_call_id',
              (p_trusted_context->>'call_deadline')::timestamptz);
          ELSE
            v_allowed:=supportguard_mcp_verify_fence(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer);
          END IF;

          IF p_trusted_context->>'phase'='execute' THEN
            IF v_allowed IS DISTINCT FROM true THEN
              RETURN pg_catalog.jsonb_build_object(
                'schema_version','mcp-wrapper-result.v1','authorized',false,
                'tool_name','query_account','phase','execute');
            END IF;
            RETURN public.supportguard_read_mcp_execute(
              'query_account',p_model_arguments,p_trusted_context);
          END IF;
          RETURN jsonb_build_object('schema_version','mcp-wrapper-result.v1',
                                    'authorized',v_allowed,'tool_name','query_account',
                                    'phase',p_trusted_context->>'phase');
        END $$;


ALTER FUNCTION public.supportguard_read_mcp_query_account(p_model_arguments jsonb, p_trusted_context jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_read_mcp_query_api_key_metadata(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_read_mcp_query_api_key_metadata(p_model_arguments jsonb, p_trusted_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_allowed boolean;
        BEGIN
          IF session_user <> 'supportguard_read_mcp' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF jsonb_typeof(p_model_arguments)<>'object'
             OR jsonb_typeof(p_trusted_context)<>'object'
             OR p_trusted_context->>'schema_version'<>'read-mcp-wrapper.v1'
             OR p_trusted_context->>'tool_name'<>'query_api_key_metadata'
             OR p_trusted_context->>'phase' NOT IN ('reserve','recheck','execute')
             OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_trusted_context) key)
                <> ARRAY['call_deadline','delivery_generation','fencing_token','job_id',
                         'logical_invocation_id','phase','provider_tool_call_id','run_id',
                         'schema_version','segment_id','tenant_id','tool_attempt_id',
                         'tool_name','trace_origin','transport_attempt_id','transport_ordinal']
          THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid read MCP wrapper envelope';
          END IF;
          IF p_trusted_context->>'phase'='reserve'
             AND p_trusted_context->>'trace_origin'='agent_read_tool' THEN
            v_allowed:=supportguard_mcp_consume_read_reservation(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer,
              p_trusted_context->>'logical_invocation_id',
              p_trusted_context->>'tool_attempt_id',
              p_trusted_context->>'transport_attempt_id',
              (p_trusted_context->>'transport_ordinal')::integer,
              'query_api_key_metadata',p_trusted_context->>'provider_tool_call_id',
              (p_trusted_context->>'call_deadline')::timestamptz);
          ELSE
            v_allowed:=supportguard_mcp_verify_fence(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer);
          END IF;

          IF p_trusted_context->>'phase'='execute' THEN
            IF v_allowed IS DISTINCT FROM true THEN
              RETURN pg_catalog.jsonb_build_object(
                'schema_version','mcp-wrapper-result.v1','authorized',false,
                'tool_name','query_api_key_metadata','phase','execute');
            END IF;
            RETURN public.supportguard_read_mcp_execute(
              'query_api_key_metadata',p_model_arguments,p_trusted_context);
          END IF;
          RETURN jsonb_build_object('schema_version','mcp-wrapper-result.v1',
