--
-- Name: supportguard_read_mcp_search_execute(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_read_mcp_search_execute(p_model_arguments jsonb, p_trusted_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $_$
        DECLARE
          ep jsonb:=p_trusted_context->'execution_payload';
          f jsonb; v_operation text; v_customer_id text; v_ticket_id text;
          v_result jsonb; v_count integer; v_trace retrieval_traces%ROWTYPE;
          v_state jsonb; v_receipt jsonb; v_scope jsonb; v_binding jsonb;
          v_request_hash text; v_response_hash text; v_filter_hash text;
          v_vector_norm double precision; v_vector_valid boolean;
          v_next_phase text;

        BEGIN
          IF current_user<>'supportguard_owner'
             OR jsonb_typeof(p_model_arguments)<>'object'
             OR (SELECT count(*) FROM jsonb_object_keys(p_model_arguments))<>1
             OR NOT p_model_arguments ? 'query'
             OR jsonb_typeof(ep)<>'object' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='search_execute_forbidden';
          END IF;
          SELECT count(*),min(r.ticket_id),min(r.customer_id)
            INTO v_count,v_ticket_id,v_customer_id
          FROM agent_runs r JOIN runtime_jobs j
            ON j.tenant_id=r.tenant_id AND j.run_id=r.id
           AND j.id=p_trusted_context->>'job_id'
           AND j.fencing_token=(p_trusted_context->>'fencing_token')::bigint
          JOIN tool_invocations i
            ON i.tenant_id=r.tenant_id AND i.run_id=r.id AND i.job_id=j.id
           AND i.logical_invocation_id=p_trusted_context->>'logical_invocation_id'
           AND i.provider_tool_call_id=p_trusted_context->>'provider_tool_call_id'
           AND i.tool_name='search_knowledge'
           AND i.arguments_hash=encode(pg_catalog.sha256(convert_to(
             supportguard_canonical_jsonb(p_model_arguments),'UTF8')),'hex')
          WHERE r.tenant_id=p_trusted_context->>'tenant_id'
            AND r.id=p_trusted_context->>'run_id' AND r.active_job_id=j.id
            AND r.active_fencing_token=j.fencing_token;
          IF v_count<>1 THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_scope_unavailable';
          END IF;
          v_operation:=ep->>'operation';
          v_binding:=ep->'binding';
          IF v_operation NOT IN ('load_scope','trace_start','candidate_universe',
               'vector_search','keyword_search','trace_terminal')
             OR jsonb_typeof(v_binding)<>'object'
             OR v_binding->>'trace_id' IS NULL
             OR v_binding->>'query_hash' !~ '^[0-9a-f]{64}$'
             OR v_binding->>'trace_logical_time' IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='search_binding_invalid';
          END IF;
          v_request_hash:=encode(pg_catalog.sha256(convert_to(
            supportguard_canonical_jsonb(ep),'UTF8')),'hex');

          SELECT * INTO v_trace FROM retrieval_traces rt
          WHERE rt.id=v_binding->>'trace_id'
            AND rt.tenant_id=p_trusted_context->>'tenant_id'
            AND rt.run_id=p_trusted_context->>'run_id'
            AND rt.job_id=p_trusted_context->>'job_id'
            AND rt.segment_id=p_trusted_context->>'segment_id'
            AND rt.tool_call_id=p_trusted_context->>'provider_tool_call_id'
            AND rt.fencing_token=(p_trusted_context->>'fencing_token')::bigint
            AND rt.delivery_generation=(p_trusted_context->>'delivery_generation')::integer
          FOR UPDATE;
          IF FOUND THEN
            v_state:=v_trace.runtime_provenance->'_restricted_search';
            v_receipt:=v_state->'receipts'->v_operation;
            IF v_receipt IS NOT NULL THEN
              IF v_receipt->>'request_hash'=v_request_hash
                 AND v_receipt->>'response_hash'=encode(pg_catalog.sha256(convert_to(
                   supportguard_canonical_jsonb(v_receipt->'response'),'UTF8')),'hex') THEN
                RETURN jsonb_build_object('schema_version','mcp-wrapper-result.v1',
                  'authorized',true,'tool_name','search_knowledge','phase','execute',
                  'result',v_receipt->'response');
              END IF;
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_replay_conflict';
            END IF;
          END IF;

          IF v_operation='load_scope' THEN
            IF v_trace.id IS NOT NULL THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_load_scope_conflict';
            END IF;
            SELECT jsonb_build_object(
              'subscription',jsonb_build_object('id',s.id,'version',s.version,'plan',s.plan),
              'region_trace',CASE WHEN a.id IS NULL THEN NULL ELSE jsonb_build_object(
                'id',a.id,'version',a.version,'region',a.region) END,
              'run_provenance',jsonb_build_object('model',r.model,
                'provider_mode',r.provider_mode,'tool_call_mode',r.tool_call_mode,
                'context_version',r.context_version),
              'snapshot',jsonb_build_object('ingest_run_id',k.id,
                'index_version',k.index_version,'pipeline_fingerprint',k.pipeline_fingerprint,
                'pipeline_identity',k.pipeline_identity),
              'invocation_internal_id',i.id,'trace_logical_time',i.created_at,'ticket_id',v_ticket_id)
              INTO v_result
            FROM agent_runs r
            JOIN subscriptions s ON s.tenant_id=r.tenant_id
              AND s.customer_id=r.customer_id
            JOIN tool_invocations i ON i.tenant_id=r.tenant_id AND i.run_id=r.id
              AND i.job_id=p_trusted_context->>'job_id'
              AND i.logical_invocation_id=p_trusted_context->>'logical_invocation_id'
            CROSS JOIN LATERAL (
              SELECT * FROM knowledge_ingest_runs
              WHERE is_active AND status='succeeded' ORDER BY created_at DESC LIMIT 2
            ) k
            LEFT JOIN LATERAL (
              SELECT * FROM api_request_traces x WHERE x.tenant_id=r.tenant_id
                AND x.customer_id=r.customer_id
              ORDER BY x.observed_at DESC,x.id DESC LIMIT 1
            ) a ON true
            WHERE r.tenant_id=p_trusted_context->>'tenant_id'
              AND r.id=p_trusted_context->>'run_id';
            SELECT count(*) INTO v_count FROM knowledge_ingest_runs
             WHERE is_active AND status='succeeded';
            IF v_count<>1 OR v_result IS NULL THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_snapshot_unavailable';
            END IF;
            v_response_hash:=encode(pg_catalog.sha256(convert_to(
              supportguard_canonical_jsonb(v_result),'UTF8')),'hex');
            v_state:=jsonb_build_object(
              'schema_version','restricted-search-state.v1','phase','scope_loaded',
              'counts',jsonb_build_object('load_scope',1,'trace_start',0,
                'candidate_universe',0,'vector_search',0,'keyword_search',0,
                'trace_terminal',0),
              'receipts',jsonb_build_object('load_scope',jsonb_build_object(
                'request_hash',v_request_hash,'response_hash',v_response_hash,
                'response',v_result)));
            INSERT INTO retrieval_traces(
              id,tenant_id,run_id,job_id,segment_id,origin_kind,
              logical_invocation_id,tool_call_id,fencing_token,delivery_generation,
              origin_job_id,origin_marker_id,origin_fencing_token,origin_segment_ref,
              trace_status,status_version,trace_logical_time,temporal_selector,query_hash,
              filter_contract,vector_candidates,keyword_candidates,rrf_candidates,
              pre_filter_candidates,selected_candidates,omission_decisions,evidence_groups,
              eligibility_envelopes,pipeline_contract,embedding_fingerprint,
              pipeline_fingerprint,index_version,corpus_snapshot_id,abstention_reason,
              runtime_provenance)
            VALUES(v_binding->>'trace_id',p_trusted_context->>'tenant_id',
              p_trusted_context->>'run_id',p_trusted_context->>'job_id',
              p_trusted_context->>'segment_id','agent_read_tool',
              v_result->>'invocation_internal_id',p_trusted_context->>'provider_tool_call_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer,
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,p_trusted_context->>'segment_id',
              'started',1,(v_result->>'trace_logical_time')::timestamptz,NULL,
              v_binding->>'query_hash','{}'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,
              '[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,
              jsonb_build_object('state','scope_loaded'),NULL,
              v_result->'snapshot'->>'pipeline_fingerprint',
              v_result->'snapshot'->>'index_version',
              v_result->'snapshot'->>'ingest_run_id',NULL,
              jsonb_build_object('_restricted_search',v_state));
          ELSIF v_operation='trace_start' THEN
            f:=ep->'trace';
            IF jsonb_typeof(f)<>'object'
               OR f->>'trace_id' IS NULL
               OR f->>'query_hash' !~ '^[0-9a-f]{64}$'
               OR f->>'pipeline_fingerprint' !~ '^[0-9a-f]{64}$' THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='search_trace_start_invalid';
            END IF;
            IF v_trace.id IS NULL OR v_state->>'phase'<>'scope_loaded'
               OR f->>'trace_id'<>v_trace.id
               OR f->>'query_hash'<>v_trace.query_hash
               OR (f->>'trace_logical_time')::timestamptz<>v_trace.trace_logical_time
               OR f->>'index_version'<>v_trace.index_version
               OR f->>'corpus_snapshot_id'<>v_trace.corpus_snapshot_id
               OR f->>'index_version'<>v_binding->>'index_version'
               OR f->>'corpus_snapshot_id'<>v_binding->>'corpus_snapshot_id'
               OR encode(pg_catalog.sha256(convert_to(
                    supportguard_canonical_jsonb(f->'filter_contract'),'UTF8')),'hex')
                    <>v_binding->>'filter_hash' THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_trace_start_binding_conflict';
            END IF;
            v_scope:=v_state->'receipts'->'load_scope'->'response';
            IF f->'filter_contract'->'scope_snapshot'->>'tenant_id'
                   <>p_trusted_context->>'tenant_id'
               OR f->'filter_contract'->'scope_snapshot'->>'customer_id'<>v_customer_id
               OR f->'filter_contract'->'scope_snapshot'->>'subscription_id'
                   <>v_scope->'subscription'->>'id'
               OR (f->'filter_contract'->'scope_snapshot'->>'subscription_version')::integer
                   <>(v_scope->'subscription'->>'version')::integer
               OR f->'filter_contract'->>'plan'<>v_scope->'subscription'->>'plan'
               OR f->'filter_contract'->>'index_version'<>v_trace.index_version
               OR f->'filter_contract'->>'corpus_snapshot_id'<>v_trace.corpus_snapshot_id THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_filter_scope_conflict';
            END IF;
            UPDATE retrieval_traces SET temporal_selector=f->'temporal_selector',
              filter_contract=f->'filter_contract',pipeline_contract=f->'pipeline_contract',
              pipeline_fingerprint=f->>'pipeline_fingerprint',
              runtime_provenance=(f->'runtime_provenance') ||
                jsonb_build_object('_restricted_search',v_state),updated_at=clock_timestamp()
            WHERE id=v_trace.id;
            v_result:=jsonb_build_object('trace_id',f->>'trace_id','status','started');
          ELSIF v_operation='trace_terminal' THEN
            f:=ep->'trace';
            IF jsonb_typeof(f)<>'object'
               OR f->>'trace_id' IS NULL
               OR f->>'trace_status' NOT IN ('terminal_ok','terminal_error') THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='search_trace_terminal_invalid';
            END IF;
            UPDATE retrieval_traces rt SET
              terminal_transport_attempt_id=p_trusted_context->>'transport_attempt_id',
              trace_status=f->>'trace_status',status_version=rt.status_version+1,
              result_digest=f->>'result_digest',error_digest=f->>'error_digest',
              temporal_selector=f->'temporal_selector',filter_contract=f->'filter_contract',
              vector_candidates=f->'vector_candidates',
              keyword_candidates=f->'keyword_candidates',rrf_candidates=f->'rrf_candidates',
              pre_filter_candidates=f->'pre_filter_candidates',
              selected_candidates=f->'selected_candidates',
              omission_decisions=f->'omission_decisions',evidence_groups=f->'evidence_groups',
              eligibility_envelopes=f->'eligibility_envelopes',
              pipeline_contract=f->'pipeline_contract',
              embedding_fingerprint=f->>'embedding_fingerprint',
              pipeline_fingerprint=f->>'pipeline_fingerprint',
              abstention_reason=f->>'abstention_reason',updated_at=clock_timestamp()
            WHERE rt.id=f->>'trace_id'
              AND rt.tenant_id=p_trusted_context->>'tenant_id'
              AND rt.run_id=p_trusted_context->>'run_id'
              AND rt.job_id=p_trusted_context->>'job_id'
              AND rt.segment_id=p_trusted_context->>'segment_id'
              AND rt.tool_call_id=p_trusted_context->>'provider_tool_call_id'
              AND rt.fencing_token=(p_trusted_context->>'fencing_token')::bigint
              AND rt.delivery_generation=(p_trusted_context->>'delivery_generation')::integer
              AND rt.trace_status='started' AND rt.status_version=1;
            IF NOT FOUND THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_trace_transition_conflict';
            END IF;
            v_result:=jsonb_build_object('trace_id',f->>'trace_id',
              'status',f->>'trace_status');
          ELSIF v_operation IN ('candidate_universe','vector_search','keyword_search') THEN
            f:=ep->'filters';
            v_filter_hash:=encode(pg_catalog.sha256(convert_to(
              supportguard_canonical_jsonb(f),'UTF8')),'hex');
            IF jsonb_typeof(f)<>'object' OR v_trace.id IS NULL
               OR v_filter_hash<>v_binding->>'filter_hash'
               OR f<>v_trace.filter_contract::jsonb THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='search_filter_invalid';
            END IF;
            IF v_operation='candidate_universe' AND v_state->>'phase'<>'trace_started' THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_candidate_order_invalid';
            ELSIF v_operation='vector_search' AND v_state->>'phase'<>'candidate_done' THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_vector_order_invalid';
            ELSIF v_operation='keyword_search' AND v_state->>'phase'<>'vector_done' THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_keyword_order_invalid';
            END IF;
            IF v_operation='vector_search' THEN
              IF jsonb_typeof(ep->'vector')<>'array'
                 OR jsonb_array_length(ep->'vector')<>384 THEN
                RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='search_vector_invalid';
              END IF;
              SELECT bool_and(jsonb_typeof(value)='number'),
                     sum(power((value #>> '{}')::double precision,2))
                INTO v_vector_valid,v_vector_norm FROM jsonb_array_elements(ep->'vector');
              IF v_vector_valid IS DISTINCT FROM true
                 OR v_vector_norm IN ('Infinity'::double precision,
                   '-Infinity'::double precision,'NaN'::double precision)
                 OR abs(v_vector_norm-1.0)>0.001 THEN
                RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='search_vector_invalid';
              END IF;
            ELSIF v_operation='keyword_search'
               AND encode(pg_catalog.sha256(convert_to(ep->>'query','UTF8')),'hex')
                   <>v_trace.query_hash THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_query_changed';
            END IF;
            IF v_operation='candidate_universe' THEN
              SELECT jsonb_build_object('rows',COALESCE(jsonb_agg(jsonb_build_object(
                'chunk_id',c.chunk_key,'document_id',d.document_key,'version',d.version,
                'status',d.status,'locator_hash',c.locator_hash,
                'filter_outcome',CASE WHEN cardinality(reasons.items)=0
                  THEN 'eligible' ELSE 'excluded' END,
                'filter_reasons',to_jsonb(reasons.items))
                ORDER BY d.document_key,c.sequence),'[]'::jsonb)) INTO v_result
              FROM knowledge_chunks c JOIN knowledge_documents d ON d.id=c.document_id
              CROSS JOIN LATERAL (SELECT array_remove(ARRAY[
                CASE WHEN NOT (f->'statuses' ? d.status) THEN 'status_filtered' END,
                CASE WHEN f->>'version' IS NOT NULL AND d.version<>f->>'version'
                  THEN 'version_filtered' END,
                CASE WHEN f->>'intent'<>'compare'
                  AND (f->'temporal_selector'->>'claim_effective_time') IS NOT NULL
                  AND NOT (d.effective_from <=
                    (f->'temporal_selector'->>'claim_effective_time')::timestamptz
                    AND (d.effective_until IS NULL OR
                    (f->'temporal_selector'->>'claim_effective_time')::timestamptz
                      < d.effective_until)) THEN 'effective_interval_filtered' END,
                CASE WHEN d.authority_level<(f->>'minimum_authority')::integer
                  THEN 'authority_filtered' END,
                CASE WHEN d.applicable_plan IS NOT NULL
                  AND d.applicable_plan IS DISTINCT FROM f->>'plan'
                  THEN 'plan_scope_filtered' END,
                CASE WHEN d.applicable_region IS NOT NULL
                  AND d.applicable_region IS DISTINCT FROM f->>'region'
                  THEN 'region_scope_filtered' END],NULL) items) reasons
              WHERE c.ingest_run_id=f->>'corpus_snapshot_id'
                AND c.index_version=f->>'index_version'
                AND d.ingest_run_id=f->>'corpus_snapshot_id'
                AND d.index_version=f->>'index_version';
            ELSIF v_operation='vector_search' THEN
              WITH ranked AS (
                SELECT c,d,(c.embedding <=> ((ep->'vector')::text)::vector) distance,
                  row_number() OVER (PARTITION BY d.status ORDER BY c.embedding <=> ((ep->'vector')::text)::vector,
                    d.authority_level DESC) rank
                FROM knowledge_chunks c JOIN knowledge_documents d ON d.id=c.document_id
                WHERE c.ingest_run_id=f->>'corpus_snapshot_id'
                  AND c.index_version=f->>'index_version'
                  AND d.ingest_run_id=f->>'corpus_snapshot_id'
                  AND d.index_version=f->>'index_version'
                  AND f->'statuses' ? d.status
                  AND (f->>'version' IS NULL OR d.version=f->>'version')
                  AND d.authority_level >= (f->>'minimum_authority')::integer
                  AND (d.applicable_plan IS NULL OR d.applicable_plan=f->>'plan')
                  AND (d.applicable_region IS NULL OR d.applicable_region=f->>'region')
                  AND (f->>'intent'='compare' OR
                    (f->'temporal_selector'->>'claim_effective_time') IS NULL OR
                    (d.effective_from <=
                      (f->'temporal_selector'->>'claim_effective_time')::timestamptz
                     AND (d.effective_until IS NULL OR
                      (f->'temporal_selector'->>'claim_effective_time')::timestamptz
                        < d.effective_until)))
                ) SELECT jsonb_build_object('rows',COALESCE(jsonb_agg(
                  supportguard_read_mcp_chunk_payload(c,d,distance,NULL,false,rank::integer)
                  ORDER BY rank),'[]'::jsonb)) INTO v_result FROM ranked
              WHERE rank<=LEAST((ep->>'limit')::integer,20);
            ELSE
              WITH ranked AS (
                SELECT c,d,(ts_rank_cd(c.search_vector,
                    websearch_to_tsquery('simple',ep->>'query')) +
                    (SELECT count(*)::real
                     FROM jsonb_array_elements_text(ep->'keyword_terms') t
                     WHERE (c.section_path||E'\n'||c.content) ILIKE '%'||t||'%')) score,
                  EXISTS (SELECT 1 FROM jsonb_array_elements_text(ep->'exact_tokens') t
                    WHERE lower(c.content) LIKE '%'||lower(t)||'%') exact_match,
                  row_number() OVER (PARTITION BY d.status ORDER BY (ts_rank_cd(c.search_vector,
                    websearch_to_tsquery('simple',ep->>'query')) +
                    (SELECT count(*)::real
                     FROM jsonb_array_elements_text(ep->'keyword_terms') t
                     WHERE (c.section_path||E'\n'||c.content) ILIKE '%'||t||'%')) DESC,
                    d.authority_level DESC) rank
                FROM knowledge_chunks c JOIN knowledge_documents d ON d.id=c.document_id
                WHERE c.ingest_run_id=f->>'corpus_snapshot_id'
                  AND c.index_version=f->>'index_version'
                  AND d.ingest_run_id=f->>'corpus_snapshot_id'
                  AND d.index_version=f->>'index_version'
                  AND f->'statuses' ? d.status
                  AND (f->>'version' IS NULL OR d.version=f->>'version')
                  AND d.authority_level >= (f->>'minimum_authority')::integer
                  AND (d.applicable_plan IS NULL OR d.applicable_plan=f->>'plan')
                  AND (d.applicable_region IS NULL OR d.applicable_region=f->>'region')
                  AND (f->>'intent'='compare' OR
                    (f->'temporal_selector'->>'claim_effective_time') IS NULL OR
                    (d.effective_from <=
                      (f->'temporal_selector'->>'claim_effective_time')::timestamptz
                     AND (d.effective_until IS NULL OR
                      (f->'temporal_selector'->>'claim_effective_time')::timestamptz
                        < d.effective_until)))
                  AND (c.search_vector @@ websearch_to_tsquery('simple',ep->>'query')
                    OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(ep->'keyword_terms') t
                      WHERE (c.section_path||E'\n'||c.content) ILIKE '%'||t||'%'))
                ) SELECT jsonb_build_object('rows',COALESCE(jsonb_agg(
                  supportguard_read_mcp_chunk_payload(c,d,NULL,score,exact_match,rank::integer)
                  ORDER BY rank),'[]'::jsonb)) INTO v_result FROM ranked
              WHERE rank<=LEAST((ep->>'limit')::integer,20);
            END IF;
          ELSE
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='search_operation_invalid';
          END IF;

          IF v_operation<>'load_scope' THEN
            IF v_trace.id IS NULL THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_trace_missing';
            END IF;
            IF v_operation='trace_start' THEN v_next_phase:='trace_started';
            ELSIF v_operation='candidate_universe' THEN v_next_phase:='candidate_done';
            ELSIF v_operation='vector_search' THEN v_next_phase:='vector_done';
            ELSIF v_operation='keyword_search' THEN v_next_phase:='keyword_done';
            ELSE v_next_phase:='terminal'; END IF;
            IF v_operation='trace_terminal' AND (
                 (ep->'trace'->>'trace_status'='terminal_ok' AND NOT (
                   v_state->>'phase'='keyword_done'
                   OR (
                     v_state->>'phase'='trace_started'
                     AND ep->'trace'->>'abstention_reason'='ambiguous_historical_anchor'
                     AND ep->'trace'->'pipeline_contract'->>'reason'='ambiguous_historical_anchor'
                     AND ep->'trace'->'temporal_selector'->>'intent'='historical'
                     AND ep->'trace'->'temporal_selector'->>'historical_version' IS NULL
                     AND ep->'trace'->'temporal_selector'->>'as_of' IS NULL
                     AND ep->'trace'->'vector_candidates'='[]'::jsonb
                     AND ep->'trace'->'keyword_candidates'='[]'::jsonb
                     AND ep->'trace'->'rrf_candidates'='[]'::jsonb
                     AND ep->'trace'->'pre_filter_candidates'='[]'::jsonb
                     AND ep->'trace'->'selected_candidates'='[]'::jsonb
                     AND ep->'trace'->'evidence_groups'='[]'::jsonb
                   )
                 ))
                 OR (ep->'trace'->>'trace_status'='terminal_error'
                   AND v_state->>'phase' NOT IN
                     ('scope_loaded','trace_started','candidate_done','vector_done','keyword_done'))
               ) THEN
              RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='search_terminal_order_invalid';
            END IF;
            v_response_hash:=encode(pg_catalog.sha256(convert_to(
              supportguard_canonical_jsonb(v_result),'UTF8')),'hex');
            v_state:=jsonb_set(v_state,ARRAY['counts',v_operation],
              to_jsonb(COALESCE((v_state->'counts'->>v_operation)::integer,0)+1),true);
            v_state:=jsonb_set(v_state,'{phase}',to_jsonb(v_next_phase),true);
            v_state:=jsonb_set(v_state,ARRAY['receipts',v_operation],
              jsonb_build_object('request_hash',v_request_hash,
                'response_hash',v_response_hash,'response',v_result),true);
            IF v_operation='vector_search' THEN
              v_state:=jsonb_set(v_state,'{vector_fingerprint}',to_jsonb(encode(
                pg_catalog.sha256(convert_to(supportguard_canonical_jsonb(ep->'vector'),
                'UTF8')),'hex')),true);
            END IF;
            UPDATE retrieval_traces SET runtime_provenance=jsonb_set(
              COALESCE(runtime_provenance::jsonb,'{}'::jsonb),
              '{_restricted_search}',v_state,true),
              updated_at=clock_timestamp() WHERE id=v_trace.id;
          END IF;
          RETURN jsonb_build_object('schema_version','mcp-wrapper-result.v1',
            'authorized',true,'tool_name','search_knowledge','phase','execute','result',v_result);
        END $_$;


ALTER FUNCTION public.supportguard_read_mcp_search_execute(p_model_arguments jsonb, p_trusted_context jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_read_mcp_search_knowledge(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_read_mcp_search_knowledge(p_model_arguments jsonb, p_trusted_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_allowed boolean;
        BEGIN
          IF session_user <> 'supportguard_read_mcp' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security_definer_session_user_forbidden';
          END IF;
          IF jsonb_typeof(p_model_arguments)<>'object'
             OR jsonb_typeof(p_trusted_context)<>'object'
             OR p_trusted_context->>'schema_version'<>'read-mcp-wrapper.v1'
             OR p_trusted_context->>'tool_name'<>'search_knowledge'
             OR p_trusted_context->>'phase' NOT IN ('reserve','recheck','execute')
             OR (
               p_trusted_context->>'phase' IN ('reserve','recheck') AND
               (SELECT array_agg(key ORDER BY key)
                  FROM jsonb_object_keys(p_trusted_context) key)
               <> ARRAY['call_deadline','delivery_generation','fencing_token','job_id',
                        'logical_invocation_id','phase','provider_tool_call_id','run_id',
                        'schema_version','segment_id','tenant_id','tool_attempt_id',
                        'tool_name','trace_origin','transport_attempt_id','transport_ordinal']
             ) OR (
               p_trusted_context->>'phase'='execute' AND
               (SELECT array_agg(key ORDER BY key)
                  FROM jsonb_object_keys(p_trusted_context) key)
               <> ARRAY['call_deadline','delivery_generation','execution_payload',
                        'fencing_token','job_id','logical_invocation_id','phase',
                        'provider_tool_call_id','run_id','schema_version','segment_id',
                        'tenant_id','tool_attempt_id','tool_name','trace_origin',
                        'transport_attempt_id','transport_ordinal']
             )
          THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid read MCP wrapper envelope';
          END IF;
          IF p_trusted_context->>'phase'='reserve'
             AND p_trusted_context->>'trace_origin'='agent_read_tool' THEN
            v_allowed:=supportguard_mcp_consume_read_reservation(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer,
              p_trusted_context->>'logical_invocation_id',
              p_trusted_context->>'tool_attempt_id',
              p_trusted_context->>'transport_attempt_id',
              (p_trusted_context->>'transport_ordinal')::integer,
              'search_knowledge',p_trusted_context->>'provider_tool_call_id',
              (p_trusted_context->>'call_deadline')::timestamptz);
          ELSE
            v_allowed:=supportguard_mcp_verify_fence(
              p_trusted_context->>'tenant_id',p_trusted_context->>'run_id',
              p_trusted_context->>'job_id',p_trusted_context->>'segment_id',
              (p_trusted_context->>'fencing_token')::bigint,
              (p_trusted_context->>'delivery_generation')::integer);
          END IF;

          IF p_trusted_context->>'phase'='execute' THEN
            IF v_allowed IS DISTINCT FROM true THEN
              RETURN pg_catalog.jsonb_build_object(
                'schema_version','mcp-wrapper-result.v1','authorized',false,
                'tool_name','search_knowledge','phase','execute');
            END IF;
            RETURN public.supportguard_read_mcp_search_execute(
              p_model_arguments,p_trusted_context);
          END IF;
          RETURN jsonb_build_object('schema_version','mcp-wrapper-result.v1',
                                    'authorized',v_allowed,'tool_name','search_knowledge',
                                    'phase',p_trusted_context->>'phase');
        END $$;


ALTER FUNCTION public.supportguard_read_mcp_search_knowledge(p_model_arguments jsonb, p_trusted_context jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_reconciler_candidates(integer); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_reconciler_candidates(p_batch_size integer) RETURNS TABLE(job_id text, job_status text, status_version bigint, fencing_token bigint, created_at timestamp with time zone, available_at timestamp with time zone, lease_expires_at timestamp with time zone, delivery_hold_reason text, outbox_id text, delivery_id text, delivery_generation integer, delivery_state_version bigint, redis_message_id text, published_at timestamp with time zone, last_delivery_at timestamp with time zone, inbox_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        BEGIN
          IF session_user<>'supportguard_reconciler' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='reconciler capability caller is not authorized';
          END IF;
          IF p_batch_size<1 OR p_batch_size>500 THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='reconciler batch outside bound';
          END IF;
          RETURN QUERY
          WITH eligible AS (
            SELECT
              j.id::text AS job_id,j.status::text AS job_status,
              j.status_version,j.fencing_token,j.created_at,j.available_at,
              j.lease_expires_at,j.delivery_hold_reason::text,
              o.id::text AS outbox_id,o.delivery_id::text,
              o.delivery_generation,o.delivery_state_version,
              o.redis_message_id::text,o.published_at,o.last_delivery_at,
              i.status::text AS inbox_status,
              (
                j.status='succeeded' AND j.outcome='verification_pending'
              ) AS effect_lane
            FROM public.runtime_jobs j
            JOIN public.agent_runs r
              ON r.id=j.run_id AND r.tenant_id=j.tenant_id
            JOIN public.support_tickets t
              ON t.id=r.ticket_id AND t.tenant_id=j.tenant_id
            CROSS JOIN LATERAL (
              SELECT CASE
                WHEN t.lifecycle<>'active' OR t.automation_mode<>'agent'
                  THEN t.status
                WHEN EXISTS (
                  SELECT 1 FROM public.conversation_turns active_turn
                  WHERE active_turn.tenant_id=j.tenant_id
                    AND active_turn.ticket_id=j.ticket_id
                    AND active_turn.activity_state IN ('queued','running')
                ) OR EXISTS (
                  SELECT 1 FROM public.runtime_jobs active_job
                  WHERE active_job.tenant_id=j.tenant_id
                    AND active_job.ticket_id=j.ticket_id
                    AND active_job.status IN ('queued','retry_wait','leased')
                ) THEN 'queued'
                WHEN EXISTS (
                  SELECT 1
                  FROM public.approval_requests active_approval
                  JOIN public.runtime_jobs effect_job
                    ON effect_job.tenant_id=active_approval.tenant_id
                   AND effect_job.ticket_id=active_approval.ticket_id
                   AND effect_job.approval_id=active_approval.id
                  WHERE active_approval.tenant_id=j.tenant_id
                    AND active_approval.ticket_id=j.ticket_id
                    AND active_approval.status='approved'
                    AND effect_job.status='succeeded'
                    AND effect_job.outcome='verification_pending'
                ) THEN 'verification_pending'
                WHEN EXISTS (
                  SELECT 1 FROM public.approval_requests active_approval
                  WHERE active_approval.tenant_id=j.tenant_id
                    AND active_approval.ticket_id=j.ticket_id
                    AND active_approval.status IN ('pending','approved')
                ) THEN 'awaiting_approval'
                WHEN j.status='dead' OR j.outcome IN (
                  'domain_terminal','verified_zero_effect'
                ) THEN 'failed'
                WHEN j.outcome='interrupted' THEN 'awaiting_approval'
                WHEN j.outcome IN ('completed','verification_executed')
                  THEN 'resolved'
                WHEN j.outcome='rejected' THEN 'rejected'
                WHEN j.outcome='manual_takeover' THEN 'manual_takeover'
                ELSE t.status
              END::text AS ticket_status
            ) projection
            LEFT JOIN LATERAL (
              SELECT x.* FROM public.outbox_events x
              WHERE x.job_id=j.id AND x.superseded_at IS NULL
              ORDER BY x.delivery_generation DESC LIMIT 1
            ) o ON true
            LEFT JOIN LATERAL (
              SELECT x.status FROM public.inbox_deliveries x
              WHERE x.delivery_id=o.delivery_id
              ORDER BY x.created_at DESC LIMIT 1
            ) i ON true
            WHERE (
              j.status IN ('queued','retry_wait')
              OR (j.status='leased' AND j.lease_expires_at<clock_timestamp())
              OR j.delivery_hold_reason='state_unknown'
              OR (
                j.status IN ('succeeded','dead') AND (
                  (
                    j.outcome='verification_pending'
                    AND j.available_at<=clock_timestamp()
                  )
                  OR j.lease_owner IS NOT NULL
                  OR j.lease_expires_at IS NOT NULL
                  OR j.delivery_hold_reason IS NOT NULL
                  OR r.active_job_id=j.id
                  OR EXISTS (
                    SELECT 1 FROM public.checkpoint_commit_markers m
                    WHERE m.job_id=j.id
                      AND m.status NOT IN ('finalized','aborted')
                  )
                  OR (
                    j.status='succeeded' AND j.outcome='interrupted'
                    AND (
                      r.status<>'interrupted'
                      OR t.status IS DISTINCT FROM projection.ticket_status
                    )
                  )
                  OR (
                    j.status='succeeded' AND j.outcome='completed'
                    AND (
                      r.status<>'completed'
                      OR t.status IS DISTINCT FROM projection.ticket_status
                    )
                  )
                  OR (
                    j.status='succeeded' AND j.outcome='rejected'
                    AND (
                      r.status<>'completed'
                      OR t.status IS DISTINCT FROM projection.ticket_status
                    )
                  )
                  OR (
                    j.status='succeeded' AND j.outcome='manual_takeover'
                    AND (
                      r.status<>'completed'
                      OR t.status IS DISTINCT FROM projection.ticket_status
                    )
                  )
                  OR (
                    j.status='succeeded' AND j.outcome='domain_terminal'
                    AND (
                      r.status<>'completed'
                      OR t.status IS DISTINCT FROM projection.ticket_status
                    )
                  )
                  OR (
                    j.status='dead'
                    AND (
                      r.status<>'failed'
                      OR t.status IS DISTINCT FROM projection.ticket_status
                    )
                  )
                )
              )
            )
          ),
          lane_presence AS (
            SELECT
              bool_or(effect_lane) AS has_effect,
              bool_or(NOT effect_lane) AS has_recovery
            FROM eligible
          ),
          ranked AS (
            SELECT e.*,
              row_number() OVER (
                PARTITION BY e.effect_lane
                ORDER BY e.available_at,e.created_at,e.job_id
              ) AS lane_rank
            FROM eligible e
          ),
          prioritized AS (
            SELECT r.*,
              CASE
                WHEN NOT p.has_effect OR NOT p.has_recovery THEN 0
                WHEN r.effect_lane AND r.lane_rank<=
                     greatest(1,p_batch_size/4) THEN 0
                WHEN NOT r.effect_lane AND r.lane_rank<=
                     p_batch_size-greatest(1,p_batch_size/4) THEN 0
                ELSE 1
              END AS spill_priority
            FROM ranked r CROSS JOIN lane_presence p
          )
          SELECT
            p.job_id,p.job_status,p.status_version,p.fencing_token,
            p.created_at,p.available_at,p.lease_expires_at,
            p.delivery_hold_reason,p.outbox_id,p.delivery_id,
            p.delivery_generation,p.delivery_state_version,
            p.redis_message_id,p.published_at,p.last_delivery_at,
            p.inbox_status
          FROM prioritized p
          ORDER BY p.spill_priority,p.available_at,p.created_at,p.job_id
          LIMIT p_batch_size;
        END
        $$;


ALTER FUNCTION public.supportguard_reconciler_candidates(p_batch_size integer) OWNER TO supportguard_owner;

--
-- Name: supportguard_reconciler_consume_v126_core(text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_reconciler_consume_v126_core(p_intent_id text, p_observation_text text, p_observation_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_intent public.reconcile_intents%ROWTYPE; v_job public.runtime_jobs%ROWTYPE;
                v_run public.agent_runs%ROWTYPE; v_outbox public.outbox_events%ROWTYPE;
                v_timing supportguard_control.runtime_timing_snapshots%ROWTYPE;
                v_observation jsonb; v_now timestamptz:=clock_timestamp(); v_inbox_hash text;
                v_computed_hash text; v_next_generation integer; v_next_outbox_id text;
                v_next_delivery_id text; v_reusable boolean; v_reason text;
                v_previous_inbox_status text;
        BEGIN
            IF session_user <> 'supportguard_reconciler' THEN
                RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='reconciler capability caller is not authorized';
            END IF;
            v_computed_hash:=encode(sha256(convert_to(p_observation_text,'UTF8')),'hex');
            IF v_computed_hash<>p_observation_hash THEN
                RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='redis observation hash mismatch';
            END IF;
            v_observation:=p_observation_text::jsonb;
            SELECT * INTO v_intent FROM public.reconcile_intents WHERE id=p_intent_id FOR UPDATE;
            IF v_intent.id IS NULL OR v_intent.status NOT IN ('prepared','observed') THEN RETURN 'stale'; END IF;
            IF v_observation->>'observation_nonce'<>v_intent.observation_nonce
               OR v_observation->>'intent_id'<>v_intent.id
               OR v_observation->>'job_id'<>v_intent.job_id
               OR v_observation->>'outbox_id'<>v_intent.outbox_id THEN
                RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='redis observation identity mismatch';
            END IF;
            SELECT * INTO v_run FROM public.agent_runs
             WHERE tenant_id=v_intent.tenant_id AND id=v_intent.run_id FOR UPDATE;
            SELECT * INTO v_job FROM public.runtime_jobs WHERE id=v_intent.job_id FOR UPDATE;
            SELECT * INTO v_outbox FROM public.outbox_events WHERE id=v_intent.outbox_id FOR UPDATE;
            SELECT encode(sha256(convert_to(coalesce(string_agg(
                i.id||'|'||i.status||'|'||coalesce(i.outcome,''),'|' ORDER BY i.id),''),'UTF8')),'hex')
             INTO v_inbox_hash FROM public.inbox_deliveries i WHERE i.delivery_id=v_outbox.delivery_id;
            IF v_job.status_version<>v_intent.prepared_job_version
               OR v_outbox.delivery_state_version<>v_intent.prepared_delivery_state_version
               OR v_inbox_hash<>v_intent.prepared_inbox_hash THEN
                UPDATE public.reconcile_intents SET status='conflicted',terminal_reason='state_drift',
                    updated_at=v_now WHERE id=v_intent.id;
                RETURN 'state_drift';
            END IF;
            INSERT INTO public.redis_delivery_observations(
                id,tenant_id,run_id,job_id,reconcile_intent_id,outbox_id,delivery_generation,
                observation_hash,observation,observed_at,created_at,updated_at
            ) VALUES (
                'redisobs_'||replace(gen_random_uuid()::text,'-',''),v_intent.tenant_id,
                v_intent.run_id,v_intent.job_id,v_intent.id,v_intent.outbox_id,
                v_intent.delivery_generation,p_observation_hash,v_observation,
                (v_observation->>'observed_at')::timestamptz,v_now,v_now
            ) ON CONFLICT(reconcile_intent_id,observation_hash) DO NOTHING;
            SELECT * INTO v_timing FROM supportguard_control.runtime_timing_snapshots
             WHERE timing_version=v_job.timing_version;
            IF v_observation->>'status'='unknown' THEN
                IF v_now<v_intent.expires_at AND v_job.attempt<v_timing.max_attempts
                   AND v_now-v_job.created_at<make_interval(secs=>v_timing.max_job_age_seconds) THEN
                    UPDATE public.runtime_jobs SET delivery_hold_reason='state_unknown',
                        delivery_hold_intent_id=v_intent.id,delivery_hold_since=coalesce(delivery_hold_since,v_now),
                        updated_at=v_now WHERE id=v_job.id;
                    UPDATE public.reconcile_intents SET status='observed',updated_at=v_now WHERE id=v_intent.id;
                    RETURN 'held_unknown';
                END IF;
                v_reason:='delivery_state_unknown_deadline';
            ELSIF v_observation->>'status'<>'known' THEN
                RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='redis observation status invalid';
            END IF;
            v_reusable:=v_reason IS NULL AND (
                v_outbox.published_at IS NULL OR (
                    coalesce((v_observation->>'delivery_present')::boolean,false)
                    AND NOT EXISTS (SELECT 1 FROM public.inbox_deliveries i
                        WHERE i.delivery_id=v_outbox.delivery_id AND i.status IN ('acked','rejected'))
                )
            );
            IF v_reusable THEN
                IF v_job.status='leased' AND v_job.lease_expires_at<v_now THEN
                    UPDATE public.agent_runs SET active_job_id=NULL,active_fencing_token=NULL,
                        status='queued',status_version=status_version+1,updated_at=v_now
                     WHERE id=v_run.id AND active_job_id=v_job.id
                       AND active_fencing_token=v_job.fencing_token;
                    UPDATE public.runtime_jobs SET status='queued',lease_owner=NULL,
                        lease_expires_at=NULL,heartbeat_at=NULL,status_version=status_version+1,
                        delivery_hold_reason=NULL,delivery_hold_intent_id=NULL,
                        delivery_hold_since=NULL,updated_at=v_now WHERE id=v_job.id;
                ELSE
                    UPDATE public.runtime_jobs SET delivery_hold_reason=NULL,
                        delivery_hold_intent_id=NULL,delivery_hold_since=NULL,updated_at=v_now
                     WHERE id=v_job.id;
                END IF;
                UPDATE public.reconcile_intents SET status='consumed',terminal_reason='delivery_reused',
                    updated_at=v_now WHERE id=v_intent.id;
                RETURN 'reused';
            END IF;
            v_next_generation:=v_outbox.delivery_generation+1;
            IF v_reason IS NULL AND (v_next_generation>v_timing.max_delivery_generation
               OR v_job.attempt>=v_timing.max_attempts
               OR v_now-v_job.created_at>=make_interval(secs=>v_timing.max_job_age_seconds)) THEN
                v_reason:=CASE WHEN v_next_generation>v_timing.max_delivery_generation
                    THEN 'delivery_generation_exhausted' WHEN v_job.attempt>=v_timing.max_attempts
                    THEN 'worker_retry_exhausted' ELSE 'job_max_age_exhausted' END;
            END IF;
            IF v_reason IS NOT NULL THEN
                UPDATE public.agent_runs SET status='failed',active_job_id=NULL,active_fencing_token=NULL,
                    status_version=status_version+1,error_code=v_reason,completed_at=v_now,updated_at=v_now
                 WHERE id=v_run.id;
                PERFORM set_config(
                  'app.dead_convergence_authorized','v1512',true
                );
                UPDATE public.runtime_jobs SET status='dead',terminal_at=v_now,last_error=v_reason,
                    lease_owner=NULL,lease_expires_at=NULL,heartbeat_at=NULL,
                    delivery_hold_reason=NULL,delivery_hold_intent_id=NULL,delivery_hold_since=NULL,
                    status_version=status_version+1,updated_at=v_now WHERE id=v_job.id;
                UPDATE public.support_tickets SET status='failed',version=version+1,
                    updated_at=v_now WHERE id=v_run.ticket_id;
                UPDATE public.approval_requests SET status='failed',
                    status_version=status_version+1,updated_at=v_now
                 WHERE id=v_job.approval_id AND status IN ('pending','approved');
                PERFORM public.supportguard_internal_activate_next_ticket_turn(
                  v_job.tenant_id,v_run.ticket_id,v_job.id
                );
                PERFORM public.supportguard_internal_converge_ticket_status(
                  v_job.tenant_id,v_run.ticket_id,'failed'
                );
                UPDATE public.checkpoint_commit_markers SET status='aborted',
                    status_version=status_version+1,updated_at=v_now WHERE job_id=v_job.id
                    AND status IN ('prepared','checkpoint_written');
                UPDATE public.reconcile_intents SET status='consumed',terminal_reason=v_reason,
                    updated_at=v_now WHERE id=v_intent.id;
                RETURN 'dead';
            END IF;
            v_next_outbox_id:='outbox_'||replace(gen_random_uuid()::text,'-','');
            v_next_delivery_id:='delivery_'||replace(gen_random_uuid()::text,'-','');
            UPDATE public.agent_runs SET active_job_id=NULL,active_fencing_token=NULL,
                status='queued',status_version=status_version+1,updated_at=v_now
             WHERE id=v_run.id AND active_job_id=v_job.id AND active_fencing_token=v_job.fencing_token;
            UPDATE public.runtime_jobs SET status='queued',available_at=v_now,lease_owner=NULL,
                lease_expires_at=NULL,heartbeat_at=NULL,delivery_hold_reason=NULL,
                delivery_hold_intent_id=NULL,delivery_hold_since=NULL,status_version=status_version+1,
                updated_at=v_now WHERE id=v_job.id;
            UPDATE public.outbox_events SET superseded_at=v_now,
                superseded_by_delivery_id=v_next_outbox_id,
                delivery_state_version=delivery_state_version+1,updated_at=v_now WHERE id=v_outbox.id;
            SELECT status INTO v_previous_inbox_status FROM public.inbox_deliveries
             WHERE delivery_id=v_outbox.delivery_id ORDER BY created_at DESC LIMIT 1;
            UPDATE public.inbox_deliveries SET status='rejected',outcome='superseded_by_redelivery',
                terminal_at=v_now,updated_at=v_now WHERE delivery_id=v_outbox.delivery_id
                AND status NOT IN ('acked','rejected');
            INSERT INTO public.outbox_events(
                id,delivery_id,tenant_id,job_id,run_id,delivery_generation,event_type,
                schema_version,payload,available_at,publish_attempts,delivery_state_version,
                created_at,updated_at
            ) VALUES (
                v_next_outbox_id,v_next_delivery_id,v_job.tenant_id,v_job.id,v_job.run_id,
                v_next_generation,'runtime_job_available','runtime-job.v1','{}'::jsonb,
                v_now,0,1,v_now,v_now
            );
            INSERT INTO public.queue_delivery_audits(
                id,tenant_id,job_id,delivery_id,redis_message_id,consumer_group,outcome,
                payload_hash,details,created_at,updated_at
            ) VALUES (
                'qaudit_'||replace(gen_random_uuid()::text,'-',''),v_job.tenant_id,v_job.id,
                v_outbox.delivery_id,coalesce(v_outbox.redis_message_id,'outbox:'||v_outbox.id),
                'reconciler','superseded_lost_or_expired',
                encode(sha256(convert_to(v_outbox.delivery_id,'UTF8')),'hex'),
                jsonb_build_object('outbox_id',v_outbox.id,'previous_status',
                    coalesce(v_previous_inbox_status,'missing'),
                    'delivery_generation',v_outbox.delivery_generation,
                    'next_generation',v_next_generation),v_now,v_now
            );
            UPDATE public.reconcile_intents SET status='consumed',terminal_reason='redelivered',
                updated_at=v_now WHERE id=v_intent.id;
            RETURN 'repaired';
        END $$;


ALTER FUNCTION public.supportguard_reconciler_consume_v126_core(p_intent_id text, p_observation_text text, p_observation_hash text) OWNER TO supportguard_owner;

--
-- Name: supportguard_reconciler_prepare(text, bigint, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_reconciler_prepare(p_job_id text, p_expected_job_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE
          v_job public.runtime_jobs%ROWTYPE;
          v_ticket public.support_tickets%ROWTYPE;
          v_result jsonb;
          v_resolution text;
        BEGIN
          IF session_user<>'supportguard_reconciler' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='reconciler capability caller is not authorized';
          END IF;
          IF p_reason NOT IN ('delivery_recovery','action_effect_reconciliation') THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='reconcile reason invalid';
          END IF;
          SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id;
          IF v_job.id IS NULL OR v_job.status_version<>p_expected_job_version THEN
            RETURN jsonb_build_object('result','stale');
          END IF;
          PERFORM set_config('app.tenant_id',v_job.tenant_id,true);
          IF p_reason='action_effect_reconciliation'
             AND NOT (
               v_job.status='succeeded'
               AND v_job.outcome='verification_pending'
               AND v_job.approval_id IS NOT NULL
             ) THEN
            RETURN jsonb_build_object('result','not_action_effect','job_id',v_job.id);
          END IF;
          SELECT * INTO v_ticket
          FROM public.support_tickets
          WHERE tenant_id=v_job.tenant_id AND id=v_job.ticket_id
          FOR UPDATE;
          SELECT * INTO v_job
          FROM public.runtime_jobs
          WHERE tenant_id=v_job.tenant_id AND id=p_job_id;
          IF v_ticket.id IS NULL OR v_job.status_version<>p_expected_job_version THEN
            RETURN jsonb_build_object('result','stale');
          END IF;
          v_result:=public.supportguard_reconciler_prepare_d049(
            p_job_id,p_expected_job_version,p_reason
          );
          IF v_result->>'result'='terminal_reconciled' THEN
            SELECT * INTO v_job
            FROM public.runtime_jobs
            WHERE tenant_id=v_job.tenant_id AND id=p_job_id
            FOR UPDATE;
            IF v_job.status_version=p_expected_job_version+1 THEN
              NULL;
            ELSIF v_job.status_version=p_expected_job_version THEN
              UPDATE public.runtime_jobs
              SET status_version=status_version+1,updated_at=clock_timestamp()
              WHERE tenant_id=v_job.tenant_id AND id=p_job_id
                AND status_version=p_expected_job_version
              RETURNING * INTO v_job;
              IF NOT FOUND THEN
                RAISE EXCEPTION USING ERRCODE='40001',
                  MESSAGE='terminal repair version changed before commit';
              END IF;
            ELSE
              RAISE EXCEPTION USING ERRCODE='40001',
                MESSAGE='terminal repair version changed before commit';
            END IF;
            IF p_reason='action_effect_reconciliation' THEN
              v_resolution:=CASE v_job.outcome
                WHEN 'verification_executed' THEN 'executed'
                WHEN 'verified_zero_effect' THEN 'confirmed_zero_effect'
                ELSE NULL
              END;
              IF v_resolution IS NULL THEN
                RAISE EXCEPTION USING ERRCODE='40001',
                  MESSAGE='terminal repair outcome changed before commit';
              END IF;
              RETURN jsonb_build_object(
                'result','terminal_reconciled','job_id',p_job_id,
                'resolution',v_resolution
              );
            END IF;
          ELSIF p_reason='action_effect_reconciliation'
                AND v_result->>'result'='verification_pending' THEN
            UPDATE public.runtime_jobs
            SET available_at=clock_timestamp()+interval '30 seconds',
                status_version=status_version+1,
                updated_at=clock_timestamp()
            WHERE tenant_id=v_job.tenant_id AND id=p_job_id
              AND status_version=p_expected_job_version
              AND status='succeeded' AND outcome='verification_pending'
            RETURNING * INTO v_job;
            IF NOT FOUND THEN
              RAISE EXCEPTION USING ERRCODE='40001',
                MESSAGE='verification retry schedule changed before commit';
            END IF;
            RETURN jsonb_build_object(
              'result','verification_pending','job_id',p_job_id,
              'next_due_at',v_job.available_at
            );
          END IF;
          RETURN v_result;
        END
        $$;


ALTER FUNCTION public.supportguard_reconciler_prepare(p_job_id text, p_expected_job_version bigint, p_reason text) OWNER TO supportguard_owner;

--
-- Name: supportguard_reconciler_prepare_d047(text, bigint, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_reconciler_prepare_d047(p_job_id text, p_expected_job_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_job public.runtime_jobs%ROWTYPE;
                v_run public.agent_runs%ROWTYPE;
                v_ticket public.support_tickets%ROWTYPE;
                v_outbox public.outbox_events%ROWTYPE;
                v_approval public.approval_requests%ROWTYPE;
                v_proposal public.proposal_records%ROWTYPE;
                v_turn public.conversation_turns%ROWTYPE;
                v_marker public.checkpoint_commit_markers%ROWTYPE;
                v_payload public.finalizer_payloads%ROWTYPE;
                v_decision text;
                v_result jsonb;
                v_payload_text text;
                v_expected_hash text;
                v_target_run text;
                v_target_ticket text;
                v_target_approval text;
                v_terminal_reason text;
                v_effect_state text;
                v_variant text;
                v_now timestamptz:=clock_timestamp();
        BEGIN
          IF session_user<>'supportguard_reconciler' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='reconciler capability caller is not authorized';
          END IF;
          IF p_reason NOT IN ('delivery_recovery','action_effect_reconciliation') THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='reconcile reason invalid';
          END IF;
          SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id;
          IF v_job.id IS NULL OR v_job.status_version<>p_expected_job_version THEN
            RETURN jsonb_build_object('result','stale');
          END IF;
          PERFORM set_config('app.tenant_id',v_job.tenant_id,true);
          SELECT t.* INTO v_ticket
          FROM public.support_tickets t
          JOIN public.agent_runs r
            ON r.tenant_id=t.tenant_id AND r.ticket_id=t.id
          WHERE r.tenant_id=v_job.tenant_id AND r.id=v_job.run_id
          FOR UPDATE OF t;
          SELECT * INTO v_marker FROM public.checkpoint_commit_markers m
          WHERE m.tenant_id=v_job.tenant_id AND m.run_id=v_job.run_id
            AND m.job_id=v_job.id
          ORDER BY m.fencing_token DESC,m.created_at DESC,m.id DESC LIMIT 1;
          IF v_job.approval_id IS NOT NULL THEN
            SELECT * INTO v_approval FROM public.approval_requests
            WHERE tenant_id=v_job.tenant_id AND id=v_job.approval_id
              AND run_id=v_job.run_id AND ticket_id=v_job.ticket_id FOR UPDATE;
          ELSIF v_job.outcome='interrupted' AND v_marker.id IS NOT NULL THEN
            SELECT * INTO v_approval FROM public.approval_requests
            WHERE tenant_id=v_job.tenant_id AND run_id=v_job.run_id
              AND marker_id=v_marker.id AND status='pending'
            ORDER BY created_at,id LIMIT 1 FOR UPDATE;
          END IF;
          IF v_approval.id IS NOT NULL THEN
            SELECT * INTO v_proposal FROM public.proposal_records
            WHERE tenant_id=v_approval.tenant_id
              AND id=v_approval.proposal_id FOR UPDATE;
          END IF;
          SELECT * INTO v_run FROM public.agent_runs
          WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id FOR UPDATE;
          IF v_run.turn_id IS NOT NULL THEN
            SELECT * INTO v_turn FROM public.conversation_turns
            WHERE tenant_id=v_job.tenant_id AND id=v_run.turn_id FOR UPDATE;
          END IF;
          SELECT * INTO v_job FROM public.runtime_jobs
          WHERE tenant_id=v_job.tenant_id AND id=p_job_id FOR UPDATE;
          IF v_ticket.id IS NULL OR v_run.id IS NULL
             OR v_run.ticket_id IS DISTINCT FROM v_job.ticket_id
             OR (v_job.kind='approval_resume' AND v_approval.id IS NULL)
             OR v_job.status_version<>p_expected_job_version THEN
            RETURN jsonb_build_object('result','stale');
          END IF;
          IF v_job.status IN ('succeeded','dead') THEN
            SELECT * INTO v_run FROM public.agent_runs
             WHERE id=v_job.run_id AND tenant_id=v_job.tenant_id FOR UPDATE;
            SELECT * INTO v_ticket FROM public.support_tickets
             WHERE id=v_run.ticket_id AND tenant_id=v_job.tenant_id FOR UPDATE;

            -- Locate the candidate marker without locking it so Approval remains
            -- ahead of Marker in the global lock order.
            SELECT * INTO v_marker FROM public.checkpoint_commit_markers m
             WHERE m.tenant_id=v_job.tenant_id AND m.run_id=v_job.run_id
               AND m.job_id=v_job.id
             ORDER BY m.fencing_token DESC,m.created_at DESC,m.id DESC LIMIT 1;
            IF v_job.approval_id IS NOT NULL THEN
              SELECT * INTO v_approval FROM public.approval_requests
               WHERE id=v_job.approval_id AND tenant_id=v_job.tenant_id FOR UPDATE;
            ELSIF v_job.outcome='interrupted' THEN
              SELECT * INTO v_approval FROM public.approval_requests
               WHERE tenant_id=v_job.tenant_id AND run_id=v_job.run_id
                 AND marker_id=v_marker.id AND status='pending'
               ORDER BY created_at,id LIMIT 1 FOR UPDATE;
              IF (SELECT count(*) FROM public.approval_requests
                   WHERE tenant_id=v_job.tenant_id AND run_id=v_job.run_id
                     AND marker_id=v_marker.id AND status='pending')<>1 THEN
                RETURN jsonb_build_object('result','terminal_outcome_unrecognized');
              END IF;
            END IF;
            IF v_marker.id IS NOT NULL THEN
              SELECT * INTO v_marker FROM public.checkpoint_commit_markers
               WHERE id=v_marker.id FOR UPDATE;
              SELECT * INTO v_payload FROM public.finalizer_payloads
               WHERE tenant_id=v_job.tenant_id AND run_id=v_job.run_id
                 AND job_id=v_job.id AND marker_id=v_marker.id;
            END IF;
            IF v_approval.id IS NOT NULL THEN
              SELECT decision INTO v_decision FROM public.human_decisions
               WHERE approval_id=v_approval.id AND tenant_id=v_job.tenant_id;
            END IF;
            SELECT * INTO v_outbox FROM public.outbox_events
             WHERE job_id=v_job.id AND superseded_at IS NULL
             ORDER BY delivery_generation DESC LIMIT 1 FOR UPDATE;

            IF v_job.status='dead' AND v_job.outcome='infrastructure_exhausted' THEN
              v_target_run:='failed'; v_target_ticket:='failed';
              v_target_approval:='failed';
              v_terminal_reason:=coalesce(v_job.last_error,'infrastructure_exhausted');
            ELSE
              IF v_marker.id IS NULL OR v_marker.segment_kind<>v_job.kind
                 OR v_marker.status<>'finalized' THEN
                RETURN jsonb_build_object('result','terminal_outcome_unrecognized');
              END IF;
              IF v_job.outcome<>'domain_terminal' THEN
                IF v_payload.id IS NULL OR v_payload.schema_version<>'finalizer.v2'
                   OR v_payload.fencing_token<>v_marker.fencing_token
                   OR v_payload.payload->>'tenant_id'<>v_job.tenant_id
                   OR v_payload.payload->>'run_id'<>v_job.run_id
                   OR v_payload.payload->>'job_id'<>v_job.id
                   OR v_payload.payload->>'marker_id'<>v_marker.id
                   OR v_payload.payload->>'segment_kind'<>v_marker.segment_kind THEN
                  RETURN jsonb_build_object('result','terminal_outcome_unrecognized');
                END IF;
              END IF;
              v_variant:=v_payload.domain_delta->>'variant';
              IF v_job.outcome='interrupted' AND v_marker.segment_kind='agent_start'
                 AND v_variant='hitl_interrupt'
                 AND v_payload.domain_delta->>'outcome'='interrupted'
                 AND v_approval.id IS NOT NULL AND v_approval.status='pending'
                 AND v_approval.marker_id=v_marker.id THEN
                v_target_run:='interrupted'; v_target_ticket:='awaiting_approval';
                v_target_approval:='pending'; v_terminal_reason:='interrupted';
              ELSIF v_job.outcome='completed' AND v_marker.segment_kind='agent_start'
                 AND v_variant='agent_complete'
                 AND v_payload.domain_delta->>'outcome'='completed'
                 AND v_payload.state_delta #>> '{state,final,terminal_state}'
                     IN ('resolved','needs_clarification','manual_takeover')
                 AND NOT EXISTS (
                   SELECT 1 FROM public.approval_requests a
                    WHERE a.tenant_id=v_job.tenant_id AND a.run_id=v_job.run_id
                      AND a.status IN ('pending','approved')
                 )
                 AND EXISTS (
                   SELECT 1 FROM public.agent_events e
                    WHERE e.tenant_id=v_job.tenant_id AND e.run_id=v_job.run_id
                      AND e.ticket_id=v_run.ticket_id
                      AND e.event_type='final_outcome' AND e.visibility='customer'
                      AND e.payload->>'terminal_state'=
                          v_payload.state_delta #>> '{state,final,terminal_state}'
                 ) THEN
                v_target_run:='completed';
                v_target_ticket:=v_payload.state_delta #>> '{state,final,terminal_state}';
                v_terminal_reason:=coalesce(v_run.agent_finish_reason,v_target_ticket);
              ELSIF v_job.outcome='completed' AND v_marker.segment_kind='approval_resume'
                 AND (
                   (
                     v_variant='approval_actionful'
                     AND v_payload.domain_delta->>'outcome'='completed'
                     AND v_decision IN ('approve','edit_and_approve')
                     AND v_decision=v_payload.domain_delta->>'decision'
                     AND v_payload.domain_delta->>'approval_id'=v_approval.id
                     AND EXISTS (
                       SELECT 1 FROM public.business_actions b
                        WHERE b.tenant_id=v_job.tenant_id
                          AND b.id=v_payload.domain_delta->>'business_action_id'
                          AND b.approval_id=v_approval.id
                          AND b.human_decision_id=v_payload.domain_delta->>'human_decision_id'
                     )
                   )
                   OR public.supportguard_internal_action_intent_executed_receipt(
                     v_job.tenant_id,v_job.id,v_job.run_id,
                     v_payload.domain_delta::jsonb
                   )
                 ) THEN
                v_target_run:='completed'; v_target_ticket:='resolved';
                v_target_approval:='executed'; v_terminal_reason:='completed';
              ELSIF v_job.outcome='rejected' AND v_marker.segment_kind='approval_resume'
                 AND v_variant='approval_no_action'
                 AND v_payload.domain_delta->>'outcome'='completed'
                 AND v_decision='reject' AND v_payload.domain_delta->>'decision'='reject'
                 AND v_payload.domain_delta->>'approval_id'=v_approval.id THEN
                v_target_run:='completed'; v_target_ticket:='rejected';
                v_target_approval:='rejected'; v_terminal_reason:='rejected';
              ELSIF v_job.outcome='manual_takeover'
                 AND v_marker.segment_kind='approval_resume'
                 AND v_variant='approval_no_action'
                 AND v_payload.domain_delta->>'outcome'='completed'
                 AND v_decision='manual_takeover'
                 AND v_payload.domain_delta->>'decision'='manual_takeover'
                 AND v_payload.domain_delta->>'approval_id'=v_approval.id THEN
                v_target_run:='completed'; v_target_ticket:='manual_takeover';
                v_target_approval:='manual_takeover'; v_terminal_reason:='manual_takeover';
              ELSIF v_job.outcome='verification_pending'
                 AND v_marker.segment_kind='approval_resume'
                 AND v_variant IN (
                   'approval_fail_closed','approval_action_intent'
                 )
                 AND v_approval.status='approved'
                 AND v_payload.domain_delta->>'approval_id'=v_approval.id THEN
                v_effect_state:=public.supportguard_internal_classify_action_effect(
                  v_job.tenant_id,v_approval.id
                );
                IF v_effect_state='executed' THEN
                  v_target_run:='completed'; v_target_ticket:='resolved';
                  v_target_approval:='executed';
                  v_terminal_reason:='verification_executed';
                ELSIF v_effect_state='confirmed_zero_effect' THEN
                  v_target_run:='completed'; v_target_ticket:='failed';
                  v_target_approval:='failed';
                  v_terminal_reason:='verified_zero_effect';
                ELSE
                  RETURN jsonb_build_object('result','verification_pending');
                END IF;
              ELSIF v_job.outcome='verification_pending' THEN
                RETURN jsonb_build_object('result','verification_pending');
              ELSIF v_job.outcome='domain_terminal'
                 AND v_run.agent_finish_reason IN ('binding_stale','logical_degradation')
                 AND (
                   (v_payload.id IS NOT NULL AND (
                     v_variant='approval_fail_closed'
                     OR public.supportguard_internal_action_intent_stale_receipt(
                       v_job.tenant_id,v_job.id,v_job.run_id,
                       v_payload.domain_delta::jsonb
                     )
                   ))
                   OR (v_payload.id IS NULL AND v_marker.segment_outcome='domain_terminal')
                 ) THEN
                v_target_run:='completed'; v_target_ticket:='failed';
                v_target_approval:=CASE WHEN v_run.agent_finish_reason='binding_stale'
                  AND v_approval.status IN ('pending','approved') THEN 'stale' ELSE NULL END;
                v_terminal_reason:=v_run.agent_finish_reason;
              ELSE
                RETURN jsonb_build_object('result','terminal_outcome_unrecognized');
              END IF;
            END IF;

            UPDATE public.runtime_jobs SET lease_owner=NULL,lease_expires_at=NULL,
                heartbeat_at=NULL,delivery_hold_reason=NULL,delivery_hold_intent_id=NULL,
                delivery_hold_since=NULL,
                outcome=CASE
                  WHEN status='dead' THEN 'infrastructure_exhausted'
                  WHEN outcome='verification_pending'
                    AND v_terminal_reason='verification_executed'
                    THEN 'verification_executed'
                  WHEN outcome='verification_pending'
                    AND v_terminal_reason='verified_zero_effect'
                    THEN 'verified_zero_effect'
                  ELSE outcome
                END,
                terminal_at=coalesce(terminal_at,v_now),updated_at=v_now WHERE id=v_job.id;
            UPDATE public.agent_runs SET status=v_target_run,active_job_id=NULL,
                active_fencing_token=NULL,error_code=CASE WHEN v_target_run='failed'
                  THEN v_terminal_reason ELSE error_code END,
                completed_at=CASE WHEN v_target_run IN ('completed','failed')
                  THEN coalesce(completed_at,v_now) ELSE completed_at END,
                updated_at=v_now WHERE id=v_run.id;
            UPDATE public.support_tickets SET status=v_target_ticket,version=version+1,
                updated_at=v_now WHERE id=v_ticket.id
                AND status IS DISTINCT FROM v_target_ticket;
            IF v_target_approval IS NOT NULL AND v_target_approval<>'pending' THEN
              UPDATE public.approval_requests SET status=v_target_approval,
                  status_version=status_version+1,updated_at=v_now
               WHERE id=v_approval.id
                 AND (v_target_approval<>'failed' OR status IN ('pending','approved'))
                 AND status IS DISTINCT FROM v_target_approval;
              IF v_proposal.id IS NOT NULL
                 AND v_proposal.status IN ('draft','bound') THEN
                UPDATE public.proposal_records SET status='stale',
                    status_version=status_version+1,updated_at=v_now
                 WHERE tenant_id=v_proposal.tenant_id AND id=v_proposal.id;
              END IF;
            END IF;
            IF v_terminal_reason='verified_zero_effect' THEN
              PERFORM public.supportguard_internal_publish_verified_zero_effect_event(
                v_job.tenant_id,v_ticket.id,v_run.id,v_approval.id,v_job.id
              );
            END IF;
            PERFORM public.supportguard_internal_activate_next_ticket_turn(
              v_job.tenant_id,v_ticket.id,v_job.id
            );
            v_target_ticket:=public.supportguard_internal_converge_ticket_status(
              v_job.tenant_id,v_ticket.id,v_target_ticket
            );
            UPDATE public.checkpoint_commit_markers SET
                status=CASE WHEN v_job.status='dead' THEN 'aborted' ELSE 'finalized' END,
                status_version=status_version+1,updated_at=v_now
             WHERE job_id=v_job.id AND status NOT IN ('finalized','aborted');
            UPDATE public.inbox_deliveries SET status='acked',
                outcome='terminal_aggregate_reconciled',
                terminal_at=coalesce(terminal_at,v_now),updated_at=v_now
             WHERE job_id=v_job.id AND status IN ('received','claimed');
            IF v_outbox.id IS NOT NULL THEN
              INSERT INTO public.queue_delivery_audits(
                id,tenant_id,job_id,delivery_id,redis_message_id,consumer_group,outcome,
                payload_hash,details,created_at,updated_at
              ) VALUES (
                'qaudit_terminal_'||substr(md5(v_job.id||':'||coalesce(v_job.outcome,'')),1,32),
                v_job.tenant_id,v_job.id,v_outbox.delivery_id,
                coalesce(v_outbox.redis_message_id,'outbox:'||v_outbox.id),'reconciler',
                'terminal_aggregate_reconciled',
                encode(sha256(convert_to(v_job.id||':'||coalesce(v_job.outcome,''),'UTF8')),'hex'),
                jsonb_build_object('run_status',v_target_run,'ticket_status',v_target_ticket,
                  'terminal_reason',v_terminal_reason),v_now,v_now
              ) ON CONFLICT(id) DO NOTHING;
            END IF;
            RETURN jsonb_build_object('result','terminal_reconciled','job_id',v_job.id,
              'run_status',v_target_run,'ticket_status',v_target_ticket);
          END IF;

          SELECT * INTO v_outbox FROM public.outbox_events
           WHERE job_id=v_job.id AND superseded_at IS NULL
           ORDER BY delivery_generation DESC LIMIT 1 FOR UPDATE;
          v_result:=public.supportguard_reconciler_prepare_v126_core(
            v_job.id,v_job.fencing_token,v_outbox.id
          );
          IF v_result->>'result'<>'prepared' THEN RETURN v_result; END IF;
          v_payload_text:='{"schema_version":"runtime-job.v1","event_id":'||
            to_jsonb(v_outbox.id)::text||',"delivery_id":'||
            to_jsonb(v_outbox.delivery_id)::text||',"job_id":'||
            to_jsonb(v_job.id)::text||',"run_id":'||to_jsonb(v_job.run_id)::text||
            ',"tenant_id":'||to_jsonb(v_job.tenant_id)::text||
            ',"delivery_generation":'||v_outbox.delivery_generation::text||
            ',"traceparent":'||coalesce(to_jsonb(v_outbox.payload->>'traceparent')::text,'null')||'}';
          v_expected_hash:=encode(sha256(convert_to(v_payload_text,'UTF8')),'hex');
          UPDATE public.reconcile_intents SET expected_stream_payload_hash=v_expected_hash,
              updated_at=v_now WHERE id=v_result->>'intent_id'
              AND expected_stream_payload_hash IS DISTINCT FROM v_expected_hash;
          RETURN v_result||jsonb_build_object('expected_stream_payload_hash',v_expected_hash);
        END $$;


ALTER FUNCTION public.supportguard_reconciler_prepare_d047(p_job_id text, p_expected_job_version bigint, p_reason text) OWNER TO supportguard_owner;

--
-- Name: supportguard_reconciler_prepare_d049(text, bigint, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_reconciler_prepare_d049(p_job_id text, p_expected_job_version bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_job public.runtime_jobs%ROWTYPE;
                v_run public.agent_runs%ROWTYPE;
                v_marker public.checkpoint_commit_markers%ROWTYPE;
                v_payload public.finalizer_payloads%ROWTYPE;
                v_reason text;
        BEGIN
          IF session_user<>'supportguard_reconciler' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='reconciler capability caller is not authorized';
          END IF;
          SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id FOR UPDATE;
          IF v_job.id IS NULL OR v_job.status_version<>p_expected_job_version THEN
            RETURN jsonb_build_object('result','stale');
          END IF;
          PERFORM set_config('app.tenant_id',v_job.tenant_id,true);
          IF v_job.status='succeeded' AND v_job.outcome='domain_terminal' THEN
            SELECT * INTO v_run FROM public.agent_runs
             WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id;
            SELECT * INTO v_marker FROM public.checkpoint_commit_markers m
             WHERE m.tenant_id=v_job.tenant_id AND m.run_id=v_job.run_id
               AND m.job_id=v_job.id
             ORDER BY m.fencing_token DESC,m.created_at DESC,m.id DESC LIMIT 1;
            SELECT * INTO v_payload FROM public.finalizer_payloads f
             WHERE f.tenant_id=v_job.tenant_id AND f.run_id=v_job.run_id
               AND f.job_id=v_job.id AND f.marker_id=v_marker.id;
            v_reason:=v_payload.domain_delta->>'domain_outcome_reason';
            IF v_marker.id IS NULL OR v_marker.status<>'finalized'
               OR v_payload.id IS NULL OR v_payload.schema_version<>'finalizer.v2'
               OR v_payload.fencing_token<>v_marker.fencing_token
               OR v_payload.payload->>'tenant_id'<>v_job.tenant_id
               OR v_payload.payload->>'run_id'<>v_job.run_id
               OR v_payload.payload->>'job_id'<>v_job.id
               OR v_payload.payload->>'marker_id'<>v_marker.id
               OR v_payload.payload->>'segment_kind'<>v_marker.segment_kind
               OR NOT (
                 (
                   v_payload.domain_delta->>'variant'='approval_fail_closed'
                   AND v_reason IN ('binding_stale','logical_degradation')
                   AND v_reason IS NOT DISTINCT FROM v_run.agent_finish_reason
                 )
                 OR (
                   v_run.agent_finish_reason='binding_stale'
                   AND public.supportguard_internal_action_intent_stale_receipt(
                     v_job.tenant_id,v_job.id,v_job.run_id,
                     v_payload.domain_delta::jsonb
                   )
                 )
               ) THEN
              RETURN jsonb_build_object('result','terminal_outcome_unrecognized');
            END IF;
          END IF;
          RETURN public.supportguard_reconciler_prepare_d047(
            p_job_id,p_expected_job_version,p_reason
          );
        END $$;


ALTER FUNCTION public.supportguard_reconciler_prepare_d049(p_job_id text, p_expected_job_version bigint, p_reason text) OWNER TO supportguard_owner;

--
-- Name: supportguard_reconciler_prepare_v126_core(text, bigint, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_reconciler_prepare_v126_core(p_job_id text, p_expected_fence bigint, p_expected_outbox_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_job public.runtime_jobs%ROWTYPE; v_outbox public.outbox_events%ROWTYPE;
                v_intent public.reconcile_intents%ROWTYPE; v_inbox_hash text;
                v_payload_hash text; v_now timestamptz:=clock_timestamp(); v_sequence bigint;
                v_timing supportguard_control.runtime_timing_snapshots%ROWTYPE;
        BEGIN
            IF session_user <> 'supportguard_reconciler' THEN
                RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='reconciler capability caller is not authorized';
            END IF;
            SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id FOR UPDATE;
            IF v_job.id IS NULL OR v_job.fencing_token<>p_expected_fence
               OR v_job.status NOT IN ('queued','retry_wait','leased') THEN
                RETURN jsonb_build_object('result','stale');
            END IF;
            SELECT * INTO v_outbox FROM public.outbox_events WHERE job_id=v_job.id
             AND superseded_at IS NULL ORDER BY delivery_generation DESC LIMIT 1 FOR UPDATE;
            IF coalesce(v_outbox.id,'')<>coalesce(p_expected_outbox_id,'') THEN
                RETURN jsonb_build_object('result','stale');
            END IF;
            IF v_outbox.id IS NULL THEN
                RETURN jsonb_build_object('result','missing_outbox');
            END IF;
            SELECT * INTO v_timing FROM supportguard_control.runtime_timing_snapshots
             WHERE timing_version=v_job.timing_version;
            SELECT encode(sha256(convert_to(coalesce(string_agg(
                i.id||'|'||i.status||'|'||coalesce(i.outcome,''),'|' ORDER BY i.id),''),'UTF8')),'hex')
             INTO v_inbox_hash FROM public.inbox_deliveries i
             WHERE i.delivery_id=v_outbox.delivery_id;
            v_payload_hash:=encode(sha256(convert_to(
                v_job.id||'|'||v_job.status_version||'|'||v_job.fencing_token||'|'||
                v_outbox.id||'|'||v_outbox.delivery_state_version,'UTF8')),'hex');
            UPDATE public.reconcile_intents SET status='conflicted',terminal_reason='state_drift',
                updated_at=v_now WHERE job_id=v_job.id AND status IN ('prepared','observed')
                AND (prepared_job_version<>v_job.status_version
                  OR prepared_delivery_state_version<>v_outbox.delivery_state_version
                  OR prepared_inbox_hash<>v_inbox_hash);
            SELECT * INTO v_intent FROM public.reconcile_intents
             WHERE job_id=v_job.id AND delivery_generation=v_outbox.delivery_generation
               AND reason='delivery_recovery' AND status IN ('prepared','observed') FOR UPDATE;
            IF v_intent.id IS NULL THEN
                SELECT coalesce(max(intent_sequence),0)+1 INTO v_sequence
                 FROM public.reconcile_intents WHERE job_id=v_job.id
                   AND delivery_generation=v_outbox.delivery_generation
                   AND reason='delivery_recovery';
                INSERT INTO public.reconcile_intents(
                    id,tenant_id,run_id,job_id,outbox_id,delivery_generation,intent_sequence,
                    reason,status,prepared_job_version,prepared_delivery_state_version,
                    prepared_inbox_hash,prepared_payload_hash,observation_nonce,expires_at,
                    created_at,updated_at
                ) VALUES (
                    'rintent_'||replace(gen_random_uuid()::text,'-',''),v_job.tenant_id,v_job.run_id,
                    v_job.id,v_outbox.id,v_outbox.delivery_generation,v_sequence,
                    'delivery_recovery','prepared',v_job.status_version,
                    v_outbox.delivery_state_version,v_inbox_hash,v_payload_hash,
                    replace(gen_random_uuid()::text,'-',''),
                    v_now+make_interval(secs=>v_timing.redelivery_grace_seconds),v_now,v_now
                ) RETURNING * INTO v_intent;
            END IF;
            RETURN jsonb_build_object('result','prepared','intent_id',v_intent.id,
                'intent_sequence',v_intent.intent_sequence,'observation_nonce',v_intent.observation_nonce,
                'stream_message_id',v_outbox.redis_message_id,'delivery_id',v_outbox.delivery_id,
                'job_id',v_job.id,'run_id',v_job.run_id,'tenant_id',v_job.tenant_id,
                'outbox_id',v_outbox.id,'delivery_generation',v_outbox.delivery_generation,
                'expires_at',v_intent.expires_at,'prepared_payload_hash',v_intent.prepared_payload_hash);
        END $$;


ALTER FUNCTION public.supportguard_reconciler_prepare_v126_core(p_job_id text, p_expected_fence bigint, p_expected_outbox_id text) OWNER TO supportguard_owner;

--
-- Name: supportguard_reconciler_repair(text, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_reconciler_repair(p_job_id text, p_expected_job_version bigint, p_intent_id text, p_observation jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_result text; v_expired_lease boolean:=false;
                v_job public.runtime_jobs%ROWTYPE; v_outbox public.outbox_events%ROWTYPE;
                v_ticket public.support_tickets%ROWTYPE;
                v_ticket_id text;
        BEGIN
          IF session_user<>'supportguard_reconciler' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='reconciler capability caller is not authorized';
          END IF;
          SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id;
          IF v_job.id IS NULL THEN RETURN 'state_drift'; END IF;
          PERFORM set_config('app.tenant_id',v_job.tenant_id,true);
          SELECT * INTO v_ticket FROM public.support_tickets
           WHERE tenant_id=v_job.tenant_id AND id=v_job.ticket_id FOR UPDATE;
          SELECT * INTO v_job FROM public.runtime_jobs
           WHERE tenant_id=v_job.tenant_id AND id=p_job_id FOR UPDATE;
          IF v_ticket.id IS NULL OR v_job.status_version<>p_expected_job_version THEN
            RETURN 'state_drift';
          END IF;
          v_expired_lease:=v_job.status='leased'
            AND v_job.lease_expires_at IS NOT NULL
            AND v_job.lease_expires_at<clock_timestamp();
          SELECT * INTO v_outbox FROM public.outbox_events
           WHERE job_id=p_job_id AND superseded_at IS NULL
           ORDER BY delivery_generation DESC LIMIT 1 FOR UPDATE;
          v_result:=public.supportguard_reconciler_repair_d067(
            p_job_id,p_expected_job_version,p_intent_id,p_observation
          );
          IF v_result='reused' AND v_expired_lease THEN
            SELECT ticket_id INTO v_ticket_id FROM public.agent_runs WHERE id=v_job.run_id;
            UPDATE public.support_tickets SET status='queued',version=version+1,
                updated_at=clock_timestamp()
             WHERE id=v_ticket_id AND status<>'queued';
            UPDATE public.checkpoint_commit_markers SET status='aborted',
                status_version=status_version+1,updated_at=clock_timestamp()
             WHERE job_id=p_job_id AND status='prepared';
            INSERT INTO public.queue_delivery_audits(
                id,tenant_id,job_id,delivery_id,redis_message_id,consumer_group,outcome,
                payload_hash,details,created_at,updated_at
            ) VALUES (
                'qaudit_expired_'||left(encode(sha256(convert_to(p_intent_id,'UTF8')),'hex'),47),
                v_job.tenant_id,v_job.id,v_outbox.delivery_id,
                coalesce(v_outbox.redis_message_id,'outbox:'||v_outbox.id),'reconciler',
                'delivery_reused',
                encode(sha256(convert_to(v_outbox.delivery_id,'UTF8')),'hex'),
                jsonb_build_object('intent_id',p_intent_id,'reason','expired_lease_reused',
                  'delivery_generation',v_outbox.delivery_generation),
                clock_timestamp(),clock_timestamp()
            ) ON CONFLICT(id) DO NOTHING;
          END IF;
          RETURN v_result;
        END $$;


ALTER FUNCTION public.supportguard_reconciler_repair(p_job_id text, p_expected_job_version bigint, p_intent_id text, p_observation jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_reconciler_repair_d066(text, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_reconciler_repair_d066(p_job_id text, p_expected_job_version bigint, p_intent_id text, p_observation jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $_$
        DECLARE v_job public.runtime_jobs%ROWTYPE;
                v_intent public.reconcile_intents%ROWTYPE;
                v_outbox public.outbox_events%ROWTYPE;
                v_inbox_status text;
                v_inbox_count bigint;
                v_keys text[];
                v_status text;
                v_hash text;
                v_normalized jsonb;
                v_matrix_known boolean:=false;
                v_known_keys constant text[]:=ARRAY[
                  'connection_generation_after','connection_generation_before',
                  'delivery_generation','delivery_present','endpoint_fingerprint_after',
                  'endpoint_fingerprint_before','intent_id','job_id','lua_observation_nonce',
                  'observation_nonce','observed_at','outbox_id','pending_groups',
                  'redis_client_id_after','redis_client_id_before','redis_principal_after',
                  'redis_principal_before','registered_groups','runner_nonce','schema_version',
                  'status','stream_payload_hash'
                ];
                v_unknown_keys constant text[]:=ARRAY[
                  'delivery_generation','error_code','intent_id','job_id','observation_nonce',
                  'observed_at','outbox_id','runner_nonce','schema_version','status'
                ];
        BEGIN
          IF session_user<>'supportguard_reconciler' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='reconciler capability caller is not authorized';
          END IF;
          SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id FOR UPDATE;
          SELECT * INTO v_intent FROM public.reconcile_intents WHERE id=p_intent_id FOR UPDATE;
          SELECT * INTO v_outbox FROM public.outbox_events WHERE id=v_intent.outbox_id FOR UPDATE;
          IF v_job.id IS NULL OR v_intent.id IS NULL OR v_outbox.id IS NULL
             OR v_intent.job_id<>v_job.id OR v_job.status_version<>p_expected_job_version THEN
            IF v_intent.id IS NOT NULL AND v_intent.status IN ('prepared','observed') THEN
              UPDATE public.reconcile_intents SET status='conflicted',
                terminal_reason='state_drift',updated_at=clock_timestamp()
               WHERE id=v_intent.id;
            END IF;
            RETURN 'state_drift';
          END IF;
          IF p_observation->>'schema_version'<>'redis-delivery-observation.v1'
             OR p_observation->>'job_id'<>v_job.id
             OR p_observation->>'intent_id'<>v_intent.id
             OR p_observation->>'outbox_id'<>v_intent.outbox_id
             OR (p_observation->>'delivery_generation')::integer<>v_intent.delivery_generation
             OR p_observation->>'observation_nonce'<>v_intent.observation_nonce
             OR coalesce(p_observation->>'runner_nonce','')!~'^[0-9a-f]{32}$'
             OR (p_observation->>'observed_at')::timestamptz IS NULL
             OR (p_observation->>'observed_at')::timestamptz>
                  clock_timestamp()+interval '5 seconds' THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='redis observation identity invalid';
          END IF;
          SELECT array_agg(key ORDER BY key) INTO v_keys FROM jsonb_object_keys(p_observation) key;
          v_status:=p_observation->>'status';
          IF v_status='known' THEN
            IF v_keys<>v_known_keys
               OR jsonb_typeof(p_observation->'delivery_present')<>'boolean'
               OR jsonb_typeof(p_observation->'pending_groups')<>'array'
               OR jsonb_typeof(p_observation->'registered_groups')<>'array'
               OR p_observation->>'redis_client_id_before'<>
                    p_observation->>'redis_client_id_after'
               OR p_observation->>'redis_principal_before'<>'reconciler'
               OR p_observation->>'redis_principal_after'<>'reconciler'
               OR p_observation->>'connection_generation_before'<>
                    p_observation->>'connection_generation_after'
               OR p_observation->>'endpoint_fingerprint_before'<>
                    p_observation->>'endpoint_fingerprint_after'
               OR p_observation->>'lua_observation_nonce'<>v_intent.observation_nonce THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='redis known observation invalid';
            END IF;
            SELECT count(*),min(status) INTO v_inbox_count,v_inbox_status
              FROM public.inbox_deliveries WHERE delivery_id=v_outbox.delivery_id;
            v_matrix_known := p_observation->'registered_groups'='["supportguard-workers-v1"]'::jsonb
              AND (
                (
                  coalesce((p_observation->>'delivery_present')::boolean,false)
                  AND p_observation->>'stream_payload_hash'=v_intent.expected_stream_payload_hash
                  AND (
                    (v_inbox_count=0 AND p_observation->'pending_groups'='[]'::jsonb)
                    OR (v_inbox_count=1 AND v_inbox_status='received'
                        AND p_observation->'pending_groups'='[]'::jsonb)
                    OR (v_inbox_count=1 AND v_inbox_status='claimed'
                        AND p_observation->'pending_groups'='["supportguard-workers-v1"]'::jsonb)
                    OR (v_inbox_count=1 AND v_inbox_status IN ('acked','rejected')
                        AND p_observation->'pending_groups'='[]'::jsonb)
                  )
                ) OR (
                  NOT coalesce((p_observation->>'delivery_present')::boolean,false)
                  AND p_observation->'stream_payload_hash'='null'::jsonb
                  AND v_inbox_count=0 AND p_observation->'pending_groups'='[]'::jsonb
                )
              );
            IF NOT v_matrix_known THEN
              v_normalized:=jsonb_build_object(
                'schema_version','redis-delivery-observation.v1','intent_id',v_intent.id,
                'observation_nonce',v_intent.observation_nonce,'job_id',v_job.id,
                'outbox_id',v_intent.outbox_id,
                'delivery_generation',v_intent.delivery_generation,
                'runner_nonce',p_observation->>'runner_nonce',
                'observed_at',p_observation->>'observed_at','status','unknown',
                'error_code','delivery_matrix_unknown'
              );
            ELSE
              IF (
                (v_inbox_count=1 AND v_inbox_status IN ('acked','rejected'))
                OR (v_inbox_count=0
                    AND NOT coalesce((p_observation->>'delivery_present')::boolean,false))
              ) AND clock_timestamp()<v_intent.expires_at THEN
                RETURN 'redelivery_grace';
              END IF;
              v_normalized:=jsonb_build_object(
                'schema_version','redis-delivery-observation.v1','intent_id',v_intent.id,
                'observation_nonce',v_intent.observation_nonce,'job_id',v_job.id,
                'outbox_id',v_intent.outbox_id,
                'delivery_generation',v_intent.delivery_generation,
                'runner_nonce',p_observation->>'runner_nonce',
                'observed_at',p_observation->>'observed_at','status','known',
                'delivery_present',(p_observation->>'delivery_present')::boolean,
                'pending_groups',p_observation->'pending_groups',
                'redis_client_id_before',p_observation->'redis_client_id_before',
                'redis_client_id_after',p_observation->'redis_client_id_after',
                'redis_principal_before',p_observation->>'redis_principal_before',
                'redis_principal_after',p_observation->>'redis_principal_after'
              );
            END IF;
          ELSIF v_status='unknown' THEN
            IF v_keys<>v_unknown_keys OR coalesce(p_observation->>'error_code','')='' THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='redis unknown observation invalid';
            END IF;
            v_normalized:=p_observation;
          ELSE
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='redis observation status invalid';
          END IF;
          v_hash:=encode(sha256(convert_to(v_normalized::text,'UTF8')),'hex');
          RETURN public.supportguard_reconciler_consume_v126_core(
            v_intent.id,v_normalized::text,v_hash
          );
        EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
          RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='redis observation typed field invalid';
        END $_$;


ALTER FUNCTION public.supportguard_reconciler_repair_d066(p_job_id text, p_expected_job_version bigint, p_intent_id text, p_observation jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_reconciler_repair_d067(text, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_reconciler_repair_d067(p_job_id text, p_expected_job_version bigint, p_intent_id text, p_observation jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_result text;
        BEGIN
          IF session_user<>'supportguard_reconciler' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='reconciler capability caller is not authorized';
          END IF;
          v_result:=public.supportguard_reconciler_repair_d066(
            p_job_id,p_expected_job_version,p_intent_id,p_observation
          );
          IF v_result='held_unknown' THEN
            UPDATE public.reconcile_intents
               SET status='consumed',terminal_reason='delivery_state_unknown',
                   updated_at=clock_timestamp()
             WHERE id=p_intent_id AND job_id=p_job_id AND status='observed';
            IF NOT FOUND THEN
              RAISE EXCEPTION USING ERRCODE='40001',
                MESSAGE='unknown delivery intent state changed before commit';
            END IF;
          END IF;
          RETURN v_result;
        END $$;


ALTER FUNCTION public.supportguard_reconciler_repair_d067(p_job_id text, p_expected_job_version bigint, p_intent_id text, p_observation jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_record_service_heartbeat(text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_record_service_heartbeat(p_instance_id text, p_service text, p_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_timing supportguard_control.runtime_timing_snapshots%ROWTYPE;
                v_heartbeat public.service_instance_heartbeats%ROWTYPE;
                v_expected_service text;
                v_payload jsonb;
                v_capabilities jsonb := '[]'::jsonb;
                v_runtime_version text := p_version;
                v_status text := 'ready';
                v_expected_head text;
                v_actual_head text;
                v_is_v2 boolean := false;
        BEGIN
          IF session_user NOT IN (
            'supportguard_api','supportguard_dispatcher','supportguard_reconciler',
            'supportguard_worker','supportguard_read_mcp','supportguard_action_mcp'
          ) THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='heartbeat capability caller is not authorized';
          END IF;
          v_expected_service:=CASE session_user
            WHEN 'supportguard_api' THEN 'api'
            WHEN 'supportguard_dispatcher' THEN 'dispatcher'
            WHEN 'supportguard_reconciler' THEN 'reconciler'
            WHEN 'supportguard_worker' THEN 'worker'
            WHEN 'supportguard_read_mcp' THEN 'read_mcp'
            WHEN 'supportguard_action_mcp' THEN 'action_mcp' END;
          IF coalesce(p_instance_id,'')='' OR coalesce(p_service,'')=''
             OR coalesce(p_version,'')=''
             OR p_service NOT IN (v_expected_service,session_user) THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='heartbeat payload invalid';
          END IF;
          SELECT * INTO STRICT v_timing
          FROM supportguard_control.runtime_timing_snapshots WHERE is_active;
          SELECT version_num INTO v_actual_head FROM public.alembic_version LIMIT 1;
          IF p_version='__healthcheck__' THEN
            SELECT * INTO v_heartbeat FROM public.service_instance_heartbeats
             WHERE id=p_instance_id AND service=p_service;
            RETURN jsonb_build_object(
              'healthy',v_heartbeat.id IS NOT NULL
                AND v_heartbeat.status='ready'
                AND v_heartbeat.timing_version=v_timing.timing_version
                AND v_heartbeat.runtime_config_hash=v_timing.config_hash
                AND v_heartbeat.last_heartbeat_at>=clock_timestamp()
                  - make_interval(secs=>v_timing.max_job_age_seconds),
              'status',v_heartbeat.status,
              'capabilities',coalesce(v_heartbeat.capabilities::jsonb,'[]'::jsonb),
              'version',v_heartbeat.version,
              'migration_head',v_actual_head,
              'timing_version',v_timing.timing_version,
              'runtime_config_hash',v_timing.config_hash
            );
          END IF;

          BEGIN
            v_payload:=p_version::jsonb;
            v_is_v2:=jsonb_typeof(v_payload)='object'
              AND v_payload->>'schema_version'='service-heartbeat.v2';
          EXCEPTION WHEN others THEN
            v_payload:=NULL;
            v_is_v2:=false;
          END;
          IF v_is_v2 THEN
            v_runtime_version:=v_payload->>'version';
            v_status:=v_payload->>'status';
            v_capabilities:=v_payload->'capabilities';
            v_expected_head:=v_payload->>'migration_head';
            IF coalesce(v_runtime_version,'')=''
               OR length(v_runtime_version)>64
               OR v_status NOT IN ('ready','degraded','stopped')
               OR jsonb_typeof(v_capabilities)<>'array'
               OR jsonb_array_length(v_capabilities)>24
               OR coalesce(v_expected_head,'')=''
               OR EXISTS (
                 SELECT 1 FROM jsonb_array_elements(v_capabilities) AS item(value)
                 WHERE jsonb_typeof(value)<>'string'
                    OR length(value #>> '{}')>256
                    OR length(value #>> '{}')=0
               ) THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='heartbeat payload invalid';
            END IF;
            IF v_actual_head IS DISTINCT FROM v_expected_head THEN
              v_status:='degraded';
            END IF;
          ELSE
            IF length(v_runtime_version)>64 THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='heartbeat payload invalid';
            END IF;
          END IF;

          INSERT INTO public.service_instance_heartbeats(
            id,service,capabilities,version,status,last_heartbeat_at,
            timing_version,runtime_config_hash,created_at,updated_at
          ) VALUES (
            p_instance_id,p_service,v_capabilities,v_runtime_version,v_status,
            clock_timestamp(),v_timing.timing_version,v_timing.config_hash,
            clock_timestamp(),clock_timestamp()
          ) ON CONFLICT(id) DO UPDATE SET
            service=excluded.service,capabilities=excluded.capabilities,
            version=excluded.version,status=excluded.status,
            timing_version=excluded.timing_version,
            runtime_config_hash=excluded.runtime_config_hash,
            last_heartbeat_at=clock_timestamp(),updated_at=clock_timestamp();
          RETURN jsonb_build_object(
            'healthy',v_status='ready',
            'status',v_status,
            'capabilities',v_capabilities,
            'version',v_runtime_version,
            'migration_head',v_actual_head,
            'timing_version',v_timing.timing_version,
            'runtime_config_hash',v_timing.config_hash
          );
        END $$;


ALTER FUNCTION public.supportguard_record_service_heartbeat(p_instance_id text, p_service text, p_version text) OWNER TO supportguard_owner;

--
-- Name: supportguard_retention_child_reference_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_retention_child_reference_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_new jsonb;
                v_old jsonb;
                v_job_id text;
                v_active_intent text;
                v_finalize_intent text:=nullif(current_setting(
                  'supportguard.retention_finalize_intent',true),'');
        BEGIN
          v_new:=CASE WHEN TG_OP='DELETE' THEN '{}'::jsonb ELSE to_jsonb(NEW) END;
          v_old:=CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
          v_job_id:=coalesce(nullif(v_new->>TG_ARGV[0],''),nullif(v_old->>TG_ARGV[0],''));
          IF v_job_id IS NULL THEN
            IF TG_OP='DELETE' THEN RETURN OLD; END IF;
            RETURN NEW;
          END IF;
          SELECT i.id INTO v_active_intent
            FROM public.retention_trim_intents i
           WHERE i.job_id=v_job_id
             AND i.status IN ('authorized','redis_trimmed','unknown_trim_state')
           ORDER BY i.id LIMIT 1;
          IF v_active_intent IS NOT NULL
             AND v_active_intent IS DISTINCT FROM v_finalize_intent THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='retention_trim_pending';
          END IF;
          IF TG_OP='DELETE' THEN RETURN OLD; END IF;
          RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_retention_child_reference_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_retention_trim_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_retention_trim_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_job_id text;
                v_active_intent text;
                v_finalize_intent text := current_setting(
                    'supportguard.retention_finalize_intent', true
                );
        BEGIN
            IF TG_TABLE_NAME='runtime_jobs' THEN
                IF TG_OP='UPDATE' THEN
                    IF OLD.terminal_at IS NULL AND OLD.status NOT IN ('succeeded','dead')
                       AND NEW.status IN ('succeeded','dead') THEN
                        NEW.terminal_at := coalesce(NEW.terminal_at,clock_timestamp());
                    ELSIF OLD.terminal_at IS NOT NULL
                          AND NEW.terminal_at IS DISTINCT FROM OLD.terminal_at THEN
                        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='terminal_anchor_immutable';
                    END IF;
                END IF;
                v_job_id := coalesce(NEW.id,OLD.id);
            ELSIF TG_TABLE_NAME='inbox_deliveries' THEN
                IF TG_OP='UPDATE' THEN
                    IF OLD.terminal_at IS NULL AND OLD.status NOT IN ('acked','rejected')
                       AND NEW.status IN ('acked','rejected') THEN
                        NEW.terminal_at := coalesce(NEW.terminal_at,clock_timestamp());
                    ELSIF OLD.terminal_at IS NOT NULL
                          AND NEW.terminal_at IS DISTINCT FROM OLD.terminal_at THEN
                        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='terminal_anchor_immutable';
                    END IF;
                END IF;
                v_job_id := coalesce(NEW.job_id,OLD.job_id);
            ELSIF TG_TABLE_NAME='outbox_events' THEN
                v_job_id := coalesce(NEW.job_id,OLD.job_id);
            ELSIF TG_TABLE_NAME='knowledge_ingest_runs' AND TG_OP='UPDATE' THEN
                IF OLD.is_active AND NOT NEW.is_active THEN
                    NEW.deactivated_at := coalesce(NEW.deactivated_at,clock_timestamp());
                ELSIF OLD.deactivated_at IS NOT NULL
                      AND NEW.deactivated_at IS DISTINCT FROM OLD.deactivated_at THEN
                    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='terminal_anchor_immutable';
                END IF;
                RETURN NEW;
            ELSIF TG_TABLE_NAME='idempotency_requests' AND TG_OP='UPDATE' THEN
                IF (OLD.completed_at IS NOT NULL
                    AND NEW.completed_at IS DISTINCT FROM OLD.completed_at)
                   OR (OLD.retention_class IS NOT NULL
                       AND NEW.retention_class IS DISTINCT FROM OLD.retention_class) THEN
                    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='retention_anchor_immutable';
                END IF;
                RETURN NEW;
            ELSE
                IF TG_OP='DELETE' THEN RETURN OLD; END IF;
                RETURN NEW;
            END IF;

            SELECT i.id INTO v_active_intent
            FROM public.retention_trim_intents i
            WHERE i.job_id=v_job_id
              AND i.status IN ('authorized','redis_trimmed','unknown_trim_state')
            ORDER BY i.id LIMIT 1;
            IF v_active_intent IS NOT NULL
               AND v_active_intent IS DISTINCT FROM nullif(v_finalize_intent,'') THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='retention_trim_pending';
            END IF;
            IF TG_OP='DELETE' THEN RETURN OLD; END IF;
            RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_retention_trim_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_run_retention(boolean, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_run_retention(p_apply boolean, p_delivery_before timestamp with time zone, p_trace_before timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_report jsonb; v_name text; v_count bigint;
                v_control constant text[]:=ARRAY[
                    'database_identity','runtime_timing_snapshots','upgrade_attestations',
                    'upgrade_phase_events','upgrade_runs'
                ];
        BEGIN
            IF session_user<>'supportguard_maintenance' THEN
                RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='retention caller is not authorized';
            END IF;
            v_report:=public.supportguard_run_retention_v125_core(
                p_apply,p_delivery_before,p_trace_before
            );
            FOREACH v_name IN ARRAY v_control LOOP
                EXECUTE format('SELECT count(*) FROM supportguard_control.%I',v_name)
                 INTO v_count;
                v_report:=jsonb_set(v_report,ARRAY['classification',
                    'supportguard_control.'||v_name],to_jsonb('protected_no_auto_delete'::text));
                v_report:=jsonb_set(v_report,ARRAY['eligible',
                    'supportguard_control.'||v_name],'0'::jsonb);
                v_report:=jsonb_set(v_report,ARRAY['deleted',
                    'supportguard_control.'||v_name],'0'::jsonb);
                v_report:=jsonb_set(v_report,ARRAY['skipped',
                    'supportguard_control.'||v_name],'0'::jsonb);
                v_report:=jsonb_set(v_report,ARRAY['protected',
                    'supportguard_control.'||v_name],to_jsonb(v_count));
            END LOOP;
            v_report:=jsonb_set(v_report,'{manifest_version}',
                to_jsonb('retention-manifest.v1.2.6'::text));
            RETURN v_report;
        END $$;


ALTER FUNCTION public.supportguard_run_retention(p_apply boolean, p_delivery_before timestamp with time zone, p_trace_before timestamp with time zone) OWNER TO supportguard_owner;

--
-- Name: supportguard_run_retention_v125_core(boolean, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_run_retention_v125_core(p_apply boolean, p_delivery_before timestamp with time zone, p_trace_before timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE
            v_batch constant integer := 500;
            v_classification constant jsonb := '{
              "agent_call_attempts":"protected_no_auto_delete","agent_events":"protected_no_auto_delete","agent_runs":"protected_no_auto_delete","api_key_metadata":"protected_no_auto_delete","api_request_traces":"delete_allowlisted","api_usage_buckets":"protected_no_auto_delete","api_usage_snapshots":"protected_no_auto_delete","approval_requests":"protected_no_auto_delete","approver_tenant_scopes":"protected_no_auto_delete","audit_events":"protected_no_auto_delete","billing_records":"protected_no_auto_delete","business_actions":"protected_no_auto_delete","checkpoint_blobs":"delete_allowlisted","checkpoint_commit_markers":"protected_no_auto_delete","checkpoint_migrations":"protected_no_auto_delete","checkpoint_task_identities":"protected_no_auto_delete","checkpoint_thread_identities":"protected_no_auto_delete","checkpoint_value_identities":"protected_no_auto_delete","checkpoint_writes":"delete_allowlisted","checkpoints":"delete_allowlisted","claim_records":"protected_no_auto_delete","context_ledgers":"protected_no_auto_delete","customers":"protected_no_auto_delete","escalation_records":"protected_no_auto_delete","finalizer_payloads":"protected_no_auto_delete","human_decisions":"protected_no_auto_delete","idempotency_requests":"delete_allowlisted","inbox_deliveries":"delete_allowlisted","incident_impacts":"protected_no_auto_delete","knowledge_chunks":"delete_allowlisted","knowledge_documents":"delete_allowlisted","knowledge_ingest_runs":"delete_allowlisted","memberships":"protected_no_auto_delete","mutation_kill_switches":"protected_no_auto_delete","outbox_events":"delete_allowlisted","plan_catalog":"protected_no_auto_delete","policy_capability_attempts":"protected_no_auto_delete","policy_capability_invocations":"protected_no_auto_delete","policy_capability_results":"protected_no_auto_delete","proposal_records":"protected_no_auto_delete","provider_runtime_events":"protected_no_auto_delete","queue_delivery_audits":"delete_allowlisted","raw_provider_decision_envelopes":"protected_no_auto_delete","reconcile_intents":"protected_no_auto_delete","redis_delivery_observations":"protected_no_auto_delete","retrieval_traces":"protected_no_auto_delete","runtime_jobs":"protected_no_auto_delete","service_incidents":"protected_no_auto_delete","service_instance_heartbeats":"delete_allowlisted","subscriptions":"protected_no_auto_delete","support_tickets":"protected_no_auto_delete","tenants":"protected_no_auto_delete","ticket_messages":"protected_no_auto_delete","ticket_summaries":"protected_no_auto_delete","tool_invocations":"protected_no_auto_delete","tool_observations":"protected_no_auto_delete","tool_transport_attempts":"protected_no_auto_delete","turn_groups":"protected_no_auto_delete","users":"protected_no_auto_delete"
            }'::jsonb;
            v_actual text[];
            v_manifest text[];
            v_eligible jsonb;
            v_deleted jsonb;
            v_skipped jsonb;
            v_protected jsonb;
            v_blocking jsonb := '{}'::jsonb;
            v_name text;
            v_class text;
            v_count bigint;
            v_deleted_count bigint;
            v_report jsonb;
        BEGIN
            IF session_user <> 'supportguard_maintenance' THEN
                RAISE EXCEPTION 'retention caller is not authorized';
            END IF;
            SELECT array_agg(tablename ORDER BY tablename COLLATE "C") INTO v_actual
              FROM pg_catalog.pg_tables
             WHERE schemaname='public' AND tablename <> 'alembic_version';
            SELECT array_agg(key ORDER BY key COLLATE "C") INTO v_manifest
              FROM jsonb_object_keys(v_classification) AS key;
            IF v_actual IS DISTINCT FROM v_manifest THEN
                RAISE EXCEPTION 'retention schema coverage mismatch actual=% manifest=%',
                    v_actual, v_manifest;
            END IF;
            SELECT jsonb_object_agg(key, 0) INTO v_eligible FROM jsonb_object_keys(v_classification) key;
            v_deleted := v_eligible;
            v_skipped := v_eligible;
            v_protected := v_eligible;

            FOR v_name, v_class IN SELECT key, value #>> '{}' FROM jsonb_each(v_classification)
            LOOP
                EXECUTE format('SELECT count(*) FROM public.%I', v_name) INTO v_count;
                IF v_class = 'protected_no_auto_delete' THEN
                    v_protected := jsonb_set(v_protected, ARRAY[v_name], to_jsonb(v_count));
                ELSE
                    v_skipped := jsonb_set(v_skipped, ARRAY[v_name], to_jsonb(v_count));
                    v_blocking := v_blocking || jsonb_build_object(
                        v_name, 'dependency_policy_not_satisfied'
                    );
                END IF;
            END LOOP;

            SELECT count(*) INTO v_count FROM public.outbox_events o
              JOIN public.runtime_jobs j ON j.id=o.job_id AND j.tenant_id=o.tenant_id
             WHERE o.created_at < p_delivery_before AND o.published_at IS NOT NULL
               AND j.status IN ('succeeded','dead');
            v_eligible := jsonb_set(v_eligible, '{outbox_events}', to_jsonb(v_count));
            v_skipped := jsonb_set(v_skipped, '{outbox_events}', '0'::jsonb);
            v_blocking := v_blocking - 'outbox_events';
            IF p_apply THEN
                WITH doomed AS (
                    SELECT o.id FROM public.outbox_events o
                    JOIN public.runtime_jobs j ON j.id=o.job_id AND j.tenant_id=o.tenant_id
                    WHERE o.created_at < p_delivery_before AND o.published_at IS NOT NULL
                      AND j.status IN ('succeeded','dead') ORDER BY o.created_at LIMIT v_batch
                ) DELETE FROM public.outbox_events o USING doomed d WHERE o.id=d.id;
                GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
                v_deleted := jsonb_set(v_deleted, '{outbox_events}', to_jsonb(v_deleted_count));
            END IF;

            SELECT count(*) INTO v_count FROM public.inbox_deliveries i
              JOIN public.runtime_jobs j ON j.id=i.job_id AND j.tenant_id=i.tenant_id
             WHERE i.created_at < p_delivery_before AND i.status='acked'
               AND j.status IN ('succeeded','dead');
            v_eligible := jsonb_set(v_eligible, '{inbox_deliveries}', to_jsonb(v_count));
            v_skipped := jsonb_set(v_skipped, '{inbox_deliveries}', '0'::jsonb);
            v_blocking := v_blocking - 'inbox_deliveries';
            IF p_apply THEN
                WITH doomed AS (
                    SELECT i.id FROM public.inbox_deliveries i
                    JOIN public.runtime_jobs j ON j.id=i.job_id AND j.tenant_id=i.tenant_id
                    WHERE i.created_at < p_delivery_before AND i.status='acked'
                      AND j.status IN ('succeeded','dead') ORDER BY i.created_at LIMIT v_batch
                ) DELETE FROM public.inbox_deliveries i USING doomed d WHERE i.id=d.id;
                GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
                v_deleted := jsonb_set(v_deleted, '{inbox_deliveries}', to_jsonb(v_deleted_count));
            END IF;

            SELECT count(*) INTO v_count FROM public.api_request_traces t
             WHERE t.created_at < p_trace_before
               AND NOT EXISTS (SELECT 1 FROM public.incident_impacts i WHERE i.request_trace_id=t.id);
            v_eligible := jsonb_set(v_eligible, '{api_request_traces}', to_jsonb(v_count));
            v_skipped := jsonb_set(v_skipped, '{api_request_traces}', '0'::jsonb);
            v_blocking := v_blocking - 'api_request_traces';
            IF p_apply THEN
                WITH doomed AS (
                    SELECT t.id FROM public.api_request_traces t
                    WHERE t.created_at < p_trace_before AND NOT EXISTS (
                        SELECT 1 FROM public.incident_impacts i WHERE i.request_trace_id=t.id
                    ) ORDER BY t.created_at LIMIT v_batch
                ) DELETE FROM public.api_request_traces t USING doomed d WHERE t.id=d.id;
                GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
                v_deleted := jsonb_set(v_deleted, '{api_request_traces}', to_jsonb(v_deleted_count));
            END IF;

            v_report := jsonb_build_object(
                'mode', CASE WHEN p_apply THEN 'apply' ELSE 'dry-run' END,
                'manifest_version','retention-manifest.v1.2.6',
                'batch_limit',v_batch,
                'classification',v_classification,
                'eligible',v_eligible,
                'deleted',v_deleted,
                'skipped',v_skipped,
                'blocking_dependencies',v_blocking,
                'protected',v_protected
            );
            INSERT INTO public.audit_events(id,event_type,actor_type,actor_ref,payload,trace_id,created_at)
            VALUES ('audit_retention_' || replace(gen_random_uuid()::text,'-',''),
                'retention_run','maintenance',session_user,v_report,
                'retention:' || clock_timestamp()::text,clock_timestamp());
            RETURN v_report;
        END;
        $$;


ALTER FUNCTION public.supportguard_run_retention_v125_core(p_apply boolean, p_delivery_before timestamp with time zone, p_trace_before timestamp with time zone) OWNER TO supportguard_owner;

--
-- Name: supportguard_runtime_acquire_writer_barrier(jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_runtime_acquire_writer_barrier(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $_$
        DECLARE v_run supportguard_control.upgrade_runs%ROWTYPE;
                v_job public.runtime_jobs%ROWTYPE;
                v_agent_run public.agent_runs%ROWTYPE;
                v_operation text:=p_payload->>'operation';
                v_nonce text:=p_payload->>'session_nonce';
                v_drain jsonb:=p_payload->'drain';
                v_expected_role text;
                v_permitted boolean:=false;
                v_denial text:='writer_barrier_input_invalid';
                v_key_count bigint;
        BEGIN
          IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='writer_barrier_input_invalid';
          END IF;
          SELECT count(*) INTO v_key_count FROM jsonb_object_keys(p_payload);
          IF v_key_count<>4 OR NOT (p_payload ?& ARRAY[
               'schema_version','operation','session_nonce','drain'
             ])
             OR p_payload->>'schema_version'<>'writer-barrier-acquire.v1'
             OR v_nonce !~ '^[0-9a-f]{32}$' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='writer_barrier_input_invalid';
          END IF;
          v_expected_role:=CASE v_operation
            WHEN 'dispatcher' THEN 'supportguard_dispatcher'
            WHEN 'worker' THEN 'supportguard_worker'
            WHEN 'reconciler' THEN 'supportguard_reconciler'
            WHEN 'maintenance' THEN 'supportguard_maintenance'
            ELSE NULL END;
          IF v_expected_role IS NULL OR (
            session_user<>v_expected_role
            AND session_user NOT IN ('supportguard','supportguard_owner')
          ) THEN
            RAISE EXCEPTION USING ERRCODE='42501',
              MESSAGE='writer barrier capability caller is not authorized';
          END IF;
          PERFORM pg_advisory_lock_shared(
            hashtextextended('supportguard.writer-barrier.v1',0)
          );
          SELECT * INTO v_run FROM supportguard_control.upgrade_runs
            WHERE phase<>'attested' ORDER BY started_at DESC LIMIT 1;
          IF v_run.id IS NULL THEN
            IF jsonb_typeof(v_drain)='null' THEN
              v_permitted:=true;
              v_denial:=NULL;
            ELSE
              v_denial:='drain_without_fence';
            END IF;
          ELSIF v_run.phase<>'quiescing' THEN
            v_denial:='fence_not_quiescing';
          ELSIF v_operation NOT IN ('worker','reconciler') THEN
            v_denial:='operation_not_drain_capable';
          ELSIF jsonb_typeof(v_drain)<>'object' THEN
            v_denial:='drain_identity_invalid';
          ELSE
            SELECT count(*) INTO v_key_count FROM jsonb_object_keys(v_drain);
            IF v_key_count<>4
               OR NOT (v_drain ?& ARRAY['job_id','run_id','owner','fencing_token'])
               OR coalesce(v_drain->>'job_id','')=''
               OR coalesce(v_drain->>'run_id','')=''
               OR coalesce(v_drain->>'owner','')=''
               OR jsonb_typeof(v_drain->'fencing_token')<>'number'
               OR (v_drain->>'fencing_token')::bigint<1 THEN
              v_denial:='drain_identity_invalid';
            ELSE
              SELECT * INTO v_job FROM public.runtime_jobs
                WHERE id=v_drain->>'job_id' FOR SHARE;
              SELECT * INTO v_agent_run FROM public.agent_runs
                WHERE id=v_drain->>'run_id' FOR SHARE;
              IF v_job.id IS NULL OR v_agent_run.id IS NULL
                 OR v_job.run_id<>v_drain->>'run_id'
                 OR v_job.status<>'leased'
                 OR v_job.lease_owner<>v_drain->>'owner'
                 OR v_job.fencing_token<>(v_drain->>'fencing_token')::bigint
                 OR v_job.lease_expires_at IS NULL
                 OR v_job.lease_expires_at<=clock_timestamp()
                 OR v_job.updated_at>=v_run.started_at
                 OR v_agent_run.tenant_id<>v_job.tenant_id
                 OR v_agent_run.active_job_id<>v_job.id
                 OR v_agent_run.active_fencing_token<>v_job.fencing_token THEN
                v_denial:='drain_lease_not_pre_fence_current';
              ELSE
                v_permitted:=true;
                v_denial:=NULL;
              END IF;
            END IF;
          END IF;
          INSERT INTO supportguard_control.writer_barrier_receipts(
            session_nonce,operation,backend_pid,upgrade_run_id,fence_phase,
            tenant_id,drain_job_id,drain_run_id,drain_owner,drain_fencing_token,
            permitted,denial_code
          ) VALUES (
            v_nonce,v_operation,pg_backend_pid(),v_run.id,v_run.phase,
            CASE WHEN v_permitted AND v_run.id IS NOT NULL THEN v_job.tenant_id END,
            CASE WHEN v_permitted AND v_run.id IS NOT NULL THEN v_job.id END,
            CASE WHEN v_permitted AND v_run.id IS NOT NULL THEN v_job.run_id END,
            CASE WHEN v_permitted AND v_run.id IS NOT NULL THEN v_job.lease_owner END,
            CASE WHEN v_permitted AND v_run.id IS NOT NULL THEN v_job.fencing_token END,
            v_permitted,v_denial
          );
          RETURN jsonb_build_object(
            'backend_pid',pg_backend_pid(),
            'upgrade_run_id',v_run.id,
            'fence_phase',v_run.phase,
            'permitted',v_permitted,
            'denial_code',v_denial
          );
        END $_$;


ALTER FUNCTION public.supportguard_runtime_acquire_writer_barrier(p_payload jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_runtime_bind_drain(jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_runtime_bind_drain(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $_$
        DECLARE v_receipt supportguard_control.writer_barrier_receipts%ROWTYPE;
                v_job public.runtime_jobs%ROWTYPE;
                v_run supportguard_control.upgrade_runs%ROWTYPE;
                v_nonce text:=p_payload->>'session_nonce';
                v_expected_role text;
                v_lock_live boolean;
                v_key_count bigint;
        BEGIN
          IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='drain_bind_input_invalid';
          END IF;
          SELECT count(*) INTO v_key_count FROM jsonb_object_keys(p_payload);
          IF v_key_count<>6 OR NOT (p_payload ?& ARRAY[
               'schema_version','session_nonce','job_id','run_id','owner','fencing_token'
             ])
             OR p_payload->>'schema_version'<>'writer-drain-bind.v1'
             OR v_nonce !~ '^[0-9a-f]{32}$'
             OR jsonb_typeof(p_payload->'fencing_token')<>'number' THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='drain_bind_input_invalid';
          END IF;
          SELECT * INTO v_receipt
          FROM supportguard_control.writer_barrier_receipts
          WHERE session_nonce=v_nonce;
          v_expected_role:=CASE v_receipt.operation
            WHEN 'worker' THEN 'supportguard_worker'
            WHEN 'reconciler' THEN 'supportguard_reconciler'
            ELSE NULL END;
          SELECT EXISTS (
            WITH barrier AS (
              SELECT hashtextextended('supportguard.writer-barrier.v1',0) AS key
            )
            SELECT 1 FROM pg_locks,barrier
            WHERE pid=v_receipt.backend_pid AND locktype='advisory'
              AND classid=((barrier.key >> 32) & 4294967295)::oid
              AND objid=(barrier.key & 4294967295)::oid
              AND objsubid=1 AND mode='ShareLock' AND granted
          ) INTO v_lock_live;
          SELECT * INTO v_run FROM supportguard_control.upgrade_runs
          WHERE id=v_receipt.upgrade_run_id;
          SELECT * INTO v_job FROM public.runtime_jobs
          WHERE id=v_receipt.drain_job_id FOR SHARE;
          IF v_receipt.session_nonce IS NULL OR NOT v_receipt.permitted
             OR v_receipt.released_at IS NOT NULL OR NOT v_lock_live
             OR v_expected_role IS NULL OR session_user<>v_expected_role
             OR v_run.id IS NULL OR v_run.phase<>'quiescing'
             OR p_payload->>'job_id'<>v_receipt.drain_job_id
             OR p_payload->>'run_id'<>v_receipt.drain_run_id
             OR p_payload->>'owner'<>v_receipt.drain_owner
             OR (p_payload->>'fencing_token')::bigint<>v_receipt.drain_fencing_token
             OR v_job.id IS NULL OR v_job.status<>'leased'
             OR v_job.run_id<>v_receipt.drain_run_id
             OR v_job.lease_owner<>v_receipt.drain_owner
             OR v_job.fencing_token<>v_receipt.drain_fencing_token
             OR v_job.lease_expires_at IS NULL
             OR v_job.lease_expires_at<=clock_timestamp() THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='drain_binding_invalid';
          END IF;
          PERFORM set_config('supportguard.drain_session_nonce',v_nonce,true);
          PERFORM set_config('supportguard.drain_job_id',v_receipt.drain_job_id,true);
          PERFORM set_config('supportguard.drain_run_id',v_receipt.drain_run_id,true);
          PERFORM set_config('supportguard.drain_tenant_id',v_receipt.tenant_id,true);
          PERFORM set_config(
            'supportguard.drain_fencing_token',v_receipt.drain_fencing_token::text,true
          );
          RETURN jsonb_build_object(
            'result','bound','session_nonce',v_nonce,
            'job_id',v_receipt.drain_job_id,
            'run_id',v_receipt.drain_run_id,
            'fencing_token',v_receipt.drain_fencing_token
          );
        END $_$;


ALTER FUNCTION public.supportguard_runtime_bind_drain(p_payload jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_runtime_job_bind_active_timing(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_runtime_job_bind_active_timing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_timing_version bigint;
        BEGIN
          SELECT timing_version INTO v_timing_version
          FROM supportguard_control.runtime_timing_snapshots
          WHERE is_active FOR SHARE;
          IF v_timing_version IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',
              MESSAGE='active_runtime_timing_missing';
          END IF;
          NEW.timing_version:=v_timing_version;
          RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_runtime_job_bind_active_timing() OWNER TO supportguard_owner;

--
-- Name: supportguard_runtime_job_identity_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_runtime_job_identity_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_ticket_id text;
        BEGIN
          SELECT r.ticket_id INTO v_ticket_id
          FROM public.agent_runs r
          WHERE r.tenant_id=NEW.tenant_id AND r.id=NEW.run_id;
          IF v_ticket_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='23503',
              MESSAGE='runtime_job_run_missing';
          END IF;
          IF TG_OP='INSERT' THEN
            IF NEW.ticket_id IS NOT NULL
               AND NEW.ticket_id IS DISTINCT FROM v_ticket_id THEN
              RAISE EXCEPTION USING ERRCODE='23514',
                MESSAGE='runtime_job_ticket_identity_conflict';
            END IF;
            IF NEW.dispatch_sequence IS NOT NULL THEN
              RAISE EXCEPTION USING ERRCODE='23514',
                MESSAGE='runtime_job_dispatch_sequence_runtime_owned';
            END IF;
            NEW.ticket_id:=v_ticket_id;
            NEW.dispatch_sequence:=
              public.supportguard_internal_allocate_dispatch_sequence(
                NEW.tenant_id,v_ticket_id
              );
          ELSIF current_setting('app.v1512_backfill_authorized',true)='v1512'
             AND OLD.ticket_id IS NULL AND OLD.dispatch_sequence IS NULL
             AND NEW.ticket_id=v_ticket_id
             AND NEW.dispatch_sequence IS NOT NULL
             AND NEW.dispatch_sequence>0 THEN
            RETURN NEW;
          ELSIF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
             OR NEW.run_id IS DISTINCT FROM OLD.run_id
             OR NEW.ticket_id IS DISTINCT FROM OLD.ticket_id
             OR NEW.dispatch_sequence IS DISTINCT FROM OLD.dispatch_sequence THEN
            RAISE EXCEPTION USING ERRCODE='55000',
              MESSAGE='runtime_job_dispatch_identity_immutable';
          END IF;
          RETURN NEW;
        END
        $$;


ALTER FUNCTION public.supportguard_runtime_job_identity_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_runtime_job_outcome_version_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_runtime_job_outcome_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF NEW.outcome IS DISTINCT FROM OLD.outcome
             AND NEW.status_version=OLD.status_version THEN
            NEW.status_version:=OLD.status_version+1;
          END IF;
          RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_runtime_job_outcome_version_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_runtime_job_timing_immutable(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_runtime_job_timing_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
        BEGIN
            IF NEW.timing_version IS DISTINCT FROM OLD.timing_version THEN
                RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='job_timing_version_immutable';
            END IF;
            RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_runtime_job_timing_immutable() OWNER TO supportguard_owner;

--
-- Name: supportguard_runtime_release_writer_barrier(text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_runtime_release_writer_barrier(p_session_nonce text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_receipt supportguard_control.writer_barrier_receipts%ROWTYPE;
                v_expected_role text;
        BEGIN
          SELECT * INTO v_receipt
          FROM supportguard_control.writer_barrier_receipts
          WHERE session_nonce=p_session_nonce FOR UPDATE;
          v_expected_role:=CASE v_receipt.operation
            WHEN 'dispatcher' THEN 'supportguard_dispatcher'
            WHEN 'worker' THEN 'supportguard_worker'
            WHEN 'reconciler' THEN 'supportguard_reconciler'
            WHEN 'maintenance' THEN 'supportguard_maintenance'
            ELSE NULL END;
          IF v_receipt.session_nonce IS NULL
             OR v_receipt.released_at IS NOT NULL
             OR v_receipt.backend_pid<>pg_backend_pid()
             OR (session_user<>v_expected_role
                 AND session_user NOT IN ('supportguard','supportguard_owner')) THEN
            RAISE EXCEPTION USING ERRCODE='55000',
              MESSAGE='writer_barrier_release_not_owned';
          END IF;
          UPDATE supportguard_control.writer_barrier_receipts
          SET released_at=clock_timestamp()
          WHERE session_nonce=p_session_nonce;
          RETURN true;
        END $$;


ALTER FUNCTION public.supportguard_runtime_release_writer_barrier(p_session_nonce text) OWNER TO supportguard_owner;

--
-- Name: supportguard_runtime_snapshot_internal(boolean); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_runtime_snapshot_internal(p_lock boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_timing supportguard_control.runtime_timing_snapshots%ROWTYPE;
                v_count bigint; v_oldest timestamptz; v_workers bigint;
                v_fallback_principal_count bigint;
                v_worker_components jsonb;
                v_migration_head text;
                v_now timestamptz := clock_timestamp();
        BEGIN
          IF p_lock THEN
            SELECT * INTO v_timing FROM supportguard_control.runtime_timing_snapshots
            WHERE is_active FOR UPDATE;
            PERFORM pg_advisory_xact_lock(
              hashtextextended('supportguard.runtime.admission',0)
            );
          ELSE
            SELECT * INTO v_timing FROM supportguard_control.runtime_timing_snapshots
            WHERE is_active;
          END IF;
          IF v_timing.timing_version IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='active_runtime_timing_missing';
          END IF;
          SELECT version_num INTO v_migration_head FROM public.alembic_version LIMIT 1;
          SELECT count(*),min(created_at) INTO v_count,v_oldest
          FROM public.runtime_jobs WHERE status IN ('queued','retry_wait','leased');
          SELECT count(*) INTO v_workers FROM public.service_instance_heartbeats
          WHERE service='worker' AND status='ready'
            AND last_heartbeat_at>=v_now-make_interval(secs=>30)
            AND timing_version=v_timing.timing_version
            AND runtime_config_hash=v_timing.config_hash;
          SELECT coalesce(jsonb_agg(jsonb_build_object(
              'instance_id',id,'status',status,'version',version,
              'capabilities',capabilities,'last_heartbeat_at',last_heartbeat_at,
              'timing_version',timing_version,'runtime_config_hash',runtime_config_hash
            ) ORDER BY id),'[]'::jsonb)
            INTO v_worker_components
          FROM public.service_instance_heartbeats
          WHERE service='worker'
            AND last_heartbeat_at>=v_now-make_interval(secs=>v_timing.max_job_age_seconds);
          SELECT count(*) INTO v_fallback_principal_count
          FROM public.idempotency_requests
          WHERE tenant_id=current_setting('app.tenant_id',true)
            AND principal_id=current_setting('app.principal_id',true)
            AND created_at>=v_now-make_interval(secs=>60);
          RETURN jsonb_build_object(
            'timing_version',v_timing.timing_version,
            'max_job_age_seconds',v_timing.max_job_age_seconds,
            'max_attempts',v_timing.max_attempts,
            'max_delivery_generation',v_timing.max_delivery_generation,
            'redelivery_grace_seconds',v_timing.redelivery_grace_seconds,
            'lease_seconds',v_timing.lease_seconds,
            'backlog_count_limit',v_timing.backlog_count_limit,
            'oldest_backlog_seconds',v_timing.oldest_backlog_seconds,
            'config_hash',v_timing.config_hash,
            'migration_head',v_migration_head,
            'active_count',v_count,'oldest_created_at',v_oldest,'database_now',v_now,
            'ready_worker_count',v_workers,
            'worker_components',v_worker_components,
            'fallback_principal_count',v_fallback_principal_count,
            'admitted',v_count<v_timing.backlog_count_limit AND
              (v_oldest IS NULL OR
               v_now-v_oldest<make_interval(secs=>v_timing.oldest_backlog_seconds))
          );
        END $$;


ALTER FUNCTION public.supportguard_runtime_snapshot_internal(p_lock boolean) OWNER TO supportguard_owner;

--
-- Name: supportguard_runtime_timing_snapshot(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_runtime_timing_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        BEGIN
            IF session_user NOT IN (
                'supportguard_api','supportguard_dispatcher','supportguard_reconciler',
                'supportguard_worker','supportguard_maintenance'
            ) THEN
                RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='runtime timing caller is not authorized';
            END IF;
            RETURN supportguard_runtime_snapshot_internal(false);
        END $$;


ALTER FUNCTION public.supportguard_runtime_timing_snapshot() OWNER TO supportguard_owner;

--
-- Name: supportguard_runtime_writer_barrier_guard(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_runtime_writer_barrier_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_revision public.approval_action_revisions%ROWTYPE;
                v_upgrade supportguard_control.upgrade_runs%ROWTYPE;
                v_receipt supportguard_control.writer_barrier_receipts%ROWTYPE;
                v_row jsonb;
                v_nonce text;
                v_target_match boolean:=false;
                v_lock_live boolean:=false;
        BEGIN
          IF TG_TABLE_NAME='service_instance_heartbeats' THEN
            IF TG_OP='DELETE' THEN RETURN OLD; END IF;
            RETURN NEW;
          END IF;
          IF session_user<>'supportguard_migrator' THEN
            PERFORM pg_advisory_xact_lock_shared(
              hashtextextended('supportguard.writer-barrier.v1',0)
            );
            SELECT * INTO v_upgrade FROM supportguard_control.upgrade_runs
            WHERE phase<>'attested' ORDER BY started_at DESC LIMIT 1;
            IF v_upgrade.id IS NOT NULL THEN
              v_row:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
              v_nonce:=current_setting('supportguard.drain_session_nonce',true);
              IF v_upgrade.phase='quiescing'
                 AND session_user IN ('supportguard_worker','supportguard_reconciler')
                 AND coalesce(v_nonce,'')<>'' THEN
                SELECT * INTO v_receipt
                FROM supportguard_control.writer_barrier_receipts
                WHERE session_nonce=v_nonce;
                SELECT EXISTS (
                  WITH barrier AS (
                    SELECT hashtextextended('supportguard.writer-barrier.v1',0) AS key
                  )
                  SELECT 1 FROM pg_locks,barrier
                  WHERE pid=v_receipt.backend_pid AND locktype='advisory'
                    AND classid=((barrier.key >> 32) & 4294967295)::oid
                    AND objid=(barrier.key & 4294967295)::oid
                    AND objsubid=1 AND mode='ShareLock' AND granted
                ) INTO v_lock_live;
                v_target_match := (
                  v_receipt.permitted AND v_receipt.released_at IS NULL
                  AND v_receipt.upgrade_run_id=v_upgrade.id
                  AND v_receipt.fence_phase='quiescing'
                  AND v_receipt.operation=CASE session_user
                    WHEN 'supportguard_worker' THEN 'worker' ELSE 'reconciler' END
                  AND current_setting('supportguard.drain_job_id',true)=v_receipt.drain_job_id
                  AND current_setting('supportguard.drain_run_id',true)=v_receipt.drain_run_id
                  AND current_setting('supportguard.drain_tenant_id',true)=v_receipt.tenant_id
                  AND current_setting('supportguard.drain_fencing_token',true)=
                      v_receipt.drain_fencing_token::text
                  AND v_lock_live
                  AND NOT (TG_TABLE_NAME='outbox_events' AND TG_OP='INSERT')
                  AND (
                    (TG_TABLE_NAME='runtime_jobs' AND v_row->>'id'=v_receipt.drain_job_id)
                    OR (TG_TABLE_NAME='agent_runs' AND v_row->>'id'=v_receipt.drain_run_id)
                    OR (
                      v_row ? 'job_id'
                      AND v_row->>'job_id'=v_receipt.drain_job_id
                      AND (NOT (v_row ? 'run_id')
                           OR v_row->>'run_id'=v_receipt.drain_run_id)
                      AND (NOT (v_row ? 'tenant_id')
                           OR v_row->>'tenant_id'=v_receipt.tenant_id)
                    )
                    OR (
                      v_row ? 'origin_job_id'
                      AND v_row->>'origin_job_id'=v_receipt.drain_job_id
                      AND (NOT (v_row ? 'run_id')
                           OR v_row->>'run_id'=v_receipt.drain_run_id)
                    )
                    OR (
                      v_row ? 'executor_job_id'
                      AND v_row->>'executor_job_id'=v_receipt.drain_job_id
                      AND (NOT (v_row ? 'run_id')
                           OR v_row->>'run_id'=v_receipt.drain_run_id)
                    )
                    OR (
                      TG_TABLE_NAME='support_tickets'
                      AND EXISTS (
                        SELECT 1 FROM public.agent_runs r
                        WHERE r.id=v_receipt.drain_run_id
                          AND r.ticket_id=v_row->>'id'
                      )
                    )
                    OR (
                      TG_TABLE_NAME='redis_delivery_observations'
                      AND EXISTS (
                        SELECT 1 FROM public.reconcile_intents i
                        WHERE i.id=v_row->>'reconcile_intent_id'
                          AND i.job_id=v_receipt.drain_job_id
                          AND i.run_id=v_receipt.drain_run_id
                          AND i.tenant_id=v_receipt.tenant_id
                      )
                    )
                  )
                );
              END IF;
              IF NOT v_target_match THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='upgrade_in_progress';
              END IF;
            END IF;
          END IF;
          IF TG_OP='INSERT' AND TG_TABLE_NAME='retrieval_traces' THEN
            IF NEW.trace_status<>'started'
               OR NEW.status_version<>1
               OR NEW.result_digest IS NOT NULL
               OR NEW.error_digest IS NOT NULL
               OR NEW.terminal_transport_attempt_id IS NOT NULL
               OR jsonb_array_length(NEW.vector_candidates::jsonb)<>0
               OR jsonb_array_length(NEW.keyword_candidates::jsonb)<>0
               OR jsonb_array_length(NEW.rrf_candidates::jsonb)<>0
               OR jsonb_array_length(NEW.pre_filter_candidates::jsonb)<>0
               OR jsonb_array_length(NEW.selected_candidates::jsonb)<>0
               OR jsonb_array_length(NEW.eligibility_envelopes::jsonb)<>0 THEN
                RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='retrieval_trace_must_start';
            END IF;
          ELSIF TG_OP='UPDATE' AND TG_TABLE_NAME='proposal_records' THEN
            IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
               OR NEW.run_id IS DISTINCT FROM OLD.run_id
               OR NEW.proposal_identity IS DISTINCT FROM OLD.proposal_identity
               OR NEW.action_type IS DISTINCT FROM OLD.action_type
               OR NEW.resource_id IS DISTINCT FROM OLD.resource_id
               OR NEW.resource_version IS DISTINCT FROM OLD.resource_version
               OR NEW.action_payload::jsonb IS DISTINCT FROM OLD.action_payload::jsonb
               OR NEW.observation_binding::jsonb IS DISTINCT FROM OLD.observation_binding::jsonb
               OR NEW.action_hash IS DISTINCT FROM OLD.action_hash
               OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
                RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='proposal_identity_immutable';
            END IF;
            IF NEW.status_version <> OLD.status_version + 1 THEN
                RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='proposal_status_version_conflict';
            END IF;
            IF NOT (
                (OLD.status='draft' AND NEW.status IN ('bound','stale'))
                OR (OLD.status='bound' AND NEW.status='stale')
            ) THEN
                RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='proposal_status_transition_invalid';
            END IF;
          ELSIF TG_OP='UPDATE' AND TG_TABLE_NAME='retrieval_traces' THEN
            IF OLD.trace_status='started' AND NEW.trace_status='started' THEN
              IF NEW.status_version<>OLD.status_version
                 OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
                 OR NEW.run_id IS DISTINCT FROM OLD.run_id
                 OR NEW.job_id IS DISTINCT FROM OLD.job_id
                 OR NEW.segment_id IS DISTINCT FROM OLD.segment_id
                 OR NEW.origin_kind IS DISTINCT FROM OLD.origin_kind
                 OR NEW.logical_invocation_id IS DISTINCT FROM OLD.logical_invocation_id
                 OR NEW.tool_call_id IS DISTINCT FROM OLD.tool_call_id
                 OR NEW.fencing_token IS DISTINCT FROM OLD.fencing_token
                 OR NEW.delivery_generation IS DISTINCT FROM OLD.delivery_generation
                 OR NEW.origin_job_id IS DISTINCT FROM OLD.origin_job_id
                 OR NEW.origin_marker_id IS DISTINCT FROM OLD.origin_marker_id
                 OR NEW.origin_fencing_token IS DISTINCT FROM OLD.origin_fencing_token
                 OR NEW.origin_segment_ref IS DISTINCT FROM OLD.origin_segment_ref
                 OR NEW.trace_logical_time IS DISTINCT FROM OLD.trace_logical_time
                 OR NEW.query_hash IS DISTINCT FROM OLD.query_hash
                 OR NEW.index_version IS DISTINCT FROM OLD.index_version
                 OR NEW.corpus_snapshot_id IS DISTINCT FROM OLD.corpus_snapshot_id
                 OR NEW.result_digest IS DISTINCT FROM OLD.result_digest
                 OR NEW.error_digest IS DISTINCT FROM OLD.error_digest
                 OR NEW.terminal_transport_attempt_id IS DISTINCT FROM OLD.terminal_transport_attempt_id
                 OR NEW.vector_candidates::jsonb IS DISTINCT FROM OLD.vector_candidates::jsonb
                 OR NEW.keyword_candidates::jsonb IS DISTINCT FROM OLD.keyword_candidates::jsonb
                 OR NEW.rrf_candidates::jsonb IS DISTINCT FROM OLD.rrf_candidates::jsonb
                 OR NEW.pre_filter_candidates::jsonb IS DISTINCT FROM OLD.pre_filter_candidates::jsonb
                 OR NEW.selected_candidates::jsonb IS DISTINCT FROM OLD.selected_candidates::jsonb
                 OR NEW.omission_decisions::jsonb IS DISTINCT FROM OLD.omission_decisions::jsonb
                 OR NEW.evidence_groups::jsonb IS DISTINCT FROM OLD.evidence_groups::jsonb
                 OR NEW.eligibility_envelopes::jsonb IS DISTINCT FROM OLD.eligibility_envelopes::jsonb
                 OR NEW.abstention_reason IS DISTINCT FROM OLD.abstention_reason THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='retrieval_substate_mutation_invalid';
              END IF;
              IF OLD.runtime_provenance::jsonb->'_restricted_search'->>'phase'='scope_loaded'
                 AND NEW.runtime_provenance::jsonb->'_restricted_search'
                       =OLD.runtime_provenance::jsonb->'_restricted_search'
                 AND OLD.filter_contract::jsonb='{}'::jsonb
                 AND NEW.filter_contract::jsonb<>'{}'::jsonb THEN
                RETURN NEW;
              END IF;
              IF NEW.runtime_provenance::jsonb-'_restricted_search'
                    IS DISTINCT FROM OLD.runtime_provenance::jsonb-'_restricted_search'
                 OR NOT (
                   (OLD.runtime_provenance::jsonb->'_restricted_search'->>'phase'='scope_loaded'
                    AND NEW.runtime_provenance::jsonb->'_restricted_search'->>'phase'='trace_started')
                   OR (OLD.runtime_provenance::jsonb->'_restricted_search'->>'phase'='trace_started'
                    AND NEW.runtime_provenance::jsonb->'_restricted_search'->>'phase'='candidate_done')
                   OR (OLD.runtime_provenance::jsonb->'_restricted_search'->>'phase'='candidate_done'
                    AND NEW.runtime_provenance::jsonb->'_restricted_search'->>'phase'='vector_done')
                   OR (OLD.runtime_provenance::jsonb->'_restricted_search'->>'phase'='vector_done'
                    AND NEW.runtime_provenance::jsonb->'_restricted_search'->>'phase'='keyword_done')
                 ) THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='retrieval_substate_transition_invalid';
              END IF;
              RETURN NEW;
            ELSIF OLD.trace_status IN ('terminal_ok','terminal_error')
               AND NEW.trace_status=OLD.trace_status THEN
              IF NEW.status_version<>OLD.status_version
                 OR to_jsonb(NEW)-ARRAY['runtime_provenance','updated_at']
                    IS DISTINCT FROM to_jsonb(OLD)-ARRAY['runtime_provenance','updated_at']
                 OR NEW.runtime_provenance::jsonb-'_restricted_search'
                    IS DISTINCT FROM OLD.runtime_provenance::jsonb-'_restricted_search'
                 OR OLD.runtime_provenance::jsonb->'_restricted_search'->>'phase'
                    NOT IN ('scope_loaded','trace_started','candidate_done','vector_done','keyword_done')
                 OR NEW.runtime_provenance::jsonb->'_restricted_search'->>'phase'<>'terminal' THEN
                RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='retrieval_terminal_receipt_invalid';
              END IF;
              RETURN NEW;
            END IF;
            IF OLD.trace_status<>'started'
               OR NEW.trace_status NOT IN ('terminal_ok','terminal_error')
               OR NEW.status_version<>OLD.status_version+1
               OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
               OR NEW.run_id IS DISTINCT FROM OLD.run_id
               OR NEW.job_id IS DISTINCT FROM OLD.job_id
               OR NEW.segment_id IS DISTINCT FROM OLD.segment_id
               OR NEW.origin_kind IS DISTINCT FROM OLD.origin_kind
               OR NEW.logical_invocation_id IS DISTINCT FROM OLD.logical_invocation_id
               OR NEW.tool_call_id IS DISTINCT FROM OLD.tool_call_id
               OR NEW.fencing_token IS DISTINCT FROM OLD.fencing_token
               OR NEW.delivery_generation IS DISTINCT FROM OLD.delivery_generation
               OR NEW.origin_job_id IS DISTINCT FROM OLD.origin_job_id
               OR NEW.origin_marker_id IS DISTINCT FROM OLD.origin_marker_id
               OR NEW.origin_fencing_token IS DISTINCT FROM OLD.origin_fencing_token
               OR NEW.origin_segment_ref IS DISTINCT FROM OLD.origin_segment_ref
               OR NEW.trace_logical_time IS DISTINCT FROM OLD.trace_logical_time
               OR NEW.query_hash IS DISTINCT FROM OLD.query_hash
               OR NEW.index_version IS DISTINCT FROM OLD.index_version
               OR NEW.corpus_snapshot_id IS DISTINCT FROM OLD.corpus_snapshot_id
               OR NEW.runtime_provenance::jsonb IS DISTINCT FROM OLD.runtime_provenance::jsonb
               OR (NEW.trace_status='terminal_ok' AND (
                    NEW.result_digest IS NULL OR NEW.error_digest IS NOT NULL
               ))
               OR (NEW.trace_status='terminal_error' AND (
                    NEW.error_digest IS NULL OR NEW.result_digest IS NOT NULL
               )) THEN
                RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='retrieval_trace_transition_invalid';
            END IF;
          ELSIF TG_OP='INSERT' AND TG_TABLE_NAME='approval_requests' THEN
            PERFORM public.supportguard_internal_validate_approval_transition(
              NULL,NEW.status,'INSERT',NULL,NEW.status_version
            );
            SELECT p.resource_id,
                   CASE p.action_type
                     WHEN 'refund' THEN 'billing_record_id'
                     WHEN 'api_key_revocation' THEN 'api_key_id'
                     WHEN 'entitlement_change' THEN 'subscription_id'
                   END,
                   r.turn_id
              INTO NEW.resource_id,NEW.resource_type,NEW.origin_turn_id
            FROM public.proposal_records p
            JOIN public.agent_runs r
              ON r.tenant_id=p.tenant_id AND r.id=p.run_id
            WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.proposal_id
              AND p.run_id=NEW.run_id AND p.action_type=NEW.action_type
              AND p.resource_version=NEW.business_version
              AND r.ticket_id=NEW.ticket_id;
            IF NEW.resource_id IS NULL OR NEW.resource_type IS NULL
               OR NEW.origin_turn_id IS NULL THEN
              RAISE EXCEPTION USING ERRCODE='23514',
                MESSAGE='approval_resource_identity_invalid';
            END IF;
          ELSIF TG_OP='UPDATE' AND TG_TABLE_NAME='approval_requests' THEN
            PERFORM public.supportguard_internal_validate_approval_transition(
              OLD.status,NEW.status,'UPDATE',OLD.status_version,NEW.status_version
            );
            IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
               OR NEW.ticket_id IS DISTINCT FROM OLD.ticket_id
               OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
               OR NEW.proposal_id IS DISTINCT FROM OLD.proposal_id
               OR NEW.run_id IS DISTINCT FROM OLD.run_id
               OR NEW.checkpoint_id IS DISTINCT FROM OLD.checkpoint_id
               OR NEW.canonical_checkpoint_ns IS DISTINCT FROM OLD.canonical_checkpoint_ns
               OR NEW.canonical_checkpoint_hash IS DISTINCT FROM OLD.canonical_checkpoint_hash
               OR NEW.checkpoint_version IS DISTINCT FROM OLD.checkpoint_version
               OR NEW.marker_id IS DISTINCT FROM OLD.marker_id
               OR (
                 (
                   NEW.expected_ticket_head_event_id IS DISTINCT FROM
                     OLD.expected_ticket_head_event_id
                   OR NEW.expected_ticket_sequence IS DISTINCT FROM OLD.expected_ticket_sequence
                   OR NEW.expected_ticket_event_hash IS DISTINCT FROM OLD.expected_ticket_event_hash
                 )
                 AND NOT (
                   NEW.status=OLD.status
                   AND NEW.status_version=OLD.status_version
                 )
               )
               OR NEW.action_type IS DISTINCT FROM OLD.action_type
               OR NEW.resource_type IS DISTINCT FROM OLD.resource_type
               OR NEW.resource_id IS DISTINCT FROM OLD.resource_id
               OR NEW.origin_turn_id IS DISTINCT FROM OLD.origin_turn_id
               OR NEW.action_payload::jsonb IS DISTINCT FROM OLD.action_payload::jsonb
               OR NEW.review_context::jsonb IS DISTINCT FROM OLD.review_context::jsonb
               OR NEW.action_hash IS DISTINCT FROM OLD.action_hash
               OR NEW.business_version IS DISTINCT FROM OLD.business_version
               OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
               OR NEW.approver_id IS DISTINCT FROM OLD.approver_id
               OR NEW.decision_reason IS DISTINCT FROM OLD.decision_reason
               OR NEW.approver_note IS DISTINCT FROM OLD.approver_note
               OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
                RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='approval_update_invalid';
            END IF;
            IF NEW.selected_revision_id IS NOT NULL THEN
                SELECT * INTO v_revision FROM public.approval_action_revisions
                WHERE id=NEW.selected_revision_id;
                IF v_revision.id IS NULL
                   OR v_revision.tenant_id<>NEW.tenant_id
                   OR v_revision.approval_id<>NEW.id
                   OR v_revision.proposal_id IS DISTINCT FROM NEW.proposal_id
                   OR v_revision.revision_number IS DISTINCT FROM NEW.selected_revision_number
                   OR v_revision.resource_version IS DISTINCT FROM NEW.business_version THEN
                    RAISE EXCEPTION USING
                        ERRCODE='23514', MESSAGE='approval_revision_binding_invalid';
                END IF;
            ELSIF NEW.selected_revision_number IS NOT NULL THEN
                RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='approval_revision_binding_invalid';
            END IF;
          END IF;
          IF TG_OP='DELETE' THEN RETURN OLD; END IF;
          RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_runtime_writer_barrier_guard() OWNER TO supportguard_owner;

--
-- Name: supportguard_set_conversation_title(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_set_conversation_title() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF NEW.role='user' THEN
            UPDATE public.support_tickets
            SET title=left(regexp_replace(trim(NEW.content),'[[:space:]]+',' ','g'),80)
            WHERE tenant_id=NEW.tenant_id AND id=NEW.ticket_id AND title IS NULL;
          END IF;
          RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_set_conversation_title() OWNER TO supportguard_owner;

--
-- Name: supportguard_timing_snapshot_immutable(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_timing_snapshot_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
        BEGIN
            IF TG_OP='DELETE' OR NEW.timing_version<>OLD.timing_version
               OR NEW.max_job_age_seconds<>OLD.max_job_age_seconds
               OR NEW.max_attempts<>OLD.max_attempts
               OR NEW.max_delivery_generation<>OLD.max_delivery_generation
               OR NEW.redelivery_grace_seconds<>OLD.redelivery_grace_seconds
               OR NEW.lease_seconds<>OLD.lease_seconds
               OR NEW.backlog_count_limit<>OLD.backlog_count_limit
               OR NEW.oldest_backlog_seconds<>OLD.oldest_backlog_seconds
               OR NEW.config_hash<>OLD.config_hash OR NEW.activated_at<>OLD.activated_at THEN
                RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='runtime_timing_snapshot_immutable';
            END IF;
            RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_timing_snapshot_immutable() OWNER TO supportguard_owner;

--
-- Name: supportguard_tool_logical_time_immutable(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_tool_logical_time_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
          IF NEW.logical_time_utc IS DISTINCT FROM OLD.logical_time_utc THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='tool_logical_time_immutable';
          END IF;
          RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_tool_logical_time_immutable() OWNER TO supportguard_owner;

