--
-- Name: supportguard_v15_message_after_insert(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_v15_message_after_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_mode text;
        BEGIN
          IF NEW.message_kind='customer' AND NEW.turn_id IS NULL THEN
            SELECT automation_mode INTO v_mode FROM public.support_tickets
              WHERE tenant_id=NEW.tenant_id AND id=NEW.ticket_id;
            INSERT INTO public.conversation_turns(
              id,tenant_id,ticket_id,customer_message_id,ordinal,activity_state,result_state,
              automation_mode,created_at,updated_at
            ) VALUES (
              'turn_'||pg_catalog.md5(NEW.id),NEW.tenant_id,NEW.ticket_id,NEW.id,
              NEW.conversation_sequence,CASE WHEN v_mode='human_queue' THEN 'completed' ELSE 'accepted' END,
              CASE WHEN v_mode='human_queue' THEN 'human_queue' ELSE NULL END,
              v_mode,NEW.created_at,NEW.updated_at
            ) ON CONFLICT (customer_message_id) DO NOTHING;
            UPDATE public.ticket_messages SET turn_id='turn_'||pg_catalog.md5(NEW.id)
              WHERE tenant_id=NEW.tenant_id AND id=NEW.id AND turn_id IS NULL;
          END IF;
          RETURN NULL;
        END $$;


ALTER FUNCTION public.supportguard_v15_message_after_insert() OWNER TO supportguard_owner;

--
-- Name: supportguard_v15_message_before_insert(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_v15_message_before_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_sequence bigint; v_receipt jsonb;
        BEGIN
          -- Keep an explicit, stable domain error in front of RLS. RLS remains
          -- enabled as the independent fail-closed boundary.
          IF session_user <> 'supportguard'
             AND NULLIF(current_setting('app.tenant_id',true),'') IS DISTINCT FROM NEW.tenant_id THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='tenant_scope_mismatch';
          END IF;
          IF NEW.conversation_sequence IS NULL THEN
            UPDATE public.support_tickets SET next_message_sequence=next_message_sequence+1
            WHERE tenant_id=NEW.tenant_id AND id=NEW.ticket_id
            RETURNING next_message_sequence INTO v_sequence;
            IF v_sequence IS NULL THEN RAISE EXCEPTION 'conversation_not_found'; END IF;
            NEW.conversation_sequence := v_sequence;
          END IF;
          UPDATE public.support_tickets
          SET last_message_at=greatest(
            coalesce(last_message_at,created_at),
            coalesce(NEW.created_at,pg_catalog.statement_timestamp())
          )
          WHERE tenant_id=NEW.tenant_id AND id=NEW.ticket_id;
          IF NOT FOUND THEN RAISE EXCEPTION 'conversation_not_found'; END IF;
          NEW.message_kind := coalesce(NEW.message_kind,
            CASE WHEN NEW.role IN ('user','customer') THEN 'customer' ELSE 'assistant' END);
          IF NEW.message_kind='customer' THEN
            BEGIN
              v_receipt := nullif(current_setting('app.ingress_redaction_receipt',true),'')::jsonb;
            EXCEPTION WHEN others THEN
              v_receipt := NULL;
            END;
            IF pg_catalog.jsonb_typeof(v_receipt)='array' AND pg_catalog.jsonb_array_length(v_receipt)>0 THEN
              NEW.source_refs := v_receipt;
            END IF;
          END IF;
          RETURN NEW;
        END $$;


ALTER FUNCTION public.supportguard_v15_message_before_insert() OWNER TO supportguard_owner;

--
-- Name: supportguard_v15_run_after_write(); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_v15_run_after_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_state text; v_result text; v_mode text;
        BEGIN
          SELECT automation_mode INTO v_mode FROM public.support_tickets
            WHERE tenant_id=NEW.tenant_id AND id=NEW.ticket_id;
          v_state := CASE NEW.status WHEN 'interrupted' THEN 'waiting_external'
            WHEN 'completed' THEN 'completed' WHEN 'failed' THEN 'failed'
            WHEN 'running' THEN 'running' ELSE 'queued' END;
          v_result := CASE
            WHEN NEW.status='interrupted' THEN 'proposal_created'
            WHEN NEW.status='failed' THEN 'failed'
            WHEN NEW.status<>'completed' THEN NULL
            WHEN NEW.agent_finish_reason='needs_clarification' THEN 'needs_clarification'
            WHEN NEW.agent_finish_reason='evidence_freshness_insufficient' THEN 'answered_limited'
            WHEN NEW.agent_finish_reason IN ('rejected','refused','out_of_scope') THEN 'refused'
            WHEN NEW.agent_finish_reason IN ('proposed','proposal_created') THEN 'proposal_created'
            WHEN NEW.agent_finish_reason='manual_takeover' AND v_mode='human_queue' THEN 'human_queue'
            WHEN NEW.agent_finish_reason IN (
              'provider_failed','provider_decision_invalid','provider_terminal_schema_invalid','tool_failed',
              'policy_failed','proposal_eligibility_failed','citation_binding_incomplete','insufficient_evidence',
              'no_progress','budget_exhausted','tool_round_budget_exhausted','tool_attempt_budget_exhausted',
              'llm_call_budget_exhausted','context_budget_exhausted','time_budget_exhausted',
              'logical_degradation','binding_stale','manual_takeover') THEN 'failed'
            ELSE 'answered' END;
          UPDATE public.conversation_turns SET run_id=NEW.id,activity_state=v_state,result_state=v_result,
            model=NEW.model,provider_mode=NEW.provider_mode,tool_call_mode=NEW.tool_call_mode,
            context_version=NEW.context_version,completed_at=NEW.completed_at,updated_at=NEW.updated_at
          WHERE tenant_id=NEW.tenant_id AND customer_message_id=NEW.message_id;
          UPDATE public.agent_runs SET turn_id=(SELECT ct.id FROM public.conversation_turns ct
            WHERE ct.tenant_id=NEW.tenant_id AND ct.customer_message_id=NEW.message_id)
          WHERE id=NEW.id AND turn_id IS NULL;
          UPDATE public.ticket_messages SET run_id=NEW.id
          WHERE tenant_id=NEW.tenant_id AND id=NEW.message_id
            AND message_kind='customer'
            AND run_id IS NULL;
          IF NOT FOUND THEN
            PERFORM 1 FROM public.ticket_messages
            WHERE tenant_id=NEW.tenant_id AND id=NEW.message_id
              AND message_kind='customer' AND run_id=NEW.id;
            IF NOT FOUND THEN
              RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='customer_message_run_binding_missing';
            END IF;
          END IF;
          RETURN NULL;
        END $$;


ALTER FUNCTION public.supportguard_v15_run_after_write() OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_accept_delivery(jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_accept_delivery(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
        DECLARE v_required text[]:=ARRAY[
          'schema_version','event_id','delivery_id','job_id','run_id','tenant_id',
          'generation','redis_message_id','consumer_group','owner','payload_hash'
        ]; v_result jsonb; v_job public.runtime_jobs%ROWTYPE;
        BEGIN
          IF session_user<>'supportguard_worker' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker_role_required';
          END IF;
          IF jsonb_typeof(p_payload)<>'object'
             OR p_payload->>'schema_version'<>'worker-delivery.v1'
             OR NOT p_payload ?& v_required OR p_payload-v_required<>'{}'::jsonb
             OR coalesce(length(p_payload->>'event_id'),0)=0
             OR coalesce(length(p_payload->>'delivery_id'),0)=0
             OR coalesce(length(p_payload->>'job_id'),0)=0
             OR coalesce(length(p_payload->>'run_id'),0)=0
             OR coalesce(length(p_payload->>'tenant_id'),0)=0
             OR coalesce(length(p_payload->>'redis_message_id'),0)=0
             OR coalesce(length(p_payload->>'consumer_group'),0)=0
             OR coalesce(length(p_payload->>'owner'),0)=0
             OR (p_payload->>'payload_hash') !~ '^[0-9a-f]{64}$'
             OR jsonb_typeof(p_payload->'generation')<>'number' THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker_delivery_schema_invalid';
          END IF;
          v_result:=public.supportguard_worker_accept_delivery(
            p_payload->>'event_id',p_payload->>'delivery_id',p_payload->>'job_id',
            p_payload->>'run_id',p_payload->>'tenant_id',
            (p_payload->>'generation')::integer,p_payload->>'redis_message_id',
            p_payload->>'consumer_group',p_payload->>'owner',p_payload->>'payload_hash'
          );
          IF v_result->>'result'='claimed' THEN
            SELECT * INTO v_job FROM public.runtime_jobs WHERE id=v_result->>'job_id';
            v_result:=v_result||jsonb_build_object(
              'kind',v_job.kind,'approval_id',v_job.approval_id,
              'attempt',v_job.attempt,'ticket_id',v_job.ticket_id,
              'dispatch_sequence',v_job.dispatch_sequence
            );
          END IF;
          RETURN v_result;
        EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
          RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker_delivery_schema_invalid';
        END $_$;


ALTER FUNCTION public.supportguard_worker_accept_delivery(p_payload jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_accept_delivery(text, text, text, text, text, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_accept_delivery(p_event_id text, p_delivery_id text, p_job_id text, p_run_id text, p_tenant_id text, p_generation integer, p_redis_message_id text, p_consumer_group text, p_owner text, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_job public.runtime_jobs%ROWTYPE; v_run public.agent_runs%ROWTYPE;
                v_ticket public.support_tickets%ROWTYPE; v_result jsonb;
        BEGIN
            IF session_user<>'supportguard_worker' THEN
                RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker_role_required';
            END IF;
            SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id;
            IF v_job.id IS NOT NULL THEN
                PERFORM set_config('app.tenant_id',v_job.tenant_id,true);
                SELECT * INTO v_ticket FROM public.support_tickets
                 WHERE tenant_id=v_job.tenant_id AND id=v_job.ticket_id FOR UPDATE;
                SELECT * INTO v_job FROM public.runtime_jobs
                 WHERE tenant_id=v_job.tenant_id AND id=p_job_id FOR UPDATE;
                SELECT * INTO v_run FROM public.agent_runs
                 WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id FOR UPDATE;
            END IF;
            IF v_job.kind='approval_resume' AND NOT EXISTS (
              SELECT 1 FROM public.approval_requests a
              WHERE a.tenant_id=v_job.tenant_id
                AND a.id=v_job.approval_id
                AND a.run_id=v_job.run_id
                AND a.ticket_id=v_job.ticket_id
                AND a.status='approved'
            ) THEN
              RETURN jsonb_build_object('result','not_claimable','ack',false);
            END IF;
            IF v_job.status IN ('queued','retry_wait') AND (
                 v_ticket.id IS NULL
                 OR v_ticket.lifecycle<>'active'
                 OR v_ticket.automation_mode<>'agent'
                 OR EXISTS (
                   SELECT 1 FROM public.runtime_jobs earlier
                   WHERE earlier.tenant_id=v_job.tenant_id
                     AND earlier.ticket_id=v_job.ticket_id
                     AND earlier.dispatch_sequence<v_job.dispatch_sequence
                     AND earlier.status IN ('queued','retry_wait','leased')
                 )
                 OR EXISTS (
                   SELECT 1 FROM public.runtime_jobs active
                   WHERE active.tenant_id=v_job.tenant_id
                     AND active.ticket_id=v_job.ticket_id
                     AND active.id<>v_job.id AND active.status='leased'
                 )
               ) THEN
              RETURN jsonb_build_object('result','not_claimable','ack',false);
            END IF;
            IF v_job.status='leased' AND v_run.active_job_id=v_job.id
               AND NOT (
                 v_job.lease_owner=p_owner
                 AND v_job.lease_expires_at>clock_timestamp()
                 AND v_run.active_fencing_token=v_job.fencing_token
               ) THEN
              RETURN jsonb_build_object('result','active_job_conflict','ack',false);
            END IF;
            PERFORM set_config(
              'app.dead_convergence_authorized','v1512',true
            );
            v_result:=public.supportguard_worker_accept_delivery_d069(
                p_event_id,p_delivery_id,p_job_id,p_run_id,p_tenant_id,p_generation,
                p_redis_message_id,p_consumer_group,p_owner,p_payload_hash
            );
            IF v_result->>'result'='job_exhausted' THEN
              v_result:=v_result||public.supportguard_internal_converge_dead_job(
                v_job.tenant_id,v_job.id
              )||
                public.supportguard_internal_activate_next_ticket_turn(
                  v_job.tenant_id,v_job.ticket_id,v_job.id
                );
            END IF;
            RETURN v_result;
        END $$;


ALTER FUNCTION public.supportguard_worker_accept_delivery(p_event_id text, p_delivery_id text, p_job_id text, p_run_id text, p_tenant_id text, p_generation integer, p_redis_message_id text, p_consumer_group text, p_owner text, p_payload_hash text) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_accept_delivery_d068(text, text, text, text, text, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_accept_delivery_d068(p_event_id text, p_delivery_id text, p_job_id text, p_run_id text, p_tenant_id text, p_generation integer, p_redis_message_id text, p_consumer_group text, p_owner text, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_job public.runtime_jobs%ROWTYPE; v_run public.agent_runs%ROWTYPE;
                v_outbox public.outbox_events%ROWTYPE; v_inbox public.inbox_deliveries%ROWTYPE;
                v_timing supportguard_control.runtime_timing_snapshots%ROWTYPE;
                v_now timestamptz := clock_timestamp(); v_mismatch boolean;
        BEGIN
            IF session_user <> 'supportguard_worker' THEN
                RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='worker capability caller is not authorized';
            END IF;
            SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id;
            IF v_job.id IS NOT NULL THEN
                SELECT * INTO v_run FROM public.agent_runs
                 WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id FOR UPDATE;
                SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id FOR UPDATE;
            END IF;
            SELECT * INTO v_outbox FROM public.outbox_events WHERE id=p_event_id FOR UPDATE;
            v_mismatch := v_job.id IS NULL OR v_run.id IS NULL OR v_outbox.id IS NULL
                OR v_job.tenant_id<>p_tenant_id OR v_job.run_id<>p_run_id
                OR v_job.kind NOT IN ('agent_start','approval_resume')
                OR v_outbox.delivery_id<>p_delivery_id OR v_outbox.job_id<>p_job_id
                OR v_outbox.run_id<>p_run_id OR v_outbox.tenant_id<>p_tenant_id
                OR v_outbox.delivery_generation<>p_generation OR v_outbox.superseded_at IS NOT NULL;
            IF v_mismatch THEN
                INSERT INTO public.queue_delivery_audits(
                    id,tenant_id,job_id,delivery_id,redis_message_id,consumer_group,
                    outcome,payload_hash,details,created_at,updated_at
                ) VALUES (
                    'qaudit_'||replace(gen_random_uuid()::text,'-',''),v_job.tenant_id,p_job_id,
                    p_delivery_id,left(p_redis_message_id,64),left(p_consumer_group,64),
                    'rejected_untrusted_envelope',left(p_payload_hash,64),
                    jsonb_build_object('job_exists',v_job.id IS NOT NULL,
                        'outbox_exists',v_outbox.id IS NOT NULL),v_now,v_now
                );
                RETURN jsonb_build_object('result','rejected_untrusted_envelope','ack',true);
            END IF;
            SELECT * INTO v_timing FROM supportguard_control.runtime_timing_snapshots
             WHERE timing_version=v_job.timing_version;
            IF v_timing.timing_version IS NULL THEN
                RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='job_runtime_timing_missing';
            END IF;
            IF v_job.delivery_hold_reason IS NOT NULL THEN
                RETURN jsonb_build_object('result','delivery_state_unknown','ack',false);
            END IF;
            IF v_job.status IN ('succeeded','dead') THEN
                UPDATE public.inbox_deliveries SET status='acked',outcome='already_terminal',
                    terminal_at=coalesce(terminal_at,v_now),updated_at=v_now
                 WHERE consumer_group=p_consumer_group AND delivery_id=p_delivery_id;
                RETURN jsonb_build_object('result','already_terminal','ack',true);
            END IF;
            SELECT * INTO v_inbox FROM public.inbox_deliveries
             WHERE consumer_group=p_consumer_group AND delivery_id=p_delivery_id FOR UPDATE;
            IF v_inbox.id IS NULL THEN
                INSERT INTO public.inbox_deliveries(
                    id,tenant_id,job_id,delivery_id,redis_message_id,consumer_group,status,
                    outcome,created_at,updated_at
                ) VALUES (
                    'inbox_'||replace(gen_random_uuid()::text,'-',''),v_job.tenant_id,v_job.id,
                    p_delivery_id,left(p_redis_message_id,64),left(p_consumer_group,64),
                    'received',NULL,v_now,v_now
                ) RETURNING * INTO v_inbox;
            ELSIF v_inbox.status='acked' THEN
                RETURN jsonb_build_object('result','already_acked','ack',true);
            END IF;
            IF v_job.status='leased' AND v_job.lease_owner=p_owner
               AND v_run.active_job_id=v_job.id
               AND v_run.active_fencing_token=v_job.fencing_token
               AND v_job.lease_expires_at>v_now THEN
                RETURN jsonb_build_object('result','claimed','ack',false,'reused',true,
                    'job_id',v_job.id,'run_id',v_job.run_id,'tenant_id',v_job.tenant_id,
                    'owner',p_owner,'fencing_token',v_job.fencing_token,
                    'expires_at',v_job.lease_expires_at);
            END IF;
            IF v_run.active_job_id IS NOT NULL AND v_run.active_job_id<>v_job.id THEN
                RETURN jsonb_build_object('result','active_job_conflict','ack',false);
            END IF;
            IF v_job.attempt>=v_timing.max_attempts
               OR v_now-v_job.created_at>=make_interval(secs=>v_timing.max_job_age_seconds) THEN
                UPDATE public.runtime_jobs SET status='dead',terminal_at=v_now,status_version=status_version+1,
                    last_error=CASE WHEN v_job.attempt>=v_timing.max_attempts
                        THEN 'worker_retry_exhausted' ELSE 'job_max_age_exhausted' END,
                    lease_owner=NULL,lease_expires_at=NULL,heartbeat_at=NULL,updated_at=v_now
                 WHERE id=v_job.id;
                -- Cross-aggregate convergence is owned by the v1.5.12
                -- Ticket-first helper after this legacy capability returns.
                UPDATE public.inbox_deliveries SET status='acked',outcome='job_exhausted',
                    terminal_at=v_now,updated_at=v_now WHERE id=v_inbox.id;
                RETURN jsonb_build_object('result','job_exhausted','ack',true);
            END IF;
            IF v_job.status NOT IN ('queued','retry_wait') OR v_job.available_at>v_now
               OR v_run.status NOT IN ('queued','interrupted','running') THEN
                UPDATE public.inbox_deliveries SET status='rejected',outcome='not_claimable',
                    terminal_at=v_now,updated_at=v_now WHERE id=v_inbox.id;
                RETURN jsonb_build_object('result','not_claimable','ack',false);
            END IF;
            PERFORM 1 FROM public.support_tickets WHERE id=v_run.ticket_id
             AND tenant_id=v_job.tenant_id FOR UPDATE;
            IF NOT FOUND THEN RAISE EXCEPTION 'trusted ticket is missing'; END IF;
            UPDATE public.runtime_jobs SET status='leased',attempt=attempt+1,lease_owner=p_owner,
                heartbeat_at=v_now,lease_expires_at=v_now+make_interval(secs=>v_timing.lease_seconds),
                fencing_token=fencing_token+1,status_version=status_version+1,updated_at=v_now
             WHERE id=v_job.id RETURNING * INTO v_job;
            UPDATE public.agent_runs SET active_job_id=v_job.id,
                active_fencing_token=v_job.fencing_token,status='running',
                status_version=status_version+1,updated_at=v_now WHERE id=v_run.id;
            UPDATE public.support_tickets SET status='running',version=version+1,updated_at=v_now
             WHERE id=v_run.ticket_id AND status='queued';
            UPDATE public.inbox_deliveries SET status='claimed',outcome=NULL,
                terminal_at=NULL,updated_at=v_now WHERE id=v_inbox.id;
            RETURN jsonb_build_object('result','claimed','ack',false,'reused',false,
                'job_id',v_job.id,'run_id',v_job.run_id,'tenant_id',v_job.tenant_id,
                'owner',p_owner,'fencing_token',v_job.fencing_token,
                'expires_at',v_job.lease_expires_at);
        END $$;


ALTER FUNCTION public.supportguard_worker_accept_delivery_d068(p_event_id text, p_delivery_id text, p_job_id text, p_run_id text, p_tenant_id text, p_generation integer, p_redis_message_id text, p_consumer_group text, p_owner text, p_payload_hash text) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_accept_delivery_d069(text, text, text, text, text, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_accept_delivery_d069(p_event_id text, p_delivery_id text, p_job_id text, p_run_id text, p_tenant_id text, p_generation integer, p_redis_message_id text, p_consumer_group text, p_owner text, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_job public.runtime_jobs%ROWTYPE; v_run public.agent_runs%ROWTYPE;
        BEGIN
            IF session_user<>'supportguard_worker' THEN
                RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker_role_required';
            END IF;
            SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id FOR UPDATE;
            IF v_job.id IS NOT NULL THEN
                PERFORM set_config('app.tenant_id',v_job.tenant_id,true);
                SELECT * INTO v_run FROM public.agent_runs
                 WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id FOR UPDATE;
            END IF;
            RETURN public.supportguard_worker_accept_delivery_d068(
                p_event_id,p_delivery_id,p_job_id,p_run_id,p_tenant_id,p_generation,
                p_redis_message_id,p_consumer_group,p_owner,p_payload_hash
            );
        END $$;


ALTER FUNCTION public.supportguard_worker_accept_delivery_d069(p_event_id text, p_delivery_id text, p_job_id text, p_run_id text, p_tenant_id text, p_generation integer, p_redis_message_id text, p_consumer_group text, p_owner text, p_payload_hash text) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_claim_job(text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_claim_job(p_job_id text, p_owner text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_job public.runtime_jobs%ROWTYPE;
                v_ticket public.support_tickets%ROWTYPE;
                v_run public.agent_runs%ROWTYPE;
                v_turn public.conversation_turns%ROWTYPE;
                v_now timestamptz:=clock_timestamp();
        BEGIN
          IF session_user<>'supportguard_worker' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker_role_required';
          END IF;
          IF coalesce(length(p_job_id),0)=0 OR coalesce(length(p_owner),0)=0
             OR length(p_job_id)>64 OR length(p_owner)>128 THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker_claim_schema_invalid';
          END IF;
          SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id;
          IF v_job.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='stale_fencing_token';
          END IF;
          PERFORM set_config('app.tenant_id',v_job.tenant_id,true);
          SELECT * INTO v_ticket FROM public.support_tickets
          WHERE tenant_id=v_job.tenant_id AND id=v_job.ticket_id FOR UPDATE;
          SELECT * INTO v_job FROM public.runtime_jobs
          WHERE tenant_id=v_job.tenant_id AND id=p_job_id FOR UPDATE;
          SELECT * INTO v_run FROM public.agent_runs
          WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id FOR UPDATE;
          IF v_run.turn_id IS NOT NULL THEN
            SELECT * INTO v_turn FROM public.conversation_turns
            WHERE tenant_id=v_job.tenant_id AND id=v_run.turn_id FOR UPDATE;
          END IF;
          IF v_ticket.id IS NULL OR v_run.id IS NULL
             OR v_run.ticket_id IS DISTINCT FROM v_job.ticket_id
             OR v_job.status<>'leased' OR v_job.lease_owner<>p_owner
             OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at<=v_now
             OR v_run.active_job_id IS DISTINCT FROM v_job.id
             OR v_run.active_fencing_token IS DISTINCT FROM v_job.fencing_token
             OR EXISTS (
               SELECT 1 FROM public.runtime_jobs earlier
               WHERE earlier.tenant_id=v_job.tenant_id
                 AND earlier.ticket_id=v_job.ticket_id
                 AND earlier.dispatch_sequence<v_job.dispatch_sequence
                 AND earlier.status IN ('queued','retry_wait','leased')
             )
             OR (v_job.kind='approval_resume' AND NOT EXISTS (
               SELECT 1 FROM public.approval_requests a
               WHERE a.tenant_id=v_job.tenant_id
                 AND a.id=v_job.approval_id AND a.run_id=v_job.run_id
                 AND a.ticket_id=v_job.ticket_id
                 AND a.status IN ('approved','executed','stale')
             )) THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='stale_fencing_token';
          END IF;
          RETURN jsonb_build_object(
            'job_id',v_job.id,'run_id',v_job.run_id,'tenant_id',v_job.tenant_id,
            'ticket_id',v_job.ticket_id,'dispatch_sequence',v_job.dispatch_sequence,
            'owner',v_job.lease_owner,'fencing_token',v_job.fencing_token,
            'expires_at',v_job.lease_expires_at,'kind',v_job.kind,
            'approval_id',v_job.approval_id,'attempt',v_job.attempt,'status_version',v_job.status_version,'last_error',v_job.last_error,'conversation_action_sources',coalesce((
      SELECT pg_catalog.jsonb_agg(
        selected.source_bundle
        ORDER BY selected.updated_at DESC,selected.created_at DESC,selected.id DESC
      )
      FROM (
        SELECT
          action_approval.id,
          action_approval.created_at,
          action_approval.updated_at,
          (
      SELECT pg_catalog.jsonb_build_object(
        'schema_version','conversation-action-source-bundle.v1',
        'approval',pg_catalog.jsonb_build_object(
          'id',action_approval.id,
          'tenant_id',action_approval.tenant_id,
          'ticket_id',action_approval.ticket_id,
          'customer_id',action_approval.customer_id,
          'proposal_id',action_approval.proposal_id,
          'run_id',action_approval.run_id,
          'action_type',action_approval.action_type,
          'resource_type',action_approval.resource_type,
          'resource_id',action_approval.resource_id,
          'origin_turn_id',action_approval.origin_turn_id,
          'business_version',action_approval.business_version,
          'status',action_approval.status,
          'status_version',action_approval.status_version,
          'expected_ticket_head_event_id',action_approval.expected_ticket_head_event_id,
          'expected_ticket_event_hash',action_approval.expected_ticket_event_hash,
          'transition_event_id',transition.value->>'id',
          'transition_event_hash',transition.value->>'event_hash',
          'transition_event_type',transition.value->>'event_type',
          'created_at',action_approval.created_at,
          'updated_at',action_approval.updated_at
        ),
        'proposal',(
          SELECT pg_catalog.jsonb_build_object(
            'id',proposal.id,
            'tenant_id',proposal.tenant_id,
            'run_id',proposal.run_id,
            'action_type',proposal.action_type,
            'resource_id',proposal.resource_id,
            'resource_version',proposal.resource_version,
            'status',proposal.status,
            'created_at',proposal.created_at,
            'updated_at',proposal.updated_at
          )
          FROM public.proposal_records proposal
          WHERE proposal.tenant_id=action_approval.tenant_id
            AND proposal.id=action_approval.proposal_id
          LIMIT 1
        ),
        'decision',(
          SELECT pg_catalog.jsonb_build_object(
            'id',decision.id,
            'tenant_id',decision.tenant_id,
            'approval_id',decision.approval_id,
            'decision',decision.decision,
            'canonical_event_id',decision.canonical_event_id,
            'canonical_event_hash',decision.canonical_event_hash,
            'created_at',decision.created_at,
            'updated_at',decision.updated_at
          )
          FROM public.human_decisions decision
          WHERE decision.tenant_id=action_approval.tenant_id
            AND decision.approval_id=action_approval.id
          ORDER BY decision.created_at DESC,decision.id DESC
          LIMIT 1
        ),
        'business_action',(
          SELECT pg_catalog.jsonb_build_object(
            'id',business_action.id,
            'tenant_id',business_action.tenant_id,
            'ticket_id',business_action.ticket_id,
            'customer_id',business_action.customer_id,
            'approval_id',business_action.approval_id,
            'action_type',business_action.action_type,
            'resource_id',business_action.resource_id,
            'resource_version',business_action.resource_version,
            'status',business_action.status,
            'canonical_event_id',business_action.canonical_event_id,
            'canonical_event_hash',business_action.canonical_event_hash,
            'created_at',business_action.created_at,
            'updated_at',business_action.updated_at
          )
          FROM public.business_actions business_action
          WHERE business_action.tenant_id=action_approval.tenant_id
            AND business_action.approval_id=action_approval.id
          ORDER BY business_action.created_at DESC,business_action.id DESC
          LIMIT 1
        ),
        'withdrawal',(
          SELECT pg_catalog.jsonb_build_object(
            'id',withdrawal.id,
            'tenant_id',withdrawal.tenant_id,
            'ticket_id',withdrawal.ticket_id,
            'customer_id',withdrawal.customer_id,
            'approval_id',withdrawal.approval_id,
            'proposal_id',withdrawal.proposal_id,
            'created_at',withdrawal.created_at,
            'updated_at',withdrawal.updated_at
          )
          FROM public.proposal_withdrawals withdrawal
          WHERE withdrawal.tenant_id=action_approval.tenant_id
            AND withdrawal.approval_id=action_approval.id
          ORDER BY withdrawal.created_at DESC,withdrawal.id DESC
          LIMIT 1
        ),
        'runtime_job',(
          SELECT pg_catalog.jsonb_build_object(
            'id',approval_job.id,
            'tenant_id',approval_job.tenant_id,
            'ticket_id',approval_job.ticket_id,
            'run_id',approval_job.run_id,
            'approval_id',approval_job.approval_id,
            'kind',approval_job.kind,
            'status',approval_job.status,
            'outcome',approval_job.outcome,
            'delivery_hold_reason',approval_job.delivery_hold_reason,
            'created_at',approval_job.created_at,
            'updated_at',approval_job.updated_at
          )
          FROM public.runtime_jobs approval_job
          WHERE approval_job.tenant_id=action_approval.tenant_id
            AND approval_job.approval_id=action_approval.id
            AND approval_job.kind='approval_resume'
          ORDER BY approval_job.created_at DESC,approval_job.id DESC
          LIMIT 1
        )
      )
      FROM (SELECT (
      SELECT pg_catalog.jsonb_build_object(
        'id',event.id,
        'event_hash',event.event_hash,
        'event_type',event.event_type
      )
      FROM public.agent_events event
      WHERE event.tenant_id=action_approval.tenant_id
        AND event.ticket_id=action_approval.ticket_id
        AND event.run_id=action_approval.run_id
        AND (
          (
            action_approval.status='withdrawn'
            AND event.event_type='proposal_withdrawn'
            AND event.payload->>'approval_id'=action_approval.id
          )
          OR (
            action_approval.status='stale'
            AND event.event_type IN (
              'runtime_action_reconciliation',
              'approval_staled_duplicate_identity'
            )
            AND event.payload->>'approval_id'=action_approval.id
          )
          OR (
            action_approval.status='failed'
            AND event.event_type='runtime_failed'
            AND EXISTS (
              SELECT 1
              FROM public.runtime_jobs failed_job
              WHERE failed_job.tenant_id=action_approval.tenant_id
                AND failed_job.id=event.job_id
                AND failed_job.ticket_id=action_approval.ticket_id
                AND failed_job.run_id=action_approval.run_id
                AND failed_job.approval_id=action_approval.id
            )
          )
        )
      ORDER BY event.ticket_sequence DESC,event.id DESC
      LIMIT 1
    ) AS value) transition
    ) AS source_bundle
        FROM public.approval_requests action_approval
        WHERE action_approval.tenant_id=v_job.tenant_id AND action_approval.customer_id=v_ticket.customer_id AND (action_approval.ticket_id=v_job.ticket_id OR EXISTS (SELECT 1 FROM public.ticket_messages action_alias WHERE action_alias.tenant_id=action_approval.tenant_id AND action_alias.ticket_id=v_job.ticket_id AND action_alias.approval_id=action_approval.id))
        ORDER BY action_approval.updated_at DESC,action_approval.created_at DESC,action_approval.id DESC
        LIMIT 100
      ) selected
    ),'[]'::jsonb)
          );
        END $$;


ALTER FUNCTION public.supportguard_worker_claim_job(p_job_id text, p_owner text) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_execute_approved_action(text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_execute_approved_action(p_approval_id text, p_human_decision_id text, p_job_id text, p_fencing_token bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE
          v_tenant_id text:=current_setting('app.tenant_id',true);
          v_job_probe public.runtime_jobs%ROWTYPE;
          v_job public.runtime_jobs%ROWTYPE;
          v_ticket public.support_tickets%ROWTYPE;
          v_approval public.approval_requests%ROWTYPE;
          v_proposal public.proposal_records%ROWTYPE;
          v_run public.agent_runs%ROWTYPE;
          v_turn public.conversation_turns%ROWTYPE;
          v_decision public.human_decisions%ROWTYPE;
          v_revision public.approval_action_revisions%ROWTYPE;
          v_decision_event public.agent_events%ROWTYPE;
          v_marker public.checkpoint_commit_markers%ROWTYPE;
          v_finalizer public.finalizer_payloads%ROWTYPE;
          v_snapshot public.approval_snapshots%ROWTYPE;
          v_policy_invocation public.policy_capability_invocations%ROWTYPE;
          v_policy_result public.policy_capability_results%ROWTYPE;
          v_existing public.business_actions%ROWTYPE;
          v_billing public.billing_records%ROWTYPE;
          v_key public.api_key_metadata%ROWTYPE;
          v_subscription public.subscriptions%ROWTYPE;
          v_catalog public.plan_catalog%ROWTYPE;
          v_membership_id text;
          v_scope_actor_id text;
          v_expected_resource_type text;
          v_payload_resource_id text;
          v_resource_id text;
          v_effect_identity text;
          v_action_id text;
          v_idempotency_key text;
          v_result jsonb;
          v_target jsonb;
          v_before jsonb;
          v_change_type text;
          v_stale_reason text;
          v_expected_capability text;
          v_claim_binding_refs jsonb;
          v_snapshot_binding_refs jsonb;
          v_lineage_binding_refs jsonb;
          v_snapshot_payload jsonb;
          v_rows bigint;
          v_replay_effect_visible boolean:=false;
        BEGIN
          IF session_user<>'supportguard_worker' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker_role_required';
          END IF;
          IF v_tenant_id IS NULL OR v_tenant_id='' OR p_approval_id IS NULL
             OR p_human_decision_id IS NULL OR p_job_id IS NULL
             OR p_fencing_token IS NULL OR p_fencing_token<1 THEN
            RAISE EXCEPTION USING ERRCODE='22023',
              MESSAGE='runtime_action_input_invalid';
          END IF;

          -- Identity discovery is deliberately lock-free.  Every value is
          -- re-read below after the aggregate's canonical locks are acquired.
          SELECT * INTO v_job_probe
          FROM public.runtime_jobs job
          WHERE job.tenant_id=v_tenant_id AND job.id=p_job_id;
          IF v_job_probe.id IS NULL
             OR v_job_probe.kind<>'approval_resume'
             OR v_job_probe.approval_id IS DISTINCT FROM p_approval_id
             OR v_job_probe.ticket_id IS NULL
             OR v_job_probe.run_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_binding_invalid';
          END IF;

          -- Frozen Worker Execute order:
          -- Ticket -> Approval/Proposal -> Run/Turn -> RuntimeJob ->
          -- immutable Decision/Revision -> business Resource/Action.
          SELECT * INTO v_ticket
          FROM public.support_tickets ticket
          WHERE ticket.tenant_id=v_tenant_id
            AND ticket.id=v_job_probe.ticket_id
          FOR UPDATE;
          IF v_ticket.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_binding_invalid';
          END IF;

          SELECT * INTO v_approval
          FROM public.approval_requests approval
          WHERE approval.tenant_id=v_tenant_id
            AND approval.id=p_approval_id
            AND approval.ticket_id=v_ticket.id
            AND approval.run_id=v_job_probe.run_id
            AND approval.customer_id=v_ticket.customer_id
          FOR UPDATE;
          IF v_approval.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_binding_invalid';
          END IF;

          -- The terminal transition invalidates every still-live Proposal for
          -- the same action resource.  Lock that complete set (plus the
          -- current Proposal even if its binding is malformed) in one stable
          -- order before any Run or business-resource lock.  Locking only the
          -- current row here and discovering siblings after the resource CAS
          -- lets two Tickets each hold one Proposal and wait on the other.
          PERFORM proposal.id
          FROM public.proposal_records proposal
          WHERE proposal.tenant_id=v_tenant_id
            AND (
              proposal.id=v_approval.proposal_id
              OR (
                proposal.action_type=v_approval.action_type
                AND proposal.resource_id=v_approval.resource_id
                AND proposal.status IN ('draft','bound')
              )
            )
          ORDER BY proposal.id
          FOR UPDATE;
          SELECT * INTO v_proposal
          FROM public.proposal_records proposal
          WHERE proposal.tenant_id=v_tenant_id
            AND proposal.id=v_approval.proposal_id
            AND proposal.run_id=v_approval.run_id;

          SELECT * INTO v_run
          FROM public.agent_runs run
          WHERE run.tenant_id=v_tenant_id
            AND run.id=v_approval.run_id
            AND run.ticket_id=v_approval.ticket_id
            AND run.customer_id=v_approval.customer_id
          FOR UPDATE;
          IF v_run.id IS NULL
             OR v_run.turn_id IS DISTINCT FROM v_approval.origin_turn_id THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_binding_invalid';
          END IF;

          SELECT * INTO v_turn
          FROM public.conversation_turns turn_row
          WHERE turn_row.tenant_id=v_tenant_id
            AND turn_row.id=v_approval.origin_turn_id
            AND turn_row.ticket_id=v_approval.ticket_id
            AND turn_row.run_id=v_approval.run_id
          FOR UPDATE;
          IF v_turn.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_binding_invalid';
          END IF;

          SELECT * INTO v_job
          FROM public.runtime_jobs job
          WHERE job.tenant_id=v_tenant_id
            AND job.id=v_job_probe.id
            AND job.kind='approval_resume'
            AND job.approval_id=v_approval.id
            AND job.run_id=v_approval.run_id
            AND job.ticket_id=v_approval.ticket_id
            AND job.dispatch_sequence=v_job_probe.dispatch_sequence
          FOR UPDATE;
          IF v_job.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_binding_invalid';
          END IF;
          IF v_job.status<>'leased'
             OR v_job.fencing_token<>p_fencing_token
             OR v_run.active_job_id IS DISTINCT FROM v_job.id
             OR v_run.active_fencing_token IS DISTINCT FROM v_job.fencing_token THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='stale_fencing_token';
          END IF;

          -- The action carries no caller-supplied publication document.  Its
          -- only admissible source is the unique fenced approval-resume
          -- checkpoint owned by this Job.  Segment.finalize has already
          -- verified and rebuilt the payload, but the mutation capability
          -- independently proves the durable identity and hashes.
          SELECT * INTO v_marker
          FROM public.checkpoint_commit_markers marker
          WHERE marker.tenant_id=v_tenant_id
            AND marker.run_id=v_job.run_id
            AND marker.job_id=v_job.id
            AND marker.fencing_token=v_job.fencing_token
            AND marker.segment_kind='approval_resume'
            AND marker.status IN ('checkpoint_written','finalized');
          IF v_marker.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_finalizer_binding_invalid';
          END IF;
          SELECT * INTO v_finalizer
          FROM public.finalizer_payloads payload
          WHERE payload.tenant_id=v_tenant_id
            AND payload.run_id=v_job.run_id
            AND payload.job_id=v_job.id
            AND payload.marker_id=v_marker.id
            AND payload.fencing_token=v_job.fencing_token;
          IF v_finalizer.id IS NULL
             OR v_finalizer.schema_version<>'finalizer.v2'
             OR v_finalizer.payload::jsonb->>'schema_version'<>'finalizer.v2'
             OR v_finalizer.payload::jsonb->>'canonicalization_version'
                  <>'canonical-json.v1'
             OR v_finalizer.payload::jsonb->>'tenant_id'<>v_tenant_id
             OR v_finalizer.payload::jsonb->>'ticket_id'<>v_ticket.id
             OR v_finalizer.payload::jsonb->>'run_id'<>v_run.id
             OR v_finalizer.payload::jsonb->>'job_id'<>v_job.id
             OR v_finalizer.payload::jsonb->>'marker_id'<>v_marker.id
             OR v_finalizer.payload::jsonb->>'segment_id'<>v_marker.id
             OR v_finalizer.payload::jsonb->>'segment_kind'
                  <>'approval_resume'
             OR (v_finalizer.payload::jsonb->>'fencing_token')::bigint
                  <>v_job.fencing_token
             OR (v_finalizer.payload::jsonb->>'delivery_generation')::integer
                  <>v_marker.delivery_generation
             OR v_finalizer.payload::jsonb->>'prepared_payload_hash'
                  IS DISTINCT FROM v_marker.prepared_payload_hash
             OR v_finalizer.payload::jsonb->'state_delta'
                  IS DISTINCT FROM v_finalizer.state_delta::jsonb
             OR v_finalizer.payload::jsonb->'domain_delta'
                  IS DISTINCT FROM v_finalizer.domain_delta::jsonb
             OR v_finalizer.payload::jsonb->'expected_heads'
                  IS DISTINCT FROM v_finalizer.expected_heads::jsonb
             OR v_finalizer.payload::jsonb->>'payload_hash'
                  IS DISTINCT FROM v_finalizer.payload_hash
             OR encode(sha256(convert_to(supportguard_canonical_jsonb(
                  v_finalizer.payload::jsonb-'payload_hash'
                ),'UTF8')),'hex') IS DISTINCT FROM v_finalizer.payload_hash
             OR encode(sha256(convert_to(supportguard_canonical_jsonb(
                  v_finalizer.payload::jsonb->'state_delta'
                ),'UTF8')),'hex') IS DISTINCT FROM
                  v_finalizer.payload::jsonb->>'state_delta_hash'
             OR encode(sha256(convert_to(supportguard_canonical_jsonb(
                  v_finalizer.payload::jsonb->'domain_delta'
                ),'UTF8')),'hex') IS DISTINCT FROM
                  v_finalizer.payload::jsonb->>'domain_delta_hash'
             OR v_finalizer.payload::jsonb#>>'{domain_delta,variant}'
                  <>'approval_action_intent'
             OR v_finalizer.payload::jsonb#>>'{domain_delta,outcome}'
                  <>'completed'
             OR v_finalizer.payload::jsonb#>>'{domain_delta,approval_id}'
                  <>v_approval.id
             OR v_finalizer.payload::jsonb#>>'{domain_delta,human_decision_id}'
                  <>p_human_decision_id
             OR v_finalizer.payload::jsonb#>>'{domain_delta,decision}'
                  NOT IN ('approve','edit_and_approve')
             OR v_finalizer.payload::jsonb#>>'{domain_delta,action_hash}'
                  <>v_approval.action_hash
             OR v_finalizer.payload::jsonb#>>'{domain_delta,execution_intent}'
                  <>'execute_runtime_action'
             OR v_finalizer.payload::jsonb#>>'{domain_delta,expected_approval_status}'
                  NOT IN ('approved','executed') THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_finalizer_binding_invalid';
          END IF;

          SELECT * INTO v_decision
          FROM public.human_decisions decision_row
          WHERE decision_row.tenant_id=v_tenant_id
            AND decision_row.id=p_human_decision_id
            AND decision_row.approval_id=v_approval.id;
          SELECT * INTO v_revision
          FROM public.approval_action_revisions revision
          WHERE revision.tenant_id=v_tenant_id
            AND revision.id=v_approval.selected_revision_id
            AND revision.approval_id=v_approval.id
            AND revision.proposal_id=v_approval.proposal_id
            AND revision.revision_number=v_approval.selected_revision_number;
          IF v_decision.canonical_event_id IS NOT NULL THEN
            SELECT * INTO v_decision_event
            FROM public.agent_events event
            WHERE event.tenant_id=v_tenant_id
              AND event.id=v_decision.canonical_event_id
              AND event.run_id=v_approval.run_id
              AND event.ticket_id=v_approval.ticket_id
              AND event.event_type='human_decision_accepted';
          END IF;

          IF v_proposal.id IS NULL
             OR v_decision.id IS NULL
             OR v_revision.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_binding_invalid';
          END IF;

          v_expected_resource_type:=CASE v_approval.action_type
            WHEN 'refund' THEN 'billing_record_id'
            WHEN 'api_key_revocation' THEN 'api_key_id'
            WHEN 'entitlement_change' THEN 'subscription_id'
            ELSE NULL END;
          v_resource_id:=v_approval.resource_id;
          v_payload_resource_id:=CASE v_approval.action_type
            WHEN 'refund' THEN v_revision.action_payload->>'billing_record_id'
            WHEN 'api_key_revocation' THEN v_revision.action_payload->>'api_key_id'
            WHEN 'entitlement_change' THEN v_revision.action_payload->>'subscription_id'
            ELSE NULL END;

          IF v_expected_resource_type IS NULL
             OR v_approval.resource_type IS DISTINCT FROM v_expected_resource_type
             OR v_resource_id IS NULL OR v_resource_id=''
             OR v_payload_resource_id IS DISTINCT FROM v_resource_id
             OR v_job.approval_id IS DISTINCT FROM v_approval.id
             OR v_decision.decision NOT IN ('approve','edit_and_approve')
             OR v_finalizer.payload::jsonb#>>'{domain_delta,decision}'
                  IS DISTINCT FROM v_decision.decision
             OR v_decision.action_revision_id IS DISTINCT FROM v_revision.id
             OR v_decision.action_hash IS DISTINCT FROM v_revision.action_hash
             OR v_decision.decision_hash IS NULL
             OR v_decision.canonical_event_id IS NULL
             OR v_decision.canonical_event_hash IS NULL
             OR v_decision_event.id IS NULL
             OR v_decision_event.event_hash IS DISTINCT FROM
                  v_decision.canonical_event_hash
             OR v_proposal.action_type IS DISTINCT FROM v_approval.action_type
             OR v_proposal.resource_id IS DISTINCT FROM v_resource_id
             OR v_proposal.resource_version IS DISTINCT FROM
                  v_approval.business_version
             OR v_revision.resource_version IS DISTINCT FROM
                  v_approval.business_version
             OR v_approval.action_hash IS DISTINCT FROM v_proposal.action_hash
             OR (
               v_revision.revision_number=0
               AND (
                 v_revision.action_hash IS DISTINCT FROM v_proposal.action_hash
                 OR v_revision.action_payload::jsonb IS DISTINCT FROM
                      v_proposal.action_payload::jsonb
               )
             )
             OR (
               v_revision.revision_number<>0
               AND (
                 v_decision.decision<>'edit_and_approve'
                 OR v_revision.revision_number<>1
                 OR v_revision.action_hash IS DISTINCT FROM
                      encode(sha256(convert_to(
                        supportguard_canonical_jsonb(
                          v_revision.action_payload::jsonb
                        ),'UTF8'
                      )),'hex')
                 OR NOT coalesce(CASE v_approval.action_type
                   WHEN 'refund' THEN
                     (v_revision.action_payload::jsonb-'refund_reason')
                       IS NOT DISTINCT FROM
                       (v_proposal.action_payload::jsonb-'refund_reason')
                     AND pg_catalog.jsonb_typeof(
                       v_revision.action_payload::jsonb->'refund_reason'
                     )='string'
                     AND pg_catalog.btrim(coalesce(
                       v_revision.action_payload->>'refund_reason',''
                     ))<>''
                   WHEN 'entitlement_change' THEN
                     v_proposal.action_payload->>'change_type'='quota_change'
                     AND pg_catalog.jsonb_typeof(
                       v_proposal.action_payload::jsonb->'target'
                     )='object'
                     AND (v_proposal.action_payload::jsonb->'target')
                           - 'concurrency_limit'::text = '{}'::jsonb
                     AND (SELECT pg_catalog.count(*)
                          FROM pg_catalog.jsonb_object_keys(
                            v_proposal.action_payload::jsonb->'target'
                          ))=1
                     AND (v_revision.action_payload::jsonb-'target')
                       IS NOT DISTINCT FROM
                       (v_proposal.action_payload::jsonb-'target')
                     AND pg_catalog.jsonb_typeof(
                       v_revision.action_payload::jsonb->'target'
                     )='object'
                     AND (v_revision.action_payload::jsonb->'target')
                           - 'concurrency_limit'::text = '{}'::jsonb
                     AND (SELECT pg_catalog.count(*)
                          FROM pg_catalog.jsonb_object_keys(
                            v_revision.action_payload::jsonb->'target'
                          ))=1
                     AND CASE WHEN pg_catalog.jsonb_typeof(
                       v_revision.action_payload::jsonb
                         #> '{target,concurrency_limit}'
                     )='number' THEN
                       (v_revision.action_payload
                         #>> '{target,concurrency_limit}')::numeric
                           BETWEEN 1 AND 1000000
                       AND (v_revision.action_payload
                         #>> '{target,concurrency_limit}')::numeric
                           = pg_catalog.trunc((v_revision.action_payload
                             #>> '{target,concurrency_limit}')::numeric)
                     ELSE false END
                   ELSE false
                 END,false)
               )
             ) THEN
            v_stale_reason:='binding_stale';
          END IF;

          -- Approval publication authority is reconstructed only from the
          -- durable approval Snapshot and this fenced FinalizerPayload.  The
          -- worker cannot substitute an arbitrary publication_state argument.
          SELECT * INTO v_snapshot
          FROM public.approval_snapshots snapshot
          WHERE snapshot.tenant_id=v_tenant_id
            AND snapshot.approval_id=v_approval.id;
          IF v_snapshot.id IS NULL THEN
            v_stale_reason:=coalesce(v_stale_reason,'publication_binding_stale');
          ELSE
            v_snapshot_payload:=jsonb_build_object(
              'schema_version','approval-snapshot.v2',
              'approval_id',v_snapshot.approval_id,
              'proposal_id',v_snapshot.proposal_id,
              'origin',jsonb_build_object(
                'tenant_id',v_snapshot.tenant_id,
                'run_id',v_snapshot.run_id,
                'job_id',v_snapshot.origin_job_id,
                'marker_id',v_snapshot.origin_marker_id,
                'fencing_token',v_snapshot.origin_fencing_token
              ),
              'action_type',v_snapshot.action_type,
              'action_payload',v_snapshot.action_payload::jsonb,
              'action_hash',v_snapshot.action_hash,
              'resource_version',v_snapshot.resource_version,
              'policy_binding',v_snapshot.policy_binding::jsonb,
              'citation_binding_refs',v_snapshot.citation_binding_refs::jsonb
            );
            IF v_snapshot.ticket_id IS DISTINCT FROM v_approval.ticket_id
               OR v_snapshot.customer_id IS DISTINCT FROM v_approval.customer_id
               OR v_snapshot.run_id IS DISTINCT FROM v_approval.run_id
               OR v_snapshot.proposal_id IS DISTINCT FROM v_approval.proposal_id
               OR v_snapshot.action_type IS DISTINCT FROM v_approval.action_type
               OR v_snapshot.action_payload::jsonb IS DISTINCT FROM
                    v_proposal.action_payload::jsonb
               OR v_snapshot.action_hash IS DISTINCT FROM v_proposal.action_hash
               OR v_snapshot.resource_version IS DISTINCT FROM
                    v_approval.business_version
               OR v_snapshot.origin_segment_ref IS DISTINCT FROM
                    v_snapshot.origin_marker_id
               OR encode(sha256(convert_to(supportguard_canonical_jsonb(
                    v_snapshot_payload
                  ),'UTF8')),'hex') IS DISTINCT FROM v_snapshot.snapshot_hash
               OR v_snapshot.policy_binding::jsonb->>'schema_version'
                    <>'deterministic-policy-binding.v1'
               OR jsonb_typeof(v_snapshot.citation_binding_refs::jsonb)<>'array'
               OR jsonb_array_length(v_snapshot.citation_binding_refs::jsonb)=0
               OR jsonb_typeof(
                    v_snapshot.policy_binding::jsonb->'citation_lineage'
                  )<>'array'
               OR jsonb_typeof(
                    v_finalizer.payload::jsonb
                      #>'{state_delta,state,final,material_claims}'
                  )<>'array'
               OR coalesce(
                    v_finalizer.payload::jsonb
                      #>>'{state_delta,state,validated_answer}',
                    ''
                  )='' THEN
              v_stale_reason:=coalesce(
                v_stale_reason,'publication_binding_stale'
              );
            ELSE
              SELECT coalesce(
                jsonb_agg(to_jsonb(binding_id) ORDER BY binding_id),
                '[]'::jsonb
              ) INTO v_claim_binding_refs
              FROM (
                SELECT DISTINCT binding_id
                FROM jsonb_array_elements(
                  v_finalizer.payload::jsonb
                    #>'{state_delta,state,final,material_claims}'
                ) claim
                CROSS JOIN LATERAL jsonb_array_elements_text(
                  coalesce(claim->'citation_binding_ids','[]'::jsonb)
                ) binding(binding_id)
              ) normalized_claims;
              SELECT coalesce(
                jsonb_agg(to_jsonb(binding_id) ORDER BY binding_id),
                '[]'::jsonb
              ) INTO v_snapshot_binding_refs
              FROM (
                SELECT DISTINCT binding_id
                FROM jsonb_array_elements_text(
                  v_snapshot.citation_binding_refs::jsonb
                ) binding(binding_id)
              ) normalized_snapshot;
              SELECT coalesce(
                jsonb_agg(to_jsonb(binding_id) ORDER BY binding_id),
                '[]'::jsonb
              ) INTO v_lineage_binding_refs
              FROM (
                SELECT DISTINCT
                  lineage->>'citation_binding_id' AS binding_id
                FROM jsonb_array_elements(
                  v_snapshot.policy_binding::jsonb->'citation_lineage'
                ) lineage
                WHERE coalesce(lineage->>'citation_binding_id','')<>''
              ) normalized_lineage;
              IF v_claim_binding_refs IS DISTINCT FROM v_snapshot_binding_refs
                 OR v_lineage_binding_refs IS DISTINCT FROM
                      v_snapshot_binding_refs THEN
                v_stale_reason:=coalesce(
                  v_stale_reason,'publication_binding_stale'
                );
              END IF;
            END IF;
          END IF;

          IF v_stale_reason IS NULL THEN
            v_expected_capability:=CASE v_approval.action_type
              WHEN 'refund' THEN 'propose_refund'
              WHEN 'api_key_revocation' THEN 'propose_api_key_revocation'
              WHEN 'entitlement_change' THEN 'propose_entitlement_change'
              ELSE NULL END;
            SELECT * INTO v_policy_invocation
            FROM public.policy_capability_invocations invocation
            WHERE invocation.tenant_id=v_tenant_id
              AND invocation.id=(
                v_snapshot.policy_binding::jsonb
                  ->>'capability_invocation_id'
              );
            SELECT * INTO v_policy_result
            FROM public.policy_capability_results result_row
            WHERE result_row.tenant_id=v_tenant_id
              AND result_row.invocation_id=v_policy_invocation.id;
            IF v_expected_capability IS NULL
               OR v_policy_invocation.id IS NULL
               OR v_policy_result.id IS NULL
               OR v_policy_invocation.run_id IS DISTINCT FROM v_snapshot.run_id
               OR v_policy_invocation.job_id IS DISTINCT FROM
                    v_snapshot.origin_job_id
               OR v_policy_invocation.segment_id IS DISTINCT FROM
                    v_snapshot.origin_marker_id
               OR v_policy_invocation.fencing_token IS DISTINCT FROM
                    v_snapshot.origin_fencing_token
               OR v_policy_invocation.capability_name IS DISTINCT FROM
                    v_expected_capability
               OR v_policy_invocation.capability_name IS DISTINCT FROM
                    v_snapshot.policy_binding::jsonb->>'capability_name'
               OR v_policy_invocation.causal_decision_hash IS DISTINCT FROM
                    v_snapshot.policy_binding::jsonb->>'causal_decision_hash'
               OR v_policy_invocation.observation_binding_hash IS DISTINCT FROM
                    v_snapshot.policy_binding::jsonb->>'observation_binding_hash'
               OR v_policy_invocation.effect_identity IS DISTINCT FROM
                    v_snapshot.policy_binding::jsonb->>'effect_identity'
               OR v_policy_invocation.status<>'succeeded'
               OR v_policy_result.run_id IS DISTINCT FROM v_snapshot.run_id
               OR v_policy_result.job_id IS DISTINCT FROM
                    v_snapshot.origin_job_id
               OR v_policy_result.effect_identity IS DISTINCT FROM
                    v_policy_invocation.effect_identity
               OR v_policy_result.status<>'succeeded'
               OR v_policy_result.payload_hash IS DISTINCT FROM
                    v_snapshot.policy_binding::jsonb->>'result_payload_hash'
               OR v_policy_result.payload::jsonb->>'proposal_id'
                    IS DISTINCT FROM v_snapshot.proposal_id THEN
              v_stale_reason:='publication_binding_stale';
            END IF;
          END IF;

          IF v_stale_reason IS NULL AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements(
              v_snapshot.policy_binding::jsonb->'citation_lineage'
            ) lineage
            LEFT JOIN public.citation_bindings binding
              ON binding.tenant_id=v_tenant_id
             AND binding.run_id=v_snapshot.run_id
             AND binding.id=lineage->>'citation_binding_id'
            LEFT JOIN public.context_memberships membership
              ON membership.tenant_id=binding.tenant_id
             AND membership.run_id=binding.run_id
             AND membership.id=binding.membership_id
            LEFT JOIN public.retrieval_traces trace
              ON trace.tenant_id=binding.tenant_id
             AND trace.run_id=binding.run_id
             AND trace.id=binding.retrieval_trace_id
            LEFT JOIN public.tool_invocations invocation
              ON invocation.tenant_id=binding.tenant_id
             AND invocation.run_id=binding.run_id
             AND invocation.id=binding.tool_invocation_id
            LEFT JOIN public.tool_observations observation
              ON observation.tenant_id=binding.tenant_id
             AND observation.run_id=binding.run_id
             AND observation.id=binding.observation_id
            LEFT JOIN public.tool_transport_attempts transport
              ON transport.tenant_id=binding.tenant_id
             AND transport.run_id=binding.run_id
             AND transport.id=trace.terminal_transport_attempt_id
            LEFT JOIN public.agent_call_attempts attempt
              ON attempt.tenant_id=binding.tenant_id
             AND attempt.run_id=binding.run_id
             AND attempt.id=transport.agent_call_attempt_id
            LEFT JOIN public.knowledge_chunks chunk
              ON chunk.chunk_key=(
                   trace.selected_candidates::jsonb
                     ->binding.selected_candidate_ordinal->>'chunk_id'
                 )
             AND chunk.locator_hash=(
                   trace.selected_candidates::jsonb
                     ->binding.selected_candidate_ordinal->>'locator_hash'
                 )
             AND chunk.index_version=trace.index_version
             AND chunk.ingest_run_id=trace.corpus_snapshot_id
            LEFT JOIN public.knowledge_documents document
              ON document.id=chunk.document_id
             AND document.index_version=chunk.index_version
             AND document.ingest_run_id=chunk.ingest_run_id
            LEFT JOIN public.knowledge_ingest_runs ingest
              ON ingest.id=chunk.ingest_run_id
             AND ingest.index_version=chunk.index_version
            LEFT JOIN public.subscriptions source_scope
              ON source_scope.tenant_id=v_tenant_id
             AND source_scope.customer_id=v_approval.customer_id
             AND source_scope.id=trace.filter_contract::jsonb
                  #>>'{scope_snapshot,subscription_id}'
            WHERE binding.id IS NULL
               OR binding.provider_attempt_id IS DISTINCT FROM
                    lineage->>'provider_attempt_id'
               OR binding.context_ledger_id IS DISTINCT FROM
                    lineage->>'context_ledger_id'
               OR binding.origin_job_id IS DISTINCT FROM
                    lineage->>'origin_job_id'
               OR binding.tool_invocation_id IS DISTINCT FROM
                    lineage->>'tool_invocation_id'
               OR binding.observation_id IS DISTINCT FROM
                    lineage->>'observation_id'
               OR binding.retrieval_trace_id IS DISTINCT FROM
                    lineage->>'retrieval_trace_id'
               OR binding.selected_candidate_ordinal IS DISTINCT FROM
                    (lineage->>'selected_candidate_ordinal')::integer
               OR binding.locator_hash IS DISTINCT FROM
                    lineage->>'locator_hash'
               OR binding.temporal_selector::jsonb IS DISTINCT FROM
                    lineage->'temporal_selector'
               OR trace.trace_status<>'terminal_ok'
               OR trace.trace_schema_version<>'retrieval-trace.v3'
               OR trace.origin_kind<>'agent_read_tool'
               OR trace.logical_invocation_id IS DISTINCT FROM invocation.id
               OR trace.origin_job_id IS DISTINCT FROM binding.origin_job_id
               OR trace.origin_marker_id IS DISTINCT FROM
                    membership.origin_marker_id
               OR trace.origin_fencing_token IS DISTINCT FROM
                    membership.origin_fencing_token
               OR trace.pipeline_fingerprint IS DISTINCT FROM
                    lineage->>'pipeline_fingerprint'
               OR trace.corpus_snapshot_id IS DISTINCT FROM
                    lineage->>'corpus_snapshot_id'
               OR trace.index_version IS DISTINCT FROM
                    lineage->>'index_version'
               OR encode(sha256(convert_to(supportguard_canonical_jsonb(
                    trace.filter_contract::jsonb
                  ),'UTF8')),'hex') IS DISTINCT FROM
                    lineage->>'filter_contract_hash'
               OR encode(sha256(convert_to(supportguard_canonical_jsonb(
                    jsonb_build_object('groups',trace.evidence_groups::jsonb)
                  ),'UTF8')),'hex') IS DISTINCT FROM
                    lineage->>'evidence_groups_hash'
               OR membership.logical_invocation_id IS DISTINCT FROM invocation.id
               OR membership.payload_json_pointer IS DISTINCT FROM
                    '/retrieved_evidence/'||membership.payload_ordinal::text
               OR observation.invocation_id IS DISTINCT FROM invocation.id
               OR observation.status<>'ok'
               OR transport.status<>'succeeded'
               OR attempt.status<>'succeeded'
               OR attempt.call_kind<>'read_mcp'
               OR attempt.logical_invocation_id IS DISTINCT FROM invocation.id
               OR (
                 SELECT count(*)
                 FROM public.tool_transport_attempts succeeded_transport
                 WHERE succeeded_transport.tenant_id=v_tenant_id
                   AND succeeded_transport.run_id=v_snapshot.run_id
                   AND succeeded_transport.invocation_id=invocation.id
                   AND succeeded_transport.status='succeeded'
               )<>1
               OR chunk.id IS NULL
               OR document.id IS NULL
               OR ingest.id IS NULL
               OR ingest.status<>'succeeded'
               OR document.status<>'active'
               OR document.effective_from>clock_timestamp()
               OR (
                 document.effective_until IS NOT NULL
                 AND document.effective_until<=clock_timestamp()
               )
               OR trace.filter_contract::jsonb#>>'{temporal_selector,mode}'
                    <>'current'
               OR source_scope.id IS NULL
               OR source_scope.status<>'active'
               OR source_scope.version IS DISTINCT FROM
                    (trace.filter_contract::jsonb
                      #>>'{scope_snapshot,subscription_version}')::integer
               OR source_scope.plan IS DISTINCT FROM
                    trace.filter_contract::jsonb#>>'{scope_snapshot,plan}'
               OR NOT EXISTS (
                 SELECT 1
                 FROM jsonb_array_elements(coalesce(
                   observation.payload::jsonb#>'{data,evidence}',
                   observation.payload::jsonb->'evidence',
                   '[]'::jsonb
                 )) evidence
                 WHERE evidence#>>'{source_locator,locator_hash}'
                         =binding.locator_hash
                   AND evidence->>'chunk_id'=chunk.chunk_key
                   AND evidence->>'content_hash'=chunk.content_hash
                   AND evidence#>>'{source_locator,document_internal_id}'
                         =document.id
                   AND evidence#>>'{source_locator,document_version}'
                         =document.version
                   AND evidence#>>'{source_locator,source_hash}'
                         =document.content_hash
                   AND evidence#>>'{source_locator,corpus_snapshot_id}'
                         =ingest.id
                   AND evidence#>>'{source_locator,index_version}'
                         =ingest.index_version
                 )
               OR (
                 trace.filter_contract::jsonb
                   #>>'{scope_snapshot,region_trace_id}' IS NULL
                 AND EXISTS (
                   SELECT 1 FROM public.api_request_traces latest_region
                   WHERE latest_region.tenant_id=v_tenant_id
                     AND latest_region.customer_id=v_approval.customer_id
                 )
               )
               OR (
                 trace.filter_contract::jsonb
                   #>>'{scope_snapshot,region_trace_id}' IS NOT NULL
                 AND (
                   SELECT latest_region.id
                   FROM public.api_request_traces latest_region
                   WHERE latest_region.tenant_id=v_tenant_id
                     AND latest_region.customer_id=v_approval.customer_id
                   ORDER BY latest_region.observed_at DESC,latest_region.id DESC
                   LIMIT 1
                 ) IS DISTINCT FROM
                   trace.filter_contract::jsonb
                     #>>'{scope_snapshot,region_trace_id}'
               )
          ) THEN
            v_stale_reason:='publication_binding_stale';
          END IF;

          IF v_stale_reason IS NULL AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements(
              v_finalizer.payload::jsonb
                #>'{state_delta,state,final,material_claims}'
            ) claim
            WHERE coalesce(claim->>'text','')=''
               OR NOT EXISTS (
                 SELECT 1
                 FROM public.claim_records claim_record
                 WHERE claim_record.tenant_id=v_tenant_id
                   AND claim_record.run_id=v_snapshot.run_id
                   AND claim_record.status='validated'
                   AND claim_record.claim_text=claim->>'text'
                   AND claim_record.answer_hash=encode(sha256(convert_to(
                     v_finalizer.payload::jsonb
                       #>>'{state_delta,state,validated_answer}',
                     'UTF8'
                   )),'hex')
                   AND claim_record.support_refs::jsonb
                         ->'citation_binding_ids'
                         IS NOT DISTINCT FROM
                       coalesce(claim->'citation_binding_ids','[]'::jsonb)
               )
          ) THEN
            v_stale_reason:='publication_binding_stale';
          END IF;

          IF v_approval.status IN (
            'rejected','withdrawn','failed','manual_takeover'
          ) THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='approval_terminal_not_executable';
          ELSIF v_approval.status='stale' THEN
            UPDATE public.proposal_records
            SET status='stale',status_version=status_version+1,
                updated_at=clock_timestamp()
            WHERE tenant_id=v_tenant_id
              AND action_type=v_approval.action_type
              AND resource_id=v_resource_id
              AND status IN ('draft','bound');
            RETURN jsonb_build_object(
              'schema_version','runtime-action-result.v1',
              'approval_id',v_approval.id,
              'human_decision_id',p_human_decision_id,
              'business_action_id',NULL,
              'action_type',v_approval.action_type,
              'resource_id',v_resource_id,
              'status','stale','reused',true,
              'reason',coalesce(v_stale_reason,'binding_stale'));
          ELSIF v_approval.status NOT IN ('approved','executed') THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='approval_not_executable';
          END IF;

          IF v_stale_reason IS NULL THEN
            SELECT membership.id INTO v_membership_id
            FROM public.memberships membership
            WHERE membership.tenant_id=v_tenant_id
              AND membership.user_id=v_decision.actor_id
              AND membership.role='support_approver'
              AND membership.status='active'
            FOR SHARE;
            SELECT scope_row.user_id INTO v_scope_actor_id
            FROM public.approver_tenant_scopes scope_row
            WHERE scope_row.tenant_id=v_tenant_id
              AND scope_row.user_id=v_decision.actor_id
            FOR SHARE;
            IF v_membership_id IS NULL OR v_scope_actor_id IS NULL THEN
              v_stale_reason:='approver_scope_stale';
            END IF;
          END IF;

          IF v_stale_reason IS NULL AND NOT EXISTS (
            SELECT 1
            FROM public.mutation_kill_switches switch_row
            WHERE switch_row.tenant_id=v_tenant_id
              AND switch_row.action_type=v_approval.action_type
              AND switch_row.enabled
          ) THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='mutation_disabled';
          END IF;

          v_effect_identity:=encode(sha256(convert_to(
            '{"action_type":'||to_jsonb(v_approval.action_type)::text||
            ',"resource_id":'||to_jsonb(v_resource_id)::text||
            ',"resource_version":'||v_approval.business_version::text||
            ',"tenant_id":'||to_jsonb(v_tenant_id)::text||'}','UTF8')),'hex');

          IF v_approval.action_type='refund' THEN
            SELECT * INTO v_billing
            FROM public.billing_records billing
            WHERE billing.tenant_id=v_tenant_id
              AND billing.customer_id=v_approval.customer_id
              AND billing.id=v_resource_id
            FOR UPDATE;
          ELSIF v_approval.action_type='api_key_revocation' THEN
            SELECT * INTO v_key
            FROM public.api_key_metadata api_key
            WHERE api_key.tenant_id=v_tenant_id
              AND api_key.customer_id=v_approval.customer_id
              AND api_key.key_id=v_resource_id
            FOR UPDATE;
          ELSE
            SELECT * INTO v_subscription
            FROM public.subscriptions subscription
            WHERE subscription.tenant_id=v_tenant_id
              AND subscription.customer_id=v_approval.customer_id
              AND subscription.id=v_resource_id
            FOR UPDATE;
          END IF;

          SELECT * INTO v_existing
          FROM public.business_actions action_row
          WHERE action_row.tenant_id=v_tenant_id
            AND action_row.effect_identity=v_effect_identity
          FOR SHARE;
          IF v_existing.id IS NOT NULL THEN
            IF v_existing.approval_id IS DISTINCT FROM v_approval.id
               OR v_existing.human_decision_id IS DISTINCT FROM v_decision.id
               OR v_existing.action_revision_id IS DISTINCT FROM v_revision.id
               OR v_existing.action_hash IS DISTINCT FROM v_revision.action_hash
               OR v_existing.decision_hash IS DISTINCT FROM v_decision.decision_hash
               OR v_existing.action_type IS DISTINCT FROM v_approval.action_type
               OR v_existing.resource_id IS DISTINCT FROM v_resource_id
               OR v_existing.resource_version IS DISTINCT FROM
                    v_approval.business_version
               OR v_existing.status IS DISTINCT FROM 'succeeded'
               OR v_existing.canonical_event_id IS NULL
               OR v_existing.canonical_event_hash IS NULL THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='action_effect_binding_conflict';
            END IF;
            v_replay_effect_visible:=CASE v_approval.action_type
              WHEN 'refund' THEN
                v_billing.id IS NOT NULL
                AND v_billing.status='refunded'
                AND v_billing.version=v_approval.business_version+1
              WHEN 'api_key_revocation' THEN
                v_key.id IS NOT NULL
                AND v_key.status='revoked'
                AND v_key.version=v_approval.business_version+1
              WHEN 'entitlement_change' THEN
                v_subscription.id IS NOT NULL
                AND v_subscription.version=v_approval.business_version+1
                AND (
                  NOT (v_revision.action_payload::jsonb->'target' ? 'plan')
                  OR v_subscription.plan=
                    v_revision.action_payload::jsonb#>>'{target,plan}'
                )
                AND (
                  NOT (v_revision.action_payload::jsonb->'target' ? 'rpm_limit')
                  OR v_subscription.rpm_limit=(
                    v_revision.action_payload::jsonb#>>'{target,rpm_limit}'
                  )::integer
                )
                AND (
                  NOT (
                    v_revision.action_payload::jsonb->'target'
                      ? 'concurrency_limit'
                  )
                  OR v_subscription.concurrency_limit=(
                    v_revision.action_payload::jsonb#>>
                      '{target,concurrency_limit}'
                  )::integer
                )
              ELSE false END;
            IF NOT coalesce(v_replay_effect_visible,false) THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='action_effect_binding_conflict';
            END IF;
            IF v_approval.status='approved' THEN
              UPDATE public.approval_requests
              SET status='executed',consumed_at=clock_timestamp(),
                  status_version=status_version+1,updated_at=clock_timestamp()
              WHERE tenant_id=v_tenant_id AND id=v_approval.id
                AND status='approved'
                AND status_version=v_approval.status_version
                AND consumed_at IS NULL;
              GET DIAGNOSTICS v_rows=ROW_COUNT;
              IF v_rows<>1 THEN
                RAISE EXCEPTION USING ERRCODE='P0001',
                  MESSAGE='approval_state_conflict';
              END IF;
            END IF;
            UPDATE public.proposal_records
            SET status='stale',status_version=status_version+1,
                updated_at=clock_timestamp()
            WHERE tenant_id=v_tenant_id
              AND action_type=v_approval.action_type
              AND resource_id=v_resource_id
              AND status IN ('draft','bound');
            RETURN jsonb_build_object(
              'schema_version','runtime-action-result.v1',
              'approval_id',v_approval.id,
              'human_decision_id',v_decision.id,
              'business_action_id',v_existing.id,
              'action_type',v_approval.action_type,
              'resource_id',v_resource_id,
              'status','succeeded','reused',true,'reason',NULL);
          END IF;

          IF v_approval.status='executed' THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_terminal_binding_conflict';
          END IF;

          IF v_stale_reason IS NULL AND v_approval.action_type='refund' THEN
            IF v_billing.id IS NULL
               OR v_billing.status<>'charged'
               OR v_billing.version<>v_approval.business_version
               OR v_revision.action_payload->>'customer_id'
                    IS DISTINCT FROM v_approval.customer_id
               OR v_revision.action_payload->>'business_version'
                    IS DISTINCT FROM v_approval.business_version::text
               OR v_revision.action_payload->>'amount'
                    IS DISTINCT FROM v_billing.amount::text
               OR v_revision.action_payload->>'currency'
                    IS DISTINCT FROM v_billing.currency THEN
              v_stale_reason:='resource_snapshot_stale';
            ELSE
              v_result:=jsonb_build_object(
                'approval_id',v_approval.id,
                'billing_record_id',v_billing.id,
                'amount',v_billing.amount::text,
                'currency',v_billing.currency
              );
            END IF;
          ELSIF v_stale_reason IS NULL
                AND v_approval.action_type='api_key_revocation' THEN
            IF v_key.id IS NULL
               OR v_key.status<>'active'
               OR v_key.version<>v_approval.business_version
               OR v_revision.action_payload->>'customer_id'
                    IS DISTINCT FROM v_approval.customer_id
               OR v_revision.action_payload->>'business_version'
                    IS DISTINCT FROM v_approval.business_version::text
               OR v_revision.action_payload->>'fingerprint'
                    IS DISTINCT FROM v_key.fingerprint THEN
              v_stale_reason:='resource_snapshot_stale';
            ELSE
              v_result:=jsonb_build_object(
                'approval_id',v_approval.id,'status','revoked'
              );
            END IF;
          ELSIF v_stale_reason IS NULL
                AND v_approval.action_type='entitlement_change' THEN
            v_target:=v_revision.action_payload::jsonb->'target';
            v_change_type:=v_revision.action_payload->>'change_type';
            IF v_subscription.id IS NULL
               OR v_subscription.version<>v_approval.business_version
               OR v_revision.action_payload->>'customer_id'
                    IS DISTINCT FROM v_approval.customer_id
               OR v_revision.action_payload->>'business_version'
                    IS DISTINCT FROM v_approval.business_version::text
               OR jsonb_typeof(v_target)<>'object' THEN
              v_stale_reason:='resource_snapshot_stale';
            ELSE
              v_before:=jsonb_build_object(
                'plan',v_subscription.plan,
                'rpm_limit',v_subscription.rpm_limit,
                'concurrency_limit',v_subscription.concurrency_limit
              );
              IF v_change_type='quota_change'
                 AND (SELECT count(*) FROM jsonb_object_keys(v_target))=1
                 AND (
                   v_target ? 'rpm_limit'
                   OR v_target ? 'concurrency_limit'
                 ) THEN
                SELECT * INTO v_catalog
                FROM public.plan_catalog catalog
                WHERE catalog.plan=v_subscription.plan
                ORDER BY catalog.version DESC
                LIMIT 1;
                IF v_catalog.id IS NULL
                   OR (
                     v_target ? 'rpm_limit'
                     AND (
                       jsonb_typeof(v_target->'rpm_limit')<>'number'
                       OR (v_target->>'rpm_limit')::integer
                            NOT BETWEEN v_catalog.min_rpm AND v_catalog.max_rpm
                       OR (v_target->>'rpm_limit')::integer=
                            v_subscription.rpm_limit
                     )
                   )
                   OR (
                     v_target ? 'concurrency_limit'
                     AND (
                       jsonb_typeof(v_target->'concurrency_limit')<>'number'
                       OR (v_target->>'concurrency_limit')::integer
                            NOT BETWEEN v_catalog.min_concurrency
                                AND v_catalog.max_concurrency
                       OR (v_target->>'concurrency_limit')::integer=
                            v_subscription.concurrency_limit
                     )
                   ) THEN
                  v_stale_reason:='policy_stale';
                END IF;
              ELSIF v_change_type='plan_change'
                    AND (
                      SELECT count(*) FROM jsonb_object_keys(v_target)
                    )=1
                    AND v_target ? 'plan'
                    AND jsonb_typeof(v_target->'plan')='string'
                    AND v_target->>'plan'<>v_subscription.plan
                    AND EXISTS (
                      SELECT 1 FROM public.plan_catalog catalog
                      WHERE catalog.plan=v_target->>'plan'
                    ) THEN
                NULL;
              ELSE
                v_stale_reason:='policy_stale';
              END IF;
              v_result:=jsonb_build_object(
                'approval_id',v_approval.id,
                'before',v_before,'after',v_target
              );
            END IF;
          END IF;

          IF v_stale_reason IS NOT NULL THEN
            UPDATE public.approval_requests
            SET status='stale',status_version=status_version+1,
                updated_at=clock_timestamp()
            WHERE tenant_id=v_tenant_id AND id=v_approval.id
              AND status='approved'
              AND status_version=v_approval.status_version
              AND consumed_at IS NULL;
            GET DIAGNOSTICS v_rows=ROW_COUNT;
            IF v_rows<>1 THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='approval_state_conflict';
            END IF;
            UPDATE public.proposal_records
            SET status='stale',status_version=status_version+1,
                updated_at=clock_timestamp()
            WHERE tenant_id=v_tenant_id
              AND action_type=v_approval.action_type
              AND resource_id=v_resource_id
              AND status IN ('draft','bound');
            RETURN jsonb_build_object(
              'schema_version','runtime-action-result.v1',
              'approval_id',v_approval.id,
              'human_decision_id',v_decision.id,
              'business_action_id',NULL,
              'action_type',v_approval.action_type,
              'resource_id',v_resource_id,
              'status','stale','reused',false,
              'reason',v_stale_reason);
          END IF;

          v_action_id:='action_'||substr(
            encode(sha256(convert_to(v_effect_identity,'UTF8')),'hex'),1,55
          );
          v_idempotency_key:=CASE WHEN v_approval.action_type='refund'
            THEN v_approval.idempotency_key
            ELSE
              'effect:'||v_tenant_id||':'||v_approval.action_type||':'||
              v_resource_id||':'||v_approval.business_version::text
            END;
          INSERT INTO public.business_actions(
            id,tenant_id,ticket_id,customer_id,action_type,resource_id,
            resource_version,action_hash,approval_id,human_decision_id,
            action_revision_id,decision_hash,effect_identity,status,
            idempotency_key,result,created_at,updated_at
          ) VALUES (
            v_action_id,v_tenant_id,v_approval.ticket_id,
            v_approval.customer_id,v_approval.action_type,v_resource_id,
            v_approval.business_version,v_revision.action_hash,v_approval.id,
            v_decision.id,v_revision.id,v_decision.decision_hash,
            v_effect_identity,'succeeded',v_idempotency_key,v_result,
            clock_timestamp(),clock_timestamp()
          );

          IF v_approval.action_type='refund' THEN
            UPDATE public.billing_records
            SET status='refunded',version=version+1,
                updated_at=clock_timestamp()
            WHERE tenant_id=v_tenant_id
              AND customer_id=v_approval.customer_id
              AND id=v_resource_id
              AND status='charged'
              AND version=v_approval.business_version;
          ELSIF v_approval.action_type='api_key_revocation' THEN
            UPDATE public.api_key_metadata
            SET status='revoked',version=version+1,
                updated_at=clock_timestamp()
            WHERE tenant_id=v_tenant_id
              AND customer_id=v_approval.customer_id
              AND key_id=v_resource_id
              AND status='active'
              AND version=v_approval.business_version;
          ELSE
            UPDATE public.subscriptions
            SET plan=coalesce(v_target->>'plan',plan),
                rpm_limit=coalesce(
                  (v_target->>'rpm_limit')::integer,rpm_limit
                ),
                concurrency_limit=coalesce(
                  (v_target->>'concurrency_limit')::integer,
                  concurrency_limit
                ),
                version=version+1,updated_at=clock_timestamp()
            WHERE tenant_id=v_tenant_id
              AND customer_id=v_approval.customer_id
              AND id=v_resource_id
              AND version=v_approval.business_version;
          END IF;
          GET DIAGNOSTICS v_rows=ROW_COUNT;
          IF v_rows<>1 THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='action_resource_cas_conflict';
          END IF;

          UPDATE public.approval_requests
          SET status='executed',consumed_at=clock_timestamp(),
              status_version=status_version+1,updated_at=clock_timestamp()
          WHERE tenant_id=v_tenant_id AND id=v_approval.id
            AND status='approved'
            AND status_version=v_approval.status_version
            AND consumed_at IS NULL;
          GET DIAGNOSTICS v_rows=ROW_COUNT;
          IF v_rows<>1 THEN
            RAISE EXCEPTION USING ERRCODE='P0001',
              MESSAGE='approval_state_conflict';
          END IF;

          UPDATE public.proposal_records
          SET status='stale',status_version=status_version+1,
              updated_at=clock_timestamp()
          WHERE tenant_id=v_tenant_id
            AND action_type=v_approval.action_type
            AND resource_id=v_resource_id
            AND status IN ('draft','bound');

          RETURN jsonb_build_object(
            'schema_version','runtime-action-result.v1',
            'approval_id',v_approval.id,
            'human_decision_id',v_decision.id,
            'business_action_id',v_action_id,
            'action_type',v_approval.action_type,
            'resource_id',v_resource_id,
            'status','succeeded','reused',false,'reason',NULL);
        END
        $$;


ALTER FUNCTION public.supportguard_worker_execute_approved_action(p_approval_id text, p_human_decision_id text, p_job_id text, p_fencing_token bigint) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_finalize(jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_finalize(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_required text[]:=ARRAY[
          'schema_version','job_id','run_id','tenant_id','owner','fencing_token',
          'status','outcome'
        ]; v_job public.runtime_jobs%ROWTYPE;
           v_ticket public.support_tickets%ROWTYPE;
           v_proposal_probe public.proposal_records%ROWTYPE;
           v_proposal public.proposal_records%ROWTYPE;
           v_active_approval public.approval_requests%ROWTYPE;
           v_active_after public.approval_requests%ROWTYPE;
           v_run public.agent_runs%ROWTYPE;
           v_turn public.conversation_turns%ROWTYPE;
           v_resource_type text;
            v_now timestamptz:=clock_timestamp();
        BEGIN
          IF session_user<>'supportguard_worker' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker_role_required';
          END IF;
          IF p_payload->>'schema_version'='worker-interrupt-fence.v1' THEN
            IF jsonb_typeof(p_payload)<>'object'
               OR NOT p_payload ?& ARRAY[
                    'schema_version','job_id','run_id','tenant_id','owner',
                    'fencing_token','proposal_id'
                  ]::text[]
               OR p_payload-ARRAY[
                    'schema_version','job_id','run_id','tenant_id','owner',
                    'fencing_token','proposal_id'
                  ]::text[]<>'{}'::jsonb
               OR jsonb_typeof(p_payload->'fencing_token')<>'number'
               OR coalesce(length(p_payload->>'proposal_id'),0)=0 THEN
              RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='worker_interrupt_fence_schema_invalid';
            END IF;

            -- Identity discovery is deliberately lock-free.  No value from
            -- these probes is authority until it is re-read under the frozen
            -- aggregate locks below.
            SELECT * INTO v_job
            FROM public.runtime_jobs job
            WHERE job.id=p_payload->>'job_id';
            IF v_job.id IS NULL
               OR v_job.tenant_id IS DISTINCT FROM p_payload->>'tenant_id'
               OR v_job.run_id IS DISTINCT FROM p_payload->>'run_id' THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='stale_fencing_token';
            END IF;
            PERFORM set_config('app.tenant_id',v_job.tenant_id,true);
            SELECT * INTO v_proposal_probe
            FROM public.proposal_records proposal
            WHERE proposal.tenant_id=v_job.tenant_id
              AND proposal.id=p_payload->>'proposal_id'
              AND proposal.run_id=v_job.run_id;
            IF v_proposal_probe.id IS NULL THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='stale_fencing_token';
            END IF;
            v_resource_type:=CASE v_proposal_probe.action_type
              WHEN 'refund' THEN 'billing_record_id'
              WHEN 'api_key_revocation' THEN 'api_key_id'
              WHEN 'entitlement_change' THEN 'subscription_id'
              ELSE NULL
            END;
            IF v_resource_type IS NULL THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='stale_fencing_token';
            END IF;

            -- Frozen Worker interrupt-finalize order:
            -- Ticket -> canonical active Approval -> every live Proposal for
            -- the same action resource (stable ID order) -> Run/Turn ->
            -- RuntimeJob.  Marker remains an application-side later lock.
            SELECT * INTO v_ticket
            FROM public.support_tickets ticket
            WHERE ticket.tenant_id=v_job.tenant_id
              AND ticket.id=v_job.ticket_id
            FOR UPDATE;
            IF v_ticket.id IS NULL THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='stale_fencing_token';
            END IF;

            SELECT * INTO v_active_approval
            FROM public.approval_requests approval
            WHERE approval.tenant_id=v_job.tenant_id
              AND approval.customer_id=v_ticket.customer_id
              AND approval.action_type=v_proposal_probe.action_type
              AND approval.resource_type=v_resource_type
              AND approval.resource_id=v_proposal_probe.resource_id
              AND approval.status IN ('pending','approved')
            ORDER BY approval.id
            LIMIT 1
            FOR UPDATE;

            PERFORM proposal.id
            FROM public.proposal_records proposal
            WHERE proposal.tenant_id=v_job.tenant_id
              AND (
                proposal.id=p_payload->>'proposal_id'
                OR (
                  proposal.action_type=v_proposal_probe.action_type
                  AND proposal.resource_id=v_proposal_probe.resource_id
                  AND proposal.status IN ('draft','bound')
                )
              )
            ORDER BY proposal.id
            FOR UPDATE;
            SELECT * INTO v_proposal
            FROM public.proposal_records proposal
            WHERE proposal.tenant_id=v_job.tenant_id
              AND proposal.id=p_payload->>'proposal_id'
              AND proposal.run_id=v_job.run_id;

            SELECT * INTO v_run
            FROM public.agent_runs run
            WHERE run.tenant_id=v_job.tenant_id
              AND run.id=v_job.run_id
              AND run.ticket_id=v_ticket.id
            FOR UPDATE;
            IF v_run.turn_id IS NOT NULL THEN
              SELECT * INTO v_turn
              FROM public.conversation_turns turn_row
              WHERE turn_row.tenant_id=v_job.tenant_id
                AND turn_row.id=v_run.turn_id
                AND turn_row.ticket_id=v_ticket.id
              FOR UPDATE;
            END IF;
            SELECT * INTO v_job
            FROM public.runtime_jobs job
            WHERE job.tenant_id=v_job.tenant_id
              AND job.id=p_payload->>'job_id'
              AND job.run_id=p_payload->>'run_id'
              AND job.ticket_id=v_ticket.id
            FOR UPDATE;

            IF v_ticket.id IS NULL
               OR v_proposal.id IS NULL
               OR v_run.id IS NULL
               OR (v_run.turn_id IS NOT NULL AND v_turn.id IS NULL)
               OR v_job.id IS NULL
               OR v_job.kind<>'agent_start'
               OR v_job.status<>'leased'
               OR v_job.lease_owner IS DISTINCT FROM p_payload->>'owner'
               OR v_job.fencing_token IS DISTINCT FROM
                    (p_payload->>'fencing_token')::bigint
               OR v_job.lease_expires_at IS NULL
               OR v_job.lease_expires_at<=clock_timestamp()
               OR v_run.active_job_id IS DISTINCT FROM v_job.id
               OR v_run.active_fencing_token IS DISTINCT FROM v_job.fencing_token
               OR v_proposal.status<>'draft'
               OR v_proposal.run_id IS DISTINCT FROM v_run.id
               OR v_proposal.action_type IS DISTINCT FROM
                    v_proposal_probe.action_type
               OR v_proposal.resource_id IS DISTINCT FROM
                    v_proposal_probe.resource_id
               OR v_proposal.resource_version IS DISTINCT FROM
                    v_proposal_probe.resource_version
               OR v_proposal.run_id IS DISTINCT FROM v_proposal_probe.run_id THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='stale_fencing_token';
            END IF;
            IF v_active_approval.id IS NOT NULL
               AND (
                 v_active_approval.tenant_id IS DISTINCT FROM v_job.tenant_id
                 OR v_active_approval.customer_id IS DISTINCT FROM
                      v_ticket.customer_id
                 OR v_active_approval.action_type IS DISTINCT FROM
                      v_proposal.action_type
                 OR v_active_approval.resource_type IS DISTINCT FROM
                      v_resource_type
                 OR v_active_approval.resource_id IS DISTINCT FROM
                      v_proposal.resource_id
                 OR v_active_approval.status NOT IN ('pending','approved')
               ) THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='stale_fencing_token';
            END IF;

            -- If no Approval existed at the first read, this transaction may
            -- have waited while another corrected interrupt created one.
            -- Proposal locks now serialize any further creation.  Observe the
            -- committed winner without taking an Approval lock after Proposal;
            -- doing so would recreate the execute/interrupt inverse edge.
            IF v_active_approval.id IS NULL THEN
              SELECT * INTO v_active_after
              FROM public.approval_requests approval
              WHERE approval.tenant_id=v_job.tenant_id
                AND approval.customer_id=v_ticket.customer_id
                AND approval.action_type=v_proposal.action_type
                AND approval.resource_type=v_resource_type
                AND approval.resource_id=v_proposal.resource_id
                AND approval.status IN ('pending','approved')
              ORDER BY approval.id
              LIMIT 1;
              IF v_active_after.id IS NOT NULL THEN
                v_active_approval:=v_active_after;
              END IF;
            END IF;

            RETURN jsonb_build_object(
              'result','locked',
              'job_id',v_job.id,
              'run_id',v_run.id,
              'tenant_id',v_job.tenant_id,
              'ticket_id',v_ticket.id,
              'proposal_id',v_proposal.id,
              'fencing_token',v_job.fencing_token,
              'dispatch_sequence',v_job.dispatch_sequence,
              'active_approval_id',v_active_approval.id,
              'active_approval_status',v_active_approval.status
            );
          END IF;
          IF jsonb_typeof(p_payload)<>'object'
             OR p_payload->>'schema_version'<>'worker-finalize.v1'
             OR NOT p_payload ?& v_required OR p_payload-v_required<>'{}'::jsonb
             OR jsonb_typeof(p_payload->'fencing_token')<>'number'
             OR p_payload->>'status' NOT IN ('succeeded','dead')
             OR coalesce(length(p_payload->>'outcome'),0)=0
             OR length(p_payload->>'outcome')>128 THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker_finalize_schema_invalid';
          END IF;
          SELECT * INTO v_job FROM public.runtime_jobs
           WHERE id=p_payload->>'job_id';
          IF v_job.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='stale_fencing_token';
          END IF;
          PERFORM set_config('app.tenant_id',v_job.tenant_id,true);
          SELECT * INTO v_ticket FROM public.support_tickets
           WHERE tenant_id=v_job.tenant_id AND id=v_job.ticket_id FOR UPDATE;
          SELECT * INTO v_run FROM public.agent_runs
           WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id FOR UPDATE;
          SELECT * INTO v_job FROM public.runtime_jobs
           WHERE tenant_id=v_job.tenant_id AND id=p_payload->>'job_id' FOR UPDATE;
          IF v_ticket.id IS NULL OR v_job.run_id<>p_payload->>'run_id'
             OR v_job.tenant_id<>p_payload->>'tenant_id' OR v_job.status<>'leased'
             OR v_job.lease_owner<>p_payload->>'owner'
             OR v_job.fencing_token<>(p_payload->>'fencing_token')::bigint
             OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at<=v_now THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='stale_fencing_token';
          END IF;
          IF v_run.id IS NULL OR v_run.active_job_id IS NOT NULL
             OR v_run.active_fencing_token IS NOT NULL
             OR (p_payload->>'status'='dead' AND v_run.status<>'failed')
             OR (p_payload->>'status'='succeeded' AND v_run.status NOT IN ('completed','interrupted'))
             OR NOT EXISTS (
               SELECT 1 FROM public.checkpoint_commit_markers m
                WHERE m.tenant_id=v_job.tenant_id AND m.run_id=v_job.run_id
                  AND m.job_id=v_job.id
                  AND (
                    (p_payload->>'status'='dead' AND m.status='aborted')
                    OR (p_payload->>'status'='succeeded' AND m.status='finalized')
                  )
             ) THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='worker_finalize_binding_invalid';
          END IF;
          IF p_payload->>'status'='dead' THEN
            PERFORM set_config(
              'app.dead_convergence_authorized','v1512',true
            );
          END IF;
          UPDATE public.runtime_jobs SET status=p_payload->>'status',
            outcome=p_payload->>'outcome',
            last_error=CASE WHEN p_payload->>'status'='dead' THEN p_payload->>'outcome' ELSE NULL END,
            terminal_at=coalesce(terminal_at,v_now),lease_owner=NULL,
            lease_expires_at=NULL,heartbeat_at=NULL,status_version=status_version+1,
            updated_at=v_now WHERE id=v_job.id;
          IF p_payload->>'status'='dead' THEN
            PERFORM public.supportguard_internal_converge_dead_job(
              v_job.tenant_id,v_job.id
            );
          ELSE
            PERFORM public.supportguard_internal_activate_next_ticket_turn(
              v_job.tenant_id,v_job.ticket_id,v_job.id
            );
            PERFORM public.supportguard_internal_converge_ticket_status(
              v_job.tenant_id,v_job.ticket_id,v_ticket.status
            );
          END IF;
          RETURN jsonb_build_object('job_id',v_job.id,'status',p_payload->>'status',
            'outcome',p_payload->>'outcome');
        EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
          RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker_finalize_schema_invalid';
        END $$;


ALTER FUNCTION public.supportguard_worker_finalize(p_payload jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_finish_job(text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_finish_job(p_job_id text, p_owner text, p_fencing_token bigint, p_outcome text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE v_job public.runtime_jobs%ROWTYPE;
                v_ticket public.support_tickets%ROWTYPE;
                v_approval public.approval_requests%ROWTYPE;
                v_proposal public.proposal_records%ROWTYPE;
                v_run public.agent_runs%ROWTYPE;
                v_turn public.conversation_turns%ROWTYPE;
                v_marker public.checkpoint_commit_markers%ROWTYPE;
                v_payload public.finalizer_payloads%ROWTYPE;
                v_timing supportguard_control.runtime_timing_snapshots%ROWTYPE;
                v_now timestamptz:=clock_timestamp();
                v_terminal boolean;
                v_status text;
                v_decision text;
                v_variant text;
                v_payload_outcome text;
                v_canonical_outcome text;
                v_domain_reason text;
                v_commit_mode text;
                v_effect_state text;
                v_activation jsonb:='{}'::jsonb;
        BEGIN
          IF session_user<>'supportguard_worker' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker_role_required';
          END IF;
          IF p_outcome IS NULL OR length(p_outcome)=0 OR length(p_outcome)>128 THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker_outcome_invalid';
          END IF;
          SELECT * INTO v_job FROM public.runtime_jobs WHERE id=p_job_id;
          IF v_job.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='stale_fencing_token';
          END IF;
          PERFORM set_config('app.tenant_id',v_job.tenant_id,true);
          SELECT * INTO v_ticket FROM public.support_tickets
          WHERE tenant_id=v_job.tenant_id AND id=v_job.ticket_id FOR UPDATE;
          IF v_ticket.id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='stale_fencing_token';
          END IF;
          SELECT * INTO v_approval FROM public.approval_requests
          WHERE tenant_id=v_job.tenant_id
            AND (
              (id=v_job.approval_id AND run_id=v_job.run_id
                AND ticket_id=v_job.ticket_id)
              OR (
                v_job.approval_id IS NULL AND run_id=v_job.run_id
                AND ticket_id=v_job.ticket_id
                AND status IN ('pending','approved')
              )
            )
          ORDER BY CASE WHEN id=v_job.approval_id THEN 0 ELSE 1 END,created_at,id
          LIMIT 1 FOR UPDATE;
          IF v_approval.id IS NOT NULL THEN
            SELECT * INTO v_proposal FROM public.proposal_records
            WHERE tenant_id=v_approval.tenant_id
              AND id=v_approval.proposal_id FOR UPDATE;
          END IF;
          SELECT * INTO v_run FROM public.agent_runs
          WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id FOR UPDATE;
          IF v_run.turn_id IS NOT NULL THEN
            SELECT * INTO v_turn FROM public.conversation_turns
            WHERE tenant_id=v_job.tenant_id AND id=v_run.turn_id FOR UPDATE;
          END IF;
          SELECT * INTO v_job FROM public.runtime_jobs
          WHERE tenant_id=v_job.tenant_id AND id=p_job_id FOR UPDATE;
          IF v_run.id IS NULL OR v_run.ticket_id IS DISTINCT FROM v_job.ticket_id
             OR (v_job.kind='approval_resume' AND v_approval.id IS NULL) THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='stale_fencing_token';
          END IF;

          -- A Finalizer abort commits its dead aggregate before control returns
          -- to the queue consumer.  The outer finish call must converge the
          -- Inbox row and return the already persisted terminal state rather
          -- than treating the released lease as a stale-fence process error.
          IF v_job.status='dead' AND v_job.fencing_token=p_fencing_token
             AND v_job.lease_owner IS NULL AND v_job.lease_expires_at IS NULL
             AND NOT EXISTS (
               SELECT 1 FROM public.agent_runs r WHERE r.id=v_job.run_id
                AND (r.active_job_id IS NOT NULL OR r.active_fencing_token IS NOT NULL)
             ) THEN
            UPDATE public.inbox_deliveries SET status='acked',
                outcome=coalesce(v_job.outcome,'infrastructure_exhausted'),
                terminal_at=coalesce(terminal_at,clock_timestamp()),
                updated_at=clock_timestamp()
             WHERE tenant_id=v_job.tenant_id AND job_id=v_job.id
               AND status IN ('received','claimed');
            v_activation:=public.supportguard_internal_activate_next_ticket_turn(
              v_job.tenant_id,v_job.ticket_id,v_job.id
            );
            PERFORM public.supportguard_internal_converge_ticket_status(
              v_job.tenant_id,v_job.ticket_id,
              CASE
                WHEN p_outcome LIKE 'domain_terminal:%'
                  OR p_outcome LIKE 'failed:%' OR p_outcome='failed' THEN 'failed'
                WHEN p_outcome='interrupted' THEN 'awaiting_approval'
                WHEN p_outcome='rejected' THEN 'rejected'
                WHEN p_outcome='manual_takeover' THEN 'manual_takeover'
                ELSE (SELECT status FROM public.support_tickets
                  WHERE tenant_id=v_job.tenant_id AND id=v_job.ticket_id)
              END
            );
            RETURN jsonb_build_object('job_id',v_job.id,'ticket_id',(SELECT r.ticket_id FROM public.agent_runs r WHERE r.tenant_id=v_job.tenant_id AND r.id=v_job.run_id),'status','dead',
              'outcome',coalesce(v_job.outcome,'infrastructure_exhausted'))
              ||jsonb_build_object(
                'dispatch_sequence',v_job.dispatch_sequence
              )||v_activation;
          END IF;


          -- Only an exception raised while awaiting the outer COMMIT may use
          -- this outcome.  A landed COMMIT is handed to the existing typed
          -- terminal verifier below.  A non-landed ordinary Finalizer retains
          -- its checkpoint_written Marker and enters bounded finalizer-only
          -- retry.  Only an Approval action lane may enter effect verification.
          IF p_outcome LIKE 'finalizer_commit_unknown:%' THEN
            v_commit_mode:=split_part(p_outcome,':',2);
            IF v_commit_mode NOT IN ('action_effect','finalizer_only')
               OR p_outcome IS DISTINCT FROM
                    'finalizer_commit_unknown:'||v_commit_mode THEN
              RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='finalizer_commit_unknown_schema_invalid';
            END IF;
            IF v_job.status='succeeded' THEN
              IF v_commit_mode='action_effect'
                 AND v_job.kind<>'approval_resume' THEN
                RAISE EXCEPTION USING ERRCODE='P0001',
                  MESSAGE='finalizer_commit_unknown_lane_invalid';
              END IF;
              IF v_job.outcome='verification_pending' THEN
                SELECT * INTO v_marker
                FROM public.checkpoint_commit_markers marker
                WHERE marker.tenant_id=v_job.tenant_id
                  AND marker.run_id=v_job.run_id
                  AND marker.job_id=v_job.id
                  AND marker.fencing_token=p_fencing_token
                ORDER BY marker.created_at DESC,marker.id DESC
                LIMIT 1 FOR UPDATE;
                SELECT * INTO v_payload
                FROM public.finalizer_payloads payload
                WHERE payload.tenant_id=v_job.tenant_id
                  AND payload.run_id=v_job.run_id
                  AND payload.job_id=v_job.id
                  AND payload.marker_id=v_marker.id;
                IF v_commit_mode<>'action_effect'
                   OR v_marker.id IS NULL
                   OR v_marker.status<>'finalized'
                   OR v_marker.segment_kind<>'approval_resume'
                   OR v_payload.id IS NULL
                   OR v_payload.schema_version<>'finalizer.v2'
                   OR v_payload.fencing_token<>p_fencing_token
                   OR v_payload.domain_delta->>'variant'
                        NOT IN ('approval_action_intent','approval_fail_closed')
                   OR v_payload.domain_delta->>'approval_id'
                        IS DISTINCT FROM v_approval.id
                   OR v_approval.status<>'approved' THEN
                  RAISE EXCEPTION USING ERRCODE='P0001',
                    MESSAGE='finalizer_commit_unknown_terminal_invalid';
                END IF;
                UPDATE public.inbox_deliveries
                SET status='acked',outcome='verification_pending',
                    terminal_at=coalesce(terminal_at,v_now),updated_at=v_now
                WHERE tenant_id=v_job.tenant_id AND job_id=v_job.id
                  AND status IN ('received','claimed');
                RETURN jsonb_build_object(
                  'job_id',v_job.id,'ticket_id',v_job.ticket_id,
                  'status','succeeded','outcome','verification_pending',
                  'dispatch_sequence',v_job.dispatch_sequence
                );
              END IF;
              -- Re-enter the existing landed-COMMIT verifier with the
              -- transport outcome implied by durable terminal truth, never
              -- the uncertain signal.  The Finalizer's persisted domain
              -- outcome (for example ``resolved``) is intentionally richer
              -- than this handoff's small protocol vocabulary.
              p_outcome:=CASE
                WHEN v_job.outcome IN ('interrupted','awaiting_approval')
                  THEN 'interrupted'
                WHEN v_job.outcome IN ('rejected','manual_takeover')
                  THEN v_job.outcome
                ELSE 'completed'
              END;
            ELSIF v_job.status='leased'
                  AND v_job.lease_owner=p_owner
                  AND v_job.fencing_token=p_fencing_token
                  AND v_run.active_job_id=v_job.id
                  AND v_run.active_fencing_token=v_job.fencing_token THEN
              IF v_commit_mode='finalizer_only' THEN
                -- The ordinary failed-infrastructure branch below releases
                -- this fence into bounded retry.  Recovery consumes only the
                -- already committed Marker and never calls the Provider.
                p_outcome:='failed:FinalizerCommitUnknown';
              ELSE
                IF v_job.kind<>'approval_resume'
                   OR v_approval.id IS NULL
                   OR v_approval.status<>'approved' THEN
                  RAISE EXCEPTION USING ERRCODE='P0001',
                    MESSAGE='finalizer_commit_unknown_lane_invalid';
                END IF;
                SELECT * INTO v_marker
                FROM public.checkpoint_commit_markers marker
                WHERE marker.tenant_id=v_job.tenant_id
                  AND marker.run_id=v_job.run_id
                  AND marker.job_id=v_job.id
                  AND marker.fencing_token=p_fencing_token
                ORDER BY marker.created_at DESC,marker.id DESC
                LIMIT 1 FOR UPDATE;
                SELECT * INTO v_payload
                FROM public.finalizer_payloads payload
                WHERE payload.tenant_id=v_job.tenant_id
                  AND payload.run_id=v_job.run_id
                  AND payload.job_id=v_job.id
                  AND payload.marker_id=v_marker.id;
                IF v_marker.id IS NULL
                   OR v_marker.status<>'checkpoint_written'
                   OR v_marker.segment_kind<>'approval_resume'
                   OR v_marker.final_checkpoint_id IS NULL
                   OR v_marker.final_checkpoint_hash IS NULL
                   OR v_marker.final_checkpoint_version IS DISTINCT FROM
                        v_marker.parent_checkpoint_version+1
                   OR v_payload.id IS NULL
                   OR v_payload.schema_version<>'finalizer.v2'
                   OR v_payload.fencing_token<>p_fencing_token
                   OR v_payload.payload->>'tenant_id'<>v_job.tenant_id
                   OR v_payload.payload->>'run_id'<>v_job.run_id
                   OR v_payload.payload->>'job_id'<>v_job.id
                   OR v_payload.payload->>'marker_id'<>v_marker.id
                   OR v_payload.payload->>'segment_kind'<>'approval_resume'
                   OR v_payload.domain_delta->>'variant'
                        <>'approval_action_intent'
                   OR v_payload.domain_delta->>'outcome'<>'completed'
                   OR v_payload.domain_delta->>'approval_id'
                        IS DISTINCT FROM v_approval.id THEN
                  RAISE EXCEPTION USING ERRCODE='P0001',
                    MESSAGE='finalizer_commit_unknown_binding_invalid';
                END IF;
                UPDATE public.checkpoint_commit_markers
                SET status='finalized',status_version=status_version+1,
                    updated_at=v_now
                WHERE tenant_id=v_job.tenant_id AND id=v_marker.id
                  AND status='checkpoint_written';
                UPDATE public.agent_runs
                SET canonical_checkpoint_ns=v_marker.private_namespace,
                    canonical_checkpoint_id=v_marker.final_checkpoint_id,
                    canonical_checkpoint_hash=v_marker.final_checkpoint_hash,
                    canonical_checkpoint_version=v_marker.final_checkpoint_version,
                    status='interrupted',
                    checkpoint_stage='verification_pending',
                    checkpoint_id=v_marker.final_checkpoint_id,
                    agent_finish_reason='verification_pending',
                    error_code=NULL,active_job_id=NULL,
                    active_fencing_token=NULL,completed_at=NULL,
                    status_version=status_version+1,updated_at=v_now
                WHERE tenant_id=v_job.tenant_id AND id=v_run.id;
                IF v_turn.id IS NOT NULL THEN
                  UPDATE public.conversation_turns
                  SET activity_state='waiting_external',
                      completed_at=NULL,updated_at=v_now
                  WHERE tenant_id=v_job.tenant_id AND id=v_turn.id;
                END IF;
                UPDATE public.support_tickets
                SET status='verification_pending',version=version+1,
                    updated_at=v_now
                WHERE tenant_id=v_job.tenant_id AND id=v_ticket.id;
                UPDATE public.runtime_jobs
                SET status='succeeded',outcome='verification_pending',
                    last_error='finalizer_commit_result_unknown',
                    terminal_at=coalesce(terminal_at,v_now),
                    lease_owner=NULL,lease_expires_at=NULL,heartbeat_at=NULL,
                    status_version=status_version+1,updated_at=v_now
                WHERE tenant_id=v_job.tenant_id AND id=v_job.id;
                UPDATE public.inbox_deliveries
                SET status='acked',outcome='verification_pending',
                    terminal_at=coalesce(terminal_at,v_now),updated_at=v_now
                WHERE tenant_id=v_job.tenant_id AND job_id=v_job.id
                  AND status IN ('received','claimed');
                v_activation:=public.supportguard_internal_activate_next_ticket_turn(
                  v_job.tenant_id,v_ticket.id,v_job.id
                );
                PERFORM public.supportguard_internal_converge_ticket_status(
                  v_job.tenant_id,v_ticket.id,'verification_pending'
                );
                RETURN jsonb_build_object(
                  'job_id',v_job.id,'ticket_id',v_ticket.id,
                  'status','succeeded','outcome','verification_pending',
                  'dispatch_sequence',v_job.dispatch_sequence
                )||v_activation;
              END IF;
            ELSE
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='finalizer_commit_unknown_state_invalid';
            END IF;
          END IF;

          -- A validated action intent that failed before entering the
          -- Runtime-only effect boundary has a provable zero effect.  Converge
          -- its whole lifecycle atomically instead of leaving Approval=approved
          -- beside Job=dead or silently reopening the action identity.
          IF p_outcome LIKE 'finalizer_zero_effect_failed:%' THEN
            IF v_job.status<>'leased'
               OR v_job.lease_owner<>p_owner
               OR v_job.fencing_token<>p_fencing_token
               OR v_job.kind<>'approval_resume'
               OR v_approval.id IS NULL
               OR v_approval.status<>'approved'
               OR v_run.active_job_id<>v_job.id
               OR v_run.active_fencing_token<>v_job.fencing_token
               OR split_part(p_outcome,':',2)=''
               OR p_outcome IS DISTINCT FROM
                    'finalizer_zero_effect_failed:'||split_part(p_outcome,':',2)
            THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='finalizer_zero_effect_binding_invalid';
            END IF;
            v_effect_state:=public.supportguard_internal_classify_action_effect(
              v_job.tenant_id,v_approval.id
            );
            IF v_effect_state<>'confirmed_zero_effect' THEN
              RAISE EXCEPTION USING ERRCODE='P0001',
                MESSAGE='finalizer_zero_effect_unproven';
            END IF;
            PERFORM set_config(
              'app.dead_convergence_authorized','v1512',true
            );
            UPDATE public.runtime_jobs
            SET status='dead',outcome='confirmed_zero_effect_failure',
                last_error=left(split_part(p_outcome,':',2),128),
                terminal_at=coalesce(terminal_at,v_now),
                lease_owner=NULL,lease_expires_at=NULL,heartbeat_at=NULL,
                status_version=status_version+1,updated_at=v_now
            WHERE tenant_id=v_job.tenant_id AND id=v_job.id;
            PERFORM public.supportguard_internal_converge_dead_job(
              v_job.tenant_id,v_job.id
            );
            UPDATE public.inbox_deliveries
            SET status='acked',outcome='confirmed_zero_effect_failure',
                terminal_at=coalesce(terminal_at,v_now),updated_at=v_now
            WHERE tenant_id=v_job.tenant_id AND job_id=v_job.id
              AND status IN ('received','claimed');
            RETURN jsonb_build_object(
              'job_id',v_job.id,'ticket_id',v_ticket.id,
              'status','dead','outcome','confirmed_zero_effect_failure',
              'dispatch_sequence',v_job.dispatch_sequence
            );
          END IF;

          -- The deterministic Finalizer commits Job/Run/Ticket/Marker first. The
          -- outer worker then performs this same-fence handoff to normalize the
          -- transport outcome and ack delivery, without replaying business work.
          IF v_job.status='succeeded' AND v_job.fencing_token=p_fencing_token
             AND v_job.lease_owner IS NULL AND v_job.lease_expires_at IS NULL
             AND NOT EXISTS (
               SELECT 1 FROM public.agent_runs r WHERE r.id=v_job.run_id
                AND (r.active_job_id IS NOT NULL OR r.active_fencing_token IS NOT NULL)
             ) THEN
            SELECT * INTO v_marker FROM public.checkpoint_commit_markers m
             WHERE m.tenant_id=v_job.tenant_id AND m.run_id=v_job.run_id
               AND m.job_id=v_job.id AND m.fencing_token=p_fencing_token
             ORDER BY m.created_at DESC,m.id DESC LIMIT 1 FOR UPDATE;
            SELECT * INTO v_payload FROM public.finalizer_payloads f
             WHERE f.tenant_id=v_job.tenant_id AND f.run_id=v_job.run_id
               AND f.job_id=v_job.id AND f.marker_id=v_marker.id;
            IF v_marker.id IS NULL OR v_marker.status<>'finalized'
               OR v_marker.segment_kind<>v_job.kind OR v_payload.id IS NULL
               OR v_payload.schema_version<>'finalizer.v2'
               OR v_payload.fencing_token<>p_fencing_token
               OR v_payload.payload->>'tenant_id'<>v_job.tenant_id
               OR v_payload.payload->>'run_id'<>v_job.run_id
               OR v_payload.payload->>'job_id'<>v_job.id
               OR v_payload.payload->>'marker_id'<>v_marker.id
               OR v_payload.payload->>'segment_kind'<>v_marker.segment_kind THEN
              RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='terminal_handoff_binding_invalid';
            END IF;
            v_variant:=v_payload.domain_delta->>'variant';
            v_payload_outcome:=v_payload.domain_delta->>'outcome';
            IF v_marker.segment_kind='agent_start' AND v_variant='agent_complete'
               AND v_payload_outcome='completed' AND p_outcome='completed' THEN
              v_canonical_outcome:='completed';
            ELSIF v_marker.segment_kind='agent_start' AND v_variant='hitl_interrupt'
               AND v_payload_outcome='interrupted' AND p_outcome='interrupted'
               AND EXISTS (
                 SELECT 1 FROM public.approval_requests a
                  WHERE a.tenant_id=v_job.tenant_id AND a.run_id=v_job.run_id
                    AND a.marker_id=v_marker.id AND a.status='pending'
               ) THEN
              v_canonical_outcome:='interrupted';
            ELSIF v_marker.segment_kind='approval_resume'
               AND v_variant='approval_actionful' AND v_payload_outcome='completed'
               AND p_outcome='completed' THEN
              SELECT d.decision INTO v_decision FROM public.human_decisions d
               WHERE d.tenant_id=v_job.tenant_id
                 AND d.id=v_payload.domain_delta->>'human_decision_id'
                 AND d.approval_id=v_payload.domain_delta->>'approval_id';
              IF v_decision NOT IN ('approve','edit_and_approve')
                 OR v_decision<>v_payload.domain_delta->>'decision'
                 OR NOT EXISTS (
                   SELECT 1 FROM public.business_actions b
                    WHERE b.tenant_id=v_job.tenant_id
                      AND b.id=v_payload.domain_delta->>'business_action_id'
                      AND b.approval_id=v_payload.domain_delta->>'approval_id'
                      AND b.human_decision_id=v_payload.domain_delta->>'human_decision_id'
                 ) THEN
                RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='terminal_handoff_action_invalid';
              END IF;
              v_canonical_outcome:='completed';
            ELSIF v_marker.segment_kind='approval_resume'
               AND v_variant='approval_action_intent'
               AND v_payload_outcome='completed' AND p_outcome='completed' THEN
              SELECT d.decision INTO v_decision FROM public.human_decisions d
               WHERE d.tenant_id=v_job.tenant_id
                 AND d.id=v_payload.domain_delta->>'human_decision_id'
                 AND d.approval_id=v_payload.domain_delta->>'approval_id';
              IF v_decision NOT IN ('approve','edit_and_approve')
                 OR v_decision<>v_payload.domain_delta->>'decision'
                 OR v_approval.id IS DISTINCT FROM
                      v_payload.domain_delta->>'approval_id'
                 OR v_approval.action_hash IS DISTINCT FROM
                      v_payload.domain_delta->>'action_hash' THEN
                RAISE EXCEPTION USING ERRCODE='P0001',
                  MESSAGE='terminal_handoff_action_invalid';
              END IF;
              IF public.supportguard_internal_action_intent_executed_receipt(
                   v_job.tenant_id,v_job.id,v_job.run_id,
                   v_payload.domain_delta::jsonb
                 ) THEN
                v_canonical_outcome:='completed';
              ELSIF public.supportguard_internal_action_intent_stale_receipt(
                   v_job.tenant_id,v_job.id,v_job.run_id,
                   v_payload.domain_delta::jsonb
                 ) THEN
                v_canonical_outcome:='domain_terminal';
                v_domain_reason:='binding_stale';
              ELSE
                RAISE EXCEPTION USING ERRCODE='P0001',
                  MESSAGE='terminal_handoff_action_invalid';
              END IF;
            ELSIF v_marker.segment_kind='approval_resume'
               AND v_variant='approval_no_action' AND v_payload_outcome='completed' THEN
              SELECT d.decision INTO v_decision FROM public.human_decisions d
               WHERE d.tenant_id=v_job.tenant_id
                 AND d.id=v_payload.domain_delta->>'human_decision_id'
                 AND d.approval_id=v_payload.domain_delta->>'approval_id';
              IF v_decision<>v_payload.domain_delta->>'decision'
                 OR v_decision NOT IN ('reject','manual_takeover') THEN
                RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='terminal_handoff_decision_invalid';
              END IF;
              v_canonical_outcome:=CASE WHEN v_decision='reject'
                THEN 'rejected' ELSE 'manual_takeover' END;
              IF p_outcome NOT IN ('completed',v_canonical_outcome) THEN
                RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='terminal_handoff_outcome_invalid';
              END IF;
            ELSIF v_marker.segment_kind='approval_resume'
               AND v_variant='approval_fail_closed' AND v_payload_outcome='completed'
               AND p_outcome='completed' THEN
              v_domain_reason:=coalesce(
                nullif(v_payload.domain_delta->>'domain_outcome_reason',''),
                'binding_stale'
              );
              IF v_domain_reason NOT IN ('binding_stale','logical_degradation') THEN
                RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='domain_outcome_reason_invalid';
              END IF;
              IF v_domain_reason='logical_degradation'
                 AND v_payload.domain_delta->>'validation_result'='approved'
                 AND EXISTS (
                   SELECT 1 FROM public.approval_requests a
                   WHERE a.tenant_id=v_job.tenant_id
                     AND a.id=v_payload.domain_delta->>'approval_id'
                     AND a.run_id=v_job.run_id
                     AND a.ticket_id=v_job.ticket_id
                     AND a.status='approved'
                 ) THEN
                v_canonical_outcome:='verification_pending';
              ELSE
                v_canonical_outcome:='domain_terminal';
              END IF;
            ELSE
              RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='terminal_handoff_outcome_invalid';
            END IF;
            UPDATE public.runtime_jobs SET outcome=v_canonical_outcome,
                last_error=CASE
                  WHEN v_canonical_outcome='domain_terminal'
                    THEN v_payload.domain_delta->>'validation_result'
                  WHEN v_canonical_outcome='verification_pending'
                    THEN 'effect_status_unknown'
                  ELSE last_error
                END,
                terminal_at=coalesce(terminal_at,v_now),updated_at=v_now
             WHERE id=v_job.id AND (
               outcome IS DISTINCT FROM v_canonical_outcome OR terminal_at IS NULL
               OR (v_canonical_outcome='domain_terminal' AND last_error IS DISTINCT FROM
                 v_payload.domain_delta->>'validation_result')
               OR (v_canonical_outcome='verification_pending'
                   AND last_error IS DISTINCT FROM 'effect_status_unknown')
             );
            IF v_domain_reason IS NOT NULL THEN
              UPDATE public.agent_runs SET agent_finish_reason=CASE
                    WHEN v_canonical_outcome='verification_pending'
                      THEN 'verification_pending'
                    ELSE v_domain_reason
                  END,updated_at=v_now
               WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id
                 AND agent_finish_reason IS DISTINCT FROM v_domain_reason;
            END IF;
            UPDATE public.inbox_deliveries SET status='acked',outcome=v_canonical_outcome,
                terminal_at=coalesce(terminal_at,v_now),updated_at=v_now
             WHERE tenant_id=v_job.tenant_id AND job_id=v_job.id
               AND status IN ('received','claimed');
            v_activation:=public.supportguard_internal_activate_next_ticket_turn(
              v_job.tenant_id,v_job.ticket_id,v_job.id
            );
            PERFORM public.supportguard_internal_converge_ticket_status(
              v_job.tenant_id,v_job.ticket_id,
              CASE
                WHEN p_outcome LIKE 'domain_terminal:%'
                  OR p_outcome LIKE 'failed:%' OR p_outcome='failed' THEN 'failed'
                WHEN p_outcome='interrupted' THEN 'awaiting_approval'
                WHEN p_outcome='rejected' THEN 'rejected'
                WHEN p_outcome='manual_takeover' THEN 'manual_takeover'
                ELSE (SELECT status FROM public.support_tickets
                  WHERE tenant_id=v_job.tenant_id AND id=v_job.ticket_id)
              END
            );
            RETURN jsonb_build_object('job_id',v_job.id,'ticket_id',(SELECT r.ticket_id FROM public.agent_runs r WHERE r.tenant_id=v_job.tenant_id AND r.id=v_job.run_id),'status','succeeded',
              'outcome',v_canonical_outcome)
              ||jsonb_build_object(
                'dispatch_sequence',v_job.dispatch_sequence
              )||v_activation;
          END IF;

          IF v_job.status<>'leased' OR v_job.lease_owner<>p_owner
             OR v_job.fencing_token<>p_fencing_token
             OR NOT EXISTS (
               SELECT 1 FROM public.agent_runs r
                WHERE r.tenant_id=v_job.tenant_id AND r.id=v_job.run_id
                  AND r.active_job_id=v_job.id
                  AND r.active_fencing_token=v_job.fencing_token
             ) THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='stale_fencing_token';
          END IF;
          SELECT * INTO v_timing FROM supportguard_control.runtime_timing_snapshots
           WHERE timing_version=v_job.timing_version;
          IF v_timing.timing_version IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='runtime_timing_missing';
          END IF;
          IF p_outcome LIKE 'domain_terminal:%' THEN
            IF split_part(p_outcome,':',2) NOT IN ('binding_stale','logical_degradation') THEN
              RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='domain_outcome_reason_invalid';
            END IF;
            v_status:='succeeded';
            UPDATE public.runtime_jobs SET status='succeeded',outcome='domain_terminal',
                last_error=left(split_part(p_outcome,':',3),128),
                terminal_at=coalesce(terminal_at,v_now),lease_owner=NULL,
                lease_expires_at=NULL,heartbeat_at=NULL,
                status_version=status_version+1,updated_at=v_now WHERE id=v_job.id;
            UPDATE public.agent_runs SET active_job_id=NULL,active_fencing_token=NULL,
                status='completed',agent_finish_reason=split_part(p_outcome,':',2),
                completed_at=v_now,status_version=status_version+1,updated_at=v_now
             WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id;
            UPDATE public.support_tickets SET status='failed',
                version=version+1,updated_at=v_now WHERE tenant_id=v_job.tenant_id
                AND id=(SELECT ticket_id FROM public.agent_runs
                  WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id);
            IF split_part(p_outcome,':',2)='binding_stale' THEN
              UPDATE public.approval_requests SET status='stale',
                  status_version=status_version+1,updated_at=v_now
               WHERE tenant_id=v_job.tenant_id AND run_id=v_job.run_id
                 AND status IN ('pending','approved');
            END IF;
            UPDATE public.checkpoint_commit_markers SET status='finalized',
                segment_outcome='domain_terminal',status_version=status_version+1,
                updated_at=v_now WHERE tenant_id=v_job.tenant_id AND run_id=v_job.run_id
                AND job_id=v_job.id AND status IN ('prepared','checkpoint_written');
          ELSIF p_outcome LIKE 'terminal_failed:%' THEN
            IF v_job.kind<>'agent_start'
               OR split_part(p_outcome,':',2)=''
               OR p_outcome IS DISTINCT FROM
                    'terminal_failed:'||split_part(p_outcome,':',2) THEN
              RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='terminal_failure_handoff_invalid';
            END IF;
            PERFORM set_config(
              'app.dead_convergence_authorized','v1512',true
            );
            v_status:='dead';
            UPDATE public.runtime_jobs
            SET status='dead',outcome='infrastructure_exhausted',
                last_error=left(split_part(p_outcome,':',2),128),
                terminal_at=coalesce(terminal_at,v_now),
                lease_owner=NULL,lease_expires_at=NULL,heartbeat_at=NULL,
                status_version=status_version+1,updated_at=v_now
            WHERE tenant_id=v_job.tenant_id AND id=v_job.id;
            PERFORM public.supportguard_internal_converge_dead_job(
              v_job.tenant_id,v_job.id
            );
            p_outcome:='failed:'||split_part(p_outcome,':',2);
          ELSIF p_outcome LIKE 'failed:%' OR p_outcome='failed' THEN
            v_terminal:=v_job.attempt>=v_timing.max_attempts OR
              v_now>v_job.created_at+make_interval(secs=>v_timing.max_job_age_seconds);
            v_status:=CASE WHEN v_terminal THEN 'dead' ELSE 'retry_wait' END;
            IF v_terminal THEN
              PERFORM set_config(
                'app.dead_convergence_authorized','v1512',true
              );
            END IF;
            UPDATE public.runtime_jobs SET status=v_status,
                outcome=CASE WHEN v_terminal THEN 'infrastructure_exhausted' ELSE NULL END,
                last_error=left(p_outcome,128),
                terminal_at=CASE WHEN v_terminal THEN coalesce(terminal_at,v_now) ELSE NULL END,
                available_at=CASE WHEN v_terminal THEN available_at ELSE
                  v_now+make_interval(secs=>least(30.0,power(2,v_job.attempt))+
                    (get_byte(decode(md5(v_job.id||':'||v_job.attempt::text),'hex'),0)*256+
                     get_byte(decode(md5(v_job.id||':'||v_job.attempt::text),'hex'),1))
                    %1001/1000.0) END,
                lease_owner=NULL,lease_expires_at=NULL,heartbeat_at=NULL,
                status_version=status_version+1,updated_at=v_now WHERE id=v_job.id;
            IF v_terminal THEN
              PERFORM public.supportguard_internal_converge_dead_job(
                v_job.tenant_id,v_job.id
              );
            ELSE
              UPDATE public.agent_runs
              SET active_job_id=NULL,active_fencing_token=NULL,
                  status='queued',status_version=status_version+1,
                  updated_at=v_now
              WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id;
            END IF;
          ELSE
            v_status:='succeeded';
            UPDATE public.runtime_jobs SET status='succeeded',outcome=p_outcome,
                terminal_at=coalesce(terminal_at,v_now),lease_owner=NULL,
                lease_expires_at=NULL,heartbeat_at=NULL,
                status_version=status_version+1,updated_at=v_now WHERE id=v_job.id;
            UPDATE public.agent_runs SET active_job_id=NULL,active_fencing_token=NULL,
                status=CASE WHEN p_outcome='interrupted' THEN 'interrupted' ELSE 'completed' END,
                completed_at=CASE WHEN p_outcome='interrupted' THEN completed_at ELSE v_now END,
                status_version=status_version+1,updated_at=v_now
             WHERE tenant_id=v_job.tenant_id AND id=v_job.run_id;
          END IF;
          UPDATE public.inbox_deliveries SET status='acked',outcome=CASE
                WHEN p_outcome LIKE 'domain_terminal:%' THEN 'domain_terminal' ELSE p_outcome END,
              terminal_at=coalesce(terminal_at,v_now),updated_at=v_now
           WHERE tenant_id=v_job.tenant_id AND job_id=v_job.id
             AND status IN ('received','claimed');
          v_activation:=public.supportguard_internal_activate_next_ticket_turn(
            v_job.tenant_id,v_job.ticket_id,v_job.id
          );
          PERFORM public.supportguard_internal_converge_ticket_status(
            v_job.tenant_id,v_job.ticket_id,
            CASE
              WHEN p_outcome LIKE 'domain_terminal:%'
                OR p_outcome LIKE 'failed:%' OR p_outcome='failed' THEN 'failed'
              WHEN p_outcome='interrupted' THEN 'awaiting_approval'
              WHEN p_outcome='rejected' THEN 'rejected'
              WHEN p_outcome='manual_takeover' THEN 'manual_takeover'
              ELSE (SELECT status FROM public.support_tickets
                WHERE tenant_id=v_job.tenant_id AND id=v_job.ticket_id)
            END
          );
          RETURN jsonb_build_object('job_id',v_job.id,'ticket_id',(SELECT r.ticket_id FROM public.agent_runs r WHERE r.tenant_id=v_job.tenant_id AND r.id=v_job.run_id),'status',v_status,'outcome',
            CASE WHEN p_outcome LIKE 'domain_terminal:%' THEN 'domain_terminal' ELSE p_outcome END)
            ||jsonb_build_object(
              'dispatch_sequence',v_job.dispatch_sequence
            )||v_activation;
        END $$;


ALTER FUNCTION public.supportguard_worker_finish_job(p_job_id text, p_owner text, p_fencing_token bigint, p_outcome text) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_heartbeat_job(text, text, bigint); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_heartbeat_job(p_job_id text, p_owner text, p_fencing_token bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE
            v_job public.runtime_jobs%ROWTYPE;
            v_timing supportguard_control.runtime_timing_snapshots%ROWTYPE;
            v_now timestamptz := clock_timestamp();
        BEGIN
            IF session_user <> 'supportguard_worker' THEN
                RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='worker_role_required';
            END IF;
            SELECT * INTO v_job FROM public.runtime_jobs
            WHERE id=p_job_id FOR UPDATE;
            IF v_job.id IS NULL OR v_job.status <> 'leased'
               OR v_job.lease_owner <> p_owner
               OR v_job.fencing_token <> p_fencing_token
               OR v_job.lease_expires_at IS NULL OR v_job.lease_expires_at <= v_now
               OR NOT EXISTS (
                    SELECT 1 FROM public.agent_runs r
                    WHERE r.tenant_id=v_job.tenant_id AND r.id=v_job.run_id
                      AND r.active_job_id=v_job.id
                      AND r.active_fencing_token=v_job.fencing_token
               ) THEN
                RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='stale_fencing_token';
            END IF;
            SELECT * INTO v_timing
            FROM supportguard_control.runtime_timing_snapshots
            WHERE timing_version=v_job.timing_version;
            IF v_timing.timing_version IS NULL THEN
                RAISE EXCEPTION USING ERRCODE='P0001', MESSAGE='runtime_timing_missing';
            END IF;
            UPDATE public.runtime_jobs
            SET heartbeat_at=v_now,
                lease_expires_at=v_now + make_interval(secs=>v_timing.lease_seconds),
                updated_at=v_now
            WHERE id=v_job.id;
            RETURN jsonb_build_object(
                'job_id',v_job.id,'fencing_token',v_job.fencing_token,
                'lease_expires_at',v_now + make_interval(secs=>v_timing.lease_seconds)
            );
        END $$;


ALTER FUNCTION public.supportguard_worker_heartbeat_job(p_job_id text, p_owner text, p_fencing_token bigint) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_publish_conversation_message(jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_publish_conversation_message(p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        DECLARE v_tenant_id text:=current_setting('app.tenant_id',true);
          v_run public.agent_runs%ROWTYPE; v_ticket public.support_tickets%ROWTYPE;
          v_existing public.ticket_messages%ROWTYPE; v_message public.ticket_messages%ROWTYPE;
        BEGIN
          IF session_user<>'supportguard_worker' OR p_request IS NULL
             OR coalesce(p_request->>'run_id','')='' OR coalesce(p_request->>'kind','')=''
             OR coalesce(p_request->>'publication_key','')='' THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='publish_message_invalid';
          END IF;
          SELECT * INTO v_run FROM public.agent_runs WHERE tenant_id=v_tenant_id
            AND id=p_request->>'run_id';
          IF NOT FOUND THEN
            RETURN pg_catalog.jsonb_build_object('error_code','run_not_found');
          END IF;
          SELECT * INTO v_ticket FROM public.support_tickets WHERE tenant_id=v_tenant_id
            AND id=v_run.ticket_id FOR UPDATE;
          SELECT * INTO v_existing FROM public.ticket_messages WHERE tenant_id=v_tenant_id
            AND publication_key=p_request->>'publication_key';
          IF FOUND THEN RETURN pg_catalog.to_jsonb(v_existing); END IF;
          INSERT INTO public.ticket_messages(
            id,tenant_id,ticket_id,turn_id,run_id,approval_id,message_kind,publication_key,
            role,content,source_refs,created_at,updated_at
          ) VALUES (p_request->>'message_id',v_tenant_id,v_run.ticket_id,v_run.turn_id,v_run.id,
            nullif(p_request->>'approval_id',''),p_request->>'kind',
            p_request->>'publication_key',CASE WHEN p_request->>'kind'='assistant'
              THEN 'assistant' ELSE 'action' END,p_request->>'content',
            coalesce(p_request->'source_refs','[]'::jsonb),clock_timestamp(),clock_timestamp())
          RETURNING * INTO v_message;
          RETURN pg_catalog.to_jsonb(v_message);
        END $$;


ALTER FUNCTION public.supportguard_worker_publish_conversation_message(p_request jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_record_poison(jsonb); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_record_poison(p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
        DECLARE v_required text[] := ARRAY[
            'schema_version','redis_message_id','consumer_group','payload_hash','error_type'
        ];
        BEGIN
            IF session_user <> 'supportguard_worker' THEN
                RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='worker_role_required';
            END IF;
            IF jsonb_typeof(p_payload)<>'object'
               OR p_payload->>'schema_version'<>'worker-poison.v1'
               OR NOT p_payload ?& v_required
               OR p_payload - v_required <> '{}'::jsonb
               OR coalesce(length(p_payload->>'redis_message_id'),0)=0
               OR coalesce(length(p_payload->>'consumer_group'),0)=0
               OR (p_payload->>'payload_hash') !~ '^[0-9a-f]{64}$'
               OR coalesce(length(p_payload->>'error_type'),0)=0
               OR length(p_payload->>'error_type')>100 THEN
                RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='worker_poison_schema_invalid';
            END IF;
            PERFORM public.supportguard_worker_record_poison(
                p_payload->>'redis_message_id',p_payload->>'consumer_group',
                p_payload->>'payload_hash',p_payload->>'error_type'
            );
        END $_$;


ALTER FUNCTION public.supportguard_worker_record_poison(p_payload jsonb) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_record_poison(text, text, text, text); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_record_poison(p_redis_message_id text, p_consumer_group text, p_payload_hash text, p_error_type text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
        BEGIN
            IF session_user <> 'supportguard_worker' THEN
                RAISE EXCEPTION 'worker capability caller is not authorized';
            END IF;
            INSERT INTO public.queue_delivery_audits(
                id,tenant_id,job_id,delivery_id,redis_message_id,consumer_group,
                outcome,payload_hash,details,created_at,updated_at
            ) VALUES (
                'qaudit_' || replace(gen_random_uuid()::text,'-',''),NULL,NULL,NULL,
                left(p_redis_message_id,64),left(p_consumer_group,64),
                'poison_invalid_schema',left(p_payload_hash,64),
                jsonb_build_object('error_type',left(p_error_type,100)),
                statement_timestamp(),statement_timestamp()
            );
        END; $$;


ALTER FUNCTION public.supportguard_worker_record_poison(p_redis_message_id text, p_consumer_group text, p_payload_hash text, p_error_type text) OWNER TO supportguard_owner;

--
-- Name: supportguard_worker_revalidate_approver_scope(text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: supportguard_owner
--

CREATE FUNCTION public.supportguard_worker_revalidate_approver_scope(p_approval_id text, p_human_decision_id text, p_job_id text, p_fencing_token bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'supportguard_control'
    AS $$
        DECLARE
          v_tenant_id text:=current_setting('app.tenant_id',true);
          v_run_id text;
          v_actor_id text;
          v_membership_id text;
          v_scope_actor_id text;
        BEGIN
          IF session_user<>'supportguard_worker' THEN
            RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker_role_required';
          END IF;
          IF v_tenant_id IS NULL OR v_tenant_id='' OR p_approval_id IS NULL
             OR p_human_decision_id IS NULL OR p_job_id IS NULL
             OR p_fencing_token IS NULL OR p_fencing_token<1 THEN
            RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='approver_scope_input_invalid';
          END IF;

          SELECT j.run_id INTO v_run_id
            FROM public.runtime_jobs j
            JOIN public.agent_runs r
              ON r.tenant_id=j.tenant_id AND r.id=j.run_id
           WHERE j.tenant_id=v_tenant_id AND j.id=p_job_id
             AND j.kind='approval_resume' AND j.status='leased'
             AND j.fencing_token=p_fencing_token
             AND r.active_job_id=j.id
             AND r.active_fencing_token=j.fencing_token
           FOR SHARE OF j,r;
          IF v_run_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='stale_fencing_token';
          END IF;

          SELECT d.actor_id INTO v_actor_id
            FROM public.approval_requests a
            JOIN public.human_decisions d
              ON d.tenant_id=a.tenant_id AND d.approval_id=a.id
            JOIN public.approval_action_revisions ar
              ON ar.tenant_id=a.tenant_id AND ar.approval_id=a.id
             AND ar.id=a.selected_revision_id
            JOIN public.proposal_records p
              ON p.tenant_id=a.tenant_id AND p.id=a.proposal_id
             AND p.run_id=a.run_id
           WHERE a.tenant_id=v_tenant_id AND a.id=p_approval_id
             AND a.run_id=v_run_id AND a.status='approved'
             AND d.id=p_human_decision_id
             AND d.decision IN ('approve','edit_and_approve')
             AND d.action_revision_id=ar.id
             AND d.action_hash=ar.action_hash
             AND a.action_hash=p.action_hash
             AND p.action_type=a.action_type
             AND p.resource_version=ar.resource_version
             AND a.selected_revision_number=ar.revision_number
           FOR SHARE OF a,d,ar;
          IF v_actor_id IS NULL THEN
            RETURN false;
          END IF;

          SELECT m.id INTO v_membership_id
            FROM public.memberships m
           WHERE m.tenant_id=v_tenant_id AND m.user_id=v_actor_id
             AND m.role='support_approver' AND m.status='active'
           FOR SHARE OF m;
          IF v_membership_id IS NULL THEN
            RETURN false;
          END IF;
          SELECT s.user_id INTO v_scope_actor_id
            FROM public.approver_tenant_scopes s
           WHERE s.tenant_id=v_tenant_id AND s.user_id=v_actor_id
           FOR SHARE OF s;
          RETURN v_scope_actor_id IS NOT NULL;
        END $$;


ALTER FUNCTION public.supportguard_worker_revalidate_approver_scope(p_approval_id text, p_human_decision_id text, p_job_id text, p_fencing_token bigint) OWNER TO supportguard_owner;

--
-- Name: agent_call_attempts; Type: TABLE; Schema: public; Owner: supportguard_owner
--

CREATE TABLE public.agent_call_attempts (
    id character varying(64) NOT NULL,
    tenant_id character varying(64) NOT NULL,
    run_id character varying(64) NOT NULL,
    job_id character varying(64) NOT NULL,
    fencing_token bigint NOT NULL,
    call_kind character varying(32) NOT NULL,
    ordinal integer NOT NULL,
    status character varying(32) NOT NULL,
    prompt_tokens integer NOT NULL,
    completion_tokens integer NOT NULL,
    latency_ms integer,
    error_code character varying(100),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    logical_invocation_id character varying(64),
    transport_ordinal integer,
    runtime_provenance json DEFAULT '{}'::json NOT NULL,
    CONSTRAINT ck_agent_call_attempts_attempt_status_valid CHECK (((status)::text = ANY ((ARRAY['started'::character varying, 'succeeded'::character varying, 'failed'::character varying, 'unknown'::character varying])::text[])))
);

ALTER TABLE ONLY public.agent_call_attempts FORCE ROW LEVEL SECURITY;


ALTER TABLE public.agent_call_attempts OWNER TO supportguard_owner;

--
-- Name: agent_events; Type: TABLE; Schema: public; Owner: supportguard_owner
--

CREATE TABLE public.agent_events (
    id character varying(64) NOT NULL,
    run_id character varying(64) NOT NULL,
    ticket_id character varying(64) NOT NULL,
    customer_id character varying(64) NOT NULL,
    sequence integer NOT NULL,
    step_index integer NOT NULL,
    tool_round integer NOT NULL,
    event_type character varying(100) NOT NULL,
    status character varying(32) NOT NULL,
    visibility character varying(32) NOT NULL,
    tool_call_id character varying(64),
    payload json NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    tenant_id character varying(64) NOT NULL,
    ticket_sequence bigint NOT NULL,
    run_sequence bigint NOT NULL,
    job_id character varying(64),
    parent_event_hash character varying(64) NOT NULL,
    event_hash character varying(64) NOT NULL,
    correlation_id character varying(64) NOT NULL,
    causation_id character varying(64),
    payload_hash character varying(64) NOT NULL,
    previous_event_id character varying(64),
    idempotency_id character varying(128),
    delivery_generation integer,
    fencing_token bigint,
