-- Name: runtime_timing_snapshots; Type: TABLE; Schema: supportguard_control; Owner: supportguard_owner
--

CREATE TABLE supportguard_control.runtime_timing_snapshots (
    timing_version bigint NOT NULL,
    max_job_age_seconds integer NOT NULL,
    max_attempts integer NOT NULL,
    max_delivery_generation integer NOT NULL,
    redelivery_grace_seconds integer NOT NULL,
    lease_seconds integer NOT NULL,
    backlog_count_limit integer NOT NULL,
    oldest_backlog_seconds integer NOT NULL,
    config_hash text NOT NULL,
    activated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    is_active boolean DEFAULT false NOT NULL,
    CONSTRAINT runtime_timing_default_contract CHECK (((timing_version <> 1) OR ((max_job_age_seconds = 600) AND (max_attempts = 5) AND (max_delivery_generation = 5) AND (backlog_count_limit = 500) AND (oldest_backlog_seconds = 600)))),
    CONSTRAINT runtime_timing_snapshots_backlog_count_limit_check CHECK (((backlog_count_limit >= 1) AND (backlog_count_limit <= 100000))),
    CONSTRAINT runtime_timing_snapshots_config_hash_check CHECK ((length(config_hash) = 64)),
    CONSTRAINT runtime_timing_snapshots_lease_seconds_check CHECK (((lease_seconds >= 5) AND (lease_seconds <= 300))),
    CONSTRAINT runtime_timing_snapshots_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 100))),
    CONSTRAINT runtime_timing_snapshots_max_delivery_generation_check CHECK (((max_delivery_generation >= 1) AND (max_delivery_generation <= 20))),
    CONSTRAINT runtime_timing_snapshots_max_job_age_seconds_check CHECK (((max_job_age_seconds >= 60) AND (max_job_age_seconds <= 86400))),
    CONSTRAINT runtime_timing_snapshots_oldest_backlog_seconds_check CHECK (((oldest_backlog_seconds >= 1) AND (oldest_backlog_seconds <= 86400))),
    CONSTRAINT runtime_timing_snapshots_redelivery_grace_seconds_check CHECK (((redelivery_grace_seconds >= 0) AND (redelivery_grace_seconds <= 300)))
);


ALTER TABLE supportguard_control.runtime_timing_snapshots OWNER TO supportguard_owner;

