    upgrade_run_id text,
    fence_phase text,
    tenant_id text,
    drain_job_id text,
    drain_run_id text,
    drain_owner text,
    drain_fencing_token bigint,
    permitted boolean NOT NULL,
    denial_code text,
    acquired_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    released_at timestamp with time zone,
    CONSTRAINT writer_barrier_receipts_backend_pid_check CHECK ((backend_pid > 0)),
    CONSTRAINT writer_barrier_receipts_check CHECK (((permitted AND (denial_code IS NULL)) OR ((NOT permitted) AND (denial_code IS NOT NULL)))),
    CONSTRAINT writer_barrier_receipts_check1 CHECK ((((drain_job_id IS NULL) AND (drain_run_id IS NULL) AND (drain_owner IS NULL) AND (drain_fencing_token IS NULL) AND (tenant_id IS NULL)) OR ((drain_job_id IS NOT NULL) AND (drain_run_id IS NOT NULL) AND (drain_owner IS NOT NULL) AND (drain_fencing_token > 0) AND (tenant_id IS NOT NULL)))),
    CONSTRAINT writer_barrier_receipts_operation_check CHECK ((operation = ANY (ARRAY['dispatcher'::text, 'worker'::text, 'reconciler'::text, 'maintenance'::text])))
);


